// 自動產生檔案，請勿手動編輯 —— 執行 build_book_text_data.py 重新產生
// 來源：bible_data/bible_text/GEN.json（A1下載產出）

const GEN_DATA = {"book": "GEN", "book_zh": "創世記", "chapters": {"1": {"verses": {"1": {"en": "In the beginning, God created the heavens and the earth.", "zh": "起初，上帝創造天地。", "ja": "はじめに神は天と地とを創造された。"}, "2": {"en": "The earth was formless and empty. Darkness was on the surface of the deep and God’s Spirit was hovering over the surface of the waters.", "zh": "地是空虛混沌，淵面黑暗；上帝的靈運行在水面上。", "ja": "地は形なく、むなしく、やみが淵のおもてにあり、神の霊が水のおもてをおおっていた。"}, "3": {"en": "God said, “Let there be light,” and there was light.", "zh": "上帝說：「要有光」，就有了光。", "ja": "神は「光あれ」と言われた。すると光があった。"}, "4": {"en": "God saw the light, and saw that it was good. God divided the light from the darkness.", "zh": "上帝看光是好的，就把光暗分開了。", "ja": "神はその光を見て、良しとされた。神はその光とやみとを分けられた。"}, "5": {"en": "God called the light “day”, and the darkness he called “night”. There was evening and there was morning, the first day.", "zh": "上帝稱光為「晝」，稱暗為「夜」。有晚上，有早晨，這是頭一日。", "ja": "神は光を昼と名づけ、やみを夜と名づけられた。夕となり、また朝となった。第一日である。"}, "6": {"en": "God said, “Let there be an expanse in the middle of the waters, and let it divide the waters from the waters.”", "zh": "上帝說：「諸水之間要有空氣，將水分為上下。」", "ja": "神はまた言われた、「水の間におおぞらがあって、水と水とを分けよ」。"}, "7": {"en": "God made the expanse, and divided the waters which were under the expanse from the waters which were above the expanse; and it was so.", "zh": "上帝就造出空氣，將空氣以下的水、空氣以上的水分開了。事就這樣成了。", "ja": "そのようになった。神はおおぞらを造って、おおぞらの下の水とおおぞらの上の水とを分けられた。"}, "8": {"en": "God called the expanse “sky”. There was evening and there was morning, a second day.", "zh": "上帝稱空氣為「天」。有晚上，有早晨，是第二日。", "ja": "神はそのおおぞらを天と名づけられた。夕となり、また朝となった。第二日である。"}, "9": {"en": "God said, “Let the waters under the sky be gathered together to one place, and let the dry land appear;” and it was so.", "zh": "上帝說：「天下的水要聚在一處，使旱地露出來。」事就這樣成了。", "ja": "神はまた言われた、「天の下の水は一つ所に集まり、かわいた地が現れよ」。そのようになった。"}, "10": {"en": "God called the dry land “earth”, and the gathering together of the waters he called “seas”. God saw that it was good.", "zh": "上帝稱旱地為「地」，稱水的聚處為「海」。上帝看着是好的。", "ja": "神はそのかわいた地を陸と名づけ、水の集まった所を海と名づけられた。神は見て、良しとされた。"}, "11": {"en": "God said, “Let the earth yield grass, herbs yielding seeds, and fruit trees bearing fruit after their kind, with their seeds in it, on the earth;” and it was so.", "zh": "上帝說：「地要發生青草和結種子的菜蔬，並結果子的樹木，各從其類，果子都包着核。」事就這樣成了。", "ja": "神はまた言われた、「地は青草と、種をもつ草と、種類にしたがって種のある実を結ぶ果樹とを地の上にはえさせよ」。そのようになった。"}, "12": {"en": "The earth yielded grass, herbs yielding seed after their kind, and trees bearing fruit, with their seeds in it, after their kind; and God saw that it was good.", "zh": "於是地發生了青草和結種子的菜蔬，各從其類；並結果子的樹木，各從其類；果子都包着核。上帝看着是好的。", "ja": "地は青草と、種類にしたがって種をもつ草と、種類にしたがって種のある実を結ぶ木とをはえさせた。神は見て、良しとされた。"}, "13": {"en": "There was evening and there was morning, a third day.", "zh": "有晚上，有早晨，是第三日。", "ja": "夕となり、また朝となった。第三日である。"}, "14": {"en": "God said, “Let there be lights in the expanse of the sky to divide the day from the night; and let them be for signs to mark seasons, days, and years;", "zh": "上帝說：「天上要有光體，可以分晝夜，作記號，定節令、日子、年歲，", "ja": "神はまた言われた、「天のおおぞらに光があって昼と夜とを分け、しるしのため、季節のため、日のため、年のためになり、"}, "15": {"en": "and let them be for lights in the expanse of the sky to give light on the earth;” and it was so.", "zh": "並要發光在天空，普照在地上。」事就這樣成了。", "ja": "天のおおぞらにあって地を照らす光となれ」。そのようになった。"}, "16": {"en": "God made the two great lights: the greater light to rule the day, and the lesser light to rule the night. He also made the stars.", "zh": "於是上帝造了兩個大光，大的管晝，小的管夜，又造眾星，", "ja": "神は二つの大きな光を造り、大きい光に昼をつかさどらせ、小さい光に夜をつかさどらせ、また星を造られた。"}, "17": {"en": "God set them in the expanse of the sky to give light to the earth,", "zh": "就把這些光擺列在天空，普照在地上，", "ja": "神はこれらを天のおおぞらに置いて地を照らさせ、"}, "18": {"en": "and to rule over the day and over the night, and to divide the light from the darkness. God saw that it was good.", "zh": "管理晝夜，分別明暗。上帝看着是好的。", "ja": "昼と夜とをつかさどらせ、光とやみとを分けさせられた。神は見て、良しとされた。"}, "19": {"en": "There was evening and there was morning, a fourth day.", "zh": "有晚上，有早晨，是第四日。", "ja": "夕となり、また朝となった。第四日である。"}, "20": {"en": "God said, “Let the waters abound with living creatures, and let birds fly above the earth in the open expanse of the sky.”", "zh": "上帝說：「水要多多滋生有生命的物；要有雀鳥飛在地面以上，天空之中。」", "ja": "神はまた言われた、「水は生き物の群れで満ち、鳥は地の上、天のおおぞらを飛べ」。"}, "21": {"en": "God created the large sea creatures and every living creature that moves, with which the waters swarmed, after their kind, and every winged bird after its kind. God saw that it was good.", "zh": "上帝就造出大魚和水中所滋生各樣有生命的動物，各從其類；又造出各樣飛鳥，各從其類。上帝看着是好的。", "ja": "神は海の大いなる獣と、水に群がるすべての動く生き物とを、種類にしたがって創造し、また翼のあるすべての鳥を、種類にしたがって創造された。神は見て、良しとされた。"}, "22": {"en": "God blessed them, saying, “Be fruitful, and multiply, and fill the waters in the seas, and let birds multiply on the earth.”", "zh": "上帝就賜福給這一切，說：「滋生繁多，充滿海中的水；雀鳥也要多生在地上。」", "ja": "神はこれらを祝福して言われた、「生めよ、ふえよ、海の水に満ちよ、また鳥は地にふえよ」。"}, "23": {"en": "There was evening and there was morning, a fifth day.", "zh": "有晚上，有早晨，是第五日。", "ja": "夕となり、また朝となった。第五日である。"}, "24": {"en": "God said, “Let the earth produce living creatures after their kind, livestock, creeping things, and animals of the earth after their kind;” and it was so.", "zh": "上帝說：「地要生出活物來，各從其類；牲畜、昆蟲、野獸，各從其類。」事就這樣成了。", "ja": "神はまた言われた、「地は生き物を種類にしたがっていだせ。家畜と、這うものと、地の獣とを種類にしたがっていだせ」。そのようになった。"}, "25": {"en": "God made the animals of the earth after their kind, and the livestock after their kind, and everything that creeps on the ground after its kind. God saw that it was good.", "zh": "於是上帝造出野獸，各從其類；牲畜，各從其類；地上一切昆蟲，各從其類。上帝看着是好的。", "ja": "神は地の獣を種類にしたがい、家畜を種類にしたがい、また地に這うすべての物を種類にしたがって造られた。神は見て、良しとされた。"}, "26": {"en": "God said, “Let’s make man in our image, after our likeness. Let them have dominion over the fish of the sea, and over the birds of the sky, and over the livestock, and over all the earth, and over every creeping thing that creeps on the earth.”", "zh": "上帝說：「我們要照着我們的形像、按着我們的樣式造人，使他們管理海裏的魚、空中的鳥、地上的牲畜，和全地，並地上所爬的一切昆蟲。」", "ja": "神はまた言われた、「われわれのかたちに、われわれにかたどって人を造り、これに海の魚と、空の鳥と、家畜と、地のすべての獣と、地のすべての這うものとを治めさせよう」。"}, "27": {"en": "God created man in his own image. In God’s image he created him; male and female he created them.", "zh": "上帝就照着自己的形像造人，乃是照着他的形像造男造女。", "ja": "神は自分のかたちに人を創造された。すなわち、神のかたちに創造し、男と女とに創造された。"}, "28": {"en": "God blessed them. God said to them, “Be fruitful, multiply, fill the earth, and subdue it. Have dominion over the fish of the sea, over the birds of the sky, and over every living thing that moves on the earth.”", "zh": "上帝就賜福給他們，又對他們說：「要生養眾多，遍滿地面，治理這地，也要管理海裏的魚、空中的鳥，和地上各樣行動的活物。」", "ja": "神は彼らを祝福して言われた、「生めよ、ふえよ、地に満ちよ、地を従わせよ。また海の魚と、空の鳥と、地に動くすべての生き物とを治めよ」。"}, "29": {"en": "God said, “Behold, I have given you every herb yielding seed, which is on the surface of all the earth, and every tree, which bears fruit yielding seed. It will be your food.", "zh": "上帝說：「看哪，我將遍地上一切結種子的菜蔬和一切樹上所結有核的果子全賜給你們作食物。", "ja": "神はまた言われた、「わたしは全地のおもてにある種をもつすべての草と、種のある実を結ぶすべての木とをあなたがたに与える。これはあなたがたの食物となるであろう。"}, "30": {"en": "To every animal of the earth, and to every bird of the sky, and to everything that creeps on the earth, in which there is life, I have given every green herb for food;” and it was so.", "zh": "至於地上的走獸和空中的飛鳥，並各樣爬在地上有生命的物，我將青草賜給牠們作食物。」事就這樣成了。", "ja": "また地のすべての獣、空のすべての鳥、地を這うすべてのもの、すなわち命あるものには、食物としてすべての青草を与える」。そのようになった。"}, "31": {"en": "God saw everything that he had made, and, behold, it was very good. There was evening and there was morning, a sixth day.", "zh": "上帝看着一切所造的都甚好。有晚上，有早晨，是第六日。", "ja": "神が造ったすべての物を見られたところ、それは、はなはだ良かった。夕となり、また朝となった。第六日である。"}}}, "2": {"verses": {"1": {"en": "The heavens, the earth, and all their vast array were finished.", "zh": "天地萬物都造齊了。", "ja": "こうして天と地と、その万象とが完成した。"}, "2": {"en": "On the seventh day God finished his work which he had done; and he rested on the seventh day from all his work which he had done.", "zh": "到第七日，上帝造物的工已經完畢，就在第七日歇了他一切的工，安息了。", "ja": "神は第七日にその作業を終えられた。すなわち、そのすべての作業を終って第七日に休まれた。"}, "3": {"en": "God blessed the seventh day, and made it holy, because he rested in it from all his work of creation which he had done.", "zh": "上帝賜福給第七日，定為聖日；因為在這日，上帝歇了他一切創造的工，就安息了。", "ja": "神はその第七日を祝福して、これを聖別された。神がこの日に、そのすべての創造のわざを終って休まれたからである。"}, "4": {"en": "This is the history of the generations of the heavens and of the earth when they were created, in the day that the LORD God made the earth and the heavens.", "zh": "創造天地的來歷，在耶和華上帝造天地的日子，乃是這樣，", "ja": "これが天地創造の由来である。主なる神が地と天とを造られた時、"}, "5": {"en": "No plant of the field was yet on the earth, and no herb of the field had yet sprung up; for the LORD God had not caused it to rain on the earth. There was not a man to till the ground,", "zh": "野地還沒有草木，田間的菜蔬還沒有長起來；因為耶和華上帝還沒有降雨在地上，也沒有人耕地，", "ja": "地にはまだ野の木もなく、また野の草もはえていなかった。主なる神が地に雨を降らせず、また土を耕す人もなかったからである。"}, "6": {"en": "but a mist went up from the earth, and watered the whole surface of the ground.", "zh": "但有霧氣從地上騰，滋潤遍地。", "ja": "しかし地から泉がわきあがって土の全面を潤していた。"}, "7": {"en": "The LORD God formed man from the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul.", "zh": "耶和華上帝用地上的塵土造人，將生氣吹在他鼻孔裏，他就成了有靈的活人，名叫 亞當。", "ja": "主なる神は土のちりで人を造り、命の息をその鼻に吹きいれられた。そこで人は生きた者となった。"}, "8": {"en": "The LORD God planted a garden eastward, in Eden, and there he put the man whom he had formed.", "zh": "耶和華上帝在東方的伊甸立了一個園子，把所造的人安置在那裏。", "ja": "主なる神は東のかた、エデンに一つの園を設けて、その造った人をそこに置かれた。"}, "9": {"en": "Out of the ground the LORD God made every tree to grow that is pleasant to the sight, and good for food, including the tree of life in the middle of the garden and the tree of the knowledge of good and evil.", "zh": "耶和華上帝使各樣的樹從地裏長出來，可以悅人的眼目，其上的果子好作食物。園子當中又有生命樹和分別善惡的樹。", "ja": "また主なる神は、見て美しく、食べるに良いすべての木を土からはえさせ、更に園の中央に命の木と、善悪を知る木とをはえさせられた。"}, "10": {"en": "A river went out of Eden to water the garden; and from there it was parted, and became the source of four rivers.", "zh": "有河從伊甸流出來，滋潤那園子，從那裏分為四道：", "ja": "また一つの川がエデンから流れ出て園を潤し、そこから分れて四つの川となった。"}, "11": {"en": "The name of the first is Pishon: it flows through the whole land of Havilah, where there is gold;", "zh": "第一道名叫比遜，就是環繞哈腓拉全地的。在那裏有金子，", "ja": "その第一の名はピソンといい、金のあるハビラの全地をめぐるもので、"}, "12": {"en": "and the gold of that land is good. Bdellium and onyx stone are also there.", "zh": "並且那地的金子是好的；在那裏又有珍珠和紅瑪瑙。", "ja": "その地の金は良く、またそこはブドラクと、しまめのうとを産した。"}, "13": {"en": "The name of the second river is Gihon. It is the same river that flows through the whole land of Cush.", "zh": "第二道河名叫基訓，就是環繞古實全地的。", "ja": "第二の川の名はギホンといい、クシの全地をめぐるもの。"}, "14": {"en": "The name of the third river is Hiddekel. This is the one which flows in front of Assyria. The fourth river is the Euphrates.", "zh": "第三道河名叫底格里斯，流在亞述的東邊。第四道河就是幼發拉底河。", "ja": "第三の川の名はヒデケルといい、アッスリヤの東を流れるもの。第四の川はユフラテである。"}, "15": {"en": "The LORD God took the man, and put him into the garden of Eden to cultivate and keep it.", "zh": "耶和華上帝將那人安置在伊甸園，使他修理，看守。", "ja": "主なる神は人を連れて行ってエデンの園に置き、これを耕させ、これを守らせられた。"}, "16": {"en": "The LORD God commanded the man, saying, “You may freely eat of every tree of the garden;", "zh": "耶和華上帝吩咐他說：「園中各樣樹上的果子，你可以隨意吃，", "ja": "主なる神はその人に命じて言われた、「あなたは園のどの木からでも心のままに取って食べてよろしい。"}, "17": {"en": "but you shall not eat of the tree of the knowledge of good and evil; for in the day that you eat of it, you will surely die.”", "zh": "只是分別善惡樹上的果子，你不可吃，因為你吃的日子必定死！」", "ja": "しかし善悪を知る木からは取って食べてはならない。それを取って食べると、きっと死ぬであろう」。"}, "18": {"en": "The LORD God said, “It is not good for the man to be alone. I will make him a helper comparable to him.”", "zh": "耶和華上帝說：「那人獨居不好，我要為他造一個配偶幫助他。」", "ja": "また主なる神は言われた、「人がひとりでいるのは良くない。彼のために、ふさわしい助け手を造ろう」。"}, "19": {"en": "Out of the ground the LORD God formed every animal of the field, and every bird of the sky, and brought them to the man to see what he would call them. Whatever the man called every living creature became its name.", "zh": "耶和華上帝用土所造成的野地各樣走獸和空中各樣飛鳥都帶到那人面前，看他叫甚麼。那人怎樣叫各樣的活物，那就是牠的名字。", "ja": "そして主なる神は野のすべての獣と、空のすべての鳥とを土で造り、人のところへ連れてきて、彼がそれにどんな名をつけるかを見られた。人がすべて生き物に与える名は、その名となるのであった。"}, "20": {"en": "The man gave names to all livestock, and to the birds of the sky, and to every animal of the field; but for man there was not found a helper comparable to him.", "zh": "那人便給一切牲畜和空中飛鳥、野地走獸都起了名；只是那人沒有遇見配偶幫助他。", "ja": "それで人は、すべての家畜と、空の鳥と、野のすべての獣とに名をつけたが、人にはふさわしい助け手が見つからなかった。"}, "21": {"en": "The LORD God caused the man to fall into a deep sleep. As the man slept, he took one of his ribs, and closed up the flesh in its place.", "zh": "耶和華上帝使他沉睡，他就睡了；於是取下他的一條肋骨，又把肉合起來。", "ja": "そこで主なる神は人を深く眠らせ、眠った時に、そのあばら骨の一つを取って、その所を肉でふさがれた。"}, "22": {"en": "The LORD God made a woman from the rib which he had taken from the man, and brought her to the man.", "zh": "耶和華上帝就用那人身上所取的肋骨造成一個女人，領她到那人跟前。", "ja": "主なる神は人から取ったあばら骨でひとりの女を造り、人のところへ連れてこられた。"}, "23": {"en": "The man said, “This is now bone of my bones, and flesh of my flesh. She will be called ‘woman,’ because she was taken out of Man.”", "zh": "那人說： 這是我骨中的骨， 肉中的肉， 可以稱她為「女人」， 因為她是從「男人」身上取出來的。", "ja": "そのとき、人は言った。「これこそ、ついにわたしの骨の骨、わたしの肉の肉。男から取ったものだから、これを女と名づけよう」。"}, "24": {"en": "Therefore a man will leave his father and his mother, and will join with his wife, and they will be one flesh.", "zh": "因此，人要離開父母，與妻子連合，二人成為一體。", "ja": "それで人はその父と母を離れて、妻と結び合い、一体となるのである。"}, "25": {"en": "The man and his wife were both naked, and they were not ashamed.", "zh": "當時夫妻二人赤身露體，並不羞恥。", "ja": "人とその妻とは、ふたりとも裸であったが、恥ずかしいとは思わなかった。"}}}, "3": {"verses": {"1": {"en": "Now the serpent was more subtle than any animal of the field which the LORD God had made. He said to the woman, “Has God really said, ‘You shall not eat of any tree of the garden’?”", "zh": "耶和華上帝所造的，惟有蛇比田野一切的活物更狡猾。蛇對女人說：「上帝豈是真說不許你們吃園中所有樹上的果子嗎？」", "ja": "さて主なる神が造られた野の生き物のうちで、へびが最も狡猾であった。へびは女に言った、「園にあるどの木からも取って食べるなと、ほんとうに神が言われたのですか」。"}, "2": {"en": "The woman said to the serpent, “We may eat fruit from the trees of the garden,", "zh": "女人對蛇說：「園中樹上的果子，我們可以吃，", "ja": "女はへびに言った、「わたしたちは園の木の実を食べることは許されていますが、"}, "3": {"en": "but not the fruit of the tree which is in the middle of the garden. God has said, ‘You shall not eat of it. You shall not touch it, lest you die.’ ”", "zh": "惟有園當中那棵樹上的果子，上帝曾說：『你們不可吃，也不可摸，免得你們死。』」", "ja": "ただ園の中央にある木の実については、これを取って食べるな、これに触れるな、死んではいけないからと、神は言われました」。"}, "4": {"en": "The serpent said to the woman, “You won’t really die,", "zh": "蛇對女人說：「你們不一定死；", "ja": "へびは女に言った、「あなたがたは決して死ぬことはないでしょう。"}, "5": {"en": "for God knows that in the day you eat it, your eyes will be opened, and you will be like God, knowing good and evil.”", "zh": "因為上帝知道，你們吃的日子眼睛就明亮了，你們便如上帝能知道善惡。」", "ja": "それを食べると、あなたがたの目が開け、神のように善悪を知る者となることを、神は知っておられるのです」。"}, "6": {"en": "When the woman saw that the tree was good for food, and that it was a delight to the eyes, and that the tree was to be desired to make one wise, she took some of its fruit, and ate. Then she gave some to her husband with her, and he ate it, too.", "zh": "於是女人見那棵樹的果子好作食物，也悅人的眼目，且是可喜愛的，能使人有智慧，就摘下果子來吃了，又給她丈夫，她丈夫也吃了。", "ja": "女がその木を見ると、それは食べるに良く、目には美しく、賢くなるには好ましいと思われたから、その実を取って食べ、また共にいた夫にも与えたので、彼も食べた。"}, "7": {"en": "Their eyes were opened, and they both knew that they were naked. They sewed fig leaves together, and made coverings for themselves.", "zh": "他們二人的眼睛就明亮了，才知道自己是赤身露體，便拿無花果樹的葉子為自己編做裙子。", "ja": "すると、ふたりの目が開け、自分たちの裸であることがわかったので、いちじくの葉をつづり合わせて、腰に巻いた。"}, "8": {"en": "They heard the LORD God’s voice walking in the garden in the cool of the day, and the man and his wife hid themselves from the presence of the LORD God among the trees of the garden.", "zh": "天起了涼風，耶和華上帝在園中行走。那人和他妻子聽見上帝的聲音，就藏在園裏的樹木中，躲避耶和華上帝的面。", "ja": "彼らは、日の涼しい風の吹くころ、園の中に主なる神の歩まれる音を聞いた。そこで、人とその妻とは主なる神の顔を避けて、園の木の間に身を隠した。"}, "9": {"en": "The LORD God called to the man, and said to him, “Where are you?”", "zh": "耶和華上帝呼喚那人，對他說：「你在哪裏？」", "ja": "主なる神は人に呼びかけて言われた、「あなたはどこにいるのか」。"}, "10": {"en": "The man said, “I heard your voice in the garden, and I was afraid, because I was naked; so I hid myself.”", "zh": "他說：「我在園中聽見你的聲音，我就害怕；因為我赤身露體，我便藏了。」", "ja": "彼は答えた、「園の中であなたの歩まれる音を聞き、わたしは裸だったので、恐れて身を隠したのです」。"}, "11": {"en": "God said, “Who told you that you were naked? Have you eaten from the tree that I commanded you not to eat from?”", "zh": "耶和華說：「誰告訴你赤身露體呢？莫非你吃了我吩咐你不可吃的那樹上的果子嗎？」", "ja": "神は言われた、「あなたが裸であるのを、だれが知らせたのか。食べるなと、命じておいた木から、あなたは取って食べたのか」。"}, "12": {"en": "The man said, “The woman whom you gave to be with me, she gave me fruit from the tree, and I ate it.”", "zh": "那人說：「你所賜給我、與我同居的女人，她把那樹上的果子給我，我就吃了。」", "ja": "人は答えた、「わたしと一緒にしてくださったあの女が、木から取ってくれたので、わたしは食べたのです」。"}, "13": {"en": "The LORD God said to the woman, “What have you done?” The woman said, “The serpent deceived me, and I ate.”", "zh": "耶和華上帝對女人說：「你做的是甚麼事呢？」女人說：「那蛇引誘我，我就吃了。」", "ja": "そこで主なる神は女に言われた、「あなたは、なんということをしたのです」。女は答えた、「へびがわたしをだましたのです。それでわたしは食べました」。"}, "14": {"en": "The LORD God said to the serpent, “Because you have done this, you are cursed above all livestock, and above every animal of the field. You shall go on your belly and you shall eat dust all the days of your life.", "zh": "耶和華上帝對蛇說： 你既做了這事，就必受咒詛， 比一切的牲畜野獸更甚； 你必用肚子行走， 終身吃土。", "ja": "主なる神はへびに言われた、「おまえは、この事を、したので、すべての家畜、野のすべての獣のうち、最ものろわれる。おまえは腹で、這いあるき、一生、ちりを食べるであろう。"}, "15": {"en": "I will put hostility between you and the woman, and between your offspring and her offspring. He will bruise your head, and you will bruise his heel.”", "zh": "我又要叫你和女人彼此為仇； 你的後裔和女人的後裔也彼此為仇。 女人的後裔要傷你的頭； 你要傷他的腳跟。", "ja": "わたしは恨みをおく、おまえと女とのあいだに、おまえのすえと女のすえとの間に。彼はおまえのかしらを砕き、おまえは彼のかかとを砕くであろう」。"}, "16": {"en": "To the woman he said, “I will greatly multiply your pain in childbirth. You will bear children in pain. Your desire will be for your husband, and he will rule over you.”", "zh": "又對女人說： 我必多多加增你懷胎的苦楚； 你生產兒女必多受苦楚。 你必戀慕你丈夫； 你丈夫必管轄你。", "ja": "つぎに女に言われた、「わたしはあなたの産みの苦しみを大いに増す。あなたは苦しんで子を産む。それでもなお、あなたは夫を慕い、彼はあなたを治めるであろう」。"}, "17": {"en": "To Adam he said, “Because you have listened to your wife’s voice, and have eaten from the tree, about which I commanded you, saying, ‘You shall not eat of it,’ the ground is cursed for your sake. You will eat from it with much labor all the days of your life.", "zh": "又對亞當說： 你既聽從妻子的話， 吃了我所吩咐你不可吃的那樹上的果子， 地必為你的緣故受咒詛； 你必終身勞苦才能從地裏得吃的。", "ja": "更に人に言われた、「あなたが妻の言葉を聞いて、食べるなと、わたしが命じた木から取って食べたので、地はあなたのためにのろわれ、あなたは一生、苦しんで地から食物を取る。"}, "18": {"en": "It will yield thorns and thistles to you; and you will eat the herb of the field.", "zh": "地必給你長出荊棘和蒺藜來； 你也要吃田間的菜蔬。", "ja": "地はあなたのために、いばらとあざみとを生じ、あなたは野の草を食べるであろう。"}, "19": {"en": "You will eat bread by the sweat of your face until you return to the ground, for you were taken out of it. For you are dust, and you shall return to dust.”", "zh": "你必汗流滿面才得糊口， 直到你歸了土， 因為你是從土而出的。 你本是塵土，仍要歸於塵土。", "ja": "あなたは顔に汗してパンを食べ、ついに土に帰る、あなたは土から取られたのだから。あなたは、ちりだから、ちりに帰る」。"}, "20": {"en": "The man called his wife Eve because she would be the mother of all the living.", "zh": "亞當給他妻子起名叫夏娃，因為她是眾生之母。", "ja": "さて、人はその妻の名をエバと名づけた。彼女がすべて生きた者の母だからである。"}, "21": {"en": "The LORD God made garments of animal skins for Adam and for his wife, and clothed them.", "zh": "耶和華上帝為亞當和他妻子用皮子做衣服給他們穿。", "ja": "主なる神は人とその妻とのために皮の着物を造って、彼らに着せられた。"}, "22": {"en": "The LORD God said, “Behold, the man has become like one of us, knowing good and evil. Now, lest he reach out his hand, and also take of the tree of life, and eat, and live forever—”", "zh": "耶和華上帝說：「那人已經與我們相似，能知道善惡；現在恐怕他伸手又摘生命樹的果子吃，就永遠活着。」", "ja": "主なる神は言われた、「見よ、人はわれわれのひとりのようになり、善悪を知るものとなった。彼は手を伸べ、命の木からも取って食べ、永久に生きるかも知れない」。"}, "23": {"en": "Therefore the LORD God sent him out from the garden of Eden, to till the ground from which he was taken.", "zh": "耶和華上帝便打發他出伊甸園去，耕種他所自出之土。", "ja": "そこで主なる神は彼をエデンの園から追い出して、人が造られたその土を耕させられた。"}, "24": {"en": "So he drove out the man; and he placed cherubim at the east of the garden of Eden, and a flaming sword which turned every way, to guard the way to the tree of life.", "zh": "於是把他趕出去了；又在伊甸園的東邊安設基路伯和四面轉動發火焰的劍，要把守生命樹的道路。", "ja": "神は人を追い出し、エデンの園の東に、ケルビムと、回る炎のつるぎとを置いて、命の木の道を守らせられた。"}}}, "4": {"verses": {"1": {"en": "The man knew Eve his wife. She conceived, and gave birth to Cain, and said, “I have gotten a man with the LORD’s help.”", "zh": "有一日，那人和他妻子夏娃同房，夏娃就懷孕，生了該隱，便說：「耶和華使我得了一個男子。」", "ja": "人はその妻エバを知った。彼女はみごもり、カインを産んで言った、「わたしは主によって、ひとりの人を得た」。"}, "2": {"en": "Again she gave birth, to Cain’s brother Abel. Abel was a keeper of sheep, but Cain was a tiller of the ground.", "zh": "又生了該隱的兄弟亞伯。亞伯是牧羊的；該隱是種地的。", "ja": "彼女はまた、その弟アベルを産んだ。アベルは羊を飼う者となり、カインは土を耕す者となった。"}, "3": {"en": "As time passed, Cain brought an offering to the LORD from the fruit of the ground.", "zh": "有一日，該隱拿地裏的出產為供物獻給耶和華；", "ja": "日がたって、カインは地の産物を持ってきて、主に供え物とした。"}, "4": {"en": "Abel also brought some of the firstborn of his flock and of its fat. The LORD respected Abel and his offering,", "zh": "亞伯也將他羊群中頭生的和羊的脂油獻上。耶和華看中了亞伯和他的供物，", "ja": "アベルもまた、その群れのういごと肥えたものとを持ってきた。主はアベルとその供え物とを顧みられた。"}, "5": {"en": "but he didn’t respect Cain and his offering. Cain was very angry, and the expression on his face fell.", "zh": "只是看不中該隱和他的供物。該隱就大大地發怒，變了臉色。", "ja": "しかしカインとその供え物とは顧みられなかったので、カインは大いに憤って、顔を伏せた。"}, "6": {"en": "The LORD said to Cain, “Why are you angry? Why has the expression of your face fallen?", "zh": "耶和華對該隱說：「你為甚麼發怒呢？你為甚麼變了臉色呢？", "ja": "そこで主はカインに言われた、「なぜあなたは憤るのですか、なぜ顔を伏せるのですか。"}, "7": {"en": "If you do well, won’t it be lifted up? If you don’t do well, sin crouches at the door. Its desire is for you, but you are to rule over it.”", "zh": "你若行得好，豈不蒙悅納？你若行得不好，罪就伏在門前。它必戀慕你，你卻要制伏它。」", "ja": "正しい事をしているのでしたら、顔をあげたらよいでしょう。もし正しい事をしていないのでしたら、罪が門口に待ち伏せています。それはあなたを慕い求めますが、あなたはそれを治めなければなりません」。"}, "8": {"en": "Cain said to Abel, his brother, “Let’s go into the field.” While they were in the field, Cain rose up against Abel, his brother, and killed him.", "zh": "該隱與他兄弟亞伯說話；二人正在田間。該隱起來打他兄弟亞伯，把他殺了。", "ja": "カインは弟アベルに言った、「さあ、野原へ行こう」。彼らが野にいたとき、カインは弟アベルに立ちかかって、これを殺した。"}, "9": {"en": "The LORD said to Cain, “Where is Abel, your brother?” He said, “I don’t know. Am I my brother’s keeper?”", "zh": "耶和華對該隱說：「你兄弟亞伯在哪裏？」他說：「我不知道！我豈是看守我兄弟的嗎？」", "ja": "主はカインに言われた、「弟アベルは、どこにいますか」。カインは答えた、「知りません。わたしが弟の番人でしょうか」。"}, "10": {"en": "The LORD said, “What have you done? The voice of your brother’s blood cries to me from the ground.", "zh": "耶和華說：「你做了甚麼事呢？你兄弟的血有聲音從地裏向我哀告。", "ja": "主は言われた、「あなたは何をしたのです。あなたの弟の血の声が土の中からわたしに叫んでいます。"}, "11": {"en": "Now you are cursed because of the ground, which has opened its mouth to receive your brother’s blood from your hand.", "zh": "地開了口，從你手裏接受你兄弟的血。現在你必從這地受咒詛。", "ja": "今あなたはのろわれてこの土地を離れなければなりません。この土地が口をあけて、あなたの手から弟の血を受けたからです。"}, "12": {"en": "From now on, when you till the ground, it won’t yield its strength to you. You will be a fugitive and a wanderer on the earth.”", "zh": "你種地，地不再給你效力；你必流離飄蕩在地上。」", "ja": "あなたが土地を耕しても、土地は、もはやあなたのために実を結びません。あなたは地上の放浪者となるでしょう」。"}, "13": {"en": "Cain said to the LORD, “My punishment is greater than I can bear.", "zh": "該隱對耶和華說：「我的刑罰太重，過於我所能當的。", "ja": "カインは主に言った、「わたしの罰は重くて負いきれません。"}, "14": {"en": "Behold, you have driven me out today from the surface of the ground. I will be hidden from your face, and I will be a fugitive and a wanderer on the earth. Whoever finds me will kill me.”", "zh": "你如今趕逐我離開這地，以致不見你面；我必流離飄蕩在地上，凡遇見我的必殺我。」", "ja": "あなたは、きょう、わたしを地のおもてから追放されました。わたしはあなたを離れて、地上の放浪者とならねばなりません。わたしを見付ける人はだれでもわたしを殺すでしょう」。"}, "15": {"en": "The LORD said to him, “Therefore whoever slays Cain, vengeance will be taken on him sevenfold.” The LORD appointed a sign for Cain, so that anyone finding him would not strike him.", "zh": "耶和華對他說：「凡殺該隱的，必遭報七倍。」耶和華就給該隱立一個記號，免得人遇見他就殺他。", "ja": "主はカインに言われた、「いや、そうではない。だれでもカインを殺す者は七倍の復讐を受けるでしょう」。そして主はカインを見付ける者が、だれも彼を打ち殺すことのないように、彼に一つのしるしをつけられた。"}, "16": {"en": "Cain left the LORD’s presence, and lived in the land of Nod, east of Eden.", "zh": "於是該隱離開耶和華的面，去住在伊甸東邊挪得之地。", "ja": "カインは主の前を去って、エデンの東、ノドの地に住んだ。"}, "17": {"en": "Cain knew his wife. She conceived, and gave birth to Enoch. He built a city, and named the city after the name of his son, Enoch.", "zh": "該隱與妻子同房，他妻子就懷孕，生了以諾。該隱建造了一座城，就按着他兒子的名將那城叫做以諾。", "ja": "カインはその妻を知った。彼女はみごもってエノクを産んだ。カインは町を建て、その町の名をその子の名にしたがって、エノクと名づけた。"}, "18": {"en": "Irad was born to Enoch. Irad became the father of Mehujael. Mehujael became the father of Methushael. Methushael became the father of Lamech.", "zh": "以諾生以拿；以拿生米戶雅利；米戶雅利生瑪土撒利；瑪土撒利生拉麥。", "ja": "エノクにはイラデが生れた。イラデの子はメホヤエル、メホヤエルの子はメトサエル、メトサエルの子はレメクである。"}, "19": {"en": "Lamech took two wives: the name of the first one was Adah, and the name of the second one was Zillah.", "zh": "拉麥娶了兩個妻：一個名叫亞大，一個名叫洗拉。", "ja": "レメクはふたりの妻をめとった。ひとりの名はアダといい、ひとりの名はチラといった。"}, "20": {"en": "Adah gave birth to Jabal, who was the father of those who dwell in tents and have livestock.", "zh": "亞大生雅八；雅八就是住帳棚、牧養牲畜之人的祖師。", "ja": "アダはヤバルを産んだ。彼は天幕に住んで、家畜を飼う者の先祖となった。"}, "21": {"en": "His brother’s name was Jubal, who was the father of all who handle the harp and pipe.", "zh": "雅八的兄弟名叫猶八；他是一切彈琴吹簫之人的祖師。", "ja": "その弟の名はユバルといった。彼は琴や笛を執るすべての者の先祖となった。"}, "22": {"en": "Zillah also gave birth to Tubal Cain, the forger of every cutting instrument of bronze and iron. Tubal Cain’s sister was Naamah.", "zh": "洗拉又生了土八‧該隱；他是打造各樣銅鐵利器的。土八‧該隱的妹子是拿瑪。", "ja": "チラもまたトバルカインを産んだ。彼は青銅や鉄のすべての刃物を鍛える者となった。トバルカインの妹をナアマといった。"}, "23": {"en": "Lamech said to his wives, “Adah and Zillah, hear my voice. You wives of Lamech, listen to my speech, for I have slain a man for wounding me, a young man for bruising me.", "zh": "拉麥對他兩個妻子說： 亞大、洗拉，聽我的聲音； 拉麥的妻子，細聽我的話語： 壯年人傷我，我把他殺了； 少年人損我，我把他害了 。", "ja": "レメクはその妻たちに言った、「アダとチラよ、わたしの声を聞け、レメクの妻たちよ、わたしの言葉に耳を傾けよ。わたしは受ける傷のために、人を殺し、受ける打ち傷のために、わたしは若者を殺す。"}, "24": {"en": "If Cain will be avenged seven times, truly Lamech seventy-seven times.”", "zh": "若殺該隱，遭報七倍， 殺拉麥，必遭報七十七倍。", "ja": "カインのための復讐が七倍ならば、レメクのための復讐は七十七倍」。"}, "25": {"en": "Adam knew his wife again. She gave birth to a son, and named him Seth, saying, “for God has given me another child instead of Abel, for Cain killed him.”", "zh": "亞當又與妻子同房，她就生了一個兒子，起名叫塞特，意思說：「上帝另給我立了一個兒子代替亞伯，因為該隱殺了他。」", "ja": "アダムはまたその妻を知った。彼女は男の子を産み、その名をセツと名づけて言った、「カインがアベルを殺したので、神はアベルの代りに、ひとりの子をわたしに授けられました」。"}, "26": {"en": "A son was also born to Seth, and he named him Enosh. At that time men began to call on the LORD’s name.", "zh": "塞特也生了一個兒子，起名叫以挪士。那時候，人才求告耶和華的名。", "ja": "セツにもまた男の子が生れた。彼はその名をエノスと名づけた。この時、人々は主の名を呼び始めた。"}}}, "5": {"verses": {"1": {"en": "This is the book of the generations of Adam. In the day that God created man, he made him in God’s likeness.", "zh": "亞當的後代記在下面。（當上帝造人的日子，是照着自己的樣式造的，", "ja": "アダムの系図は次のとおりである。神が人を創造された時、神をかたどって造り、"}, "2": {"en": "He created them male and female, and blessed them. On the day they were created, he named them Adam.", "zh": "並且造男造女。在他們被造的日子，上帝賜福給他們，稱他們為「人」。）", "ja": "彼らを男と女とに創造された。彼らが創造された時、神は彼らを祝福して、その名をアダムと名づけられた。"}, "3": {"en": "Adam lived one hundred thirty years, and became the father of a son in his own likeness, after his image, and named him Seth.", "zh": "亞當活到一百三十歲，生了一個兒子，形像樣式和自己相似，就給他起名叫塞特。", "ja": "アダムは百三十歳になって、自分にかたどり、自分のかたちのような男の子を生み、その名をセツと名づけた。"}, "4": {"en": "The days of Adam after he became the father of Seth were eight hundred years, and he became the father of other sons and daughters.", "zh": "亞當生塞特之後，又在世八百年，並且生兒養女。", "ja": "アダムがセツを生んで後、生きた年は八百年であって、ほかに男子と女子を生んだ。"}, "5": {"en": "All the days that Adam lived were nine hundred thirty years, then he died.", "zh": "亞當共活了九百三十歲就死了。", "ja": "アダムの生きた年は合わせて九百三十歳であった。そして彼は死んだ。"}, "6": {"en": "Seth lived one hundred five years, then became the father of Enosh.", "zh": "塞特活到一百零五歲，生了以挪士。", "ja": "セツは百五歳になって、エノスを生んだ。"}, "7": {"en": "Seth lived after he became the father of Enosh eight hundred seven years, and became the father of other sons and daughters.", "zh": "塞特生以挪士之後，又活了八百零七年，並且生兒養女。", "ja": "セツはエノスを生んだ後、八百七年生きて、男子と女子を生んだ。"}, "8": {"en": "All of the days of Seth were nine hundred twelve years, then he died.", "zh": "塞特共活了九百一十二歲就死了。", "ja": "セツの年は合わせて九百十二歳であった。そして彼は死んだ。"}, "9": {"en": "Enosh lived ninety years, and became the father of Kenan.", "zh": "以挪士活到九十歲，生了該南。", "ja": "エノスは九十歳になって、カイナンを生んだ。"}, "10": {"en": "Enosh lived after he became the father of Kenan eight hundred fifteen years, and became the father of other sons and daughters.", "zh": "以挪士生該南之後，又活了八百一十五年，並且生兒養女。", "ja": "エノスはカイナンを生んだ後、八百十五年生きて、男子と女子を生んだ。"}, "11": {"en": "All of the days of Enosh were nine hundred five years, then he died.", "zh": "以挪士共活了九百零五歲就死了。", "ja": "エノスの年は合わせて九百五歳であった。そして彼は死んだ。"}, "12": {"en": "Kenan lived seventy years, then became the father of Mahalalel.", "zh": "該南活到七十歲，生了瑪勒列。", "ja": "カイナンは七十歳になって、マハラレルを生んだ。"}, "13": {"en": "Kenan lived after he became the father of Mahalalel eight hundred forty years, and became the father of other sons and daughters", "zh": "該南生瑪勒列之後，又活了八百四十年，並且生兒養女。", "ja": "カイナンはマハラレルを生んだ後、八百四十年生きて、男子と女子を生んだ。"}, "14": {"en": "and all of the days of Kenan were nine hundred ten years, then he died.", "zh": "該南共活了九百一十歲就死了。", "ja": "カイナンの年は合わせて九百十歳であった。そして彼は死んだ。"}, "15": {"en": "Mahalalel lived sixty-five years, then became the father of Jared.", "zh": "瑪勒列活到六十五歲，生了雅列。", "ja": "マハラレルは六十五歳になって、ヤレドを生んだ。"}, "16": {"en": "Mahalalel lived after he became the father of Jared eight hundred thirty years, and became the father of other sons and daughters.", "zh": "瑪勒列生雅列之後，又活了八百三十年，並且生兒養女。", "ja": "マハラレルはヤレドを生んだ後、八百三十年生きて、男子と女子を生んだ。"}, "17": {"en": "All of the days of Mahalalel were eight hundred ninety-five years, then he died.", "zh": "瑪勒列共活了八百九十五歲就死了。", "ja": "マハラレルの年は合わせて八百九十五歳であった。そして彼は死んだ。"}, "18": {"en": "Jared lived one hundred sixty-two years, then became the father of Enoch.", "zh": "雅列活到一百六十二歲，生了以諾。", "ja": "ヤレドは百六十二歳になって、エノクを生んだ。"}, "19": {"en": "Jared lived after he became the father of Enoch eight hundred years, and became the father of other sons and daughters.", "zh": "雅列生以諾之後，又活了八百年，並且生兒養女。", "ja": "ヤレドはエノクを生んだ後、八百年生きて、男子と女子を生んだ。"}, "20": {"en": "All of the days of Jared were nine hundred sixty-two years, then he died.", "zh": "雅列共活了九百六十二歲就死了。", "ja": "ヤレドの年は合わせて九百六十二歳であった。そして彼は死んだ。"}, "21": {"en": "Enoch lived sixty-five years, then became the father of Methuselah.", "zh": "以諾活到六十五歲，生了瑪土撒拉。", "ja": "エノクは六十五歳になって、メトセラを生んだ。"}, "22": {"en": "After Methuselah’s birth, Enoch walked with God for three hundred years, and became the father of more sons and daughters.", "zh": "以諾生瑪土撒拉之後，與上帝同行三百年，並且生兒養女。", "ja": "エノクはメトセラを生んだ後、三百年、神とともに歩み、男子と女子を生んだ。"}, "23": {"en": "All the days of Enoch were three hundred sixty-five years.", "zh": "以諾共活了三百六十五歲。", "ja": "エノクの年は合わせて三百六十五歳であった。"}, "24": {"en": "Enoch walked with God, and he was not found, for God took him.", "zh": "以諾與上帝同行，上帝將他取去，他就不在世了。", "ja": "エノクは神とともに歩み、神が彼を取られたので、いなくなった。"}, "25": {"en": "Methuselah lived one hundred eighty-seven years, then became the father of Lamech.", "zh": "瑪土撒拉活到一百八十七歲，生了拉麥。", "ja": "メトセラは百八十七歳になって、レメクを生んだ。"}, "26": {"en": "Methuselah lived after he became the father of Lamech seven hundred eighty-two years, and became the father of other sons and daughters.", "zh": "瑪土撒拉生拉麥之後，又活了七百八十二年，並且生兒養女。", "ja": "メトセラはレメクを生んだ後、七百八十二年生きて、男子と女子を生んだ。"}, "27": {"en": "All the days of Methuselah were nine hundred sixty-nine years, then he died.", "zh": "瑪土撒拉共活了九百六十九歲就死了。", "ja": "メトセラの年は合わせて九百六十九歳であった。そして彼は死んだ。"}, "28": {"en": "Lamech lived one hundred eighty-two years, then became the father of a son.", "zh": "拉麥活到一百八十二歲，生了一個兒子，", "ja": "レメクは百八十二歳になって、男の子を生み、"}, "29": {"en": "He named him Noah, saying, “This one will comfort us in our work and in the toil of our hands, caused by the ground which the LORD has cursed.”", "zh": "給他起名叫挪亞，說：「這個兒子必為我們的操作和手中的勞苦安慰我們；這操作勞苦是因為耶和華咒詛地。」", "ja": "「この子こそ、主が地をのろわれたため、骨折り働くわれわれを慰めるもの」と言って、その名をノアと名づけた。"}, "30": {"en": "Lamech lived after he became the father of Noah five hundred ninety-five years, and became the father of other sons and daughters.", "zh": "拉麥生挪亞之後，又活了五百九十五年，並且生兒養女。", "ja": "レメクはノアを生んだ後、五百九十五年生きて、男子と女子を生んだ。"}, "31": {"en": "All the days of Lamech were seven hundred seventy-seven years, then he died.", "zh": "拉麥共活了七百七十七歲就死了。", "ja": "レメクの年は合わせて七百七十七歳であった。そして彼は死んだ。"}, "32": {"en": "Noah was five hundred years old, then Noah became the father of Shem, Ham, and Japheth.", "zh": "挪亞五百歲生了閃、含、雅弗。", "ja": "ノアは五百歳になって、セム、ハム、ヤペテを生んだ。"}}}, "6": {"verses": {"1": {"en": "When men began to multiply on the surface of the ground, and daughters were born to them,", "zh": "當人在世上多起來、又生女兒的時候，", "ja": "人が地のおもてにふえ始めて、娘たちが彼らに生れた時、"}, "2": {"en": "God’s sons saw that men’s daughters were beautiful, and they took any that they wanted for themselves as wives.", "zh": "上帝的兒子們看見人的女子美貌，就隨意挑選，娶來為妻。", "ja": "神の子たちは人の娘たちの美しいのを見て、自分の好む者を妻にめとった。"}, "3": {"en": "The LORD said, “My Spirit will not strive with man forever, because he also is flesh; so his days will be one hundred twenty years.”", "zh": "耶和華說：「人既屬乎血氣，我的靈就不永遠住在他裏面；然而他的日子還可到一百二十年。」", "ja": "そこで主は言われた、「わたしの霊はながく人の中にとどまらない。彼は肉にすぎないのだ。しかし、彼の年は百二十年であろう」。"}, "4": {"en": "The Nephilim were on the earth in those days, and also after that, when God’s sons came in to men’s daughters and had children with them. Those were the mighty men who were of old, men of renown.", "zh": "那時候有偉人在地上，後來上帝的兒子們和人的女子們交合生子；那就是上古英武有名的人。", "ja": "そのころ、またその後にも、地にネピリムがいた。これは神の子たちが人の娘たちのところにはいって、娘たちに産ませたものである。彼らは昔の勇士であり、有名な人々であった。"}, "5": {"en": "The LORD saw that the wickedness of man was great on the earth, and that every imagination of the thoughts of man’s heart was continually only evil.", "zh": "耶和華見人在地上罪惡很大，終日所思想的盡都是惡，", "ja": "主は人の悪が地にはびこり、すべてその心に思いはかることが、いつも悪い事ばかりであるのを見られた。"}, "6": {"en": "The LORD was sorry that he had made man on the earth, and it grieved him in his heart.", "zh": "耶和華就後悔造人在地上，心中憂傷。", "ja": "主は地の上に人を造ったのを悔いて、心を痛め、"}, "7": {"en": "The LORD said, “I will destroy man whom I have created from the surface of the ground—man, along with animals, creeping things, and birds of the sky—for I am sorry that I have made them.”", "zh": "耶和華說：「我要將所造的人和走獸，並昆蟲，以及空中的飛鳥，都從地上除滅，因為我造他們後悔了。」", "ja": "「わたしが創造した人を地のおもてからぬぐい去ろう。人も獣も、這うものも、空の鳥までも。わたしは、これらを造ったことを悔いる」と言われた。"}, "8": {"en": "But Noah found favor in the LORD’s eyes.", "zh": "惟有挪亞在耶和華眼前蒙恩。", "ja": "しかし、ノアは主の前に恵みを得た。"}, "9": {"en": "This is the history of the generations of Noah: Noah was a righteous man, blameless among the people of his time. Noah walked with God.", "zh": "挪亞的後代記在下面。挪亞是個義人，在當時的世代是個完全人。挪亞與上帝同行。", "ja": "ノアの系図は次のとおりである。ノアはその時代の人々の中で正しく、かつ全き人であった。ノアは神とともに歩んだ。"}, "10": {"en": "Noah became the father of three sons: Shem, Ham, and Japheth.", "zh": "挪亞生了三個兒子，就是閃、含、雅弗。", "ja": "ノアはセム、ハム、ヤペテの三人の子を生んだ。"}, "11": {"en": "The earth was corrupt before God, and the earth was filled with violence.", "zh": "世界在上帝面前敗壞，地上滿了強暴。", "ja": "時に世は神の前に乱れて、暴虐が地に満ちた。"}, "12": {"en": "God saw the earth, and saw that it was corrupt, for all flesh had corrupted their way on the earth.", "zh": "上帝觀看世界，見是敗壞了；凡有血氣的人在地上都敗壞了行為。", "ja": "神が地を見られると、それは乱れていた。すべての人が地の上でその道を乱したからである。"}, "13": {"en": "God said to Noah, “I will bring an end to all flesh, for the earth is filled with violence through them. Behold, I will destroy them and the earth.", "zh": "上帝就對挪亞說：「凡有血氣的人，他的盡頭已經來到我面前；因為地上滿了他們的強暴，我要把他們和地一併毀滅。", "ja": "そこで神はノアに言われた、「わたしは、すべての人を絶やそうと決心した。彼らは地を暴虐で満たしたから、わたしは彼らを地とともに滅ぼそう。"}, "14": {"en": "Make a ship of gopher wood. You shall make rooms in the ship, and shall seal it inside and outside with pitch.", "zh": "你要用歌斐木造一隻方舟，分一間一間地造，裏外抹上松香。", "ja": "あなたは、いとすぎの木で箱舟を造り、箱舟の中にへやを設け、アスファルトでそのうちそとを塗りなさい。"}, "15": {"en": "This is how you shall make it. The length of the ship shall be three hundred cubits, its width fifty cubits, and its height thirty cubits.", "zh": "方舟的造法乃是這樣：要長三百肘，寬五十肘，高三十肘。", "ja": "その造り方は次のとおりである。すなわち箱舟の長さは三百キュビト、幅は五十キュビト、高さは三十キュビトとし、"}, "16": {"en": "You shall make a roof in the ship, and you shall finish it to a cubit upward. You shall set the door of the ship in its side. You shall make it with lower, second, and third levels.", "zh": "方舟上邊要留透光處，高一肘。方舟的門要開在旁邊。方舟要分上、中、下三層。", "ja": "箱舟に屋根を造り、上へ一キュビトにそれを仕上げ、また箱舟の戸口をその横に設けて、一階と二階と三階のある箱舟を造りなさい。"}, "17": {"en": "I, even I, will bring the flood of waters on this earth, to destroy all flesh having the breath of life from under the sky. Everything that is on the earth will die.", "zh": "看哪，我要使洪水氾濫在地上，毀滅天下；凡地上有血肉、有氣息的活物，無一不死。", "ja": "わたしは地の上に洪水を送って、命の息のある肉なるものを、みな天の下から滅ぼし去る。地にあるものは、みな死に絶えるであろう。"}, "18": {"en": "But I will establish my covenant with you. You shall come into the ship, you, your sons, your wife, and your sons’ wives with you.", "zh": "我卻要與你立約；你同你的妻，與兒子兒婦，都要進入方舟。", "ja": "ただし、わたしはあなたと契約を結ぼう。あなたは子らと、妻と、子らの妻たちと共に箱舟にはいりなさい。"}, "19": {"en": "Of every living thing of all flesh, you shall bring two of every sort into the ship, to keep them alive with you. They shall be male and female.", "zh": "凡有血肉的活物，每樣兩個，一公一母，你要帶進方舟，好在你那裏保全生命。", "ja": "またすべての生き物、すべての肉なるものの中から、それぞれ二つずつを箱舟に入れて、あなたと共にその命を保たせなさい。それらは雄と雌とでなければならない。"}, "20": {"en": "Of the birds after their kind, of the livestock after their kind, of every creeping thing of the ground after its kind, two of every sort will come to you, to keep them alive.", "zh": "飛鳥各從其類，牲畜各從其類，地上的昆蟲各從其類，每樣兩個，要到你那裏，好保全生命。", "ja": "すなわち、鳥はその種類にしたがい獣はその種類にしたがい、また地のすべての這うものも、その種類にしたがって、それぞれ二つずつ、あなたのところに入れて、命を保たせなさい。"}, "21": {"en": "Take with you some of all food that is eaten, and gather it to yourself; and it will be for food for you, and for them.”", "zh": "你要拿各樣食物積蓄起來，好作你和牠們的食物。」", "ja": "また、すべての食物となるものをとって、あなたのところにたくわえ、あなたとこれらのものとの食物としなさい」。"}, "22": {"en": "Thus Noah did. He did all that God commanded him.", "zh": "挪亞就這樣行。凡上帝所吩咐的，他都照樣行了。", "ja": "ノアはすべて神の命じられたようにした。"}}}, "7": {"verses": {"1": {"en": "The LORD said to Noah, “Come with all of your household into the ship, for I have seen your righteousness before me in this generation.", "zh": "耶和華對挪亞說：「你和你的全家都要進入方舟；因為在這世代中，我見你在我面前是義人。", "ja": "主はノアに言われた、「あなたと家族とはみな箱舟にはいりなさい。あなたがこの時代の人々の中で、わたしの前に正しい人であるとわたしは認めたからである。"}, "2": {"en": "You shall take seven pairs of every clean animal with you, the male and his female. Of the animals that are not clean, take two, the male and his female.", "zh": "凡潔淨的畜類，你要帶七公七母；不潔淨的畜類，你要帶一公一母；", "ja": "あなたはすべての清い獣の中から雄と雌とを七つずつ取り、清くない獣の中から雄と雌とを二つずつ取り、"}, "3": {"en": "Also of the birds of the sky, seven and seven, male and female, to keep seed alive on the surface of all the earth.", "zh": "空中的飛鳥也要帶七公七母，可以留種，活在全地上；", "ja": "また空の鳥の中から雄と雌とを七つずつ取って、その種類が全地のおもてに生き残るようにしなさい。"}, "4": {"en": "In seven days, I will cause it to rain on the earth for forty days and forty nights. I will destroy every living thing that I have made from the surface of the ground.”", "zh": "因為再過七天，我要降雨在地上四十晝夜，把我所造的各種活物都從地上除滅。」", "ja": "七日の後、わたしは四十日四十夜、地に雨を降らせて、わたしの造ったすべての生き物を、地のおもてからぬぐい去ります」。"}, "5": {"en": "Noah did everything that the LORD commanded him.", "zh": "挪亞就遵着耶和華所吩咐的行了。", "ja": "ノアはすべて主が命じられたようにした。"}, "6": {"en": "Noah was six hundred years old when the flood of waters came on the earth.", "zh": "當洪水氾濫在地上的時候，挪亞整六百歲。", "ja": "さて洪水が地に起った時、ノアは六百歳であった。"}, "7": {"en": "Noah went into the ship with his sons, his wife, and his sons’ wives, because of the floodwaters.", "zh": "挪亞就同他的妻和兒子兒婦都進入方舟，躲避洪水。", "ja": "ノアは子らと、妻と、子らの妻たちと共に洪水を避けて箱舟にはいった。"}, "8": {"en": "Clean animals, unclean animals, birds, and everything that creeps on the ground", "zh": "潔淨的畜類和不潔淨的畜類，飛鳥並地上一切的昆蟲，", "ja": "また清い獣と、清くない獣と、鳥と、地に這うすべてのものとの、"}, "9": {"en": "went by pairs to Noah into the ship, male and female, as God commanded Noah.", "zh": "都是一對一對地，有公有母，到挪亞那裏進入方舟，正如上帝所吩咐挪亞的。", "ja": "雄と雌とが、二つずつノアのもとにきて、神がノアに命じられたように箱舟にはいった。"}, "10": {"en": "After the seven days, the floodwaters came on the earth.", "zh": "過了那七天，洪水氾濫在地上。", "ja": "こうして七日の後、洪水が地に起った。"}, "11": {"en": "In the six hundredth year of Noah’s life, in the second month, on the seventeenth day of the month, on that day all the fountains of the great deep burst open, and the sky’s windows opened.", "zh": "當挪亞六百歲，二月十七日那一天，大淵的泉源都裂開了，天上的窗戶也敞開了，", "ja": "それはノアの六百歳の二月十七日であって、その日に大いなる淵の源は、ことごとく破れ、天の窓が開けて、"}, "12": {"en": "It rained on the earth forty days and forty nights.", "zh": "四十晝夜降大雨在地上。", "ja": "雨は四十日四十夜、地に降り注いだ。"}, "13": {"en": "In the same day Noah, and Shem, Ham, and Japheth—the sons of Noah—and Noah’s wife and the three wives of his sons with them, entered into the ship—", "zh": "正當那日，挪亞和他三個兒子閃、含、雅弗，並挪亞的妻子和三個兒婦，都進入方舟。", "ja": "その同じ日に、ノアと、ノアの子セム、ハム、ヤペテと、ノアの妻と、その子らの三人の妻とは共に箱舟にはいった。"}, "14": {"en": "they, and every animal after its kind, all the livestock after their kind, every creeping thing that creeps on the earth after its kind, and every bird after its kind, every bird of every sort.", "zh": "他們和百獸，各從其類，一切牲畜，各從其類，爬在地上的昆蟲，各從其類，一切禽鳥，各從其類，都進入方舟。", "ja": "またすべての種類の獣も、すべての種類の家畜も、地のすべての種類の這うものも、すべての種類の鳥も、すべての翼あるものも、皆はいった。"}, "15": {"en": "Pairs from all flesh with the breath of life in them went into the ship to Noah.", "zh": "凡有血肉、有氣息的活物，都一對一對地到挪亞那裏，進入方舟。", "ja": "すなわち命の息のあるすべての肉なるものが、二つずつノアのもとにきて、箱舟にはいった。"}, "16": {"en": "Those who went in, went in male and female of all flesh, as God commanded him; then the LORD shut him in.", "zh": "凡有血肉進入方舟的，都是有公有母，正如上帝所吩咐挪亞的。耶和華就把他關在方舟裏頭。", "ja": "そのはいったものは、すべて肉なるものの雄と雌とであって、神が彼に命じられたようにはいった。そこで主は彼のうしろの戸を閉ざされた。"}, "17": {"en": "The flood was forty days on the earth. The waters increased, and lifted up the ship, and it was lifted up above the earth.", "zh": "洪水氾濫在地上四十天，水往上長，把方舟從地上漂起。", "ja": "洪水は四十日のあいだ地上にあった。水が増して箱舟を浮べたので、箱舟は地から高く上がった。"}, "18": {"en": "The waters rose, and increased greatly on the earth; and the ship floated on the surface of the waters.", "zh": "水勢浩大，在地上大大地往上長，方舟在水面上漂來漂去。", "ja": "また水がみなぎり、地に増したので、箱舟は水のおもてに漂った。"}, "19": {"en": "The waters rose very high on the earth. All the high mountains that were under the whole sky were covered.", "zh": "水勢在地上極其浩大，天下的高山都淹沒了。", "ja": "水はまた、ますます地にみなぎり、天の下の高い山々は皆おおわれた。"}, "20": {"en": "The waters rose fifteen cubits higher, and the mountains were covered.", "zh": "水勢比山高過十五肘，山嶺都淹沒了。", "ja": "水はその上、さらに十五キュビトみなぎって、山々は全くおおわれた。"}, "21": {"en": "All flesh died that moved on the earth, including birds, livestock, animals, every creeping thing that creeps on the earth, and every man.", "zh": "凡在地上有血肉的動物，就是飛鳥、牲畜、走獸，和爬在地上的昆蟲，以及所有的人，都死了。", "ja": "地の上に動くすべて肉なるものは、鳥も家畜も獣も、地に群がるすべての這うものも、すべての人もみな滅びた。"}, "22": {"en": "All on the dry land, in whose nostrils was the breath of the spirit of life, died.", "zh": "凡在旱地上、鼻孔有氣息的生靈都死了。", "ja": "すなわち鼻に命の息のあるすべてのもの、陸にいたすべてのものは死んだ。"}, "23": {"en": "Every living thing was destroyed that was on the surface of the ground, including man, livestock, creeping things, and birds of the sky. They were destroyed from the earth. Only Noah was left, and those who were with him in the ship.", "zh": "凡地上各類的活物，連人帶牲畜、昆蟲，以及空中的飛鳥，都從地上除滅了，只留下挪亞和那些與他同在方舟裏的。", "ja": "地のおもてにいたすべての生き物は、人も家畜も、這うものも、空の鳥もみな地からぬぐい去られて、ただノアと、彼と共に箱舟にいたものだけが残った。"}, "24": {"en": "The waters flooded the earth one hundred fifty days.", "zh": "水勢浩大，在地上共一百五十天。", "ja": "水は百五十日のあいだ地上にみなぎった。"}}}, "8": {"verses": {"1": {"en": "God remembered Noah, all the animals, and all the livestock that were with him in the ship; and God made a wind to pass over the earth. The waters subsided.", "zh": "上帝記念挪亞和挪亞方舟裏的一切走獸牲畜。上帝叫風吹地，水勢漸落。", "ja": "神はノアと、箱舟の中にいたすべての生き物と、すべての家畜とを心にとめられた。神が風を地の上に吹かせられたので、水は退いた。"}, "2": {"en": "The deep’s fountains and the sky’s windows were also stopped, and the rain from the sky was restrained.", "zh": "淵源和天上的窗戶都閉塞了，天上的大雨也止住了。", "ja": "また淵の源と、天の窓とは閉ざされて、天から雨が降らなくなった。"}, "3": {"en": "The waters continually receded from the earth. After the end of one hundred fifty days the waters receded.", "zh": "水從地上漸退。過了一百五十天，水就漸消。", "ja": "それで水はしだいに地の上から引いて、百五十日の後には水が減り、"}, "4": {"en": "The ship rested in the seventh month, on the seventeenth day of the month, on Ararat’s mountains.", "zh": "七月十七日，方舟停在亞拉臘山上。", "ja": "箱舟は七月十七日にアララテの山にとどまった。"}, "5": {"en": "The waters receded continually until the tenth month. In the tenth month, on the first day of the month, the tops of the mountains were visible.", "zh": "水又漸消，到十月初一日，山頂都現出來了。", "ja": "水はしだいに減って、十月になり、十月一日に山々の頂が現れた。"}, "6": {"en": "At the end of forty days, Noah opened the window of the ship which he had made,", "zh": "過了四十天，挪亞開了方舟的窗戶，", "ja": "四十日たって、ノアはその造った箱舟の窓を開いて、"}, "7": {"en": "and he sent out a raven. It went back and forth, until the waters were dried up from the earth.", "zh": "放出一隻烏鴉去；那烏鴉飛來飛去，直到地上的水都乾了。", "ja": "からすを放ったところ、からすは地の上から水がかわききるまで、あちらこちらへ飛びまわった。"}, "8": {"en": "He himself sent out a dove to see if the waters were abated from the surface of the ground,", "zh": "他又放出一隻鴿子去，要看看水從地上退了沒有。", "ja": "ノアはまた地のおもてから、水がひいたかどうかを見ようと、彼の所から、はとを放ったが、"}, "9": {"en": "but the dove found no place to rest her foot, and she returned into the ship to him, for the waters were on the surface of the whole earth. He put out his hand, and took her, and brought her to him into the ship.", "zh": "但遍地上都是水，鴿子找不着落腳之地，就回到方舟挪亞那裏，挪亞伸手把鴿子接進方舟來。", "ja": "はとは足の裏をとどめる所が見つからなかったので、箱舟のノアのもとに帰ってきた。水がまだ全地のおもてにあったからである。彼は手を伸べて、これを捕え、箱舟の中の彼のもとに引き入れた。"}, "10": {"en": "He waited yet another seven days; and again he sent the dove out of the ship.", "zh": "他又等了七天，再把鴿子從方舟放出去。", "ja": "それから七日待って再びはとを箱舟から放った。"}, "11": {"en": "The dove came back to him at evening and, behold, in her mouth was a freshly plucked olive leaf. So Noah knew that the waters were abated from the earth.", "zh": "到了晚上，鴿子回到他那裏，嘴裏叼着一個新擰下來的橄欖葉子，挪亞就知道地上的水退了。", "ja": "はとは夕方になって彼のもとに帰ってきた。見ると、そのくちばしには、オリブの若葉があった。ノアは地から水がひいたのを知った。"}, "12": {"en": "He waited yet another seven days, and sent out the dove; and she didn’t return to him any more.", "zh": "他又等了七天，放出鴿子去，鴿子就不再回來了。", "ja": "さらに七日待ってまた、はとを放ったところ、もはや彼のもとには帰ってこなかった。"}, "13": {"en": "In the six hundred first year, in the first month, the first day of the month, the waters were dried up from the earth. Noah removed the covering of the ship, and looked. He saw that the surface of the ground was dry.", "zh": "到挪亞六百零一歲，正月初一日，地上的水都乾了。挪亞撤去方舟的蓋觀看，便見地面上乾了。", "ja": "六百一歳の一月一日になって、地の上の水はかれた。ノアが箱舟のおおいを取り除いて見ると、土のおもては、かわいていた。"}, "14": {"en": "In the second month, on the twenty-seventh day of the month, the earth was dry.", "zh": "到了二月二十七日，地就都乾了。", "ja": "二月二十七日になって、地は全くかわいた。"}, "15": {"en": "God spoke to Noah, saying,", "zh": "上帝對挪亞說：", "ja": "この時、神はノアに言われた、"}, "16": {"en": "“Go out of the ship, you, your wife, your sons, and your sons’ wives with you.", "zh": "「你和你的妻子、兒子、兒婦都可以出方舟。", "ja": "「あなたは妻と、子らと、子らの妻たちと共に箱舟を出なさい。"}, "17": {"en": "Bring out with you every living thing that is with you of all flesh, including birds, livestock, and every creeping thing that creeps on the earth, that they may breed abundantly on the earth, and be fruitful, and multiply on the earth.”", "zh": "在你那裏凡有血肉的活物，就是飛鳥、牲畜，和一切爬在地上的昆蟲，都要帶出來，叫牠在地上多多滋生，大大興旺。」", "ja": "あなたは、共にいる肉なるすべての生き物、すなわち鳥と家畜と、地のすべての這うものとを連れて出て、これらのものが地に群がり、地の上にふえ広がるようにしなさい」。"}, "18": {"en": "Noah went out, with his sons, his wife, and his sons’ wives with him.", "zh": "於是挪亞和他的妻子、兒子、兒婦都出來了。", "ja": "ノアは共にいた子らと、妻と、子らの妻たちとを連れて出た。"}, "19": {"en": "Every animal, every creeping thing, and every bird, whatever moves on the earth, after their families, went out of the ship.", "zh": "一切走獸、昆蟲、飛鳥，和地上所有的動物，各從其類，也都出了方舟。", "ja": "またすべての獣、すべての這うもの、すべての鳥、すべて地の上に動くものは皆、種類にしたがって箱舟を出た。"}, "20": {"en": "Noah built an altar to the LORD, and took of every clean animal, and of every clean bird, and offered burnt offerings on the altar.", "zh": "挪亞為耶和華築了一座壇，拿各類潔淨的牲畜、飛鳥獻在壇上為燔祭。", "ja": "ノアは主に祭壇を築いて、すべての清い獣と、すべての清い鳥とのうちから取って、燔祭を祭壇の上にささげた。"}, "21": {"en": "The LORD smelled the pleasant aroma. The LORD said in his heart, “I will not again curse the ground any more for man’s sake because the imagination of man’s heart is evil from his youth. I will never again strike every living thing, as I have done.", "zh": "耶和華聞那馨香之氣，就心裏說：「我不再因人的緣故咒詛地（人從小時心裏懷着惡念），也不再按着我才行的滅各種的活物了。", "ja": "主はその香ばしいかおりをかいで、心に言われた、「わたしはもはや二度と人のゆえに地をのろわない。人が心に思い図ることは、幼い時から悪いからである。わたしは、このたびしたように、もう二度と、すべての生きたものを滅ぼさない。"}, "22": {"en": "While the earth remains, seed time and harvest, and cold and heat, and summer and winter, and day and night will not cease.”", "zh": "地還存留的時候，稼穡、寒暑、冬夏、晝夜就永不停息了。」", "ja": "地のある限り、種まきの時も、刈入れの時も、暑さ寒さも、夏冬も、昼も夜もやむことはないであろう」。"}}}, "9": {"verses": {"1": {"en": "God blessed Noah and his sons, and said to them, “Be fruitful, multiply, and replenish the earth.", "zh": "上帝賜福給挪亞和他的兒子，對他們說：「你們要生養眾多，遍滿了地。", "ja": "神はノアとその子らとを祝福して彼らに言われた、「生めよ、ふえよ、地に満ちよ。"}, "2": {"en": "The fear of you and the dread of you will be on every animal of the earth, and on every bird of the sky. Everything that moves along the ground, and all the fish of the sea, are delivered into your hand.", "zh": "凡地上的走獸和空中的飛鳥都必驚恐，懼怕你們，連地上一切的昆蟲並海裏一切的魚都交付你們的手。", "ja": "地のすべての獣、空のすべての鳥、地に這うすべてのもの、海のすべての魚は恐れおののいて、あなたがたの支配に服し、"}, "3": {"en": "Every moving thing that lives will be food for you. As I gave you the green herb, I have given everything to you.", "zh": "凡活着的動物都可以作你們的食物。這一切我都賜給你們，如同菜蔬一樣。", "ja": "すべて生きて動くものはあなたがたの食物となるであろう。さきに青草をあなたがたに与えたように、わたしはこれらのものを皆あなたがたに与える。"}, "4": {"en": "But flesh with its life, that is, its blood, you shall not eat.", "zh": "惟獨肉帶着血，那就是牠的生命，你們不可吃。", "ja": "しかし肉を、その命である血のままで、食べてはならない。"}, "5": {"en": "I will surely require accounting for your life’s blood. At the hand of every animal I will require it. At the hand of man, even at the hand of every man’s brother, I will require the life of man.", "zh": "流你們血、害你們命的，無論是獸是人，我必討他的罪，就是向各人的弟兄也是如此。", "ja": "あなたがたの命の血を流すものには、わたしは必ず報復するであろう。いかなる獣にも報復する。兄弟である人にも、わたしは人の命のために、報復するであろう。"}, "6": {"en": "Whoever sheds man’s blood, his blood will be shed by man, for God made man in his own image.", "zh": "凡流人血的，他的血也必被人所流，因為上帝造人是照自己的形像造的。", "ja": "人の血を流すものは、人に血を流される、神が自分のかたちに人を造られたゆえに。"}, "7": {"en": "Be fruitful and multiply. Increase abundantly on the earth, and multiply in it.”", "zh": "你們要生養眾多，在地上昌盛繁茂。」", "ja": "あなたがたは、生めよ、ふえよ、地に群がり、地の上にふえよ」。"}, "8": {"en": "God spoke to Noah and to his sons with him, saying,", "zh": "上帝曉諭挪亞和他的兒子說：", "ja": "神はノアおよび共にいる子らに言われた、"}, "9": {"en": "“As for me, behold, I establish my covenant with you, and with your offspring after you,", "zh": "「我與你們和你們的後裔立約，", "ja": "「わたしはあなたがた及びあなたがたの後の子孫と契約を立てる。"}, "10": {"en": "and with every living creature that is with you: the birds, the livestock, and every animal of the earth with you, of all that go out of the ship, even every animal of the earth.", "zh": "並與你們這裏的一切活物－就是飛鳥、牲畜、走獸，凡從方舟裏出來的活物－立約。", "ja": "またあなたがたと共にいるすべての生き物、あなたがたと共にいる鳥、家畜、地のすべての獣、すなわち、すべて箱舟から出たものは、地のすべての獣にいたるまで、わたしはそれと契約を立てよう。"}, "11": {"en": "I will establish my covenant with you: All flesh will not be cut off any more by the waters of the flood. There will never again be a flood to destroy the earth.”", "zh": "我與你們立約，凡有血肉的，不再被洪水滅絕，也不再有洪水毀壞地了。」", "ja": "わたしがあなたがたと立てるこの契約により、すべて肉なる者は、もはや洪水によって滅ぼされることはなく、また地を滅ぼす洪水は、再び起らないであろう」。"}, "12": {"en": "God said, “This is the token of the covenant which I make between me and you and every living creature that is with you, for perpetual generations:", "zh": "上帝說：「我與你們並你們這裏的各樣活物所立的永約是有記號的。", "ja": "さらに神は言われた、「これはわたしと、あなたがた及びあなたがたと共にいるすべての生き物との間に代々かぎりなく、わたしが立てる契約のしるしである。"}, "13": {"en": "I set my rainbow in the cloud, and it will be a sign of a covenant between me and the earth.", "zh": "我把虹放在雲彩中，這就可作我與地立約的記號了。", "ja": "すなわち、わたしは雲の中に、にじを置く。これがわたしと地との間の契約のしるしとなる。"}, "14": {"en": "When I bring a cloud over the earth, that the rainbow will be seen in the cloud,", "zh": "我使雲彩蓋地的時候，必有虹現在雲彩中，", "ja": "わたしが雲を地の上に起すとき、にじは雲の中に現れる。"}, "15": {"en": "I will remember my covenant, which is between me and you and every living creature of all flesh, and the waters will no more become a flood to destroy all flesh.", "zh": "我便記念我與你們和各樣有血肉的活物所立的約，水就再不氾濫、毀壞一切有血肉的物了。", "ja": "こうして、わたしは、わたしとあなたがた、及びすべて肉なるあらゆる生き物との間に立てた契約を思いおこすゆえ、水はふたたび、すべて肉なる者を滅ぼす洪水とはならない。"}, "16": {"en": "The rainbow will be in the cloud. I will look at it, that I may remember the everlasting covenant between God and every living creature of all flesh that is on the earth.”", "zh": "虹必現在雲彩中，我看見，就要記念我與地上各樣有血肉的活物所立的永約。」", "ja": "にじが雲の中に現れるとき、わたしはこれを見て、神が地上にあるすべて肉なるあらゆる生き物との間に立てた永遠の契約を思いおこすであろう」。"}, "17": {"en": "God said to Noah, “This is the token of the covenant which I have established between me and all flesh that is on the earth.”", "zh": "上帝對挪亞說：「這就是我與地上一切有血肉之物立約的記號了。」", "ja": "そして神はノアに言われた、「これがわたしと地にあるすべて肉なるものとの間に、わたしが立てた契約のしるしである」。"}, "18": {"en": "The sons of Noah who went out from the ship were Shem, Ham, and Japheth. Ham is the father of Canaan.", "zh": "出方舟挪亞的兒子就是閃、含、雅弗。含是迦南的父親。", "ja": "箱舟から出たノアの子らはセム、ハム、ヤペテであった。ハムはカナンの父である。"}, "19": {"en": "These three were the sons of Noah, and from these the whole earth was populated.", "zh": "這是挪亞的三個兒子，他們的後裔分散在全地。", "ja": "この三人はノアの子らで、全地の民は彼らから出て、広がったのである。"}, "20": {"en": "Noah began to be a farmer, and planted a vineyard.", "zh": "挪亞作起農夫來，栽了一個葡萄園。", "ja": "さてノアは農夫となり、ぶどう畑をつくり始めたが、"}, "21": {"en": "He drank of the wine and got drunk. He was uncovered within his tent.", "zh": "他喝了園中的酒便醉了，在帳棚裏赤着身子。", "ja": "彼はぶどう酒を飲んで酔い、天幕の中で裸になっていた。"}, "22": {"en": "Ham, the father of Canaan, saw the nakedness of his father, and told his two brothers outside.", "zh": "迦南的父親含看見他父親赤身，就到外邊告訴他兩個弟兄。", "ja": "カナンの父ハムは父の裸を見て、外にいるふたりの兄弟に告げた。"}, "23": {"en": "Shem and Japheth took a garment, and laid it on both their shoulders, went in backwards, and covered the nakedness of their father. Their faces were backwards, and they didn’t see their father’s nakedness.", "zh": "於是閃和雅弗拿件衣服搭在肩上，倒退着進去，給他父親蓋上；他們背着臉就看不見父親的赤身。", "ja": "セムとヤペテとは着物を取って、肩にかけ、うしろ向きに歩み寄って、父の裸をおおい、顔をそむけて父の裸を見なかった。"}, "24": {"en": "Noah awoke from his wine, and knew what his youngest son had done to him.", "zh": "挪亞醒了酒，知道小兒子向他所做的事，", "ja": "やがてノアは酔いがさめて、末の子が彼にした事を知ったとき、"}, "25": {"en": "He said, “Canaan is cursed. He will be a servant of servants to his brothers.”", "zh": "就說： 迦南當受咒詛， 必給他弟兄作奴僕的奴僕；", "ja": "彼は言った、「カナンはのろわれよ。彼はしもべのしもべとなって、その兄弟たちに仕える」。"}, "26": {"en": "He said, “Blessed be the LORD, the God of Shem. Let Canaan be his servant.", "zh": "又說： 耶和華－閃的上帝是應當稱頌的！ 願迦南作閃的奴僕。", "ja": "また言った、「セムの神、主はほむべきかな、カナンはそのしもべとなれ。"}, "27": {"en": "May God enlarge Japheth. Let him dwell in the tents of Shem. Let Canaan be his servant.”", "zh": "願上帝使雅弗擴張， 使他住在閃的帳棚裏； 又願迦南作他的奴僕。", "ja": "神はヤペテを大いならしめ、セムの天幕に彼を住まわせられるように。カナンはそのしもべとなれ」。"}, "28": {"en": "Noah lived three hundred fifty years after the flood.", "zh": "洪水以後，挪亞又活了三百五十年。", "ja": "ノアは洪水の後、なお三百五十年生きた。"}, "29": {"en": "All the days of Noah were nine hundred fifty years, and then he died.", "zh": "挪亞共活了九百五十歲就死了。", "ja": "ノアの年は合わせて九百五十歳であった。そして彼は死んだ。"}}}, "10": {"verses": {"1": {"en": "Now this is the history of the generations of the sons of Noah and of Shem, Ham, and Japheth. Sons were born to them after the flood.", "zh": "挪亞的兒子閃、含、雅弗的後代記在下面。洪水以後，他們都生了兒子。", "ja": "ノアの子セム、ハム、ヤペテの系図は次のとおりである。洪水の後、彼らに子が生れた。"}, "2": {"en": "The sons of Japheth were: Gomer, Magog, Madai, Javan, Tubal, Meshech, and Tiras.", "zh": "雅弗的兒子是歌篾、瑪各、瑪代、雅完、土巴、米設、提拉。", "ja": "ヤペテの子孫はゴメル、マゴグ、マダイ、ヤワン、トバル、メセク、テラスであった。"}, "3": {"en": "The sons of Gomer were: Ashkenaz, Riphath, and Togarmah.", "zh": "歌篾的兒子是亞實基拿、利法、陀迦瑪。", "ja": "ゴメルの子孫はアシケナズ、リパテ、トガルマ。"}, "4": {"en": "The sons of Javan were: Elishah, Tarshish, Kittim, and Dodanim.", "zh": "雅完的兒子是以利沙、他施、基提、多單。", "ja": "ヤワンの子孫はエリシャ、タルシシ、キッテム、ドダニムであった。"}, "5": {"en": "Of these were the islands of the nations divided in their lands, everyone after his language, after their families, in their nations.", "zh": "這些人的後裔將各國的地土、海島分開居住，各隨各的方言、宗族立國。", "ja": "これらから海沿いの地の国民が分れて、おのおのその土地におり、その言語にしたがい、その氏族にしたがって、その国々に住んだ。"}, "6": {"en": "The sons of Ham were: Cush, Mizraim, Put, and Canaan.", "zh": "含的兒子是古實、麥西、弗、迦南。", "ja": "ハムの子孫はクシ、ミツライム、プテ、カナンであった。"}, "7": {"en": "The sons of Cush were: Seba, Havilah, Sabtah, Raamah, and Sabteca. The sons of Raamah were: Sheba and Dedan.", "zh": "古實的兒子是西巴、哈腓拉、撒弗他、拉瑪、撒弗提迦。拉瑪的兒子是示巴、底但。", "ja": "クシの子孫はセバ、ハビラ、サブタ、ラアマ、サブテカであり、ラアマの子孫はシバとデダンであった。"}, "8": {"en": "Cush became the father of Nimrod. He began to be a mighty one on the earth.", "zh": "古實又生寧錄，他為世上英雄之首。", "ja": "クシの子はニムロデであって、このニムロデは世の権力者となった最初の人である。"}, "9": {"en": "He was a mighty hunter before the LORD. Therefore it is said, “like Nimrod, a mighty hunter before the LORD”.", "zh": "他在耶和華面前是個英勇的獵戶，所以俗語說：「像寧錄在耶和華面前是個英勇的獵戶。」", "ja": "彼は主の前に力ある狩猟者であった。これから「主の前に力ある狩猟者ニムロデのごとし」ということわざが起った。"}, "10": {"en": "The beginning of his kingdom was Babel, Erech, Accad, and Calneh, in the land of Shinar.", "zh": "他國的起頭是巴別、以力、亞甲、甲尼，都在示拿地。", "ja": "彼の国は最初シナルの地にあるバベル、エレク、アカデ、カルネであった。"}, "11": {"en": "Out of that land he went into Assyria, and built Nineveh, Rehoboth Ir, Calah,", "zh": "他從那地出來往亞述去，建造尼尼微、利河伯、迦拉，", "ja": "彼はその地からアッスリヤに出て、ニネベ、レホボテイリ、カラ、"}, "12": {"en": "and Resen between Nineveh and the great city Calah.", "zh": "和尼尼微、迦拉中間的利鮮，這就是那大城。", "ja": "およびニネベとカラとの間にある大いなる町レセンを建てた。"}, "13": {"en": "Mizraim became the father of Ludim, Anamim, Lehabim, Naphtuhim,", "zh": "麥西生路低人、亞拿米人、利哈比人、拿弗土希人、", "ja": "ミツライムからルデ族、アナミ族、レハビ族、ナフト族、"}, "14": {"en": "Pathrusim, Casluhim (which the Philistines descended from), and Caphtorim.", "zh": "帕斯魯細人、迦斯路希人、迦斐託人；從迦斐託出來的有非利士人。", "ja": "パテロス族、カスル族、カフトリ族が出た。カフトリ族からペリシテ族が出た。"}, "15": {"en": "Canaan became the father of Sidon (his firstborn), Heth,", "zh": "迦南生長子西頓，又生赫", "ja": "カナンからその長子シドンが出て、またヘテが出た。"}, "16": {"en": "the Jebusites, the Amorites, the Girgashites,", "zh": "和耶布斯人、亞摩利人、革迦撒人、", "ja": "その他エブスびと、アモリびと、ギルガシびと、"}, "17": {"en": "the Hivites, the Arkites, the Sinites,", "zh": "希未人、亞基人、西尼人、", "ja": "ヒビびと、アルキびと、セニびと、"}, "18": {"en": "the Arvadites, the Zemarites, and the Hamathites. Afterward the families of the Canaanites were spread abroad.", "zh": "亞瓦底人、洗瑪利人、哈馬人，後來迦南的諸族分散了。", "ja": "アルワデびと、ゼマリびと、ハマテびとが出た。後になってカナンびとの氏族がひろがった。"}, "19": {"en": "The border of the Canaanites was from Sidon—as you go toward Gerar—to Gaza—as you go toward Sodom, Gomorrah, Admah, and Zeboiim—to Lasha.", "zh": "迦南的境界是從西頓向基拉耳的路上，直到迦薩，又向所多瑪、蛾摩拉、押瑪、洗扁的路上，直到拉沙。", "ja": "カナンびとの境はシドンからゲラルを経てガザに至り、ソドム、ゴモラ、アデマ、ゼボイムを経て、レシャに及んだ。"}, "20": {"en": "These are the sons of Ham, after their families, according to their languages, in their lands and their nations.", "zh": "這就是含的後裔，各隨他們的宗族、方言，所住的地土、邦國。", "ja": "これらはハムの子孫であって、その氏族とその言語とにしたがって、その土地と、その国々にいた。"}, "21": {"en": "Children were also born to Shem (the elder brother of Japheth), the father of all the children of Eber.", "zh": "雅弗的哥哥閃，是希伯子孫之祖，他也生了兒子。", "ja": "セムにも子が生れた。セムはエベルのすべての子孫の先祖であって、ヤペテの兄であった。"}, "22": {"en": "The sons of Shem were: Elam, Asshur, Arpachshad, Lud, and Aram.", "zh": "閃的兒子是以攔、亞述、亞法撒、路德、亞蘭。", "ja": "セムの子孫はエラム、アシュル、アルパクサデ、ルデ、アラムであった。"}, "23": {"en": "The sons of Aram were: Uz, Hul, Gether, and Mash.", "zh": "亞蘭的兒子是烏斯、戶勒、基帖、瑪施。", "ja": "アラムの子孫はウヅ、ホル、ゲテル、マシであった。"}, "24": {"en": "Arpachshad became the father of Shelah. Shelah became the father of Eber.", "zh": "亞法撒生沙拉；沙拉生希伯。", "ja": "アルパクサデの子はシラ、シラの子はエベルである。"}, "25": {"en": "To Eber were born two sons. The name of the one was Peleg, for in his days the earth was divided. His brother’s name was Joktan.", "zh": "希伯生了兩個兒子，一個名叫法勒，因為那時人就分地居住；法勒的兄弟名叫約坍。", "ja": "エベルにふたりの子が生れた。そのひとりの名をペレグといった。これは彼の代に地の民が分れたからである。その弟の名をヨクタンといった。"}, "26": {"en": "Joktan became the father of Almodad, Sheleph, Hazarmaveth, Jerah,", "zh": "約坍生亞摩答、沙列、哈薩瑪非、耶拉、", "ja": "ヨクタンにアルモダデ、シャレフ、ハザルマウテ、エラ、"}, "27": {"en": "Hadoram, Uzal, Diklah,", "zh": "哈多蘭、烏薩、德拉、", "ja": "ハドラム、ウザル、デクラ、"}, "28": {"en": "Obal, Abimael, Sheba,", "zh": "俄巴路、亞比瑪利、示巴、", "ja": "オバル、アビマエル、シバ、"}, "29": {"en": "Ophir, Havilah, and Jobab. All these were the sons of Joktan.", "zh": "阿斐、哈腓拉、約巴，這都是約坍的兒子。", "ja": "オフル、ハビラ、ヨバブが生れた。これらは皆ヨクタンの子であった。"}, "30": {"en": "Their dwelling extended from Mesha, as you go toward Sephar, the mountain of the east.", "zh": "他們所住的地方是從米沙直到西發東邊的山。", "ja": "彼らが住んだ所はメシャから東の山地セパルに及んだ。"}, "31": {"en": "These are the sons of Shem, by their families, according to their languages, lands, and nations.", "zh": "這就是閃的子孫，各隨他們的宗族、方言，所住的地土、邦國。", "ja": "これらはセムの子孫であって、その氏族とその言語とにしたがって、その土地と、その国々にいた。"}, "32": {"en": "These are the families of the sons of Noah, by their generations, according to their nations. The nations divided from these on the earth after the flood.", "zh": "這些都是挪亞三個兒子的宗族，各隨他們的支派立國。洪水以後，他們在地上分為邦國。", "ja": "これらはノアの子らの氏族であって、血統にしたがって国々に住んでいたが、洪水の後、これらから地上の諸国民が分れたのである。"}}}, "11": {"verses": {"1": {"en": "The whole earth was of one language and of one speech.", "zh": "那時，天下人的口音、言語都是一樣。", "ja": "全地は同じ発音、同じ言葉であった。"}, "2": {"en": "As they traveled east, they found a plain in the land of Shinar, and they lived there.", "zh": "他們往東邊遷移的時候，在示拿地遇見一片平原，就住在那裏。", "ja": "時に人々は東に移り、シナルの地に平野を得て、そこに住んだ。"}, "3": {"en": "They said to one another, “Come, let’s make bricks, and burn them thoroughly.” They had brick for stone, and they used tar for mortar.", "zh": "他們彼此商量說：「來吧！我們要做磚，把磚燒透了。」他們就拿磚當石頭，又拿石漆當灰泥。", "ja": "彼らは互に言った、「さあ、れんがを造って、よく焼こう」。こうして彼らは石の代りに、れんがを得、しっくいの代りに、アスファルトを得た。"}, "4": {"en": "They said, “Come, let’s build ourselves a city, and a tower whose top reaches to the sky, and let’s make a name for ourselves, lest we be scattered abroad on the surface of the whole earth.”", "zh": "他們說：「來吧！我們要建造一座城和一座塔，塔頂通天，為要傳揚我們的名，免得我們分散在全地上。」", "ja": "彼らはまた言った、「さあ、町と塔とを建てて、その頂を天に届かせよう。そしてわれわれは名を上げて、全地のおもてに散るのを免れよう」。"}, "5": {"en": "The LORD came down to see the city and the tower, which the children of men built.", "zh": "耶和華降臨，要看看世人所建造的城和塔。", "ja": "時に主は下って、人の子たちの建てる町と塔とを見て、"}, "6": {"en": "The LORD said, “Behold, they are one people, and they all have one language, and this is what they begin to do. Now nothing will be withheld from them, which they intend to do.", "zh": "耶和華說：「看哪，他們成為一樣的人民，都是一樣的言語，如今既做起這事來，以後他們所要做的事就沒有不成就的了。", "ja": "言われた、「民は一つで、みな同じ言葉である。彼らはすでにこの事をしはじめた。彼らがしようとする事は、もはや何事もとどめ得ないであろう。"}, "7": {"en": "Come, let’s go down, and there confuse their language, that they may not understand one another’s speech.”", "zh": "我們下去，在那裏變亂他們的口音，使他們的言語彼此不通。」", "ja": "さあ、われわれは下って行って、そこで彼らの言葉を乱し、互に言葉が通じないようにしよう」。"}, "8": {"en": "So the LORD scattered them abroad from there on the surface of all the earth. They stopped building the city.", "zh": "於是耶和華使他們從那裏分散在全地上；他們就停工，不造那城了。", "ja": "こうして主が彼らをそこから全地のおもてに散らされたので、彼らは町を建てるのをやめた。"}, "9": {"en": "Therefore its name was called Babel, because there the LORD confused the language of all the earth. From there, the LORD scattered them abroad on the surface of all the earth.", "zh": "因為耶和華在那裏變亂天下人的言語，使眾人分散在全地上，所以那城名叫巴別。", "ja": "これによってその町の名はバベルと呼ばれた。主がそこで全地の言葉を乱されたからである。主はそこから彼らを全地のおもてに散らされた。"}, "10": {"en": "This is the history of the generations of Shem: Shem was one hundred years old when he became the father of Arpachshad two years after the flood.", "zh": "閃的後代記在下面。洪水以後二年，閃一百歲生了亞法撒。", "ja": "セムの系図は次のとおりである。セムは百歳になって洪水の二年の後にアルパクサデを生んだ。"}, "11": {"en": "Shem lived five hundred years after he became the father of Arpachshad, and became the father of more sons and daughters.", "zh": "閃生亞法撒之後又活了五百年，並且生兒養女。", "ja": "セムはアルパクサデを生んで後、五百年生きて、男子と女子を生んだ。"}, "12": {"en": "Arpachshad lived thirty-five years and became the father of Shelah.", "zh": "亞法撒活到三十五歲，生了沙拉。", "ja": "アルパクサデは三十五歳になってシラを生んだ。"}, "13": {"en": "Arpachshad lived four hundred three years after he became the father of Shelah, and became the father of more sons and daughters.", "zh": "亞法撒生沙拉之後又活了四百零三年，並且生兒養女。", "ja": "アルパクサデはシラを生んで後、四百三年生きて、男子と女子を生んだ。"}, "14": {"en": "Shelah lived thirty years, and became the father of Eber.", "zh": "沙拉活到三十歲，生了希伯。", "ja": "シラは三十歳になってエベルを生んだ。"}, "15": {"en": "Shelah lived four hundred three years after he became the father of Eber, and became the father of more sons and daughters.", "zh": "沙拉生希伯之後又活了四百零三年，並且生兒養女。", "ja": "シラはエベルを生んで後、四百三年生きて、男子と女子を生んだ。"}, "16": {"en": "Eber lived thirty-four years, and became the father of Peleg.", "zh": "希伯活到三十四歲，生了法勒。", "ja": "エベルは三十四歳になってペレグを生んだ。"}, "17": {"en": "Eber lived four hundred thirty years after he became the father of Peleg, and became the father of more sons and daughters.", "zh": "希伯生法勒之後又活了四百三十年，並且生兒養女。", "ja": "エベルはペレグを生んで後、四百三十年生きて、男子と女子を生んだ。"}, "18": {"en": "Peleg lived thirty years, and became the father of Reu.", "zh": "法勒活到三十歲，生了拉吳。", "ja": "ペレグは三十歳になってリウを生んだ。"}, "19": {"en": "Peleg lived two hundred nine years after he became the father of Reu, and became the father of more sons and daughters.", "zh": "法勒生拉吳之後又活了二百零九年，並且生兒養女。", "ja": "ペレグはリウを生んで後、二百九年生きて、男子と女子を生んだ。"}, "20": {"en": "Reu lived thirty-two years, and became the father of Serug.", "zh": "拉吳活到三十二歲，生了西鹿。", "ja": "リウは三十二歳になってセルグを生んだ。"}, "21": {"en": "Reu lived two hundred seven years after he became the father of Serug, and became the father of more sons and daughters.", "zh": "拉吳生西鹿之後又活了二百零七年，並且生兒養女。", "ja": "リウはセルグを生んで後、二百七年生きて、男子と女子を生んだ。"}, "22": {"en": "Serug lived thirty years, and became the father of Nahor.", "zh": "西鹿活到三十歲，生了拿鶴。", "ja": "セルグは三十歳になってナホルを生んだ。"}, "23": {"en": "Serug lived two hundred years after he became the father of Nahor, and became the father of more sons and daughters.", "zh": "西鹿生拿鶴之後又活了二百年，並且生兒養女。", "ja": "セルグはナホルを生んで後、二百年生きて、男子と女子を生んだ。"}, "24": {"en": "Nahor lived twenty-nine years, and became the father of Terah.", "zh": "拿鶴活到二十九歲，生了他拉。", "ja": "ナホルは二十九歳になってテラを生んだ。"}, "25": {"en": "Nahor lived one hundred nineteen years after he became the father of Terah, and became the father of more sons and daughters.", "zh": "拿鶴生他拉之後又活了一百一十九年，並且生兒養女。", "ja": "ナホルはテラを生んで後、百十九年生きて、男子と女子を生んだ。"}, "26": {"en": "Terah lived seventy years, and became the father of Abram, Nahor, and Haran.", "zh": "他拉活到七十歲，生了亞伯蘭、拿鶴、哈蘭。", "ja": "テラは七十歳になってアブラム、ナホルおよびハランを生んだ。"}, "27": {"en": "Now this is the history of the generations of Terah. Terah became the father of Abram, Nahor, and Haran. Haran became the father of Lot.", "zh": "他拉的後代記在下面。他拉生亞伯蘭、拿鶴、哈蘭；哈蘭生羅得。", "ja": "テラの系図は次のとおりである。テラはアブラム、ナホルおよびハランを生み、ハランはロトを生んだ。"}, "28": {"en": "Haran died in the land of his birth, in Ur of the Chaldees, while his father Terah was still alive.", "zh": "哈蘭死在他的本地迦勒底的吾珥，在他父親他拉之先。", "ja": "ハランは父テラにさきだって、その生れた地、カルデヤのウルで死んだ。"}, "29": {"en": "Abram and Nahor married wives. The name of Abram’s wife was Sarai, and the name of Nahor’s wife was Milcah, the daughter of Haran, who was also the father of Iscah.", "zh": "亞伯蘭、拿鶴各娶了妻：亞伯蘭的妻子名叫撒萊；拿鶴的妻子名叫密迦，是哈蘭的女兒；哈蘭是密迦和亦迦的父親。", "ja": "アブラムとナホルは妻をめとった。アブラムの妻の名はサライといい、ナホルの妻の名はミルカといってハランの娘である。ハランはミルカの父、またイスカの父である。"}, "30": {"en": "Sarai was barren. She had no child.", "zh": "撒萊不生育，沒有孩子。", "ja": "サライはうまずめで、子がなかった。"}, "31": {"en": "Terah took Abram his son, Lot the son of Haran, his son’s son, and Sarai his daughter-in-law, his son Abram’s wife. They went from Ur of the Chaldees, to go into the land of Canaan. They came to Haran and lived there.", "zh": "他拉帶着他兒子亞伯蘭和他孫子哈蘭的兒子羅得，並他兒婦亞伯蘭的妻子撒萊，出了迦勒底的吾珥，要往迦南地去；他們走到哈蘭，就住在那裏。", "ja": "テラはその子アブラムと、ハランの子である孫ロトと、子アブラムの妻である嫁サライとを連れて、カナンの地へ行こうとカルデヤのウルを出たが、ハランに着いてそこに住んだ。"}, "32": {"en": "The days of Terah were two hundred five years. Terah died in Haran.", "zh": "他拉共活了二百零五歲，就死在哈蘭。", "ja": "テラの年は二百五歳であった。テラはハランで死んだ。"}}}, "12": {"verses": {"1": {"en": "Now the LORD said to Abram, “Leave your country, and your relatives, and your father’s house, and go to the land that I will show you.", "zh": "耶和華對亞伯蘭說：「你要離開本地、本族、父家，往我所要指示你的地去。", "ja": "時に主はアブラムに言われた、「あなたは国を出て、親族に別れ、父の家を離れ、わたしが示す地に行きなさい。"}, "2": {"en": "I will make of you a great nation. I will bless you and make your name great. You will be a blessing.", "zh": "我必叫你成為大國。我必賜福給你，叫你的名為大；你也要叫別人得福。", "ja": "わたしはあなたを大いなる国民とし、あなたを祝福し、あなたの名を大きくしよう。あなたは祝福の基となるであろう。"}, "3": {"en": "I will bless those who bless you, and I will curse him who treats you with contempt. All the families of the earth will be blessed through you.”", "zh": "為你祝福的，我必賜福與他；那咒詛你的，我必咒詛他。地上的萬族都要因你得福。」", "ja": "あなたを祝福する者をわたしは祝福し、あなたをのろう者をわたしはのろう。地のすべてのやからは、あなたによって祝福される」。"}, "4": {"en": "So Abram went, as the LORD had told him. Lot went with him. Abram was seventy-five years old when he departed from Haran.", "zh": "亞伯蘭就照着耶和華的吩咐去了；羅得也和他同去。亞伯蘭出哈蘭的時候年七十五歲。", "ja": "アブラムは主が言われたようにいで立った。ロトも彼と共に行った。アブラムはハランを出たとき七十五歳であった。"}, "5": {"en": "Abram took Sarai his wife, Lot his brother’s son, all their possessions that they had gathered, and the people whom they had acquired in Haran, and they went to go into the land of Canaan. They entered into the land of Canaan.", "zh": "亞伯蘭將他妻子撒萊和姪兒羅得，連他們在哈蘭所積蓄的財物、所得的人口，都帶往迦南地去。他們就到了迦南地。", "ja": "アブラムは妻サライと、弟の子ロトと、集めたすべての財産と、ハランで獲た人々とを携えてカナンに行こうとしていで立ち、カナンの地にきた。"}, "6": {"en": "Abram passed through the land to the place of Shechem, to the oak of Moreh. At that time, Canaanites were in the land.", "zh": "亞伯蘭經過那地，到了示劍地方、摩利橡樹那裏。那時迦南人住在那地。", "ja": "アブラムはその地を通ってシケムの所、モレのテレビンの木のもとに着いた。そのころカナンびとがその地にいた。"}, "7": {"en": "The LORD appeared to Abram and said, “I will give this land to your offspring.”", "zh": "耶和華向亞伯蘭顯現，說：「我要把這地賜給你的後裔。」亞伯蘭就在那裏為向他顯現的耶和華築了一座壇。", "ja": "時に主はアブラムに現れて言われた、「わたしはあなたの子孫にこの地を与えます」。アブラムは彼に現れた主のために、そこに祭壇を築いた。"}, "8": {"en": "He built an altar there to the LORD, who had appeared to him.   He left from there to go to the mountain on the east of Bethel and pitched his tent, having Bethel on the west, and Ai on the east. There he built an altar to the LORD and called on the LORD’s name.", "zh": "從那裏他又遷到伯特利東邊的山，支搭帳棚；西邊是伯特利，東邊是艾。他在那裏又為耶和華築了一座壇，求告耶和華的名。", "ja": "彼はそこからベテルの東の山に移って天幕を張った。西にはベテル、東にはアイがあった。そこに彼は主のために祭壇を築いて、主の名を呼んだ。"}, "9": {"en": "Abram traveled, still going on toward the South.", "zh": "後來亞伯蘭又漸漸遷往南地去。", "ja": "アブラムはなお進んでネゲブに移った。"}, "10": {"en": "There was a famine in the land. Abram went down into Egypt to live as a foreigner there, for the famine was severe in the land.", "zh": "那地遭遇饑荒。因饑荒甚大，亞伯蘭就下埃及去，要在那裏暫居。", "ja": "さて、その地にききんがあったのでアブラムはエジプトに寄留しようと、そこに下った。ききんがその地に激しかったからである。"}, "11": {"en": "When he had come near to enter Egypt, he said to Sarai his wife, “See now, I know that you are a beautiful woman to look at.", "zh": "將近埃及，就對他妻子撒萊說：「我知道你是容貌俊美的婦人。", "ja": "エジプトにはいろうとして、そこに近づいたとき、彼は妻サライに言った、「わたしはあなたが美しい女であるのを知っています。"}, "12": {"en": "It will happen that when the Egyptians see you, they will say, ‘This is his wife.’ They will kill me, but they will save you alive.", "zh": "埃及人看見你必說：『這是他的妻子』，他們就要殺我，卻叫你存活。", "ja": "それでエジプトびとがあなたを見る時、これは彼の妻であると言ってわたしを殺し、あなたを生かしておくでしょう。"}, "13": {"en": "Please say that you are my sister, that it may be well with me for your sake, and that my soul may live because of you.”", "zh": "求你說，你是我的妹子，使我因你得平安，我的命也因你存活。」", "ja": "どうかあなたは、わたしの妹だと言ってください。そうすればわたしはあなたのおかげで無事であり、わたしの命はあなたによって助かるでしょう」。"}, "14": {"en": "When Abram had come into Egypt, some Egyptians saw that the woman was very beautiful.", "zh": "及至亞伯蘭到了埃及，埃及人看見那婦人極其美貌。", "ja": "アブラムがエジプトにはいった時エジプトびとはこの女を見て、たいそう美しい人であるとし、"}, "15": {"en": "The princes of Pharaoh saw her, and praised her to Pharaoh; and the woman was taken into Pharaoh’s house.", "zh": "法老的臣宰看見了她，就在法老面前誇獎她。那婦人就被帶進法老的宮去。", "ja": "またパロの高官たちも彼女を見てパロの前でほめたので、女はパロの家に召し入れられた。"}, "16": {"en": "He dealt well with Abram for her sake. He had sheep, cattle, male donkeys, male servants, female servants, female donkeys, and camels.", "zh": "法老因這婦人就厚待亞伯蘭，亞伯蘭得了許多牛、羊、駱駝、公驢、母驢、僕婢。", "ja": "パロは彼女のゆえにアブラムを厚くもてなしたので、アブラムは多くの羊、牛、雌雄のろば、男女の奴隷および、らくだを得た。"}, "17": {"en": "The LORD afflicted Pharaoh and his house with great plagues because of Sarai, Abram’s wife.", "zh": "耶和華因亞伯蘭妻子撒萊的緣故，降大災與法老和他的全家。", "ja": "ところで主はアブラムの妻サライのゆえに、激しい疫病をパロとその家に下された。"}, "18": {"en": "Pharaoh called Abram and said, “What is this that you have done to me? Why didn’t you tell me that she was your wife?", "zh": "法老就召了亞伯蘭來，說：「你這向我做的是甚麼事呢？為甚麼沒有告訴我她是你的妻子？", "ja": "パロはアブラムを召し寄せて言った、「あなたはわたしになんという事をしたのですか。なぜ彼女が妻であるのをわたしに告げなかったのですか。"}, "19": {"en": "Why did you say, ‘She is my sister,’ so that I took her to be my wife? Now therefore, see your wife, take her, and go your way.”", "zh": "為甚麼說她是你的妹子，以致我把她取來要作我的妻子？現在你的妻子在這裏，可以帶她走吧。」", "ja": "あなたはなぜ、彼女はわたしの妹ですと言ったのですか。わたしは彼女を妻にしようとしていました。さあ、あなたの妻はここにいます。連れて行ってください」。"}, "20": {"en": "Pharaoh commanded men concerning him, and they escorted him away with his wife and all that he had.", "zh": "於是法老吩咐人將亞伯蘭和他妻子，並他所有的都送走了。", "ja": "パロは彼の事について人々に命じ、彼とその妻およびそのすべての持ち物を送り去らせた。"}}}, "13": {"verses": {"1": {"en": "Abram went up out of Egypt—he, his wife, all that he had, and Lot with him—into the South.", "zh": "亞伯蘭帶着他的妻子與羅得，並一切所有的，都從埃及上南地去。", "ja": "アブラムは妻とすべての持ち物を携え、エジプトを出て、ネゲブに上った。ロトも彼と共に上った。"}, "2": {"en": "Abram was very rich in livestock, in silver, and in gold.", "zh": "亞伯蘭的金、銀、牲畜極多。", "ja": "アブラムは家畜と金銀に非常に富んでいた。"}, "3": {"en": "He went on his journeys from the South as far as Bethel, to the place where his tent had been at the beginning, between Bethel and Ai,", "zh": "他從南地漸漸往伯特利去，到了伯特利和艾的中間，就是從前支搭帳棚的地方，", "ja": "彼はネゲブから旅路を進めてベテルに向かい、ベテルとアイの間の、さきに天幕を張った所に行った。"}, "4": {"en": "to the place of the altar, which he had made there at the first. There Abram called on the LORD’s name.", "zh": "也是他起先築壇的地方；他又在那裏求告耶和華的名。", "ja": "すなわち彼が初めに築いた祭壇の所に行き、その所でアブラムは主の名を呼んだ。"}, "5": {"en": "Lot also, who went with Abram, had flocks, herds, and tents.", "zh": "與亞伯蘭同行的羅得也有牛群、羊群、帳棚。", "ja": "アブラムと共に行ったロトも羊、牛および天幕を持っていた。"}, "6": {"en": "The land was not able to bear them, that they might live together; for their possessions were so great that they couldn’t live together.", "zh": "那地容不下他們；因為他們的財物甚多，使他們不能同居。", "ja": "その地は彼らをささえて共に住ませることができなかった。彼らの財産が多かったため、共に住めなかったのである。"}, "7": {"en": "There was strife between the herdsmen of Abram’s livestock and the herdsmen of Lot’s livestock. The Canaanites and the Perizzites lived in the land at that time.", "zh": "當時，迦南人與比利洗人在那地居住。亞伯蘭的牧人和羅得的牧人相爭。", "ja": "アブラムの家畜の牧者たちとロトの家畜の牧者たちの間に争いがあった。そのころカナンびととペリジびとがその地に住んでいた。"}, "8": {"en": "Abram said to Lot, “Please, let there be no strife between you and me, and between your herdsmen and my herdsmen; for we are relatives.", "zh": "亞伯蘭就對羅得說：「你我不可相爭，你的牧人和我的牧人也不可相爭，因為我們是骨肉。", "ja": "アブラムはロトに言った、「わたしたちは身内の者です。わたしとあなたの間にも、わたしの牧者たちとあなたの牧者たちの間にも争いがないようにしましょう。"}, "9": {"en": "Isn’t the whole land before you? Please separate yourself from me. If you go to the left hand, then I will go to the right. Or if you go to the right hand, then I will go to the left.”", "zh": "遍地不都在你眼前嗎？請你離開我：你向左，我就向右；你向右，我就向左。」", "ja": "全地はあなたの前にあるではありませんか。どうかわたしと別れてください。あなたが左に行けばわたしは右に行きます。あなたが右に行けばわたしは左に行きましょう」。"}, "10": {"en": "Lot lifted up his eyes, and saw all the plain of the Jordan, that it was well-watered everywhere, before the LORD destroyed Sodom and Gomorrah, like the garden of the LORD, like the land of Egypt, as you go to Zoar.", "zh": "羅得舉目看見約旦河的全平原，直到瑣珥，都是滋潤的，那地在耶和華未滅所多瑪、蛾摩拉以先如同耶和華的園子，也像埃及地。", "ja": "ロトが目を上げてヨルダンの低地をあまねく見わたすと、主がソドムとゴモラを滅ぼされる前であったから、ゾアルまで主の園のように、またエジプトの地のように、すみずみまでよく潤っていた。"}, "11": {"en": "So Lot chose the Plain of the Jordan for himself. Lot traveled east, and they separated themselves from one another.", "zh": "於是羅得選擇約旦河的全平原，往東遷移；他們就彼此分離了。", "ja": "そこでロトはヨルダンの低地をことごとく選びとって東に移った。こうして彼らは互に別れた。"}, "12": {"en": "Abram lived in the land of Canaan, and Lot lived in the cities of the plain, and moved his tent as far as Sodom.", "zh": "亞伯蘭住在迦南地，羅得住在平原的城邑，漸漸挪移帳棚，直到所多瑪。", "ja": "アブラムはカナンの地に住んだが、ロトは低地の町々に住み、天幕をソドムに移した。"}, "13": {"en": "Now the men of Sodom were exceedingly wicked and sinners against the LORD.", "zh": "所多瑪人在耶和華面前罪大惡極。", "ja": "ソドムの人々はわるく、主に対して、はなはだしい罪びとであった。"}, "14": {"en": "The LORD said to Abram, after Lot was separated from him, “Now, lift up your eyes, and look from the place where you are, northward and southward and eastward and westward,", "zh": "羅得離別亞伯蘭以後，耶和華對亞伯蘭說：「從你所在的地方，你舉目向東西南北觀看；", "ja": "ロトがアブラムに別れた後に、主はアブラムに言われた、「目をあげてあなたのいる所から北、南、東、西を見わたしなさい。"}, "15": {"en": "for I will give all the land which you see to you and to your offspring forever.", "zh": "凡你所看見的一切地，我都要賜給你和你的後裔，直到永遠。", "ja": "すべてあなたが見わたす地は、永久にあなたとあなたの子孫に与えます。"}, "16": {"en": "I will make your offspring as the dust of the earth, so that if a man can count the dust of the earth, then your offspring may also be counted.", "zh": "我也要使你的後裔如同地上的塵沙那樣多，人若能數算地上的塵沙才能數算你的後裔。", "ja": "わたしはあなたの子孫を地のちりのように多くします。もし人が地のちりを数えることができるなら、あなたの子孫も数えられることができましょう。"}, "17": {"en": "Arise, walk through the land in its length and in its width; for I will give it to you.”", "zh": "你起來，縱橫走遍這地，因為我必把這地賜給你。」", "ja": "あなたは立って、その地をたてよこに行き巡りなさい。わたしはそれをあなたに与えます」。"}, "18": {"en": "Abram moved his tent, and came and lived by the oaks of Mamre, which are in Hebron, and built an altar there to the LORD.", "zh": "亞伯蘭就搬了帳棚，來到希伯崙幔利的橡樹那裏居住，在那裏為耶和華築了一座壇。", "ja": "アブラムは天幕を移してヘブロンにあるマムレのテレビンの木のかたわらに住み、その所で主に祭壇を築いた。"}}}, "14": {"verses": {"1": {"en": "In the days of Amraphel, king of Shinar; Arioch, king of Ellasar; Chedorlaomer, king of Elam; and Tidal, king of Goiim,", "zh": "當暗拉非作示拿王，亞略作以拉撒王，基大老瑪作以攔王，提達作戈印王的時候，", "ja": "シナルの王アムラペル、エラサルの王アリオク、エラムの王ケダラオメルおよびゴイムの王テダルの世に、"}, "2": {"en": "they made war with Bera, king of Sodom; Birsha, king of Gomorrah; Shinab, king of Admah; Shemeber, king of Zeboiim; and the king of Bela (also called Zoar).", "zh": "他們都攻打所多瑪王比拉、蛾摩拉王比沙、押瑪王示納、洗扁王善以別，和比拉王；比拉就是瑣珥。", "ja": "これらの王はソドムの王ベラ、ゴモラの王ビルシャ、アデマの王シナブ、ゼボイムの王セメベル、およびベラすなわちゾアルの王と戦った。"}, "3": {"en": "All these joined together in the valley of Siddim (also called the Salt Sea).", "zh": "這五王都在西訂谷會合；西訂谷就是鹽海。", "ja": "これら五人の王はみな同盟してシデムの谷、すなわち塩の海に向かって行った。"}, "4": {"en": "They served Chedorlaomer for twelve years, and in the thirteenth year they rebelled.", "zh": "他們已經事奉基大老瑪十二年，到十三年就背叛了。", "ja": "すなわち彼らは十二年の間ケダラオメルに仕えたが、十三年目にそむいたので、"}, "5": {"en": "In the fourteenth year Chedorlaomer and the kings who were with him came and struck the Rephaim in Ashteroth Karnaim, the Zuzim in Ham, the Emim in Shaveh Kiriathaim,", "zh": "十四年，基大老瑪和同盟的王都來在亞特律‧加寧，殺敗了利乏音人，在哈麥殺敗了蘇西人，在沙微‧基列亭殺敗了以米人，", "ja": "十四年目にケダラオメルは彼と連合した王たちと共にきて、アシタロテ・カルナイムでレパイムびとを、ハムでズジびとを、シャベ・キリアタイムでエミびとを撃ち、"}, "6": {"en": "and the Horites in their Mount Seir, to El Paran, which is by the wilderness.", "zh": "在何利人的西珥山殺敗了何利人，一直殺到靠近曠野的伊勒‧巴蘭。", "ja": "セイルの山地でホリびとを撃って、荒野のほとりにあるエル・パランに及んだ。"}, "7": {"en": "They returned, and came to En Mishpat (also called Kadesh), and struck all the country of the Amalekites, and also the Amorites, that lived in Hazazon Tamar.", "zh": "他們回到安‧密巴，就是加低斯，殺敗了亞瑪力全地的人，以及住在哈洗遜‧他瑪的亞摩利人。", "ja": "彼らは引き返してエン・ミシパテすなわちカデシへ行って、アマレクびとの国をことごとく撃ち、またハザゾン・タマルに住むアモリびとをも撃った。"}, "8": {"en": "The king of Sodom, and the king of Gomorrah, the king of Admah, the king of Zeboiim, and the king of Bela (also called Zoar) went out; and they set the battle in array against them in the valley of Siddim", "zh": "於是所多瑪王、蛾摩拉王、押瑪王、洗扁王，和比拉王（比拉就是瑣珥）都出來，在西訂谷擺陣，與他們交戰，", "ja": "そこでソドムの王、ゴモラの王、アデマの王、ゼボイムの王およびベラすなわちゾアルの王は出てシデムの谷で彼らに向かい、戦いの陣をしいた。"}, "9": {"en": "against Chedorlaomer king of Elam, Tidal king of Goiim, Amraphel king of Shinar, and Arioch king of Ellasar; four kings against the five.", "zh": "就是與以攔王基大老瑪、戈印王提達、示拿王暗拉非、以拉撒王亞略交戰；乃是四王與五王交戰。", "ja": "すなわちエラムの王ケダラオメル、ゴイムの王テダル、シナルの王アムラペル、エラサルの王アリオクの四人の王に対する五人の王であった。"}, "10": {"en": "Now the valley of Siddim was full of tar pits; and the kings of Sodom and Gomorrah fled, and some fell there. Those who remained fled to the hills.", "zh": "西訂谷有許多石漆坑。所多瑪王和蛾摩拉王逃跑，有掉在坑裏的，其餘的人都往山上逃跑。", "ja": "シデムの谷にはアスファルトの穴が多かったので、ソドムの王とゴモラの王は逃げてそこに落ちたが、残りの者は山にのがれた。"}, "11": {"en": "They took all the goods of Sodom and Gomorrah, and all their food, and went their way.", "zh": "四王就把所多瑪和蛾摩拉所有的財物，並一切的糧食都擄掠去了；", "ja": "そこで彼らはソドムとゴモラの財産と食料とをことごとく奪って去り、"}, "12": {"en": "They took Lot, Abram’s brother’s son, who lived in Sodom, and his goods, and departed.", "zh": "又把亞伯蘭的姪兒羅得和羅得的財物擄掠去了。當時羅得正住在所多瑪。", "ja": "またソドムに住んでいたアブラムの弟の子ロトとその財産を奪って去った。"}, "13": {"en": "One who had escaped came and told Abram, the Hebrew. At that time, he lived by the oaks of Mamre, the Amorite, brother of Eshcol and brother of Aner. They were allies of Abram.", "zh": "有一個逃出來的人告訴希伯來人亞伯蘭；亞伯蘭正住在亞摩利人幔利的橡樹那裏。幔利和以實各並亞乃都是弟兄，曾與亞伯蘭聯盟。", "ja": "時に、ひとりの人がのがれてきて、ヘブルびとアブラムに告げた。この時アブラムはエシコルの兄弟、またアネルの兄弟であるアモリびとマムレのテレビンの木のかたわらに住んでいた。彼らはアブラムと同盟していた。"}, "14": {"en": "When Abram heard that his relative was taken captive, he led out his three hundred eighteen trained men, born in his house, and pursued as far as Dan.", "zh": "亞伯蘭聽見他姪兒被擄去，就率領他家裏生養的精練壯丁三百一十八人，直追到但，", "ja": "アブラムは身内の者が捕虜になったのを聞き、訓練した家の子三百十八人を引き連れてダンまで追って行き、"}, "15": {"en": "He divided himself against them by night, he and his servants, and struck them, and pursued them to Hobah, which is on the left hand of Damascus.", "zh": "便在夜間，自己同僕人分隊殺敗敵人，又追到大馬士革左邊的何把，", "ja": "そのしもべたちを分けて、夜かれらを攻め、これを撃ってダマスコの北、ホバまで彼らを追った。"}, "16": {"en": "He brought back all the goods, and also brought back his relative Lot and his goods, and the women also, and the other people.", "zh": "將被擄掠的一切財物奪回來，連他姪兒羅得和他的財物，以及婦女、人民也都奪回來。", "ja": "そして彼はすべての財産を取り返し、また身内の者ロトとその財産および女たちと民とを取り返した。"}, "17": {"en": "The king of Sodom went out to meet him after his return from the slaughter of Chedorlaomer and the kings who were with him, at the valley of Shaveh (that is, the King’s Valley).", "zh": "亞伯蘭殺敗基大老瑪和與他同盟的王回來的時候，所多瑪王出來，在沙微谷迎接他；沙微谷就是王谷。", "ja": "アブラムがケダラオメルとその連合の王たちを撃ち破って帰った時、ソドムの王はシャベの谷、すなわち王の谷に出て彼を迎えた。"}, "18": {"en": "Melchizedek king of Salem brought out bread and wine. He was priest of God Most High.", "zh": "又有撒冷王麥基洗德帶着餅和酒出來迎接；他是至高上帝的祭司。", "ja": "その時、サレムの王メルキゼデクはパンとぶどう酒とを持ってきた。彼はいと高き神の祭司である。"}, "19": {"en": "He blessed him, and said, “Blessed be Abram of God Most High, possessor of heaven and earth.", "zh": "他為亞伯蘭祝福，說：「願天地的主、至高的上帝賜福與亞伯蘭！", "ja": "彼はアブラムを祝福して言った、「願わくは天地の主なるいと高き神が、アブラムを祝福されるように。"}, "20": {"en": "Blessed be God Most High, who has delivered your enemies into your hand.” Abram gave him a tenth of all.", "zh": "至高的上帝把敵人交在你手裏，是應當稱頌的！」亞伯蘭就把所得的拿出十分之一來，給麥基洗德。", "ja": "願わくはあなたの敵をあなたの手に渡されたいと高き神があがめられるように」。アブラムは彼にすべての物の十分の一を贈った。"}, "21": {"en": "The king of Sodom said to Abram, “Give me the people, and take the goods for yourself.”", "zh": "所多瑪王對亞伯蘭說：「你把人口給我，財物你自己拿去吧！」", "ja": "時にソドムの王はアブラムに言った、「わたしには人をください。財産はあなたが取りなさい」。"}, "22": {"en": "Abram said to the king of Sodom, “I have lifted up my hand to the LORD, God Most High, possessor of heaven and earth,", "zh": "亞伯蘭對所多瑪王說：「我已經向天地的主－至高的上帝耶和華起誓：", "ja": "アブラムはソドムの王に言った、「天地の主なるいと高き神、主に手をあげて、わたしは誓います。"}, "23": {"en": "that I will not take a thread nor a sandal strap nor anything that is yours, lest you should say, ‘I have made Abram rich.’", "zh": "凡是你的東西，就是一根線、一根鞋帶，我都不拿，免得你說：『我使亞伯蘭富足！』", "ja": "わたしは糸一本でも、くつひも一本でも、あなたのものは何にも受けません。アブラムを富ませたのはわたしだと、あなたが言わないように。"}, "24": {"en": "I will accept nothing from you except that which the young men have eaten, and the portion of the men who went with me: Aner, Eshcol, and Mamre. Let them take their portion.”", "zh": "只有僕人所吃的，並與我同行的亞乃、以實各、幔利所應得的分，可以任憑他們拿去。」", "ja": "ただし若者たちがすでに食べた物は別です。そしてわたしと共に行った人々アネルとエシコルとマムレとにはその分を取らせなさい」。"}}}, "15": {"verses": {"1": {"en": "After these things the LORD’s word came to Abram in a vision, saying, “Don’t be afraid, Abram. I am your shield, your exceedingly great reward.”", "zh": "這事以後，耶和華在異象中有話對亞伯蘭說：「亞伯蘭，你不要懼怕！我是你的盾牌，必大大地賞賜你。」", "ja": "これらの事の後、主の言葉が幻のうちにアブラムに臨んだ、「アブラムよ恐れてはならない、わたしはあなたの盾である。あなたの受ける報いは、はなはだ大きいであろう」。"}, "2": {"en": "Abram said, “Lord GOD, what will you give me, since I go childless, and he who will inherit my estate is Eliezer of Damascus?”", "zh": "亞伯蘭說：「主耶和華啊，我既無子，你還賜我甚麼呢？並且要承受我家業的是大馬士革人以利以謝。」", "ja": "アブラムは言った、「主なる神よ、わたしには子がなく、わたしの家を継ぐ者はダマスコのエリエゼルであるのに、あなたはわたしに何をくださろうとするのですか」。"}, "3": {"en": "Abram said, “Behold, you have given no children to me: and, behold, one born in my house is my heir.”", "zh": "亞伯蘭又說：「你沒有給我兒子；那生在我家中的人就是我的後嗣。」", "ja": "アブラムはまた言った、「あなたはわたしに子を賜わらないので、わたしの家に生れたしもべが、あとつぎとなるでしょう」。"}, "4": {"en": "Behold, the LORD’s word came to him, saying, “This man will not be your heir, but he who will come out of your own body will be your heir.”", "zh": "耶和華又有話對他說：「這人必不成為你的後嗣；你本身所生的才成為你的後嗣。」", "ja": "この時、主の言葉が彼に臨んだ、「この者はあなたのあとつぎとなるべきではありません。あなたの身から出る者があとつぎとなるべきです」。"}, "5": {"en": "The LORD brought him outside, and said, “Look now toward the sky, and count the stars, if you are able to count them.” He said to Abram, “So your offspring will be.”", "zh": "於是領他走到外邊，說：「你向天觀看，數算眾星，能數得過來嗎？」又對他說：「你的後裔將要如此。」", "ja": "そして主は彼を外に連れ出して言われた、「天を仰いで、星を数えることができるなら、数えてみなさい」。また彼に言われた、「あなたの子孫はあのようになるでしょう」。"}, "6": {"en": "He believed in the LORD, who credited it to him for righteousness.", "zh": "亞伯蘭信耶和華，耶和華就以此為他的義。", "ja": "アブラムは主を信じた。主はこれを彼の義と認められた。"}, "7": {"en": "He said to Abram, “I am the LORD who brought you out of Ur of the Chaldees, to give you this land to inherit it.”", "zh": "耶和華又對他說：「我是耶和華，曾領你出了迦勒底的吾珥，為要將這地賜你為業。」", "ja": "また主は彼に言われた、「わたしはこの地をあなたに与えて、これを継がせようと、あなたをカルデヤのウルから導き出した主です」。"}, "8": {"en": "He said, “Lord GOD, how will I know that I will inherit it?”", "zh": "亞伯蘭說：「主耶和華啊，我怎能知道必得這地為業呢？」", "ja": "彼は言った、「主なる神よ、わたしがこれを継ぐのをどうして知ることができますか」。"}, "9": {"en": "He said to him, “Bring me a heifer three years old, a female goat three years old, a ram three years old, a turtledove, and a young pigeon.”", "zh": "他說：「你為我取一隻三年的母牛，一隻三年的母山羊，一隻三年的公綿羊，一隻斑鳩，一隻雛鴿。」", "ja": "主は彼に言われた、「三歳の雌牛と、三歳の雌やぎと、三歳の雄羊と、山ばとと、家ばとのひなとをわたしの所に連れてきなさい」。"}, "10": {"en": "He brought him all these, and divided them in the middle, and laid each half opposite the other; but he didn’t divide the birds.", "zh": "亞伯蘭就取了這些來，每樣劈開，分成兩半，一半對着一半地擺列，只有鳥沒有劈開。", "ja": "彼はこれらをみな連れてきて、二つに裂き、裂いたものを互に向かい合わせて置いた。ただし、鳥は裂かなかった。"}, "11": {"en": "The birds of prey came down on the carcasses, and Abram drove them away.", "zh": "有鷙鳥下來，落在那死畜的肉上，亞伯蘭就把牠嚇飛了。", "ja": "荒い鳥が死体の上に降りるとき、アブラムはこれを追い払った。"}, "12": {"en": "When the sun was going down, a deep sleep fell on Abram. Now terror and great darkness fell on him.", "zh": "日頭正落的時候，亞伯蘭沉沉地睡了；忽然有驚人的大黑暗落在他身上。", "ja": "日の入るころ、アブラムが深い眠りにおそわれた時、大きな恐ろしい暗やみが彼に臨んだ。"}, "13": {"en": "He said to Abram, “Know for sure that your offspring will live as foreigners in a land that is not theirs, and will serve them. They will afflict them four hundred years.", "zh": "耶和華對亞伯蘭說：「你要的確知道，你的後裔必寄居別人的地，又服事那地的人；那地的人要苦待他們四百年。", "ja": "時に主はアブラムに言われた、「あなたはよく心にとめておきなさい。あなたの子孫は他の国に旅びととなって、その人々に仕え、その人々は彼らを四百年の間、悩ますでしょう。"}, "14": {"en": "I will also judge that nation, whom they will serve. Afterward they will come out with great wealth;", "zh": "並且他們所要服事的那國，我要懲罰，後來他們必帶着許多財物從那裏出來。", "ja": "しかし、わたしは彼らが仕えたその国民をさばきます。その後かれらは多くの財産を携えて出て来るでしょう。"}, "15": {"en": "but you will go to your fathers in peace. You will be buried at a good old age.", "zh": "但你要享大壽數，平平安安地歸到你列祖那裏，被人埋葬。", "ja": "あなたは安らかに先祖のもとに行きます。そして高齢に達して葬られるでしょう。"}, "16": {"en": "In the fourth generation they will come here again, for the iniquity of the Amorite is not yet full.”", "zh": "到了第四代，他們必回到此地，因為亞摩利人的罪孽還沒有滿盈。」", "ja": "四代目になって彼らはここに帰って来るでしょう。アモリびとの悪がまだ満ちないからです」。"}, "17": {"en": "It came to pass that, when the sun went down, and it was dark, behold, a smoking furnace and a flaming torch passed between these pieces.", "zh": "日落天黑，不料有冒煙的爐並燒着的火把從那些肉塊中經過。", "ja": "やがて日は入り、暗やみになった時、煙の立つかまど、炎の出るたいまつが、裂いたものの間を通り過ぎた。"}, "18": {"en": "In that day the LORD made a covenant with Abram, saying, “I have given this land to your offspring, from the river of Egypt to the great river, the river Euphrates:", "zh": "當那日，耶和華與亞伯蘭立約，說：「我已賜給你的後裔，從埃及河直到幼發拉底大河之地，", "ja": "その日、主はアブラムと契約を結んで言われた、「わたしはこの地をあなたの子孫に与える。エジプトの川から、かの大川ユフラテまで。"}, "19": {"en": "the land of the Kenites, the Kenizzites, the Kadmonites,", "zh": "就是基尼人、基尼洗人、甲摩尼人、", "ja": "すなわちケニびと、ケニジびと、カドモニびと、"}, "20": {"en": "the Hittites, the Perizzites, the Rephaim,", "zh": "赫人、比利洗人、利乏音人、", "ja": "ヘテびと、ペリジびと、レパイムびと、"}, "21": {"en": "the Amorites, the Canaanites, the Girgashites, and the Jebusites.”", "zh": "亞摩利人、迦南人、革迦撒人、耶布斯人之地。」", "ja": "アモリびと、カナンびと、ギルガシびと、エブスびとの地を与える」。"}}}, "16": {"verses": {"1": {"en": "Now Sarai, Abram’s wife, bore him no children. She had a servant, an Egyptian, whose name was Hagar.", "zh": "亞伯蘭的妻子撒萊不給他生兒女。撒萊有一個使女，名叫夏甲，是埃及人。", "ja": "アブラムの妻サライは子を産まなかった。彼女にひとりのつかえめがあった。エジプトの女で名をハガルといった。"}, "2": {"en": "Sarai said to Abram, “See now, the LORD has restrained me from bearing. Please go in to my servant. It may be that I will obtain children by her.” Abram listened to the voice of Sarai.", "zh": "撒萊對亞伯蘭說：「耶和華使我不能生育。求你和我的使女同房，或者我可以因她得孩子。」亞伯蘭聽從了撒萊的話。", "ja": "サライはアブラムに言った、「主はわたしに子をお授けになりません。どうぞ、わたしのつかえめの所におはいりください。彼女によってわたしは子をもつことになるでしょう」。アブラムはサライの言葉を聞きいれた。"}, "3": {"en": "Sarai, Abram’s wife, took Hagar the Egyptian, her servant, after Abram had lived ten years in the land of Canaan, and gave her to Abram her husband to be his wife.", "zh": "於是亞伯蘭的妻子撒萊將使女埃及人夏甲給了丈夫為妾；那時亞伯蘭在迦南已經住了十年。", "ja": "アブラムの妻サライはそのつかえめエジプトの女ハガルをとって、夫アブラムに妻として与えた。これはアブラムがカナンの地に十年住んだ後であった。"}, "4": {"en": "He went in to Hagar, and she conceived. When she saw that she had conceived, her mistress was despised in her eyes.", "zh": "亞伯蘭與夏甲同房，夏甲就懷了孕；她見自己有孕，就小看她的主母。", "ja": "彼はハガルの所にはいり、ハガルは子をはらんだ。彼女は自分のはらんだのを見て、女主人を見下げるようになった。"}, "5": {"en": "Sarai said to Abram, “This wrong is your fault. I gave my servant into your bosom, and when she saw that she had conceived, she despised me. May the LORD judge between me and you.”", "zh": "撒萊對亞伯蘭說：「我因你受屈。我將我的使女放在你懷中，她見自己有了孕，就小看我。願耶和華在你我中間判斷。」", "ja": "そこでサライはアブラムに言った、「わたしが受けた害はあなたの責任です。わたしのつかえめをあなたのふところに与えたのに、彼女は自分のはらんだのを見て、わたしを見下さげます。どうか、主があなたとわたしの間をおさばきになるように」。"}, "6": {"en": "But Abram said to Sarai, “Behold, your maid is in your hand. Do to her whatever is good in your eyes.” Sarai dealt harshly with her, and she fled from her face.", "zh": "亞伯蘭對撒萊說：「使女在你手下，你可以隨意待她。」撒萊苦待她，她就從撒萊面前逃走了。", "ja": "アブラムはサライに言った、「あなたのつかえめはあなたの手のうちにある。あなたの好きなように彼女にしなさい」。そしてサライが彼女を苦しめたので、彼女はサライの顔を避けて逃げた。"}, "7": {"en": "The LORD’s angel found her by a fountain of water in the wilderness, by the fountain on the way to Shur.", "zh": "耶和華的使者在曠野書珥路上的水泉旁遇見她，", "ja": "主の使は荒野にある泉のほとり、すなわちシュルの道にある泉のほとりで、彼女に会い、"}, "8": {"en": "He said, “Hagar, Sarai’s servant, where did you come from? Where are you going?” She said, “I am fleeing from the face of my mistress Sarai.”", "zh": "對她說：「撒萊的使女夏甲，你從哪裏來？要往哪裏去？」夏甲說：「我從我的主母撒萊面前逃出來。」", "ja": "そして言った、「サライのつかえめハガルよ、あなたはどこからきたのですか、またどこへ行くのですか」。彼女は言った、「わたしは女主人サライの顔を避けて逃げているのです」。"}, "9": {"en": "The LORD’s angel said to her, “Return to your mistress, and submit yourself under her hands.”", "zh": "耶和華的使者對她說：「你回到你主母那裏，服在她手下」；", "ja": "主の使は彼女に言った、「あなたは女主人のもとに帰って、その手に身を任せなさい」。"}, "10": {"en": "The LORD’s angel said to her, “I will greatly multiply your offspring, that they will not be counted for multitude.”", "zh": "又說：「我必使你的後裔極其繁多，甚至不可勝數」；", "ja": "主の使はまた彼女に言った、「わたしは大いにあなたの子孫を増して、数えきれないほどに多くしましょう」。"}, "11": {"en": "The LORD’s angel said to her, “Behold, you are with child, and will bear a son. You shall call his name Ishmael, because the LORD has heard your affliction.", "zh": "並說：「你如今懷孕要生一個兒子，可以給他起名叫以實瑪利，因為耶和華聽見了你的苦情。", "ja": "主の使はまた彼女に言った、「あなたは、みごもっています。あなたは男の子を産むでしょう。名をイシマエルと名づけなさい。主があなたの苦しみを聞かれたのです。"}, "12": {"en": "He will be like a wild donkey among men. His hand will be against every man, and every man’s hand against him. He will live opposed to all of his brothers.”", "zh": "他為人必像野驢。他的手要攻打人，人的手也要攻打他；他必住在眾弟兄的東邊。」", "ja": "彼は野ろばのような人となり、その手はすべての人に逆らい、すべての人の手は彼に逆らい、彼はすべての兄弟に敵して住むでしょう」。"}, "13": {"en": "She called the name of the LORD who spoke to her, “You are a God who sees,” for she said, “Have I even stayed alive after seeing him?”", "zh": "夏甲就稱那對她說話的耶和華為「看顧人的上帝」。因而說：「在這裏我也看見那看顧我的嗎？」", "ja": "そこで、ハガルは自分に語られた主の名を呼んで、「あなたはエル・ロイです」と言った。彼女が「ここでも、わたしを見ていられるかたのうしろを拝めたのか」と言ったことによる。"}, "14": {"en": "Therefore the well was called Beer Lahai Roi. Behold, it is between Kadesh and Bered.", "zh": "所以這井名叫庇耳‧拉海‧萊。這井正在加低斯和巴列中間。", "ja": "それでその井戸は「ベエル・ラハイ・ロイ」と呼ばれた。これはカデシとベレデの間にある。"}, "15": {"en": "Hagar bore a son for Abram. Abram called the name of his son, whom Hagar bore, Ishmael.", "zh": "後來夏甲給亞伯蘭生了一個兒子；亞伯蘭給他起名叫以實瑪利。", "ja": "ハガルはアブラムに男の子を産んだ。アブラムはハガルが産んだ子の名をイシマエルと名づけた。"}, "16": {"en": "Abram was eighty-six years old when Hagar bore Ishmael to Abram.", "zh": "夏甲給亞伯蘭生以實瑪利的時候，亞伯蘭年八十六歲。", "ja": "ハガルがイシマエルをアブラムに産んだ時、アブラムは八十六歳であった。"}}}, "17": {"verses": {"1": {"en": "When Abram was ninety-nine years old, the LORD appeared to Abram and said to him, “I am God Almighty. Walk before me and be blameless.", "zh": "亞伯蘭年九十九歲的時候，耶和華向他顯現，對他說：「我是全能的上帝。你當在我面前作完全人，", "ja": "アブラムの九十九歳の時、主はアブラムに現れて言われた、「わたしは全能の神である。あなたはわたしの前に歩み、全き者であれ。"}, "2": {"en": "I will make my covenant between me and you, and will multiply you exceedingly.”", "zh": "我就與你立約，使你的後裔極其繁多。」", "ja": "わたしはあなたと契約を結び、大いにあなたの子孫を増すであろう」。"}, "3": {"en": "Abram fell on his face. God talked with him, saying,", "zh": "亞伯蘭俯伏在地；上帝又對他說：", "ja": "アブラムは、ひれ伏した。神はまた彼に言われた、"}, "4": {"en": "“As for me, behold, my covenant is with you. You will be the father of a multitude of nations.", "zh": "「我與你立約：你要作多國的父。", "ja": "「わたしはあなたと契約を結ぶ。あなたは多くの国民の父となるであろう。"}, "5": {"en": "Your name will no more be called Abram, but your name will be Abraham; for I have made you the father of a multitude of nations.", "zh": "從此以後，你的名不再叫亞伯蘭，要叫亞伯拉罕，因為我已立你作多國的父。", "ja": "あなたの名は、もはやアブラムとは言われず、あなたの名はアブラハムと呼ばれるであろう。わたしはあなたを多くの国民の父とするからである。"}, "6": {"en": "I will make you exceedingly fruitful, and I will make nations of you. Kings will come out of you.", "zh": "我必使你的後裔極其繁多；國度從你而立，君王從你而出。", "ja": "わたしはあなたに多くの子孫を得させ、国々の民をあなたから起そう。また、王たちもあなたから出るであろう。"}, "7": {"en": "I will establish my covenant between me and you and your offspring after you throughout their generations for an everlasting covenant, to be a God to you and to your offspring after you.", "zh": "我要與你並你世世代代的後裔堅立我的約，作永遠的約，是要作你和你後裔的上帝。", "ja": "わたしはあなた及び後の代々の子孫と契約を立てて、永遠の契約とし、あなたと後の子孫との神となるであろう。"}, "8": {"en": "I will give to you, and to your offspring after you, the land where you are traveling, all the land of Canaan, for an everlasting possession. I will be their God.”", "zh": "我要將你現在寄居的地，就是迦南全地，賜給你和你的後裔永遠為業，我也必作他們的上帝。」", "ja": "わたしはあなたと後の子孫とにあなたの宿っているこの地、すなわちカナンの全地を永久の所有として与える。そしてわたしは彼らの神となるであろう」。"}, "9": {"en": "God said to Abraham, “As for you, you shall keep my covenant, you and your offspring after you throughout their generations.", "zh": "上帝又對亞伯拉罕說：「你和你的後裔必世世代代遵守我的約。", "ja": "神はまたアブラハムに言われた、「あなたと後の子孫とは共に代々わたしの契約を守らなければならない。あなたがたのうち"}, "10": {"en": "This is my covenant, which you shall keep, between me and you and your offspring after you. Every male among you shall be circumcised.", "zh": "你們所有的男子都要受割禮；這就是我與你並你的後裔所立的約，是你們所當遵守的。", "ja": "男子はみな割礼をうけなければならない。これはわたしとあなたがた及び後の子孫との間のわたしの契約であって、あなたがたの守るべきものである。"}, "11": {"en": "You shall be circumcised in the flesh of your foreskin. It will be a token of the covenant between me and you.", "zh": "你們都要受割禮；這是我與你們立約的證據。", "ja": "あなたがたは前の皮に割礼を受けなければならない。それがわたしとあなたがたとの間の契約のしるしとなるであろう。"}, "12": {"en": "He who is eight days old shall be circumcised among you, every male throughout your generations, he who is born in the house, or bought with money from any foreigner who is not of your offspring.", "zh": "你們世世代代的男子，無論是家裏生的，是在你後裔之外用銀子從外人買的，生下來第八日，都要受割禮。", "ja": "あなたがたのうちの男子はみな代々、家に生れた者も、また異邦人から銀で買い取った、あなたの子孫でない者も、生れて八日目に割礼を受けなければならない。"}, "13": {"en": "He who is born in your house, and he who is bought with your money, must be circumcised. My covenant shall be in your flesh for an everlasting covenant.", "zh": "你家裏生的和你用銀子買的，都必須受割禮。這樣，我的約就立在你們肉體上作永遠的約。", "ja": "あなたの家に生れた者も、あなたが銀で買い取った者も必ず割礼を受けなければならない。こうしてわたしの契約はあなたがたの身にあって永遠の契約となるであろう。"}, "14": {"en": "The uncircumcised male who is not circumcised in the flesh of his foreskin, that soul shall be cut off from his people. He has broken my covenant.”", "zh": "但不受割禮的男子必從民中剪除，因他背了我的約。」", "ja": "割礼を受けない男子、すなわち前の皮を切らない者はわたしの契約を破るゆえ、その人は民のうちから断たれるであろう」。"}, "15": {"en": "God said to Abraham, “As for Sarai your wife, you shall not call her name Sarai, but her name shall be Sarah.", "zh": "上帝又對亞伯拉罕說：「你的妻子撒萊不可再叫撒萊，她的名要叫撒拉。", "ja": "神はまたアブラハムに言われた、「あなたの妻サライは、もはや名をサライといわず、名をサラと言いなさい。"}, "16": {"en": "I will bless her, and moreover I will give you a son by her. Yes, I will bless her, and she will be a mother of nations. Kings of peoples will come from her.”", "zh": "我必賜福給她，也要使你從她得一個兒子。我要賜福給她，她也要作多國之母；必有百姓的君王從她而出。」", "ja": "わたしは彼女を祝福し、また彼女によって、あなたにひとりの男の子を授けよう。わたしは彼女を祝福し、彼女を国々の民の母としよう。彼女から、もろもろの民の王たちが出るであろう」。"}, "17": {"en": "Then Abraham fell on his face, and laughed, and said in his heart, “Will a child be born to him who is one hundred years old? Will Sarah, who is ninety years old, give birth?”", "zh": "亞伯拉罕就俯伏在地喜笑，心裏說：「一百歲的人還能得孩子嗎？撒拉已經九十歲了，還能生養嗎？」", "ja": "アブラハムはひれ伏して笑い、心の中で言った、「百歳の者にどうして子が生れよう。サラはまた九十歳にもなって、どうして産むことができようか」。"}, "18": {"en": "Abraham said to God, “Oh that Ishmael might live before you!”", "zh": "亞伯拉罕對上帝說：「但願以實瑪利活在你面前。」", "ja": "そしてアブラハムは神に言った、「どうかイシマエルがあなたの前に生きながらえますように」。"}, "19": {"en": "God said, “No, but Sarah, your wife, will bear you a son. You shall call his name Isaac. I will establish my covenant with him for an everlasting covenant for his offspring after him.", "zh": "上帝說：「不然，你妻子撒拉要給你生一個兒子，你要給他起名叫以撒。我要與他堅定所立的約，作他後裔永遠的約。", "ja": "神は言われた、「いや、あなたの妻サラはあなたに男の子を産むでしょう。名をイサクと名づけなさい。わたしは彼と契約を立てて、後の子孫のために永遠の契約としよう。"}, "20": {"en": "As for Ishmael, I have heard you. Behold, I have blessed him, and will make him fruitful, and will multiply him exceedingly. He will become the father of twelve princes, and I will make him a great nation.", "zh": "至於以實瑪利，我也應允你：我必賜福給他，使他昌盛，極其繁多。他必生十二個族長；我也要使他成為大國。", "ja": "またイシマエルについてはあなたの願いを聞いた。わたしは彼を祝福して多くの子孫を得させ、大いにそれを増すであろう。彼は十二人の君たちを生むであろう。わたしは彼を大いなる国民としよう。"}, "21": {"en": "But I will establish my covenant with Isaac, whom Sarah will bear to you at this set time next year.”", "zh": "到明年這時節，撒拉必給你生以撒，我要與他堅定所立的約。」", "ja": "しかしわたしは来年の今ごろサラがあなたに産むイサクと、わたしの契約を立てるであろう」。"}, "22": {"en": "When he finished talking with him, God went up from Abraham.", "zh": "上帝和亞伯拉罕說完了話，就離開他上升去了。", "ja": "神はアブラハムと語り終え、彼を離れて、のぼられた。"}, "23": {"en": "Abraham took Ishmael his son, all who were born in his house, and all who were bought with his money: every male among the men of Abraham’s house, and circumcised the flesh of their foreskin in the same day, as God had said to him.", "zh": "正當那日，亞伯拉罕遵着上帝的命，給他的兒子以實瑪利和家裏的一切男子，無論是在家裏生的，是用銀子買的，都行了割禮。", "ja": "アブラハムは神が自分に言われたように、この日その子イシマエルと、すべて家に生れた者およびすべて銀で買い取った者、すなわちアブラハムの家の人々のうち、すべての男子を連れてきて、前の皮に割礼を施した。"}, "24": {"en": "Abraham was ninety-nine years old when he was circumcised in the flesh of his foreskin.", "zh": "亞伯拉罕受割禮的時候年九十九歲。", "ja": "アブラハムが前の皮に割礼を受けた時は九十九歳、"}, "25": {"en": "Ishmael, his son, was thirteen years old when he was circumcised in the flesh of his foreskin.", "zh": "他兒子以實瑪利受割禮的時候年十三歲。", "ja": "その子イシマエルが前の皮に割礼を受けた時は十三歳であった。"}, "26": {"en": "In the same day both Abraham and Ishmael, his son, were circumcised.", "zh": "正當那日，亞伯拉罕和他兒子以實瑪利一同受了割禮。", "ja": "この日アブラハムとその子イシマエルは割礼を受けた。"}, "27": {"en": "All the men of his house, those born in the house, and those bought with money from a foreigner, were circumcised with him.", "zh": "家裏所有的人，無論是在家裏生的，是用銀子從外人買的，也都一同受了割禮。", "ja": "またその家の人々は家に生れた者も、銀で異邦人から買い取った者も皆、彼と共に割礼を受けた。"}}}, "18": {"verses": {"1": {"en": "The LORD appeared to him by the oaks of Mamre, as he sat in the tent door in the heat of the day.", "zh": "耶和華在幔利橡樹那裏向亞伯拉罕顯現出來。那時正熱，亞伯拉罕坐在帳棚門口，", "ja": "主はマムレのテレビンの木のかたわらでアブラハムに現れられた。それは昼の暑いころで、彼は天幕の入口にすわっていたが、"}, "2": {"en": "He lifted up his eyes and looked, and saw that three men stood near him. When he saw them, he ran to meet them from the tent door, and bowed himself to the earth,", "zh": "舉目觀看，見有三個人在對面站着。他一見，就從帳棚門口跑去迎接他們，俯伏在地，", "ja": "目を上げて見ると、三人の人が彼に向かって立っていた。彼はこれを見て、天幕の入口から走って行って彼らを迎え、地に身をかがめて、"}, "3": {"en": "and said, “My lord, if now I have found favor in your sight, please don’t go away from your servant.", "zh": "說：「我主，我若在你眼前蒙恩，求你不要離開僕人往前去。", "ja": "言った、「わが主よ、もしわたしがあなたの前に恵みを得ているなら、どうぞしもべを通り過ごさないでください。"}, "4": {"en": "Now let a little water be fetched, wash your feet, and rest yourselves under the tree.", "zh": "容我拿點水來，你們洗洗腳，在樹下歇息歇息。", "ja": "水をすこし取ってこさせますから、あなたがたは足を洗って、この木の下でお休みください。"}, "5": {"en": "I will get a piece of bread so you can refresh your heart. After that you may go your way, now that you have come to your servant.” They said, “Very well, do as you have said.”", "zh": "我再拿一點餅來，你們可以加添心力，然後往前去。你們既到僕人這裏來，理當如此。」他們說：「就照你說的行吧。」", "ja": "わたしは一口のパンを取ってきます。元気をつけて、それからお出かけください。せっかくしもべの所においでになったのですから」。彼らは言った、「お言葉どおりにしてください」。"}, "6": {"en": "Abraham hurried into the tent to Sarah, and said, “Quickly prepare three seahs of fine meal, knead it, and make cakes.”", "zh": "亞伯拉罕急忙進帳棚見撒拉，說：「你速速拿三細亞細麵調和做餅。」", "ja": "そこでアブラハムは急いで天幕に入り、サラの所に行って言った、「急いで細かい麦粉三セヤをとり、こねてパンを造りなさい」。"}, "7": {"en": "Abraham ran to the herd, and fetched a tender and good calf, and gave it to the servant. He hurried to dress it.", "zh": "亞伯拉罕又跑到牛群裏，牽了一隻又嫩又好的牛犢來，交給僕人，僕人急忙預備好了。", "ja": "アブラハムは牛の群れに走って行き、柔らかな良い子牛を取って若者に渡したので、急いで調理した。"}, "8": {"en": "He took butter, milk, and the calf which he had dressed, and set it before them. He stood by them under the tree, and they ate.", "zh": "亞伯拉罕又取了奶油和奶，並預備好的牛犢來，擺在他們面前，自己在樹下站在旁邊，他們就吃了。", "ja": "そしてアブラハムは凝乳と牛乳および子牛の調理したものを取って、彼らの前に供え、木の下で彼らのかたわらに立って給仕し、彼らは食事した。"}, "9": {"en": "They asked him, “Where is Sarah, your wife?” He said, “There, in the tent.”", "zh": "他們問亞伯拉罕說：「你妻子撒拉在哪裏？」他說：「在帳棚裏。」", "ja": "彼らはアブラハムに言った、「あなたの妻サラはどこにおられますか」。彼は言った、「天幕の中です」。"}, "10": {"en": "He said, “I will certainly return to you at about this time next year; and behold, Sarah your wife will have a son.”", "zh": "三人中有一位說：「到明年這時候，我必要回到你這裏；你的妻子撒拉必生一個兒子。」撒拉在那人後邊的帳棚門口也聽見了這話。", "ja": "そのひとりが言った、「来年の春、わたしはかならずあなたの所に帰ってきましょう。その時、あなたの妻サラには男の子が生れているでしょう」。サラはうしろの方の天幕の入口で聞いていた。"}, "11": {"en": "Sarah heard in the tent door, which was behind him.   Now Abraham and Sarah were old, well advanced in age. Sarah had passed the age of childbearing.", "zh": "亞伯拉罕和撒拉年紀老邁，撒拉的月經已斷絕了。", "ja": "さてアブラハムとサラとは年がすすみ、老人となり、サラは女の月のものが、すでに止まっていた。"}, "12": {"en": "Sarah laughed within herself, saying, “After I have grown old will I have pleasure, my lord being old also?”", "zh": "撒拉心裏暗笑，說：「我既已衰敗，我主也老邁，豈能有這喜事呢？」", "ja": "それでサラは心の中で笑って言った、「わたしは衰え、主人もまた老人であるのに、わたしに楽しみなどありえようか」。"}, "13": {"en": "The LORD said to Abraham, “Why did Sarah laugh, saying, ‘Will I really bear a child when I am old?’", "zh": "耶和華對亞伯拉罕說：「撒拉為甚麼暗笑，說：『我既已年老，果真能生養嗎？』", "ja": "主はアブラハムに言われた、「なぜサラは、わたしは老人であるのに、どうして子を産むことができようかと言って笑ったのか。"}, "14": {"en": "Is anything too hard for the LORD? At the set time I will return to you, when the season comes around, and Sarah will have a son.”", "zh": "耶和華豈有難成的事嗎？到了日期，明年這時候，我必回到你這裏，撒拉必生一個兒子。」", "ja": "主にとって不可能なことがありましょうか。来年の春、定めの時に、わたしはあなたの所に帰ってきます。そのときサラには男の子が生れているでしょう」。"}, "15": {"en": "Then Sarah denied it, saying, “I didn’t laugh,” for she was afraid. He said, “No, but you did laugh.”", "zh": "撒拉就害怕，不承認，說：「我沒有笑。」那位說：「不然，你實在笑了。」", "ja": "サラは恐れたので、これを打ち消して言った、「わたしは笑いません」。主は言われた、「いや、あなたは笑いました」。"}, "16": {"en": "The men rose up from there, and looked toward Sodom. Abraham went with them to see them on their way.", "zh": "三人就從那裏起行，向所多瑪觀看，亞伯拉罕也與他們同行，要送他們一程。", "ja": "その人々はそこを立ってソドムの方に向かったので、アブラハムは彼らを見送って共に行った。"}, "17": {"en": "The LORD said, “Will I hide from Abraham what I do,", "zh": "耶和華說：「我所要做的事豈可瞞着亞伯拉罕呢？", "ja": "時に主は言われた、「わたしのしようとする事をアブラハムに隠してよいであろうか。"}, "18": {"en": "since Abraham will surely become a great and mighty nation, and all the nations of the earth will be blessed in him?", "zh": "亞伯拉罕必要成為強大的國；地上的萬國都必因他得福。", "ja": "アブラハムは必ず大きな強い国民となって、地のすべての民がみな、彼によって祝福を受けるのではないか。"}, "19": {"en": "For I have known him, to the end that he may command his children and his household after him, that they may keep the way of the LORD, to do righteousness and justice; to the end that the LORD may bring on Abraham that which he has spoken of him.”", "zh": "我眷顧他，為要叫他吩咐他的眾子和他的眷屬遵守我的道，秉公行義，使我所應許亞伯拉罕的話都成就了。」", "ja": "わたしは彼が後の子らと家族とに命じて主の道を守らせ、正義と公道とを行わせるために彼を知ったのである。これは主がかつてアブラハムについて言った事を彼の上に臨ませるためである」。"}, "20": {"en": "The LORD said, “Because the cry of Sodom and Gomorrah is great, and because their sin is very grievous,", "zh": "耶和華說：「所多瑪和蛾摩拉的罪惡甚重，聲聞於我。", "ja": "主はまた言われた、「ソドムとゴモラの叫びは大きく、またその罪は非常に重いので、"}, "21": {"en": "I will go down now, and see whether their deeds are as bad as the reports which have come to me. If not, I will know.”", "zh": "我現在要下去，察看他們所行的，果然盡像那達到我耳中的聲音一樣嗎？若是不然，我也必知道。」", "ja": "わたしはいま下って、わたしに届いた叫びのとおりに、すべて彼らがおこなっているかどうかを見て、それを知ろう」。"}, "22": {"en": "The men turned from there, and went toward Sodom, but Abraham stood yet before the LORD.", "zh": "二人轉身離開那裏，向所多瑪去；但亞伯拉罕仍舊站在耶和華面前。", "ja": "その人々はそこから身を巡らしてソドムの方に行ったが、アブラハムはなお、主の前に立っていた。"}, "23": {"en": "Abraham came near, and said, “Will you consume the righteous with the wicked?", "zh": "亞伯拉罕近前來，說：「無論善惡，你都要剿滅嗎？", "ja": "アブラハムは近寄って言った、「まことにあなたは正しい者を、悪い者と一緒に滅ぼされるのですか。"}, "24": {"en": "What if there are fifty righteous within the city? Will you consume and not spare the place for the fifty righteous who are in it?", "zh": "假若那城裏有五十個義人，你還剿滅那地方嗎？不為城裏這五十個義人饒恕其中的人嗎？", "ja": "たとい、あの町に五十人の正しい者があっても、あなたはなお、その所を滅ぼし、その中にいる五十人の正しい者のためにこれをゆるされないのですか。"}, "25": {"en": "May it be far from you to do things like that, to kill the righteous with the wicked, so that the righteous should be like the wicked. May that be far from you. Shouldn’t the Judge of all the earth do right?”", "zh": "將義人與惡人同殺，將義人與惡人一樣看待，這斷不是你所行的。審判全地的主豈不行公義嗎？」", "ja": "正しい者と悪い者とを一緒に殺すようなことを、あなたは決してなさらないでしょう。正しい者と悪い者とを同じようにすることも、あなたは決してなさらないでしょう。全地をさばく者は公義を行うべきではありませんか」。"}, "26": {"en": "The LORD said, “If I find in Sodom fifty righteous within the city, then I will spare the whole place for their sake.”", "zh": "耶和華說：「我若在所多瑪城裏見有五十個義人，我就為他們的緣故饒恕那地方的眾人。」", "ja": "主は言われた、「もしソドムで町の中に五十人の正しい者があったら、その人々のためにその所をすべてゆるそう」。"}, "27": {"en": "Abraham answered, “See now, I have taken it on myself to speak to the Lord, although I am dust and ashes.", "zh": "亞伯拉罕說：「我雖然是灰塵，還敢對主說話。", "ja": "アブラハムは答えて言った、「わたしはちり灰に過ぎませんが、あえてわが主に申します。"}, "28": {"en": "What if there will lack five of the fifty righteous? Will you destroy all the city for lack of five?” He said, “I will not destroy it if I find forty-five there.”", "zh": "假若這五十個義人短了五個，你就因為短了五個毀滅全城嗎？」他說：「我在那裏若見有四十五個，也不毀滅那城。」", "ja": "もし五十人の正しい者のうち五人欠けたなら、その五人欠けたために町を全く滅ぼされますか」。主は言われた、「もしそこに四十五人いたら、滅ぼさないであろう」。"}, "29": {"en": "He spoke to him yet again, and said, “What if there are forty found there?” He said, “I will not do it for the forty’s sake.”", "zh": "亞伯拉罕又對他說：「假若在那裏見有四十個怎麼樣呢？」他說：「為這四十個的緣故，我也不做這事。」", "ja": "アブラハムはまた重ねて主に言った、「もしそこに四十人いたら」。主は言われた、「その四十人のために、これをしないであろう」。"}, "30": {"en": "He said, “Oh don’t let the Lord be angry, and I will speak. What if there are thirty found there?” He said, “I will not do it if I find thirty there.”", "zh": "亞伯拉罕說：「求主不要動怒，容我說，假若在那裏見有三十個怎麼樣呢？」他說：「我在那裏若見有三十個，我也不做這事。」", "ja": "アブラハムは言った、「わが主よ、どうかお怒りにならぬよう。わたしは申します。もしそこに三十人いたら」。主は言われた、「そこに三十人いたら、これをしないであろう」。"}, "31": {"en": "He said, “See now, I have taken it on myself to speak to the Lord. What if there are twenty found there?” He said, “I will not destroy it for the twenty’s sake.”", "zh": "亞伯拉罕說：「我還敢對主說話，假若在那裏見有二十個怎麼樣呢？」他說：「為這二十個的緣故，我也不毀滅那城。」", "ja": "アブラハムは言った、「いまわたしはあえてわが主に申します。もしそこに二十人いたら」。主は言われた、「わたしはその二十人のために滅ぼさないであろう」。"}, "32": {"en": "He said, “Oh don’t let the Lord be angry, and I will speak just once more. What if ten are found there?” He said, “I will not destroy it for the ten’s sake.”", "zh": "亞伯拉罕說：「求主不要動怒，我再說這一次，假若在那裏見有十個呢？」他說：「為這十個的緣故，我也不毀滅那城。」", "ja": "アブラハムは言った、「わが主よ、どうかお怒りにならぬよう。わたしはいま一度申します、もしそこに十人いたら」。主は言われた、「わたしはその十人のために滅ぼさないであろう」。"}, "33": {"en": "The LORD went his way as soon as he had finished communing with Abraham, and Abraham returned to his place.", "zh": "耶和華與亞伯拉罕說完了話就走了；亞伯拉罕也回到自己的地方去了。", "ja": "主はアブラハムと語り終り、去って行かれた。アブラハムは自分の所に帰った。"}}}, "19": {"verses": {"1": {"en": "The two angels came to Sodom at evening. Lot sat in the gate of Sodom. Lot saw them, and rose up to meet them. He bowed himself with his face to the earth,", "zh": "那兩個天使晚上到了所多瑪；羅得正坐在所多瑪城門口，看見他們，就起來迎接，臉伏於地下拜，", "ja": "そのふたりのみ使は夕暮にソドムに着いた。そのときロトはソドムの門にすわっていた。ロトは彼らを見て、立って迎え、地に伏して、"}, "2": {"en": "and he said, “See now, my lords, please come into your servant’s house, stay all night, wash your feet, and you can rise up early, and go on your way.” They said, “No, but we will stay in the street all night.”", "zh": "說：「我主啊，請你們到僕人家裏洗洗腳，住一夜，清早起來再走。」他們說：「不！我們要在街上過夜。」", "ja": "言った、「わが主よ、どうぞしもべの家に立寄って足を洗い、お泊まりください。そして朝早く起きてお立ちください」。彼らは言った、「いや、われわれは広場で夜を過ごします」。"}, "3": {"en": "He urged them greatly, and they came in with him, and entered into his house. He made them a feast, and baked unleavened bread, and they ate.", "zh": "羅得切切地請他們，他們這才進去，到他屋裏。羅得為他們預備筵席，烤無酵餅，他們就吃了。", "ja": "しかしロトがしいて勧めたので、彼らはついに彼の所に寄り、家にはいった。ロトは彼らのためにふるまいを設け、種入れぬパンを焼いて食べさせた。"}, "4": {"en": "But before they lay down, the men of the city, the men of Sodom, surrounded the house, both young and old, all the people from every quarter.", "zh": "他們還沒有躺下，所多瑪城裏各處的人，連老帶少，都來圍住那房子，", "ja": "ところが彼らの寝ないうちに、ソドムの町の人々は、若い者も老人も、民がみな四方からきて、その家を囲み、"}, "5": {"en": "They called to Lot, and said to him, “Where are the men who came in to you this night? Bring them out to us, that we may have sex with them.”", "zh": "呼叫羅得說：「今日晚上到你這裏來的人在哪裏呢？把他們帶出來，任我們所為。」", "ja": "ロトに叫んで言った、「今夜おまえの所にきた人々はどこにいるか。それをここに出しなさい。われわれは彼らを知るであろう」。"}, "6": {"en": "Lot went out to them through the door, and shut the door after himself.", "zh": "羅得出來，把門關上，到眾人那裏，", "ja": "ロトは入口におる彼らの所に出て行き、うしろの戸を閉じて、"}, "7": {"en": "He said, “Please, my brothers, don’t act so wickedly.", "zh": "說：「眾弟兄，請你們不要做這惡事。", "ja": "言った、「兄弟たちよ、どうか悪い事はしないでください。"}, "8": {"en": "See now, I have two virgin daughters. Please let me bring them out to you, and you may do to them what seems good to you. Only don’t do anything to these men, because they have come under the shadow of my roof.”", "zh": "我有兩個女兒，還是處女，容我領出來，任憑你們的心願而行；只是這兩個人既然到我舍下，不要向他們做甚麼。」", "ja": "わたしにまだ男を知らない娘がふたりあります。わたしはこれをあなたがたに、さし出しますから、好きなようにしてください。ただ、わたしの屋根の下にはいったこの人たちには、何もしないでください」。"}, "9": {"en": "They said, “Stand back!” Then they said, “This one fellow came in to live as a foreigner, and he appoints himself a judge. Now we will deal worse with you than with them!” They pressed hard on the man Lot, and came near to break the door.", "zh": "眾人說：「退去吧！」又說：「這個人來寄居，還想要作官哪！現在我們要害你比害他們更甚。」眾人就向前擁擠羅得，要攻破房門。", "ja": "彼らは言った、「退け」。また言った、「この男は渡ってきたよそ者であるのに、いつも、さばきびとになろうとする。それで、われわれは彼らに加えるよりも、おまえに多くの害を加えよう」。彼らはロトの身に激しく迫り、進み寄って戸を破ろうとした。"}, "10": {"en": "But the men reached out their hand, and brought Lot into the house to them, and shut the door.", "zh": "只是那二人伸出手來，將羅得拉進屋去，把門關上，", "ja": "その時、かのふたりは手を伸べてロトを家の内に引き入れ、戸を閉じた。"}, "11": {"en": "They struck the men who were at the door of the house with blindness, both small and great, so that they wearied themselves to find the door.", "zh": "並且使門外的人，無論老少，眼都昏迷；他們摸來摸去，總尋不着房門。", "ja": "そして家の入口におる人々を、老若の別なく打って目をくらましたので、彼らは入口を捜すのに疲れた。"}, "12": {"en": "The men said to Lot, “Do you have anybody else here? Sons-in-law, your sons, your daughters, and whomever you have in the city, bring them out of the place:", "zh": "二人對羅得說：「你這裏還有甚麼人嗎？無論是女婿是兒女，和這城中一切屬你的人，你都要將他們從這地方帶出去。", "ja": "ふたりはロトに言った、「ほかにあなたの身内の者がここにおりますか。あなたのむこ、むすこ、娘およびこの町におるあなたの身内の者を、皆ここから連れ出しなさい。"}, "13": {"en": "for we will destroy this place, because the outcry against them has grown so great before the LORD that the LORD has sent us to destroy it.”", "zh": "我們要毀滅這地方；因為城內罪惡的聲音在耶和華面前甚大，耶和華差我們來，要毀滅這地方。」", "ja": "われわれがこの所を滅ぼそうとしているからです。人々の叫びが主の前に大きくなり、主はこの所を滅ぼすために、われわれをつかわされたのです」。"}, "14": {"en": "Lot went out, and spoke to his sons-in-law, who were pledged to marry his daughters, and said, “Get up! Get out of this place, for the LORD will destroy the city!”", "zh": "羅得就出去，告訴娶了他女兒的女婿們說：「你們起來離開這地方，因為耶和華要毀滅這城。」他女婿們卻以為他說的是戲言。", "ja": "そこでロトは出て行って、その娘たちをめとるむこたちに告げて言った、「立ってこの所から出なさい。主がこの町を滅ぼされます」。しかしそれはむこたちには戯むれごとに思えた。"}, "15": {"en": "But he seemed to his sons-in-law to be joking.   When the morning came, then the angels hurried Lot, saying, “Get up! Take your wife and your two daughters who are here, lest you be consumed in the iniquity of the city.”", "zh": "天明了，天使催逼羅得說：「起來！帶着你的妻子和你在這裏的兩個女兒出去，免得你因這城裏的罪惡同被剿滅。」", "ja": "夜が明けて、み使たちはロトを促して言った　　「立って、ここにいるあなたの妻とふたりの娘とを連れ出しなさい。そうしなければ、あなたもこの町の不義のために滅ぼされるでしょう」。"}, "16": {"en": "But he lingered; and the men grabbed his hand, his wife’s hand, and his two daughters’ hands, the LORD being merciful to him; and they took him out, and set him outside of the city.", "zh": "但羅得遲延不走。二人因為耶和華憐恤羅得，就拉着他的手和他妻子的手，並他兩個女兒的手，把他們領出來，安置在城外；", "ja": "彼はためらっていたが、主は彼にあわれみを施されたので、かのふたりは彼の手と、その妻の手と、ふたりの娘の手を取って連れ出し、町の外に置いた。"}, "17": {"en": "It came to pass, when they had taken them out, that he said, “Escape for your life! Don’t look behind you, and don’t stay anywhere in the plain. Escape to the mountains, lest you be consumed!”", "zh": "領他們出來以後，就說：「逃命吧！不可回頭看，也不可在平原站住。要往山上逃跑，免得你被剿滅。」", "ja": "彼らを外に連れ出した時そのひとりは言った、「のがれて、自分の命を救いなさい。うしろをふりかえって見てはならない。低地にはどこにも立ち止まってはならない。山にのがれなさい。そうしなければ、あなたは滅びます」。"}, "18": {"en": "Lot said to them, “Oh, not so, my lord.", "zh": "羅得對他們說：「我主啊，不要如此！", "ja": "ロトは彼らに言った、「わが主よ、どうか、そうさせないでください。"}, "19": {"en": "See now, your servant has found favor in your sight, and you have magnified your loving kindness, which you have shown to me in saving my life. I can’t escape to the mountain, lest evil overtake me, and I die.", "zh": "你僕人已經在你眼前蒙恩；你又向我顯出莫大的慈愛，救我的性命。我不能逃到山上去，恐怕這災禍臨到我，我便死了。", "ja": "しもべはすでにあなたの前に恵みを得ました。あなたはわたしの命を救って、大いなるいつくしみを施されました。しかしわたしは山まではのがれる事ができません。災が身に追い迫ってわたしは死ぬでしょう。"}, "20": {"en": "See now, this city is near to flee to, and it is a little one. Oh let me escape there (isn’t it a little one?), and my soul will live.”", "zh": "看哪，這座城又小又近，容易逃到，這不是一個小的嗎？求你容我逃到那裏，我的性命就得存活。」", "ja": "あの町をごらんなさい。逃げていくのに近く、また小さい町です。どうかわたしをそこにのがれさせてください。それは小さいではありませんか。そうすればわたしの命は助かるでしょう」。"}, "21": {"en": "He said to him, “Behold, I have granted your request concerning this thing also, that I will not overthrow the city of which you have spoken.", "zh": "天使對他說：「這事我也應允你；我不傾覆你所說的這城。", "ja": "み使は彼に言った、「わたしはこの事でもあなたの願いをいれて、あなたの言うその町は滅ぼしません。"}, "22": {"en": "Hurry, escape there, for I can’t do anything until you get there.” Therefore the name of the city was called Zoar.", "zh": "你要速速地逃到那城；因為你還沒有到那裏，我不能做甚麼。」因此那城名叫瑣珥。", "ja": "急いでそこへのがれなさい。あなたがそこに着くまでは、わたしは何事もすることができません」。これによって、その町の名はゾアルと呼ばれた。"}, "23": {"en": "The sun had risen on the earth when Lot came to Zoar.", "zh": "羅得到了瑣珥，日頭已經出來了。", "ja": "ロトがゾアルに着いた時、日は地の上にのぼった。"}, "24": {"en": "Then the LORD rained on Sodom and on Gomorrah sulfur and fire from the LORD out of the sky.", "zh": "當時，耶和華將硫磺與火從天上耶和華那裏降與所多瑪和蛾摩拉，", "ja": "主は硫黄と火とを主の所すなわち天からソドムとゴモラの上に降らせて、"}, "25": {"en": "He overthrew those cities, all the plain, all the inhabitants of the cities, and that which grew on the ground.", "zh": "把那些城和全平原，並城裏所有的居民，連地上生長的，都毀滅了。", "ja": "これらの町と、すべての低地と、その町々のすべての住民と、その地にはえている物を、ことごとく滅ぼされた。"}, "26": {"en": "But Lot’s wife looked back from behind him, and she became a pillar of salt.", "zh": "羅得的妻子在後邊回頭一看，就變成了一根鹽柱。", "ja": "しかしロトの妻はうしろを顧みたので塩の柱になった。"}, "27": {"en": "Abraham went up early in the morning to the place where he had stood before the LORD.", "zh": "亞伯拉罕清早起來，到了他從前站在耶和華面前的地方，", "ja": "アブラハムは朝早く起き、さきに主の前に立った所に行って、"}, "28": {"en": "He looked toward Sodom and Gomorrah, and toward all the land of the plain, and saw that the smoke of the land went up as the smoke of a furnace.", "zh": "向所多瑪和蛾摩拉與平原的全地觀看，不料，那地方煙氣上騰，如同燒窯一般。", "ja": "ソドムとゴモラの方、および低地の全面をながめると、その地の煙が、かまどの煙のように立ちのぼっていた。"}, "29": {"en": "When God destroyed the cities of the plain, God remembered Abraham, and sent Lot out of the middle of the overthrow, when he overthrew the cities in which Lot lived.", "zh": "當上帝毀滅平原諸城的時候，他記念亞伯拉罕，正在傾覆羅得所住之城的時候，就打發羅得從傾覆之中出來。", "ja": "こうして神が低地の町々をこぼたれた時、すなわちロトの住んでいた町々を滅ぼされた時、神はアブラハムを覚えて、その滅びの中からロトを救い出された。"}, "30": {"en": "Lot went up out of Zoar, and lived in the mountain, and his two daughters with him; for he was afraid to live in Zoar. He lived in a cave with his two daughters.", "zh": "羅得因為怕住在瑣珥，就同他兩個女兒從瑣珥上去，住在山裏；他和兩個女兒住在一個洞裏。", "ja": "ロトはゾアルを出て上り、ふたりの娘と共に山に住んだ。ゾアルに住むのを恐れたからである。彼はふたりの娘と共に、ほら穴の中に住んだ。"}, "31": {"en": "The firstborn said to the younger, “Our father is old, and there is not a man on the earth to come in to us in the way of all the earth.", "zh": "大女兒對小女兒說：「我們的父親老了，地上又無人按着世上的常規進到我們這裏。", "ja": "時に姉が妹に言った、「わたしたちの父は老い、またこの地には世のならわしのように、わたしたちの所に来る男はいません。"}, "32": {"en": "Come, let’s make our father drink wine, and we will lie with him, that we may preserve our father’s family line.”", "zh": "來！我們可以叫父親喝酒，與他同寢。這樣，我們好從他存留後裔。」", "ja": "さあ、父に酒を飲ませ、共に寝て、父によって子を残しましょう」。"}, "33": {"en": "They made their father drink wine that night: and the firstborn went in, and lay with her father. He didn’t know when she lay down, nor when she arose.", "zh": "於是，那夜她們叫父親喝酒，大女兒就進去和她父親同寢；她幾時躺下，幾時起來，父親都不知道。", "ja": "彼女たちはその夜、父に酒を飲ませ、姉がはいって父と共に寝た。ロトは娘が寝たのも、起きたのも知らなかった。"}, "34": {"en": "It came to pass on the next day, that the firstborn said to the younger, “Behold, I lay last night with my father. Let’s make him drink wine again tonight. You go in, and lie with him, that we may preserve our father’s family line.”", "zh": "第二天，大女兒對小女兒說：「我昨夜與父親同寢。今夜我們再叫他喝酒，你可以進去與他同寢。這樣，我們好從父親存留後裔。」", "ja": "あくる日、姉は妹に言った、「わたしは昨夜、父と寝ました。わたしたちは今夜もまた父に酒を飲ませましょう。そしてあなたがはいって共に寝なさい。わたしたちは父によって子を残しましょう」。"}, "35": {"en": "They made their father drink wine that night also. The younger went and lay with him. He didn’t know when she lay down, nor when she got up.", "zh": "於是，那夜她們又叫父親喝酒，小女兒起來與她父親同寢；她幾時躺下，幾時起來，父親都不知道。", "ja": "彼らはその夜もまた父に酒を飲ませ、妹が行って父と共に寝た。ロトは娘の寝たのも、起きたのも知らなかった。"}, "36": {"en": "Thus both of Lot’s daughters were with child by their father.", "zh": "這樣，羅得的兩個女兒都從她父親懷了孕。", "ja": "こうしてロトのふたりの娘たちは父によってはらんだ。"}, "37": {"en": "The firstborn bore a son, and named him Moab. He is the father of the Moabites to this day.", "zh": "大女兒生了兒子，給他起名叫摩押，就是現今摩押人的始祖。", "ja": "姉娘は子を産み、その名をモアブと名づけた。これは今のモアブびとの先祖である。"}, "38": {"en": "The younger also bore a son, and called his name Ben Ammi. He is the father of the children of Ammon to this day.", "zh": "小女兒也生了兒子，給他起名叫便‧亞米，就是現今亞捫人的始祖。", "ja": "妹もまた子を産んで、その名をベニアンミと名づけた。これは今のアンモンびとの先祖である。"}}}, "20": {"verses": {"1": {"en": "Abraham traveled from there toward the land of the South, and lived between Kadesh and Shur. He lived as a foreigner in Gerar.", "zh": "亞伯拉罕從那裏向南地遷去，寄居在加低斯和書珥中間的基拉耳。", "ja": "アブラハムはそこからネゲブの地に移って、カデシとシュルの間に住んだ。彼がゲラルにとどまっていた時、"}, "2": {"en": "Abraham said about Sarah his wife, “She is my sister.” Abimelech king of Gerar sent, and took Sarah.", "zh": "亞伯拉罕稱他的妻撒拉為妹子，基拉耳王亞比米勒差人把撒拉取了去。", "ja": "アブラハムは妻サラのことを、「これはわたしの妹です」と言ったので、ゲラルの王アビメレクは、人をつかわしてサラを召し入れた。"}, "3": {"en": "But God came to Abimelech in a dream of the night, and said to him, “Behold, you are a dead man, because of the woman whom you have taken; for she is a man’s wife.”", "zh": "但夜間，上帝來，在夢中對亞比米勒說：「你是個死人哪！因為你取了那女人來；她原是別人的妻子。」", "ja": "ところが神は夜の夢にアビメレクに臨んで言われた、「あなたは召し入れたあの女のゆえに死なねばならない。彼女は夫のある身である」。"}, "4": {"en": "Now Abimelech had not come near her. He said, “Lord, will you kill even a righteous nation?", "zh": "亞比米勒卻還沒有親近撒拉；他說：「主啊，連有義的國，你也要毀滅嗎？", "ja": "アビメレクはまだ彼女に近づいていなかったので言った、「主よ、あなたは正しい民でも殺されるのですか。"}, "5": {"en": "Didn’t he tell me, ‘She is my sister’? She, even she herself, said, ‘He is my brother.’ I have done this in the integrity of my heart and the innocence of my hands.”", "zh": "那人豈不是自己對我說『她是我的妹子』嗎？就是女人也自己說：『他是我的哥哥。』我做這事是心正手潔的。」", "ja": "彼はわたしに、これはわたしの妹ですと言ったではありませんか。また彼女も自分で、彼はわたしの兄ですと言いました。わたしは心も清く、手もいさぎよく、このことをしました」。"}, "6": {"en": "God said to him in the dream, “Yes, I know that in the integrity of your heart you have done this, and I also withheld you from sinning against me. Therefore I didn’t allow you to touch her.", "zh": "上帝在夢中對他說：「我知道你做這事是心中正直；我也攔阻了你，免得你得罪我，所以我不容你沾着她。", "ja": "神はまた夢で彼に言われた、「そうです、あなたが清い心をもってこのことをしたのを知っていたから、わたしもあなたを守って、わたしに対して罪を犯させず、彼女にふれることを許さなかったのです。"}, "7": {"en": "Now therefore, restore the man’s wife. For he is a prophet, and he will pray for you, and you will live. If you don’t restore her, know for sure that you will die, you, and all who are yours.”", "zh": "現在你把這人的妻子歸還他；因為他是先知，他要為你禱告，使你存活。你若不歸還他，你當知道，你和你所有的人都必要死。」", "ja": "いま彼の妻を返しなさい。彼は預言者ですから、あなたのために祈って、命を保たせるでしょう。もし返さないなら、あなたも身内の者もみな必ず死ぬと知らなければなりません」。"}, "8": {"en": "Abimelech rose early in the morning, and called all his servants, and told all these things in their ear. The men were very scared.", "zh": "亞比米勒清早起來，召了眾臣僕來，將這些事都說給他們聽，他們都甚懼怕。", "ja": "そこでアビメレクは朝早く起き、しもべたちをことごとく召し集めて、これらの事をみな語り聞かせたので、人々は非常に恐れた。"}, "9": {"en": "Then Abimelech called Abraham, and said to him, “What have you done to us? How have I sinned against you, that you have brought on me and on my kingdom a great sin? You have done deeds to me that ought not to be done!”", "zh": "亞比米勒召了亞伯拉罕來，對他說：「你怎麼向我這樣行呢？我在甚麼事上得罪了你，你竟使我和我國裏的人陷在大罪裏？你向我行不當行的事了！」", "ja": "そしてアビメレクはアブラハムを召して言った、「あなたはわれわれに何をするのですか。あなたに対してわたしがどんな罪を犯したために、あなたはわたしとわたしの国とに、大きな罪を負わせるのですか。あなたはしてはならぬことをわたしにしたのです」。"}, "10": {"en": "Abimelech said to Abraham, “What did you see, that you have done this thing?”", "zh": "亞比米勒又對亞伯拉罕說：「你見了甚麼才做這事呢？」", "ja": "アビメレクはまたアブラハムに言った、「あなたはなんと思って、この事をしたのですか」。"}, "11": {"en": "Abraham said, “Because I thought, ‘Surely the fear of God is not in this place. They will kill me for my wife’s sake.’", "zh": "亞伯拉罕說：「我以為這地方的人總不懼怕上帝，必為我妻子的緣故殺我。", "ja": "アブラハムは言った、「この所には神を恐れるということが、まったくないので、わたしの妻のゆえに人々がわたしを殺すと思ったからです。"}, "12": {"en": "Besides, she is indeed my sister, the daughter of my father, but not the daughter of my mother; and she became my wife.", "zh": "況且她也實在是我的妹子；她與我是同父異母，後來作了我的妻子。", "ja": "また彼女はほんとうにわたしの妹なのです。わたしの父の娘ですが、母の娘ではありません。そして、わたしの妻になったのです。"}, "13": {"en": "When God caused me to wander from my father’s house, I said to her, ‘This is your kindness which you shall show to me. Everywhere that we go, say of me, “He is my brother.” ’ ”", "zh": "當上帝叫我離開父家、飄流在外的時候，我對她說：『我們無論走到甚麼地方，你可以對人說：他是我的哥哥；這就是你待我的恩典了。』」", "ja": "神がわたしに父の家を離れて、行き巡らせた時、わたしは彼女に、あなたはわたしたちの行くさきざきでわたしを兄であると言ってください。これはあなたがわたしに施す恵みであると言いました」。"}, "14": {"en": "Abimelech took sheep and cattle, male servants and female servants, and gave them to Abraham, and restored Sarah, his wife, to him.", "zh": "亞比米勒把牛、羊、僕婢賜給亞伯拉罕，又把他的妻子撒拉歸還他。", "ja": "そこでアビメレクは羊、牛および男女の奴隷を取ってアブラハムに与え、その妻サラを彼に返した。"}, "15": {"en": "Abimelech said, “Behold, my land is before you. Dwell where it pleases you.”", "zh": "亞比米勒又說：「看哪，我的地都在你面前，你可以隨意居住」；", "ja": "そしてアビメレクは言った、「わたしの地はあなたの前にあります。あなたの好きな所に住みなさい」。"}, "16": {"en": "To Sarah he said, “Behold, I have given your brother a thousand pieces of silver. Behold, it is for you a covering of the eyes to all that are with you. In front of all you are vindicated.”", "zh": "又對撒拉說：「我給你哥哥一千銀子，作為你在閤家人面前遮羞的，你就在眾人面前沒有不是了。」", "ja": "またサラに言った、「わたしはあなたの兄に銀千シケルを与えました。これはあなたの身に起ったすべての事について、あなたに償いをするものです。こうしてすべての人にあなたは正しいと認められます」。"}, "17": {"en": "Abraham prayed to God. So God healed Abimelech, his wife, and his female servants, and they bore children.", "zh": "亞伯拉罕禱告上帝，上帝就醫好了亞比米勒和他的妻子，並他的眾女僕，她們便能生育。", "ja": "そこでアブラハムは神に祈った。神はアビメレクとその妻および、はしためたちをいやされたので、彼らは子を産むようになった。"}, "18": {"en": "For the LORD had closed up tight all the wombs of the house of Abimelech, because of Sarah, Abraham’s wife.", "zh": "因耶和華為亞伯拉罕的妻子撒拉的緣故，已經使亞比米勒家中的婦人不能生育。", "ja": "これは主がさきにアブラハムの妻サラのゆえに、アビメレクの家のすべての者の胎を、かたく閉ざされたからである。"}}}, "21": {"verses": {"1": {"en": "The LORD visited Sarah as he had said, and the LORD did to Sarah as he had spoken.", "zh": "耶和華按着先前的話眷顧撒拉，便照他所說的給撒拉成就。", "ja": "主は、さきに言われたようにサラを顧み、告げられたようにサラに行われた。"}, "2": {"en": "Sarah conceived, and bore Abraham a son in his old age, at the set time of which God had spoken to him.", "zh": "當亞伯拉罕年老的時候，撒拉懷了孕；到上帝所說的日期，就給亞伯拉罕生了一個兒子。", "ja": "サラはみごもり、神がアブラハムに告げられた時になって、年老いたアブラハムに男の子を産んだ。"}, "3": {"en": "Abraham called his son who was born to him, whom Sarah bore to him, Isaac.", "zh": "亞伯拉罕給撒拉所生的兒子起名叫以撒。", "ja": "アブラハムは生れた子、サラが産んだ男の子の名をイサクと名づけた。"}, "4": {"en": "Abraham circumcised his son, Isaac, when he was eight days old, as God had commanded him.", "zh": "以撒生下來第八日，亞伯拉罕照着上帝所吩咐的，給以撒行了割禮。", "ja": "アブラハムは神が命じられたように八日目にその子イサクに割礼を施した。"}, "5": {"en": "Abraham was one hundred years old when his son, Isaac, was born to him.", "zh": "他兒子以撒生的時候，亞伯拉罕年一百歲。", "ja": "アブラハムはその子イサクが生れた時百歳であった。"}, "6": {"en": "Sarah said, “God has made me laugh. Everyone who hears will laugh with me.”", "zh": "撒拉說：「上帝使我喜笑，凡聽見的必與我一同喜笑」；", "ja": "そしてサラは言った、「神はわたしを笑わせてくださった。聞く者は皆わたしのことで笑うでしょう」。"}, "7": {"en": "She said, “Who would have said to Abraham that Sarah would nurse children? For I have borne him a son in his old age.”", "zh": "又說：「誰能預先對亞伯拉罕說『撒拉要乳養嬰孩』呢？因為在他年老的時候，我給他生了一個兒子。」", "ja": "また言った、「サラが子に乳を飲ませるだろうと、だれがアブラハムに言い得たであろう。それなのに、わたしは彼が年とってから、子を産んだ」。"}, "8": {"en": "The child grew and was weaned. Abraham made a great feast on the day that Isaac was weaned.", "zh": "孩子漸長，就斷了奶。以撒斷奶的日子，亞伯拉罕設擺豐盛的筵席。", "ja": "さて、おさなごは育って乳離れした。イサクが乳離れした日にアブラハムは盛んなふるまいを設けた。"}, "9": {"en": "Sarah saw the son of Hagar the Egyptian, whom she had borne to Abraham, mocking.", "zh": "當時，撒拉看見埃及人夏甲給亞伯拉罕所生的兒子戲笑，", "ja": "サラはエジプトの女ハガルのアブラハムに産んだ子が、自分の子イサクと遊ぶのを見て、"}, "10": {"en": "Therefore she said to Abraham, “Cast out this servant and her son! For the son of this servant will not be heir with my son, Isaac.”", "zh": "就對亞伯拉罕說：「你把這使女和她兒子趕出去！因為這使女的兒子不可與我的兒子以撒一同承受產業。」", "ja": "アブラハムに言った、「このはしためとその子を追い出してください。このはしための子はわたしの子イサクと共に、世継となるべき者ではありません」。"}, "11": {"en": "The thing was very grievous in Abraham’s sight on account of his son.", "zh": "亞伯拉罕因他兒子的緣故很憂愁。", "ja": "この事で、アブラハムはその子のために非常に心配した。"}, "12": {"en": "God said to Abraham, “Don’t let it be grievous in your sight because of the boy, and because of your servant. In all that Sarah says to you, listen to her voice. For your offspring will be named through Isaac.", "zh": "上帝對亞伯拉罕說：「你不必為這童子和你的使女憂愁。凡撒拉對你說的話，你都該聽從；因為從以撒生的，才要稱為你的後裔。", "ja": "神はアブラハムに言われた、「あのわらべのため、またあなたのはしためのために心配することはない。サラがあなたに言うことはすべて聞きいれなさい。イサクに生れる者が、あなたの子孫と唱えられるからです。"}, "13": {"en": "I will also make a nation of the son of the servant, because he is your child.”", "zh": "至於使女的兒子，我也必使他的後裔成立一國，因為他是你所生的。」", "ja": "しかし、はしための子もあなたの子ですから、これをも、一つの国民とします」。"}, "14": {"en": "Abraham rose up early in the morning, and took bread and a container of water, and gave it to Hagar, putting it on her shoulder; and gave her the child, and sent her away. She departed, and wandered in the wilderness of Beersheba.", "zh": "亞伯拉罕清早起來，拿餅和一皮袋水，給了夏甲，搭在她的肩上，又把孩子交給她，打發她走。夏甲就走了，在別是巴的曠野走迷了路。", "ja": "そこでアブラハムは明くる朝はやく起きて、パンと水の皮袋とを取り、ハガルに与えて、肩に負わせ、その子を連れて去らせた。ハガルは去ってベエルシバの荒野にさまよった。"}, "15": {"en": "The water in the container was spent, and she put the child under one of the shrubs.", "zh": "皮袋的水用盡了，夏甲就把孩子撇在小樹底下，", "ja": "やがて皮袋の水が尽きたので、彼女はその子を木の下におき、"}, "16": {"en": "She went and sat down opposite him, a good way off, about a bow shot away. For she said, “Don’t let me see the death of the child.” She sat opposite him, and lifted up her voice, and wept.", "zh": "自己走開約有一箭之遠，相對而坐，說：「我不忍見孩子死」，就相對而坐，放聲大哭。", "ja": "「わたしはこの子の死ぬのを見るに忍びない」と言って、矢の届くほど離れて行き、子供の方に向いてすわった。彼女が子供の方に向いてすわったとき、子供は声をあげて泣いた。"}, "17": {"en": "God heard the voice of the boy.", "zh": "上帝聽見童子的聲音；上帝的使者從天上呼叫夏甲說：「夏甲，你為何這樣呢？不要害怕，上帝已經聽見童子的聲音了。", "ja": "神はわらべの声を聞かれ、神の使は天からハガルを呼んで言った、「ハガルよ、どうしたのか。恐れてはいけない。神はあそこにいるわらべの声を聞かれた。"}, "18": {"en": "The angel of God called to Hagar out of the sky, and said to her, “What troubles you, Hagar? Don’t be afraid. For God has heard the voice of the boy where he is.   Get up, lift up the boy, and hold him with your hand. For I will make him a great nation.”", "zh": "起來！把童子抱在懷中，我必使他的後裔成為大國。」", "ja": "立って行き、わらべを取り上げてあなたの手に抱きなさい。わたしは彼を大いなる国民とするであろう」。"}, "19": {"en": "God opened her eyes, and she saw a well of water. She went, filled the container with water, and gave the boy a drink.", "zh": "上帝使夏甲的眼睛明亮，她就看見一口水井，便去將皮袋盛滿了水，給童子喝。", "ja": "神がハガルの目を開かれたので、彼女は水の井戸のあるのを見た。彼女は行って皮袋に水を満たし、わらべに飲ませた。"}, "20": {"en": "God was with the boy, and he grew. He lived in the wilderness, and as he grew up, he became an archer.", "zh": "上帝保佑童子，他就漸長，住在曠野，成了弓箭手。", "ja": "神はわらべと共にいまし、わらべは成長した。彼は荒野に住んで弓を射る者となった。"}, "21": {"en": "He lived in the wilderness of Paran. His mother got a wife for him out of the land of Egypt.", "zh": "他住在巴蘭的曠野；他母親從埃及地給他娶了一個妻子。", "ja": "彼はパランの荒野に住んだ。母は彼のためにエジプトの国から妻を迎えた。"}, "22": {"en": "At that time, Abimelech and Phicol the captain of his army spoke to Abraham, saying, “God is with you in all that you do.", "zh": "當那時候，亞比米勒同他軍長非各對亞伯拉罕說：「凡你所行的事都有上帝的保佑。", "ja": "そのころアビメレクとその軍勢の長ピコルはアブラハムに言った、「あなたが何事をなさっても、神はあなたと共におられる。"}, "23": {"en": "Now, therefore, swear to me here by God that you will not deal falsely with me, nor with my son, nor with my son’s son. But according to the kindness that I have done to you, you shall do to me, and to the land in which you have lived as a foreigner.”", "zh": "我願你如今在這裏指着上帝對我起誓，不要欺負我與我的兒子，並我的子孫。我怎樣厚待了你，你也要照樣厚待我與你所寄居這地的民。」", "ja": "それゆえ、今ここでわたしをも、わたしの子をも、孫をも欺かないと、神をさしてわたしに誓ってください。わたしがあなたに親切にしたように、あなたもわたしと、このあなたの寄留の地とに、しなければなりません」。"}, "24": {"en": "Abraham said, “I will swear.”", "zh": "亞伯拉罕說：「我情願起誓。」", "ja": "アブラハムは言った、「わたしは誓います」。"}, "25": {"en": "Abraham complained to Abimelech because of a water well, which Abimelech’s servants had violently taken away.", "zh": "從前，亞比米勒的僕人霸佔了一口水井，亞伯拉罕為這事指責亞比米勒。", "ja": "アブラハムはアビメレクの家来たちが、水の井戸を奪い取ったことについてアビメルクを責めた。"}, "26": {"en": "Abimelech said, “I don’t know who has done this thing. You didn’t tell me, and I didn’t hear of it until today.”", "zh": "亞比米勒說：「誰做這事，我不知道，你也沒有告訴我，今日我才聽見了。」", "ja": "しかしアビメレクは言った、「だれがこの事をしたかわたしは知りません。あなたもわたしに告げたことはなく、わたしもきょうまで聞きませんでした」。"}, "27": {"en": "Abraham took sheep and cattle, and gave them to Abimelech. Those two made a covenant.", "zh": "亞伯拉罕把羊和牛給了亞比米勒，二人就彼此立約。", "ja": "そこでアブラハムは羊と牛とを取ってアビメレクに与え、ふたりは契約を結んだ。"}, "28": {"en": "Abraham set seven ewe lambs of the flock by themselves.", "zh": "亞伯拉罕把七隻母羊羔另放在一處。", "ja": "アブラハムが雌の小羊七頭を分けて置いたところ、"}, "29": {"en": "Abimelech said to Abraham, “What do these seven ewe lambs, which you have set by themselves, mean?”", "zh": "亞比米勒問亞伯拉罕說：「你把這七隻母羊羔另放在一處，是甚麼意思呢？」", "ja": "アビメレクはアブラハムに言った、「あなたがこれらの雌の小羊七頭を分けて置いたのは、なんのためですか」。"}, "30": {"en": "He said, “You shall take these seven ewe lambs from my hand, that it may be a witness to me, that I have dug this well.”", "zh": "他說：「你要從我手裏受這七隻母羊羔，作我挖這口井的證據。」", "ja": "アブラハムは言った、「あなたはわたしの手からこれらの雌の小羊七頭を受け取って、わたしがこの井戸を掘ったことの証拠としてください」。"}, "31": {"en": "Therefore he called that place Beersheba, because they both swore an oath there.", "zh": "所以他給那地方起名叫別是巴，因為他們二人在那裏起了誓。", "ja": "これによってその所をベエルシバと名づけた。彼らがふたりそこで誓いをしたからである。"}, "32": {"en": "So they made a covenant at Beersheba. Abimelech rose up with Phicol, the captain of his army, and they returned into the land of the Philistines.", "zh": "他們在別是巴立了約，亞比米勒就同他軍長非各起身回非利士地去了。", "ja": "このように彼らはベエルシバで契約を結び、アビメレクとその軍勢の長ピコルは立ってペリシテの地に帰った。"}, "33": {"en": "Abraham planted a tamarisk tree in Beersheba, and there he called on the name of the LORD, the Everlasting God.", "zh": "亞伯拉罕在別是巴栽上一棵垂絲柳樹，又在那裏求告耶和華－永生上帝的名。", "ja": "アブラハムはベエルシバに一本のぎょりゅうの木を植え、その所で永遠の神、主の名を呼んだ。"}, "34": {"en": "Abraham lived as a foreigner in the land of the Philistines many days.", "zh": "亞伯拉罕在非利士人的地寄居了多日。", "ja": "こうしてアブラハムは長い間ペリシテびとの地にとどまった。"}}}, "22": {"verses": {"1": {"en": "After these things, God tested Abraham, and said to him, “Abraham!” He said, “Here I am.”", "zh": "這些事以後，上帝要試驗亞伯拉罕，就呼叫他說：「亞伯拉罕！」他說：「我在這裏。」", "ja": "これらの事の後、神はアブラハムを試みて彼に言われた、「アブラハムよ」。彼は言った、「ここにおります」。"}, "2": {"en": "He said, “Now take your son, your only son, Isaac, whom you love, and go into the land of Moriah. Offer him there as a burnt offering on one of the mountains which I will tell you of.”", "zh": "上帝說：「你帶着你的兒子，就是你獨生的兒子，你所愛的以撒，往摩利亞地去，在我所要指示你的山上，把他獻為燔祭。」", "ja": "神は言われた、「あなたの子、あなたの愛するひとり子イサクを連れてモリヤの地に行き、わたしが示す山で彼を燔祭としてささげなさい」。"}, "3": {"en": "Abraham rose early in the morning, and saddled his donkey; and took two of his young men with him, and Isaac his son. He split the wood for the burnt offering, and rose up, and went to the place of which God had told him.", "zh": "亞伯拉罕清早起來，備上驢，帶着兩個僕人和他兒子以撒，也劈好了燔祭的柴，就起身往上帝所指示他的地方去了。", "ja": "アブラハムは朝はやく起きて、ろばにくらを置き、ふたりの若者と、その子イサクとを連れ、また燔祭のたきぎを割り、立って神が示された所に出かけた。"}, "4": {"en": "On the third day Abraham lifted up his eyes, and saw the place far off.", "zh": "到了第三日，亞伯拉罕舉目遠遠地看見那地方。", "ja": "三日目に、アブラハムは目をあげて、はるかにその場所を見た。"}, "5": {"en": "Abraham said to his young men, “Stay here with the donkey. The boy and I will go over there. We will worship, and come back to you.”", "zh": "亞伯拉罕對他的僕人說：「你們和驢在此等候，我與童子往那裏去拜一拜，就回到你們這裏來。」", "ja": "そこでアブラハムは若者たちに言った、「あなたがたは、ろばと一緒にここにいなさい。わたしとわらべは向こうへ行って礼拝し、そののち、あなたがたの所に帰ってきます」。"}, "6": {"en": "Abraham took the wood of the burnt offering and laid it on Isaac his son. He took in his hand the fire and the knife. They both went together.", "zh": "亞伯拉罕把燔祭的柴放在他兒子以撒身上，自己手裏拿着火與刀；於是二人同行。", "ja": "アブラハムは燔祭のたきぎを取って、その子イサクに負わせ、手に火と刃物とを執って、ふたり一緒に行った。"}, "7": {"en": "Isaac spoke to Abraham his father, and said, “My father?” He said, “Here I am, my son.” He said, “Here is the fire and the wood, but where is the lamb for a burnt offering?”", "zh": "以撒對他父親亞伯拉罕說：「父親哪！」亞伯拉罕說：「我兒，我在這裏。」以撒說：「請看，火與柴都有了，但燔祭的羊羔在哪裏呢？」", "ja": "やがてイサクは父アブラハムに言った、「父よ」。彼は答えた、「子よ、わたしはここにいます」。イサクは言った、「火とたきぎとはありますが、燔祭の小羊はどこにありますか」。"}, "8": {"en": "Abraham said, “God will provide himself the lamb for a burnt offering, my son.” So they both went together.", "zh": "亞伯拉罕說：「我兒，上帝必自己預備作燔祭的羊羔。」於是二人同行。", "ja": "アブラハムは言った、「子よ、神みずから燔祭の小羊を備えてくださるであろう」。こうしてふたりは一緒に行った。"}, "9": {"en": "They came to the place which God had told him of. Abraham built the altar there, and laid the wood in order, bound Isaac his son, and laid him on the altar, on the wood.", "zh": "他們到了上帝所指示的地方，亞伯拉罕在那裏築壇，把柴擺好，捆綁他的兒子以撒，放在壇的柴上。", "ja": "彼らが神の示された場所にきたとき、アブラハムはそこに祭壇を築き、たきぎを並べ、その子イサクを縛って祭壇のたきぎの上に載せた。"}, "10": {"en": "Abraham stretched out his hand, and took the knife to kill his son.", "zh": "亞伯拉罕就伸手拿刀，要殺他的兒子。", "ja": "そしてアブラハムが手を差し伸べ、刃物を執ってその子を殺そうとした時、"}, "11": {"en": "The LORD’s angel called to him out of the sky, and said, “Abraham, Abraham!” He said, “Here I am.”", "zh": "耶和華的使者從天上呼叫他說：「亞伯拉罕！亞伯拉罕！」他說：「我在這裏。」", "ja": "主の使が天から彼を呼んで言った、「アブラハムよ、アブラハムよ」。彼は答えた、「はい、ここにおります」。"}, "12": {"en": "He said, “Don’t lay your hand on the boy or do anything to him. For now I know that you fear God, since you have not withheld your son, your only son, from me.”", "zh": "天使說：「你不可在這童子身上下手。一點不可害他！現在我知道你是敬畏上帝的了；因為你沒有將你的兒子，就是你獨生的兒子，留下不給我。」", "ja": "み使が言った、「わらべを手にかけてはならない。また何も彼にしてはならない。あなたの子、あなたのひとり子をさえ、わたしのために惜しまないので、あなたが神を恐れる者であることをわたしは今知った」。"}, "13": {"en": "Abraham lifted up his eyes, and looked, and saw that behind him was a ram caught in the thicket by his horns. Abraham went and took the ram, and offered him up for a burnt offering instead of his son.", "zh": "亞伯拉罕舉目觀看，不料，有一隻公羊，兩角扣在稠密的小樹中。亞伯拉罕就取了那隻公羊來，獻為燔祭，代替他的兒子。", "ja": "この時アブラハムが目をあげて見ると、うしろに、角をやぶに掛けている一頭の雄羊がいた。アブラハムは行ってその雄羊を捕え、それをその子のかわりに燔祭としてささげた。"}, "14": {"en": "Abraham called the name of that place “The LORD Will Provide”. As it is said to this day, “On the LORD’s mountain, it will be provided.”", "zh": "亞伯拉罕給那地方起名叫「耶和華以勒」，直到今日人還說：「在耶和華的山上必有預備。」", "ja": "それでアブラハムはその所の名をアドナイ・エレと呼んだ。これにより、人々は今日もなお「主の山に備えあり」と言う。"}, "15": {"en": "The LORD’s angel called to Abraham a second time out of the sky,", "zh": "耶和華的使者第二次從天上呼叫亞伯拉罕說：", "ja": "主の使は再び天からアブラハムを呼んで、"}, "16": {"en": "and said, “ ‘I have sworn by myself,’ says the LORD, ‘because you have done this thing, and have not withheld your son, your only son,", "zh": "「耶和華說：『你既行了這事，不留下你的兒子，就是你獨生的兒子，我便指着自己起誓說：", "ja": "言った、「主は言われた、『わたしは自分をさして誓う。あなたがこの事をし、あなたの子、あなたのひとり子をも惜しまなかったので、"}, "17": {"en": "that I will bless you greatly, and I will multiply your offspring greatly like the stars of the heavens, and like the sand which is on the seashore. Your offspring will possess the gate of his enemies.", "zh": "論福，我必賜大福給你；論子孫，我必叫你的子孫多起來，如同天上的星，海邊的沙。你子孫必得着仇敵的城門，", "ja": "わたしは大いにあなたを祝福し、大いにあなたの子孫をふやして、天の星のように、浜べの砂のようにする。あなたの子孫は敵の門を打ち取り、"}, "18": {"en": "All the nations of the earth will be blessed by your offspring, because you have obeyed my voice.’ ”", "zh": "並且地上萬國都必因你的後裔得福，因為你聽從了我的話。』」", "ja": "また地のもろもろの国民はあなたの子孫によって祝福を得るであろう。あなたがわたしの言葉に従ったからである』」。"}, "19": {"en": "So Abraham returned to his young men, and they rose up and went together to Beersheba. Abraham lived at Beersheba.", "zh": "於是亞伯拉罕回到他僕人那裏，他們一同起身往別是巴去，亞伯拉罕就住在別是巴。", "ja": "アブラハムは若者たちの所に帰り、みな立って、共にベエルシバへ行った。そしてアブラハムはベエルシバに住んだ。"}, "20": {"en": "After these things, Abraham was told, “Behold, Milcah, she also has borne children to your brother Nahor:", "zh": "這事以後，有人告訴亞伯拉罕說：「密迦給你兄弟拿鶴生了幾個兒子，", "ja": "これらの事の後、ある人がアブラハムに告げて言った、「ミルカもまたあなたの兄弟ナホルに子どもを産みました。"}, "21": {"en": "Uz his firstborn, Buz his brother, Kemuel the father of Aram,", "zh": "長子是烏斯，他的兄弟是布斯和亞蘭的父親基母利，", "ja": "長男はウヅ、弟はブズ、次はアラムの父ケムエル、"}, "22": {"en": "Chesed, Hazo, Pildash, Jidlaph, and Bethuel.”", "zh": "並基薛、哈瑣、必達、益拉、彼土利（彼土利生利百加）。」", "ja": "次はケセデ、ハゾ、ピルダシ、エデラフ、ベトエルです」。"}, "23": {"en": "Bethuel became the father of Rebekah. These eight Milcah bore to Nahor, Abraham’s brother.", "zh": "這八個人都是密迦給亞伯拉罕的兄弟拿鶴生的。", "ja": "ベトエルの子はリベカであって、これら八人はミルカがアブラハムの兄弟ナホルに産んだのである。"}, "24": {"en": "His concubine, whose name was Reumah, also bore Tebah, Gaham, Tahash, and Maacah.", "zh": "拿鶴的妾名叫流瑪，生了提八、迦含、他轄，和瑪迦。", "ja": "ナホルのそばめで、名をルマという女もまたテバ、ガハム、タハシおよびマアカを産んだ。"}}}, "23": {"verses": {"1": {"en": "Sarah lived one hundred twenty-seven years. This was the length of Sarah’s life.", "zh": "撒拉享壽一百二十七歲，這是撒拉一生的歲數。", "ja": "サラの一生は百二十七年であった。これがサラの生きながらえた年である。"}, "2": {"en": "Sarah died in Kiriath Arba (also called Hebron), in the land of Canaan. Abraham came to mourn for Sarah, and to weep for her.", "zh": "撒拉死在迦南地的基列‧亞巴，就是希伯崙。亞伯拉罕為她哀慟哭號。", "ja": "サラはカナンの地のキリアテ・アルバすなわちヘブロンで死んだ。アブラハムは中にはいってサラのために悲しみ泣いた。"}, "3": {"en": "Abraham rose up from before his dead and spoke to the children of Heth, saying,", "zh": "後來亞伯拉罕從死人面前起來，對赫人說：", "ja": "アブラハムは死人のそばから立って、ヘテの人々に言った、"}, "4": {"en": "“I am a stranger and a foreigner living with you. Give me a possession of a burying-place with you, that I may bury my dead out of my sight.”", "zh": "「我在你們中間是外人，是寄居的。求你們在這裏給我一塊地，我好埋葬我的死人，使她不在我眼前。」", "ja": "「わたしはあなたがたのうちの旅の者で寄留者ですが、わたしの死人を出して葬るため、あなたがたのうちにわたしの所有として一つの墓地をください」。"}, "5": {"en": "The children of Heth answered Abraham, saying to him,", "zh": "赫人回答亞伯拉罕說：", "ja": "ヘテの人々はアブラハムに答えて言った、"}, "6": {"en": "“Hear us, my lord. You are a prince of God among us. Bury your dead in the best of our tombs. None of us will withhold from you his tomb. Bury your dead.”", "zh": "「我主請聽。你在我們中間是一位尊大的王子，只管在我們最好的墳地裏埋葬你的死人；我們沒有一人不容你在他的墳地裏埋葬你的死人。」", "ja": "「わが主よ、お聞きなさい。あなたはわれわれのうちにおられて、神のような主君です。われわれの墓地の最も良い所にあなたの死人を葬りなさい。その墓地を拒んで、あなたにその死人を葬らせない者はわれわれのうちには、ひとりもないでしょう」。"}, "7": {"en": "Abraham rose up, and bowed himself to the people of the land, to the children of Heth.", "zh": "亞伯拉罕就起來，向那地的赫人下拜，", "ja": "アブラハムは立ちあがり、その地の民ヘテの人々に礼をして、"}, "8": {"en": "He talked with them, saying, “If you agree that I should bury my dead out of my sight, hear me, and entreat for me to Ephron the son of Zohar,", "zh": "對他們說：「你們若有意叫我埋葬我的死人，使她不在我眼前，就請聽我的話，為我求瑣轄的兒子以弗崙，", "ja": "彼らに言った、「もしわたしの死人を葬るのに同意されるなら、わたしの願いをいれて、わたしのためにゾハルの子エフロンに頼み、"}, "9": {"en": "that he may sell me the cave of Machpelah, which he has, which is in the end of his field. For the full price let him sell it to me among you as a possession for a burial place.”", "zh": "把田頭上那麥比拉洞給我，他可以按着足價賣給我，作我在你們中間的墳地。」", "ja": "彼が持っている畑の端のマクペラのほら穴をじゅうぶんな代価でわたしに与え、あなたがたのうちに墓地を持たせてください」。"}, "10": {"en": "Now Ephron was sitting in the middle of the children of Heth. Ephron the Hittite answered Abraham in the hearing of the children of Heth, even of all who went in at the gate of his city, saying,", "zh": "當時以弗崙正坐在赫人中間。於是，赫人以弗崙在城門出入的赫人面前對亞伯拉罕說：", "ja": "時にエフロンはヘテの人々のうちにすわっていた。そこでヘテびとエフロンはヘテの人々、すなわちすべてその町の門にはいる人々の聞いているところで、アブラハムに答えて言った、"}, "11": {"en": "“No, my lord, hear me. I give you the field, and I give you the cave that is in it. In the presence of the children of my people I give it to you. Bury your dead.”", "zh": "「不然，我主請聽。我送給你這塊田，連田間的洞也送給你，在我同族的人面前都給你，可以埋葬你的死人。」", "ja": "「いいえ、わが主よ、お聞きなさい。わたしはあの畑をあなたにさしあげます。またその中にあるほら穴もさしあげます。わたしの民の人々の前で、それをさしあげます。あなたの死人を葬りなさい」。"}, "12": {"en": "Abraham bowed himself down before the people of the land.", "zh": "亞伯拉罕就在那地的人民面前下拜，", "ja": "アブラハムはその地の民の前で礼をし、"}, "13": {"en": "He spoke to Ephron in the audience of the people of the land, saying, “But if you will, please hear me. I will give the price of the field. Take it from me, and I will bury my dead there.”", "zh": "在他們面前對以弗崙說：「你若應允，請聽我的話。我要把田價給你，求你收下，我就在那裏埋葬我的死人。」", "ja": "その地の民の聞いているところでエフロンに言った、「あなたがそれを承諾されるなら、お聞きなさい。わたしはその畑の代価を払います。お受け取りください。わたしの死人をそこに葬りましょう」。"}, "14": {"en": "Ephron answered Abraham, saying to him,", "zh": "以弗崙回答亞伯拉罕說：", "ja": "エフロンはアブラハムに答えて言った、"}, "15": {"en": "“My lord, listen to me. What is a piece of land worth four hundred shekels of silver between me and you? Therefore bury your dead.”", "zh": "「我主請聽。值四百舍客勒銀子的一塊田，在你我中間還算甚麼呢？只管埋葬你的死人吧！」", "ja": "「わが主よ、お聞きなさい。あの地は銀四百シケルですが、これはわたしとあなたの間で、なにほどのことでしょう。あなたの死人を葬りなさい」。"}, "16": {"en": "Abraham listened to Ephron. Abraham weighed to Ephron the silver which he had named in the hearing of the children of Heth, four hundred shekels of silver, according to the current merchants’ standard.", "zh": "亞伯拉罕聽從了以弗崙，照着他在赫人面前所說的話，把買賣通用的銀子平了四百舍客勒給以弗崙。", "ja": "そこでアブラハムはエフロンの言葉にしたがい、エフロンがヘテの人々の聞いているところで言った銀、すなわち商人の通用銀四百シケルを量ってエフロンに与えた。"}, "17": {"en": "So the field of Ephron, which was in Machpelah, which was before Mamre, the field, the cave which was in it, and all the trees that were in the field, that were in all of its borders, were deeded", "zh": "於是，麥比拉、幔利前、以弗崙的那塊田和其中的洞，並田間四圍的樹木，", "ja": "こうしてマムレの前のマクペラにあるエフロンの畑は、畑も、その中のほら穴も、畑の中およびその周囲の境にあるすべての木も皆、"}, "18": {"en": "to Abraham for a possession in the presence of the children of Heth, before all who went in at the gate of his city.", "zh": "都定準歸與亞伯拉罕，乃是他在赫人面前並城門出入的人面前買妥的。", "ja": "ヘテの人々の前、すなわちその町の門にはいるすべての人々の前で、アブラハムの所有と決まった。"}, "19": {"en": "After this, Abraham buried Sarah his wife in the cave of the field of Machpelah before Mamre (that is, Hebron), in the land of Canaan.", "zh": "此後，亞伯拉罕把他妻子撒拉埋葬在迦南地幔利前的麥比拉田間的洞裏。（幔利就是希伯崙）。", "ja": "その後、アブラハムはその妻サラをカナンの地にあるマムレ、すなわちヘブロンの前のマクペラの畑のほら穴に葬った。"}, "20": {"en": "The field, and the cave that is in it, were deeded to Abraham by the children of Heth as a possession for a burial place.", "zh": "從此，那塊田和田間的洞就藉着赫人定準歸與亞伯拉罕作墳地。", "ja": "このように畑とその中にあるほら穴とはヘテの人々によってアブラハムの所有の墓地と定められた。"}}}, "24": {"verses": {"1": {"en": "Abraham was old, and well advanced in age. The LORD had blessed Abraham in all things.", "zh": "亞伯拉罕年紀老邁，向來在一切事上耶和華都賜福給他。", "ja": "アブラハムは年が進んで老人となった。主はすべての事にアブラハムを恵まれた。"}, "2": {"en": "Abraham said to his servant, the elder of his house, who ruled over all that he had, “Please put your hand under my thigh.", "zh": "亞伯拉罕對管理他全業最老的僕人說：「請你把手放在我大腿底下。", "ja": "さてアブラハムは所有のすべてを管理させていた家の年長のしもべに言った、「あなたの手をわたしのももの下に入れなさい。"}, "3": {"en": "I will make you swear by the LORD, the God of heaven and the God of the earth, that you shall not take a wife for my son of the daughters of the Canaanites, among whom I live.", "zh": "我要叫你指着耶和華－天地的主起誓，不要為我兒子娶這迦南地中的女子為妻。", "ja": "わたしはあなたに天地の神、主をさして誓わせる。あなたはわたしが今一緒に住んでいるカナンびとのうちから、娘をわたしの子の妻にめとってはならない。"}, "4": {"en": "But you shall go to my country, and to my relatives, and take a wife for my son Isaac.”", "zh": "你要往我本地本族去，為我的兒子以撒娶一個妻子。」", "ja": "あなたはわたしの国へ行き、親族の所へ行って、わたしの子イサクのために妻をめとらなければならない」。"}, "5": {"en": "The servant said to him, “What if the woman isn’t willing to follow me to this land? Must I bring your son again to the land you came from?”", "zh": "僕人對他說：「倘若女子不肯跟我到這地方來，我必須將你的兒子帶回你原出之地嗎？」", "ja": "しもべは彼に言った、「もしその女がわたしについてこの地に来ることを好まない時は、わたしはあなたの子をあなたの出身地に連れ帰るべきでしょうか」。"}, "6": {"en": "Abraham said to him, “Beware that you don’t bring my son there again.", "zh": "亞伯拉罕對他說：「你要謹慎，不要帶我的兒子回那裏去。", "ja": "アブラハムは彼に言った、「わたしの子は決して向こうへ連れ帰ってはならない。"}, "7": {"en": "The LORD, the God of heaven—who took me from my father’s house, and from the land of my birth, who spoke to me, and who swore to me, saying, ‘I will give this land to your offspring—he will send his angel before you, and you shall take a wife for my son from there.", "zh": "耶和華－天上的主曾帶領我離開父家和本族的地，對我說話，向我起誓說：『我要將這地賜給你的後裔。』他必差遣使者在你面前，你就可以從那裏為我兒子娶一個妻子。", "ja": "天の神、主はわたしを父の家、親族の地から導き出してわたしに語り、わたしに誓って、おまえの子孫にこの地を与えると言われた。主は、み使をあなたの前につかわされるであろう。あなたはあそこからわたしの子に妻をめとらねばならない。"}, "8": {"en": "If the woman isn’t willing to follow you, then you shall be clear from this oath to me. Only you shall not bring my son there again.”", "zh": "倘若女子不肯跟你來，我使你起的誓就與你無干了，只是不可帶我的兒子回那裏去。」", "ja": "けれどもその女があなたについて来ることを好まないなら、あなたはこの誓いを解かれる。ただわたしの子を向こうへ連れ帰ってはならない」。"}, "9": {"en": "The servant put his hand under the thigh of Abraham his master, and swore to him concerning this matter.", "zh": "僕人就把手放在他主人亞伯拉罕的大腿底下，為這事向他起誓。", "ja": "そこでしもべは手を主人アブラハムのももの下に入れ、この事について彼に誓った。"}, "10": {"en": "The servant took ten of his master’s camels, and departed, having a variety of good things of his master’s with him. He arose, and went to Mesopotamia, to the city of Nahor.", "zh": "那僕人從他主人的駱駝裏取了十匹駱駝，並帶些他主人各樣的財物，起身往美索不達米亞去，到了拿鶴的城。", "ja": "しもべは主人のらくだのうちから十頭のらくだを取って出かけた。すなわち主人のさまざまの良い物を携え、立ってアラム・ナハライムにむかい、ナホルの町へ行った。"}, "11": {"en": "He made the camels kneel down outside the city by the well of water at the time of evening, the time that women go out to draw water.", "zh": "天將晚，眾女子出來打水的時候，他便叫駱駝跪在城外的水井那裏。", "ja": "彼はらくだを町の外の、水の井戸のそばに伏させた。時は夕暮で、女たちが水をくみに出る時刻であった。"}, "12": {"en": "He said, “LORD, the God of my master Abraham, please give me success today, and show kindness to my master Abraham.", "zh": "他說：「耶和華－我主人亞伯拉罕的上帝啊，求你施恩給我主人亞伯拉罕，使我今日遇見好機會。", "ja": "彼は言った、「主人アブラハムの神、主よ、どうか、きょう、わたしにしあわせを授け、主人アブラハムに恵みを施してください。"}, "13": {"en": "Behold, I am standing by the spring of water. The daughters of the men of the city are coming out to draw water.", "zh": "我現今站在井旁，城內居民的女子們正出來打水。", "ja": "わたしは泉のそばに立っています。町の人々の娘たちが水をくみに出てきたとき、"}, "14": {"en": "Let it happen, that the young lady to whom I will say, ‘Please let down your pitcher, that I may drink,’ then she says, ‘Drink, and I will also give your camels a drink,’—let her be the one you have appointed for your servant Isaac. By this I will know that you have shown kindness to my master.”", "zh": "我向那一個女子說：『請你拿下水瓶來，給我水喝。』她若說：『請喝！我也給你的駱駝喝。』願那女子就作你所預定給你僕人以撒的妻。這樣，我便知道你施恩給我主人了。」", "ja": "娘に向かって『お願いです、あなたの水がめを傾けてわたしに飲ませてください』と言い、娘が答えて、『お飲みください。あなたのらくだにも飲ませましょう』と言ったなら、その者こそ、あなたがしもべイサクのために定められた者ということにしてください。わたしはこれによって、あなたがわたしの主人に恵みを施されることを知りましょう」。"}, "15": {"en": "Before he had finished speaking, behold, Rebekah came out, who was born to Bethuel the son of Milcah, the wife of Nahor, Abraham’s brother, with her pitcher on her shoulder.", "zh": "話還沒有說完，不料，利百加肩頭上扛着水瓶出來。利百加是彼土利所生的；彼土利是亞伯拉罕兄弟拿鶴妻子密迦的兒子。", "ja": "彼がまだ言い終らないうちに、アブラハムの兄弟ナホルの妻ミルカの子ベトエルの娘リベカが、水がめを肩に載せて出てきた。"}, "16": {"en": "The young lady was very beautiful to look at, a virgin. No man had known her. She went down to the spring, filled her pitcher, and came up.", "zh": "那女子容貌極其俊美，還是處女，也未曾有人親近她。她下到井旁，打滿了瓶，又上來。", "ja": "その娘は非常に美しく、男を知らぬ処女であった。彼女が泉に降りて、水がめを満たし、上がってきた時、"}, "17": {"en": "The servant ran to meet her, and said, “Please give me a drink, a little water from your pitcher.”", "zh": "僕人跑上前去迎着她，說：「求你將瓶裏的水給我一點喝。」", "ja": "しもべは走り寄って、彼女に会って言った、「お願いです。あなたの水がめの水を少し飲ませてください」。"}, "18": {"en": "She said, “Drink, my lord.” She hurried, and let down her pitcher on her hand, and gave him a drink.", "zh": "女子說：「我主請喝！」就急忙拿下瓶來，托在手上給他喝。", "ja": "すると彼女は「わが主よ、お飲みください」と言って、急いで水がめを自分の手に取りおろして彼に飲ませた。"}, "19": {"en": "When she had finished giving him a drink, she said, “I will also draw for your camels, until they have finished drinking.”", "zh": "女子給他喝了，就說：「我再為你的駱駝打水，叫駱駝也喝足。」", "ja": "飲ませ終って、彼女は言った、「あなたのらくだもみな飲み終るまで、わたしは水をくみましょう」。"}, "20": {"en": "She hurried, and emptied her pitcher into the trough, and ran again to the well to draw, and drew for all his camels.", "zh": "她就急忙把瓶裏的水倒在槽裏，又跑到井旁打水，就為所有的駱駝打上水來。", "ja": "彼女は急いでかめの水を水ぶねにあけ、再び水をくみに井戸に走って行って、すべてのらくだのために水をくんだ。"}, "21": {"en": "The man looked steadfastly at her, remaining silent, to know whether the LORD had made his journey prosperous or not.", "zh": "那人定睛看她，一句話也不說，要曉得耶和華賜他通達的道路沒有。", "ja": "その間その人は主が彼の旅の祝福されるか、どうかを知ろうと、黙って彼女を見つめていた。"}, "22": {"en": "As the camels had finished drinking, the man took a golden ring of half a shekel weight, and two bracelets for her hands of ten shekels weight of gold,", "zh": "駱駝喝足了，那人就拿一個金環，重半舍客勒，兩個金鐲，重十舍客勒，給了那女子，", "ja": "らくだが飲み終ったとき、その人は重さ半シケルの金の鼻輪一つと、重さ十シケルの金の腕輪二つを取って、"}, "23": {"en": "and said, “Whose daughter are you? Please tell me. Is there room in your father’s house for us to stay?”", "zh": "說：「請告訴我，你是誰的女兒？你父親家裏有我們住宿的地方沒有？」", "ja": "言った、「あなたはだれの娘か、わたしに話してください。あなたの父の家にわたしどもの泊まる場所がありましょうか」。"}, "24": {"en": "She said to him, “I am the daughter of Bethuel the son of Milcah, whom she bore to Nahor.”", "zh": "女子說：「我是密迦與拿鶴之子彼土利的女兒」；", "ja": "彼女は彼に言った、「わたしはナホルの妻ミルカの子ベトエルの娘です」。"}, "25": {"en": "She said moreover to him, “We have both straw and feed enough, and room to lodge in.”", "zh": "又說：「我們家裏足有糧草，也有住宿的地方。」", "ja": "また彼に言った、「わたしどもには、わらも、飼葉もたくさんあります。また泊まる場所もあります」。"}, "26": {"en": "The man bowed his head, and worshiped the LORD.", "zh": "那人就低頭向耶和華下拜，", "ja": "その人は頭を下げ、主を拝して、"}, "27": {"en": "He said, “Blessed be the LORD, the God of my master Abraham, who has not forsaken his loving kindness and his truth toward my master. As for me, the LORD has led me on the way to the house of my master’s relatives.”", "zh": "說：「耶和華－我主人亞伯拉罕的上帝是應當稱頌的，因他不斷地以慈愛誠實待我主人。至於我，耶和華在路上引領我，直走到我主人的兄弟家裏。」", "ja": "言った、「主人アブラハムの神、主はほむべきかな。主はわたしの主人にいつくしみと、まこととを惜しまれなかった。そして主は旅にあるわたしを主人の兄弟の家に導かれた」。"}, "28": {"en": "The young lady ran, and told her mother’s house about these words.", "zh": "女子跑回去，照着這些話告訴她母親和她家裏的人。   29-", "ja": "娘は走って行って、母の家のものにこれらの事を告げた。"}, "29": {"en": "Rebekah had a brother, and his name was Laban. Laban ran out to the man, to the spring.", "zh": "", "ja": "リベカにひとりの兄があって、名をラバンといった。ラバンは泉のそばにいるその人の所へ走って行った。"}, "30": {"en": "When he saw the ring, and the bracelets on his sister’s hands, and when he heard the words of Rebekah his sister, saying, “This is what the man said to me,” he came to the man. Behold, he was standing by the camels at the spring.", "zh": "利百加有一個哥哥，名叫拉班，看見金環，又看見金鐲在他妹子的手上，並聽見他妹子利百加的話，說那人對我如此如此說。拉班就跑出來往井旁去，到那人跟前，見他仍站在駱駝旁邊的井旁那裏，", "ja": "彼は鼻輪と妹の手にある腕輪とを見、また妹リベカが「その人はわたしにこう言った」というのを聞いて、その人の所へ行ってみると、その人は泉のほとりで、らくだのそばに立っていた。"}, "31": {"en": "He said, “Come in, you blessed of the LORD. Why do you stand outside? For I have prepared the house, and room for the camels.”", "zh": "便對他說：「你這蒙耶和華賜福的，請進來，為甚麼站在外邊？我已經收拾了房屋，也為駱駝預備了地方。」", "ja": "そこでその人に言った、「主に祝福された人よ、おはいりください。なぜ外に立っておられますか。わたしは家を準備し、らくだのためにも場所を準備しておきました」。"}, "32": {"en": "The man came into the house, and he unloaded the camels. He gave straw and feed for the camels, and water to wash his feet and the feet of the men who were with him.", "zh": "那人就進了拉班的家。拉班卸了駱駝，用草料餵上，拿水給那人和跟隨的人洗腳；", "ja": "その人は家にはいった。ラバンはらくだの荷を解いて、わらと飼葉をらくだに与え、また水を与えてその人の足と、その従者たちの足を洗わせた。"}, "33": {"en": "Food was set before him to eat, but he said, “I will not eat until I have told my message.” Laban said, “Speak on.”", "zh": "把飯擺在他面前，叫他吃，他卻說：「我不吃，等我說明白我的事情再吃。」拉班說：「請說。」", "ja": "そして彼の前に食物を供えたが、彼は言った、「わたしは用向きを話すまでは食べません」。ラバンは言った、「お話しください」。"}, "34": {"en": "He said, “I am Abraham’s servant.", "zh": "他說：「我是亞伯拉罕的僕人。", "ja": "そこで彼は言った、「わたしはアブラハムのしもべです。"}, "35": {"en": "The LORD has blessed my master greatly. He has become great. The LORD has given him flocks and herds, silver and gold, male servants and female servants, and camels and donkeys.", "zh": "耶和華大大地賜福給我主人，使他昌大，又賜給他羊群、牛群、金銀、僕婢、駱駝，和驢。", "ja": "主はわたしの主人を大いに祝福して、大いなる者とされました。主はまた彼に羊、牛、銀、金、男女の奴隷、らくだ、ろばを与えられました。"}, "36": {"en": "Sarah, my master’s wife, bore a son to my master when she was old. He has given all that he has to him.", "zh": "我主人的妻子撒拉年老的時候給我主人生了一個兒子；我主人也將一切所有的都給了這個兒子。", "ja": "主人の妻サラは年老いてから、主人に男の子を産みました。主人はその所有を皆これに与えました。"}, "37": {"en": "My master made me swear, saying, ‘You shall not take a wife for my son from the daughters of the Canaanites, in whose land I live,", "zh": "我主人叫我起誓說：『你不要為我兒子娶迦南地的女子為妻。", "ja": "ところで主人はわたしに誓わせて言いました、『わたしの住んでいる地のカナンびとの娘を、わたしの子の妻にめとってはならない。"}, "38": {"en": "but you shall go to my father’s house, and to my relatives, and take a wife for my son.’", "zh": "你要往我父家、我本族那裏去，為我的兒子娶一個妻子。』", "ja": "おまえはわたしの父の家、親族の所へ行って、わたしの子に妻をめとらなければならない』。"}, "39": {"en": "I asked my master, ‘What if the woman will not follow me?’", "zh": "我對我主人說：『恐怕女子不肯跟我來。』", "ja": "わたしは主人に言いました、『もしその女がわたしについてこない時はどういたしましょうか』。"}, "40": {"en": "He said to me, ‘The LORD, before whom I walk, will send his angel with you, and prosper your way. You shall take a wife for my son from my relatives, and of my father’s house.", "zh": "他就說：『我所事奉的耶和華必要差遣他的使者與你同去，叫你的道路通達，你就得以在我父家、我本族那裏，給我的兒子娶一個妻子。", "ja": "主人はわたしに言いました、『わたしの仕えている主は、み使をおまえと一緒につかわして、おまえの旅にさいわいを与えられるであろう。おまえはわたしの親族、わたしの父の家からわたしの子に妻をめとらなければならない。"}, "41": {"en": "Then you will be clear from my oath, when you come to my relatives. If they don’t give her to you, you shall be clear from my oath.’", "zh": "只要你到了我本族那裏，我使你起的誓就與你無干。他們若不把女子交給你，我使你起的誓也與你無干。』", "ja": "そのとき、おまえはわたしにした誓いから解かれるであろう。またおまえがわたしの親族に行く時、彼らがおまえにその娘を与えないなら、おまえはわたしにした誓いから解かれるであろう』。"}, "42": {"en": "I came today to the spring, and said, ‘The LORD, the God of my master Abraham, if now you do prosper my way which I go—", "zh": "「我今日到了井旁，便說：『耶和華－我主人亞伯拉罕的上帝啊，願你叫我所行的道路通達。", "ja": "わたしはきょう、泉のところにきて言いました、『主人アブラハムの神、主よ、どうか今わたしのゆく道にさいわいを与えてください。"}, "43": {"en": "behold, I am standing by this spring of water. Let it happen, that the maiden who comes out to draw, to whom I will say, “Please give me a little water from your pitcher to drink,”", "zh": "我如今站在井旁，對哪一個出來打水的女子說：請你把你瓶裏的水給我一點喝；", "ja": "わたしはこの泉のそばに立っていますが、水をくみに出てくる娘に向かって、「お願いです。あなたの水がめの水を少し飲ませてください」と言い、"}, "44": {"en": "then she tells me, “Drink, and I will also draw for your camels,”—let her be the woman whom the LORD has appointed for my master’s son.’", "zh": "她若說：你只管喝，我也為你的駱駝打水；願那女子就作耶和華給我主人兒子所預定的妻。』", "ja": "「お飲みください。あなたのらくだのためにも、くみましょう」とわたしに言うなら、その娘こそ、主がわたしの主人の子のために定められた女ということにしてください』。"}, "45": {"en": "Before I had finished speaking in my heart, behold, Rebekah came out with her pitcher on her shoulder. She went down to the spring, and drew. I said to her, ‘Please let me drink.’", "zh": "我心裏的話還沒有說完，利百加就出來，肩頭上扛着水瓶，下到井旁打水。我便對她說：『請你給我水喝。』", "ja": "わたしが心のうちでそう言い終らないうちに、リベカが水がめを肩に載せて出てきて、水をくみに泉に降りたので、わたしは『お願いです、飲ませてください』と言いますと、"}, "46": {"en": "She hurried and let down her pitcher from her shoulder, and said, ‘Drink, and I will also give your camels a drink.’ So I drank, and she also gave the camels a drink.", "zh": "她就急忙從肩頭上拿下瓶來，說：『請喝！我也給你的駱駝喝。』我便喝了；她又給我的駱駝喝了。", "ja": "彼女は急いで水がめを肩からおろし、『お飲みください。わたしはあなたのらくだにも飲ませましょう』と言いました。それでわたしは飲みましたが、彼女はらくだにも飲ませました。"}, "47": {"en": "I asked her, and said, ‘Whose daughter are you?’ She said, ‘The daughter of Bethuel, Nahor’s son, whom Milcah bore to him.’ I put the ring on her nose, and the bracelets on her hands.", "zh": "我問她說：『你是誰的女兒？』她說：『我是密迦與拿鶴之子彼土利的女兒。』我就把環子戴在她鼻子上，把鐲子戴在她兩手上。", "ja": "わたしは彼女に尋ねて、『あなたはだれの娘ですか』と言いますと、『ナホルとその妻ミルカの子ベトエルの娘です』と答えました。そこでわたしは彼女の鼻に鼻輪をつけ、手に腕輪をつけました。"}, "48": {"en": "I bowed my head, and worshiped the LORD, and blessed the LORD, the God of my master Abraham, who had led me in the right way to take my master’s brother’s daughter for his son.", "zh": "隨後我低頭向耶和華下拜，稱頌耶和華－我主人亞伯拉罕的上帝；因為他引導我走合式的道路，使我得着我主人兄弟的孫女，給我主人的兒子為妻。", "ja": "そしてわたしは頭をさげて主を拝し、主人アブラハムの神、主をほめたたえました。主は主人の兄弟の娘を子にめとらせようと、わたしを正しい道に導かれたからです。"}, "49": {"en": "Now if you will deal kindly and truly with my master, tell me. If not, tell me, that I may turn to the right hand, or to the left.”", "zh": "現在你們若願以慈愛誠實待我主人，就告訴我；若不然，也告訴我，使我可以或向左，或向右。」", "ja": "あなたがたが、もしわたしの主人にいつくしみと、まことを尽そうと思われるなら、そうとわたしにお話しください。そうでなければ、そうでないとお話しください。それによってわたしは右か左に決めましょう」。"}, "50": {"en": "Then Laban and Bethuel answered, “The thing proceeds from the LORD. We can’t speak to you bad or good.", "zh": "拉班和彼土利回答說：「這事乃出於耶和華，我們不能向你說好說歹。", "ja": "ラバンとベトエルは答えて言った、「この事は主から出たことですから、わたしどもはあなたによしあしを言うことができません。"}, "51": {"en": "Behold, Rebekah is before you. Take her, and go, and let her be your master’s son’s wife, as the LORD has spoken.”", "zh": "看哪，利百加在你面前，可以將她帶去，照着耶和華所說的，給你主人的兒子為妻。」", "ja": "リベカがここにおりますから連れて行って、主が言われたように、あなたの主人の子の妻にしてください」。"}, "52": {"en": "When Abraham’s servant heard their words, he bowed himself down to the earth to the LORD.", "zh": "亞伯拉罕的僕人聽見他們這話，就向耶和華俯伏在地。", "ja": "アブラハムのしもべは彼らの言葉を聞いて、地に伏し、主を拝した。"}, "53": {"en": "The servant brought out jewels of silver, and jewels of gold, and clothing, and gave them to Rebekah. He also gave precious things to her brother and her mother.", "zh": "當下僕人拿出金器、銀器，和衣服送給利百加，又將寶物送給她哥哥和她母親。", "ja": "そしてしもべは銀の飾りと、金の飾り、および衣服を取り出してリベカに与え、その兄と母とにも価の高い品々を与えた。"}, "54": {"en": "They ate and drank, he and the men who were with him, and stayed all night. They rose up in the morning, and he said, “Send me away to my master.”", "zh": "僕人和跟從他的人吃了喝了，住了一夜。早晨起來，僕人就說：「請打發我回我主人那裏去吧。」", "ja": "彼と従者たちは飲み食いして宿ったが、あくる朝彼らが起きた時、しもべは言った、「わたしを主人のもとに帰らせてください」。"}, "55": {"en": "Her brother and her mother said, “Let the young lady stay with us a few days, at least ten. After that she will go.”", "zh": "利百加的哥哥和她母親說：「讓女子同我們再住幾天，至少十天，然後她可以去。」", "ja": "リベカの兄と母とは言った、「娘は数日、少なくとも十日、わたしどもと共にいて、それから行かせましょう」。"}, "56": {"en": "He said to them, “Don’t hinder me, since the LORD has prospered my way. Send me away that I may go to my master.”", "zh": "僕人說：「耶和華既賜給我通達的道路，你們不要耽誤我，請打發我走，回我主人那裏去吧。」", "ja": "しもべは彼らに言った、「主はわたしの道にさいわいを与えられましたから、わたしを引きとめずに、主人のもとに帰らせてください」。"}, "57": {"en": "They said, “We will call the young lady, and ask her.”", "zh": "他們說：「我們把女子叫來問問她」，", "ja": "彼らは言った、「娘を呼んで聞いてみましょう」。"}, "58": {"en": "They called Rebekah, and said to her, “Will you go with this man?” She said, “I will go.”", "zh": "就叫了利百加來，問她說：「你和這人同去嗎？」利百加說：「我去。」", "ja": "彼らはリベカを呼んで言った、「あなたはこの人と一緒に行きますか」。彼女は言った、「行きます」。"}, "59": {"en": "They sent away Rebekah, their sister, with her nurse, Abraham’s servant, and his men.", "zh": "於是他們打發妹子利百加和她的乳母，同亞伯拉罕的僕人，並跟從僕人的，都走了。", "ja": "そこで彼らは妹リベカと、そのうばと、アブラハムのしもべと、その従者とを送り去らせた。"}, "60": {"en": "They blessed Rebekah, and said to her, “Our sister, may you be the mother of thousands of ten thousands, and let your offspring possess the gate of those who hate them.”", "zh": "他們就給利百加祝福說： 我們的妹子啊，願你作千萬人的母！ 願你的後裔得着仇敵的城門！", "ja": "彼らはリベカを祝福して彼女に言った、「妹よ、あなたは、ちよろずの人の母となれ。あなたの子孫はその敵の門を打ち取れ」。"}, "61": {"en": "Rebekah arose with her ladies. They rode on the camels, and followed the man. The servant took Rebekah, and went his way.", "zh": "利百加和她的使女們起來，騎上駱駝，跟着那僕人，僕人就帶着利百加走了。", "ja": "リベカは立って侍女たちと共にらくだに乗り、その人に従って行った。しもべはリベカを連れて立ち去った。"}, "62": {"en": "Isaac came from the way of Beer Lahai Roi, for he lived in the land of the South.", "zh": "那時，以撒住在南地，剛從庇耳‧拉海‧萊回來。", "ja": "さてイサクはベエル・ラハイ・ロイからきて、ネゲブの地に住んでいた。"}, "63": {"en": "Isaac went out to meditate in the field at the evening. He lifted up his eyes and looked. Behold, there were camels coming.", "zh": "天將晚，以撒出來在田間默想，舉目一看，見來了些駱駝。", "ja": "イサクは夕暮、野に出て歩いていたが、目をあげて、らくだの来るのを見た。"}, "64": {"en": "Rebekah lifted up her eyes, and when she saw Isaac, she got off the camel.", "zh": "利百加舉目看見以撒，就急忙下了駱駝，", "ja": "リベカは目をあげてイサクを見、らくだからおりて、"}, "65": {"en": "She said to the servant, “Who is the man who is walking in the field to meet us?” The servant said, “It is my master.”", "zh": "問那僕人說：「這田間走來迎接我們的是誰？」僕人說：「是我的主人。」利百加就拿帕子蒙上臉。", "ja": "しもべに言った、「わたしたちに向かって、野を歩いて来るあの人はだれでしょう」。しもべは言った、「あれはわたしの主人です」。するとリベカは、被衣で身をおおった。"}, "66": {"en": "She took her veil, and covered herself.   The servant told Isaac all the things that he had done.", "zh": "僕人就將所辦的一切事都告訴以撒。", "ja": "しもべは自分がしたことのすべてをイサクに話した。"}, "67": {"en": "Isaac brought her into his mother Sarah’s tent, and took Rebekah, and she became his wife. He loved her. So Isaac was comforted after his mother’s death.", "zh": "以撒便領利百加進了他母親撒拉的帳棚，娶了她為妻，並且愛她。以撒自從他母親不在了，這才得了安慰。", "ja": "イサクはリベカを天幕に連れて行き、リベカをめとって妻とし、彼女を愛した。こうしてイサクは母の死後、慰めを得た。"}}}, "25": {"verses": {"1": {"en": "Abraham took another wife, and her name was Keturah.", "zh": "亞伯拉罕又娶了一妻，名叫基土拉。", "ja": "アブラハムは再び妻をめとった。名をケトラという。"}, "2": {"en": "She bore him Zimran, Jokshan, Medan, Midian, Ishbak, and Shuah.", "zh": "基土拉給他生了心蘭、約珊、米但、米甸、伊施巴，和書亞。", "ja": "彼女はジムラン、ヨクシャン、メダン、ミデアン、イシバクおよびシュワを産んだ。"}, "3": {"en": "Jokshan became the father of Sheba, and Dedan. The sons of Dedan were Asshurim, Letushim, and Leummim.", "zh": "約珊生了示巴和底但。底但的子孫是亞書利族、利都是族，和利烏米族。", "ja": "ヨクシャンの子はシバとデダン。デダンの子孫はアシュリびと、レトシびと、レウミびとである。"}, "4": {"en": "The sons of Midian were Ephah, Epher, Hanoch, Abida, and Eldaah. All these were the children of Keturah.", "zh": "米甸的兒子是以法、以弗、哈諾、亞比大，和以勒大。這都是基土拉的子孫。", "ja": "ミデアンの子孫はエパ、エペル、ヘノク、アビダ、エルダアであって、これらは皆ケトラの子孫であった。"}, "5": {"en": "Abraham gave all that he had to Isaac,", "zh": "亞伯拉罕將一切所有的都給了以撒。", "ja": "アブラハムはその所有をことごとくイサクに与えた。"}, "6": {"en": "but Abraham gave gifts to the sons of Abraham’s concubines. While he still lived, he sent them away from Isaac his son, eastward, to the east country.", "zh": "亞伯拉罕把財物分給他庶出的眾子，趁着自己還在世的時候打發他們離開他的兒子以撒，往東方去。", "ja": "またそのそばめたちの子らにもアブラハムは物を与え、なお生きている間に彼らをその子イサクから離して、東の方、東の国に移らせた。"}, "7": {"en": "These are the days of the years of Abraham’s life which he lived: one hundred seventy-five years.", "zh": "亞伯拉罕一生的年日是一百七十五歲。", "ja": "アブラハムの生きながらえた年は百七十五年である。"}, "8": {"en": "Abraham gave up his spirit, and died at a good old age, an old man, and full of years, and was gathered to his people.", "zh": "亞伯拉罕壽高年邁，氣絕而死，歸到他列祖那裏。", "ja": "アブラハムは高齢に達し、老人となり、年が満ちて息絶え、死んでその民に加えられた。"}, "9": {"en": "Isaac and Ishmael, his sons, buried him in the cave of Machpelah, in the field of Ephron, the son of Zohar the Hittite, which is near Mamre,", "zh": "他兩個兒子以撒、以實瑪利把他埋葬在麥比拉洞裏。這洞在幔利前、赫人瑣轄的兒子以弗崙的田中，", "ja": "その子イサクとイシマエルは彼をヘテびとゾハルの子エフロンの畑にあるマクペラのほら穴に葬った。これはマムレの向かいにあり、"}, "10": {"en": "the field which Abraham purchased from the children of Heth. Abraham was buried there with Sarah, his wife.", "zh": "就是亞伯拉罕向赫人買的那塊田。亞伯拉罕和他妻子撒拉都葬在那裏。", "ja": "アブラハムがヘテの人々から、買い取った畑であって、そこにアブラハムとその妻サラが葬られた。"}, "11": {"en": "After the death of Abraham, God blessed Isaac, his son. Isaac lived by Beer Lahai Roi.", "zh": "亞伯拉罕死了以後，上帝賜福給他的兒子以撒。以撒靠近庇耳‧拉海‧萊居住。", "ja": "アブラハムが死んだ後、神はその子イサクを祝福された。イサクはベエル・ラハイ・ロイのほとりに住んだ。"}, "12": {"en": "Now this is the history of the generations of Ishmael, Abraham’s son, whom Hagar the Egyptian, Sarah’s servant, bore to Abraham.", "zh": "撒拉的使女埃及人夏甲給亞伯拉罕所生的兒子是以實瑪利。", "ja": "サラのつかえめエジプトびとハガルがアブラハムに産んだアブラハムの子イシマエルの系図は次のとおりである。"}, "13": {"en": "These are the names of the sons of Ishmael, by their names, according to the order of their birth: the firstborn of Ishmael, Nebaioth, then Kedar, Adbeel, Mibsam,", "zh": "以實瑪利兒子們的名字，按着他們的家譜記在下面。以實瑪利的長子是尼拜約，又有基達、亞德別、米比衫、", "ja": "イシマエルの子らの名を世代にしたがって、その名をいえば次のとおりである。すなわちイシマエルの長子はネバヨテ、次はケダル、アデビエル、ミブサム、"}, "14": {"en": "Mishma, Dumah, Massa,", "zh": "米施瑪、度瑪、瑪撒、", "ja": "ミシマ、ドマ、マッサ、"}, "15": {"en": "Hadad, Tema, Jetur, Naphish, and Kedemah.", "zh": "哈大、提瑪、伊突、拿非施、基底瑪。", "ja": "ハダデ、テマ、エトル、ネフシ、ケデマ。"}, "16": {"en": "These are the sons of Ishmael, and these are their names, by their villages, and by their encampments: twelve princes, according to their nations.", "zh": "這是以實瑪利眾子的名字，照着他們的村莊、營寨，作了十二族的族長。", "ja": "これはイシマエルの子らであり、村と宿営とによる名であって、その氏族による十二人の君たちである。"}, "17": {"en": "These are the years of the life of Ishmael: one hundred thirty-seven years. He gave up his spirit and died, and was gathered to his people.", "zh": "以實瑪利享壽一百三十七歲，氣絕而死，歸到他列祖那裏。", "ja": "イシマエルのよわいは百三十七年である。彼は息絶えて死に、その民に加えられた。"}, "18": {"en": "They lived from Havilah to Shur that is before Egypt, as you go toward Assyria. He lived opposite all his relatives.", "zh": "他子孫的住處在他眾弟兄東邊，從哈腓拉直到埃及前的書珥，正在亞述的道上。", "ja": "イシマエルの子らはハビラからエジプトの東、シュルまでの間に住んで、アシュルに及んだ。イシマエルはすべての兄弟の東に住んだ。"}, "19": {"en": "This is the history of the generations of Isaac, Abraham’s son. Abraham became the father of Isaac.", "zh": "亞伯拉罕的兒子以撒的後代記在下面。亞伯拉罕生以撒。", "ja": "アブラハムの子イサクの系図は次のとおりである。アブラハムの子はイサクであって、"}, "20": {"en": "Isaac was forty years old when he took Rebekah, the daughter of Bethuel the Syrian of Paddan Aram, the sister of Laban the Syrian, to be his wife.", "zh": "以撒娶利百加為妻的時候正四十歲。利百加是巴旦‧亞蘭地的亞蘭人彼土利的女兒，是亞蘭人拉班的妹子。", "ja": "イサクは四十歳の時、パダンアラムのアラムびとベトエルの娘で、アラムびとラバンの妹リベカを妻にめとった。"}, "21": {"en": "Isaac entreated the LORD for his wife, because she was barren. The LORD was entreated by him, and Rebekah his wife conceived.", "zh": "以撒因他妻子不生育，就為她祈求耶和華；耶和華應允他的祈求，他的妻子利百加就懷了孕。", "ja": "イサクは妻が子を産まなかったので、妻のために主に祈り願った。主はその願いを聞かれ、妻リベカはみごもった。"}, "22": {"en": "The children struggled together within her. She said, “If it is like this, why do I live?” She went to inquire of the LORD.", "zh": "孩子們在她腹中彼此相爭，她就說：「若是這樣，我為甚麼活着呢？」她就去求問耶和華。", "ja": "ところがその子らが胎内で押し合ったので、リベカは言った、「こんなことでは、わたしはどうなるでしょう」。彼女は行って主に尋ねた。"}, "23": {"en": "The LORD said to her, “Two nations are in your womb. Two peoples will be separated from your body. The one people will be stronger than the other people. The elder will serve the younger.”", "zh": "耶和華對她說： 兩國在你腹內； 兩族要從你身上出來。 這族必強於那族； 將來大的要服事小的。", "ja": "主は彼女に言われた、「二つの国民があなたの胎内にあり、二つの民があなたの腹から別れて出る。一つの民は他の民よりも強く、兄は弟に仕えるであろう」。"}, "24": {"en": "When her days to be delivered were fulfilled, behold, there were twins in her womb.", "zh": "生產的日子到了，腹中果然是雙子。", "ja": "彼女の出産の日がきたとき、胎内にはふたごがあった。"}, "25": {"en": "The first came out red all over, like a hairy garment. They named him Esau.", "zh": "先產的身體發紅，渾身有毛，如同皮衣，他們就給他起名叫以掃。", "ja": "さきに出たのは赤くて全身毛ごろものようであった。それで名をエサウと名づけた。"}, "26": {"en": "After that, his brother came out, and his hand had hold on Esau’s heel. He was named Jacob. Isaac was sixty years old when she bore them.", "zh": "隨後又生了以掃的兄弟，手抓住以掃的腳跟，因此給他起名叫雅各。利百加生下兩個兒子的時候，以撒年正六十歲。", "ja": "その後に弟が出た。その手はエサウのかかとをつかんでいた。それで名をヤコブと名づけた。リベカが彼らを産んだ時、イサクは六十歳であった。"}, "27": {"en": "The boys grew. Esau was a skillful hunter, a man of the field. Jacob was a quiet man, living in tents.", "zh": "兩個孩子漸漸長大，以掃善於打獵，常在田野；雅各為人安靜，常住在帳棚裏。", "ja": "さてその子らは成長し、エサウは巧みな狩猟者となり、野の人となったが、ヤコブは穏やかな人で、天幕に住んでいた。"}, "28": {"en": "Now Isaac loved Esau, because he ate his venison. Rebekah loved Jacob.", "zh": "以撒愛以掃，因為常吃他的野味；利百加卻愛雅各。", "ja": "イサクは、しかの肉が好きだったので、エサウを愛したが、リベカはヤコブを愛した。"}, "29": {"en": "Jacob boiled stew. Esau came in from the field, and he was famished.", "zh": "有一天，雅各熬湯，以掃從田野回來累昏了。", "ja": "ある日ヤコブが、あつものを煮ていた時、エサウは飢え疲れて野から帰ってきた。"}, "30": {"en": "Esau said to Jacob, “Please feed me with some of that red stew, for I am famished.” Therefore his name was called Edom.", "zh": "以掃對雅各說：「我累昏了，求你把這紅湯給我喝。」因此以掃又叫以東。", "ja": "エサウはヤコブに言った、「わたしは飢え疲れた。お願いだ。赤いもの、その赤いものをわたしに食べさせてくれ」。彼が名をエドムと呼ばれたのはこのためである。"}, "31": {"en": "Jacob said, “First, sell me your birthright.”", "zh": "雅各說：「你今日把長子的名分賣給我吧。」", "ja": "ヤコブは言った、「まずあなたの長子の特権をわたしに売りなさい」。"}, "32": {"en": "Esau said, “Behold, I am about to die. What good is the birthright to me?”", "zh": "以掃說：「我將要死，這長子的名分於我有甚麼益處呢？」", "ja": "エサウは言った、「わたしは死にそうだ。長子の特権などわたしに何になろう」。"}, "33": {"en": "Jacob said, “Swear to me first.”", "zh": "雅各說：「你今日對我起誓吧。」以掃就對他起了誓，把長子的名分賣給雅各。", "ja": "ヤコブはまた言った、「まずわたしに誓いなさい」。彼は誓って長子の特権をヤコブに売った。"}, "34": {"en": "He swore to him. He sold his birthright to Jacob.   Jacob gave Esau bread and lentil stew. He ate and drank, rose up, and went his way. So Esau despised his birthright.", "zh": "於是雅各將餅和紅豆湯給了以掃，以掃吃了喝了，便起來走了。這就是以掃輕看了他長子的名分。", "ja": "そこでヤコブはパンとレンズ豆のあつものとをエサウに与えたので、彼は飲み食いして、立ち去った。このようにしてエサウは長子の特権を軽んじた。"}}}, "26": {"verses": {"1": {"en": "There was a famine in the land, in addition to the first famine that was in the days of Abraham. Isaac went to Abimelech king of the Philistines, to Gerar.", "zh": "在亞伯拉罕的日子，那地有一次饑荒；這時又有饑荒，以撒就往基拉耳去，到非利士人的王亞比米勒那裏。", "ja": "アブラハムの時にあった初めのききんのほか、またききんがその国にあったので、イサクはゲラルにいるペリシテびとの王アビメレクの所へ行った。"}, "2": {"en": "The LORD appeared to him, and said, “Don’t go down into Egypt. Live in the land I will tell you about.", "zh": "耶和華向以撒顯現，說：「你不要下埃及去，要住在我所指示你的地。", "ja": "その時、主は彼に現れて言われた、「エジプトへ下ってはならない。わたしがあなたに示す地にとどまりなさい。"}, "3": {"en": "Live in this land, and I will be with you, and will bless you. For I will give to you, and to your offspring, all these lands, and I will establish the oath which I swore to Abraham your father.", "zh": "你寄居在這地，我必與你同在，賜福給你，因為我要將這些地都賜給你和你的後裔。我必堅定我向你父亞伯拉罕所起的誓。", "ja": "あなたがこの地にとどまるなら、わたしはあなたと共にいて、あなたを祝福し、これらの国をことごとくあなたと、あなたの子孫とに与え、わたしがあなたの父アブラハムに誓った誓いを果そう。"}, "4": {"en": "I will multiply your offspring as the stars of the sky, and will give all these lands to your offspring. In your offspring all the nations of the earth will be blessed,", "zh": "我要加增你的後裔，像天上的星那樣多，又要將這些地都賜給你的後裔。並且地上萬國必因你的後裔得福－", "ja": "またわたしはあなたの子孫を増して天の星のようにし、あなたの子孫にこれらの地をみな与えよう。そして地のすべての国民はあなたの子孫によって祝福をえるであろう。"}, "5": {"en": "because Abraham obeyed my voice, and kept my requirements, my commandments, my statutes, and my laws.”", "zh": "都因亞伯拉罕聽從我的話，遵守我的吩咐和我的命令、律例、法度。」", "ja": "アブラハムがわたしの言葉にしたがってわたしのさとしと、いましめと、さだめと、おきてとを守ったからである」。"}, "6": {"en": "Isaac lived in Gerar.", "zh": "以撒就住在基拉耳。", "ja": "こうしてイサクはゲラルに住んだ。"}, "7": {"en": "The men of the place asked him about his wife. He said, “She is my sister,” for he was afraid to say, “My wife”, lest, he thought, “the men of the place might kill me for Rebekah, because she is beautiful to look at.”", "zh": "那地方的人問到他的妻子，他便說：「那是我的妹子。」原來他怕說：「是我的妻子」；他心裏想：「恐怕這地方的人為利百加的緣故殺我」，因為她容貌俊美。", "ja": "その所の人々が彼の妻のことを尋ねたとき、「彼女はわたしの妹です」と彼は言った。リベカは美しかったので、その所の人々がリベカのゆえに自分を殺すかもしれないと思って、「わたしの妻です」と言うのを恐れたからである。"}, "8": {"en": "When he had been there a long time, Abimelech king of the Philistines looked out at a window, and saw, and, behold, Isaac was caressing Rebekah, his wife.", "zh": "他在那裏住了許久。有一天，非利士人的王亞比米勒從窗戶裏往外觀看，見以撒和他的妻子利百加戲玩。", "ja": "イサクは長らくそこにいたが、ある日ペリシテびとの王アビメレクは窓から外をながめていて、イサクがその妻リベカと戯れているのを見た。"}, "9": {"en": "Abimelech called Isaac, and said, “Behold, surely she is your wife. Why did you say, ‘She is my sister’?” Isaac said to him, “Because I said, ‘Lest I die because of her.’ ”", "zh": "亞比米勒召了以撒來，對他說：「她實在是你的妻子，你怎麼說她是你的妹子？」以撒說：「我心裏想，恐怕我因她而死。」", "ja": "そこでアビメレクはイサクを召して言った、「彼女は確かにあなたの妻です。あなたはどうして『彼女はわたしの妹です』と言われたのですか」。イサクは彼に言った、「わたしは彼女のゆえに殺されるかもしれないと思ったからです」。"}, "10": {"en": "Abimelech said, “What is this you have done to us? One of the people might easily have lain with your wife, and you would have brought guilt on us!”", "zh": "亞比米勒說：「你向我們做的是甚麼事呢？民中險些有人和你的妻同寢，把我們陷在罪裏。」", "ja": "アビメレクは言った、「あなたはどうしてこんな事をわれわれにされたのですか。民のひとりが軽々しくあなたの妻と寝るような事があれば、その時あなたはわれわれに罪を負わせるでしょう」。"}, "11": {"en": "Abimelech commanded all the people, saying, “He who touches this man or his wife will surely be put to death.”", "zh": "於是亞比米勒曉諭眾民說：「凡沾着這個人，或是他妻子的，定要把他治死。」", "ja": "それでアビメレクはすべての民に命じて言った、「この人、またはその妻にさわる者は必ず死ななければならない」。"}, "12": {"en": "Isaac sowed in that land, and reaped in the same year one hundred times what he planted. The LORD blessed him.", "zh": "以撒在那地耕種，那一年有百倍的收成。耶和華賜福給他，", "ja": "イサクはその地に種をまいて、その年に百倍の収穫を得た。このように主が彼を祝福されたので、"}, "13": {"en": "The man grew great, and grew more and more until he became very great.", "zh": "他就昌大，日增月盛，成了大富戶。", "ja": "彼は富み、またますます栄えて非常に裕福になり、"}, "14": {"en": "He had possessions of flocks, possessions of herds, and a great household. The Philistines envied him.", "zh": "他有羊群牛群，又有許多僕人，非利士人就嫉妒他。", "ja": "羊の群れ、牛の群れ及び多くのしもべを持つようになったので、ペリシテびとは彼をねたんだ。"}, "15": {"en": "Now all the wells which his father’s servants had dug in the days of Abraham his father, the Philistines had stopped, and filled with earth.", "zh": "當他父親亞伯拉罕在世的日子，他父親的僕人所挖的井，非利士人全都塞住，填滿了土。", "ja": "またペリシテびとは彼の父アブラハムの時に、父のしもべたちが掘ったすべての井戸をふさぎ、土で埋めた。"}, "16": {"en": "Abimelech said to Isaac, “Go away from us, for you are much mightier than we.”", "zh": "亞比米勒對以撒說：「你離開我們去吧。因為你比我們強盛得多。」", "ja": "アビメレクはイサクに言った、「あなたはわれわれよりも、はるかに強くなられたから、われわれの所を去ってください」。"}, "17": {"en": "Isaac departed from there, encamped in the valley of Gerar, and lived there.", "zh": "以撒就離開那裏，在基拉耳谷支搭帳棚，住在那裏。", "ja": "イサクはそこを去り、ゲラルの谷に天幕を張ってその所に住んだ。"}, "18": {"en": "Isaac dug again the wells of water, which they had dug in the days of Abraham his father, for the Philistines had stopped them after the death of Abraham. He called their names after the names by which his father had called them.", "zh": "當他父親亞伯拉罕在世之日所挖的水井因非利士人在亞伯拉罕死後塞住了，以撒就重新挖出來，仍照他父親所叫的叫那些井的名字。", "ja": "そしてイサクは父アブラハムの時に人々の掘った水の井戸を再び掘った。アブラハムの死後、ペリシテびとがふさいだからである。イサクは父がつけた名にしたがってそれらに名をつけた。"}, "19": {"en": "Isaac’s servants dug in the valley, and found there a well of flowing water.", "zh": "以撒的僕人在谷中挖井，便得了一口活水井。", "ja": "しかしイサクのしもべたちが谷の中を掘って、そこにわき出る水の井戸を見つけたとき、"}, "20": {"en": "The herdsmen of Gerar argued with Isaac’s herdsmen, saying, “The water is ours.” So he called the name of the well Esek, because they contended with him.", "zh": "基拉耳的牧人與以撒的牧人爭競，說：「這水是我們的。」以撒就給那井起名叫埃色，因為他們和他相爭。", "ja": "ゲラルの羊飼たちは、「この水はわれわれのものだ」と言って、イサクの羊飼たちと争ったので、イサクはその井戸の名をエセクと名づけた。彼らが彼と争ったからである。"}, "21": {"en": "They dug another well, and they argued over that, also. So he called its name Sitnah.", "zh": "以撒的僕人又挖了一口井，他們又為這井爭競，因此以撒給這井起名叫西提拿。", "ja": "彼らはまた一つの井戸を掘ったが、これをも争ったので、名をシテナと名づけた。"}, "22": {"en": "He left that place, and dug another well. They didn’t argue over that one. So he called it Rehoboth. He said, “For now the LORD has made room for us, and we will be fruitful in the land.”", "zh": "以撒離開那裏，又挖了一口井，他們不為這井爭競了，他就給那井起名叫利河伯。他說：「耶和華現在給我們寬闊之地，我們必在這地昌盛。」", "ja": "イサクはそこから移ってまた一つの井戸を掘ったが、彼らはこれを争わなかったので、その名をレホボテと名づけて言った、「いま主がわれわれの場所を広げられたから、われわれはこの地にふえるであろう」。"}, "23": {"en": "He went up from there to Beersheba.", "zh": "以撒從那裏上別是巴去。", "ja": "彼はそこからベエルシバに上った。"}, "24": {"en": "The LORD appeared to him the same night, and said, “I am the God of Abraham your father. Don’t be afraid, for I am with you, and will bless you, and multiply your offspring for my servant Abraham’s sake.”", "zh": "當夜耶和華向他顯現，說：「我是你父親亞伯拉罕的上帝，不要懼怕！因為我與你同在，要賜福給你，並要為我僕人亞伯拉罕的緣故，使你的後裔繁多。」", "ja": "その夜、主は彼に現れて言われた、「わたしはあなたの父アブラハムの神である。あなたは恐れてはならない。わたしはあなたと共におって、あなたを祝福し、わたしのしもべアブラハムのゆえにあなたの子孫を増すであろう」。"}, "25": {"en": "He built an altar there, and called on the LORD’s name, and pitched his tent there. There Isaac’s servants dug a well.", "zh": "以撒就在那裏築了一座壇，求告耶和華的名，並且支搭帳棚；他的僕人便在那裏挖了一口井。", "ja": "それで彼はその所に祭壇を築いて、主の名を呼び、そこに天幕を張った。またイサクのしもべたちはそこに一つの井戸を掘った。"}, "26": {"en": "Then Abimelech went to him from Gerar with Ahuzzath his friend, and Phicol the captain of his army.", "zh": "亞比米勒，同他的朋友亞戶撒和他的軍長非各，從基拉耳來見以撒。", "ja": "時にアビメレクがその友アホザテと、軍勢の長ピコルと共にゲラルからイサクのもとにきたので、"}, "27": {"en": "Isaac said to them, “Why have you come to me, since you hate me, and have sent me away from you?”", "zh": "以撒對他們說：「你們既然恨我，打發我走了，為甚麼到我這裏來呢？」", "ja": "イサクは彼らに言った、「あなたがたはわたしを憎んで、あなたがたの中からわたしを追い出されたのに、どうしてわたしの所にこられたのですか」。"}, "28": {"en": "They said, “We saw plainly that the LORD was with you. We said, ‘Let there now be an oath between us, even between us and you, and let’s make a covenant with you,", "zh": "他們說：「我們明明地看見耶和華與你同在，便說，不如我們兩下彼此起誓，彼此立約，", "ja": "彼らは言った、「われわれは主があなたと共におられるのを、はっきり見ましたので、いまわれわれの間、すなわちわれわれとあなたとの間に一つの誓いを立てて、あなたと契約を結ぼうと思います。"}, "29": {"en": "that you will do us no harm, as we have not touched you, and as we have done to you nothing but good, and have sent you away in peace.’ You are now the blessed of the LORD.”", "zh": "使你不害我們，正如我們未曾害你，一味地厚待你，並且打發你平平安安地走。你是蒙耶和華賜福的了。」", "ja": "われわれはあなたに害を加えたことはなく、ただ良い事だけをして、安らかに去らせたのですから、あなたはわれわれに悪い事をしてはなりません。まことにあなたは主に祝福されたかたです」。"}, "30": {"en": "He made them a feast, and they ate and drank.", "zh": "以撒就為他們設擺筵席，他們便吃了喝了。", "ja": "そこでイサクは彼らのためにふるまいを設けた。彼らは飲み食いし、"}, "31": {"en": "They rose up some time in the morning, and swore an oath to one another. Isaac sent them away, and they departed from him in peace.", "zh": "他們清早起來彼此起誓。以撒打發他們走，他們就平平安安地離開他走了。", "ja": "あくる朝、はやく起きて互に誓った。こうしてイサクは彼らを去らせたので、彼らはイサクのもとから穏やかに去った。"}, "32": {"en": "The same day, Isaac’s servants came, and told him concerning the well which they had dug, and said to him, “We have found water.”", "zh": "那一天，以撒的僕人來，將挖井的事告訴他說：「我們得了水了。」", "ja": "その日、イサクのしもべたちがきて、自分たちが掘った井戸について彼に告げて言った、「わたしたちは水を見つけました」。"}, "33": {"en": "He called it “Shibah”. Therefore the name of the city is “Beersheba” to this day.", "zh": "他就給那井起名叫示巴；因此那城叫做別是巴，直到今日。", "ja": "イサクはそれをシバと名づけた。これによってその町の名は今日にいたるまでベエルシバといわれている。"}, "34": {"en": "When Esau was forty years old, he took as wife Judith, the daughter of Beeri the Hittite, and Basemath, the daughter of Elon the Hittite.", "zh": "以掃四十歲的時候娶了赫人比利的女兒猶滴，與赫人以倫的女兒巴實抹為妻。", "ja": "エサウは四十歳の時、ヘテびとベエリの娘ユデテとヘテびとエロンの娘バスマテとを妻にめとった。"}, "35": {"en": "They grieved Isaac’s and Rebekah’s spirits.", "zh": "她們常使以撒和利百加心裏愁煩。", "ja": "彼女たちはイサクとリベカにとって心の痛みとなった。"}}}, "27": {"verses": {"1": {"en": "When Isaac was old, and his eyes were dim, so that he could not see, he called Esau his elder son, and said to him, “My son?” He said to him, “Here I am.”", "zh": "以撒年老，眼睛昏花，不能看見，就叫了他大兒子以掃來，說：「我兒。」以掃說：「我在這裏。」", "ja": "イサクは年老い、目がかすんで見えなくなった時、長子エサウを呼んで言った、「子よ」。彼は答えて言った、「ここにおります」。"}, "2": {"en": "He said, “See now, I am old. I don’t know the day of my death.", "zh": "他說：「我如今老了，不知道哪一天死。", "ja": "イサクは言った。「わたしは年老いて、いつ死ぬかも知れない。"}, "3": {"en": "Now therefore, please take your weapons, your quiver and your bow, and go out to the field, and get me venison.", "zh": "現在拿你的器械，就是箭囊和弓，往田野去為我打獵，", "ja": "それであなたの武器、弓矢をもって野に出かけ、わたしのために、しかの肉をとってきて、"}, "4": {"en": "Make me savory food, such as I love, and bring it to me, that I may eat, and that my soul may bless you before I die.”", "zh": "照我所愛的做成美味，拿來給我吃，使我在未死之先給你祝福。」", "ja": "わたしの好きなおいしい食べ物を作り、持ってきて食べさせよ。わたしは死ぬ前にあなたを祝福しよう」。"}, "5": {"en": "Rebekah heard when Isaac spoke to Esau his son. Esau went to the field to hunt for venison, and to bring it.", "zh": "以撒對他兒子以掃說話，利百加也聽見了。以掃往田野去打獵，要得野味帶來。", "ja": "イサクがその子エサウに語るのをリベカは聞いていた。やがてエサウが、しかの肉を獲ようと野に出かけたとき、"}, "6": {"en": "Rebekah spoke to Jacob her son, saying, “Behold, I heard your father speak to Esau your brother, saying,", "zh": "利百加就對她兒子雅各說：「我聽見你父親對你哥哥以掃說：", "ja": "リベカはその子ヤコブに言った、「わたしは聞いていましたが、父は兄エサウに、"}, "7": {"en": "‘Bring me venison, and make me savory food, that I may eat, and bless you before the LORD before my death.’", "zh": "『你去把野獸帶來，做成美味給我吃，我好在未死之先，在耶和華面前給你祝福。』", "ja": "『わたしのために、しかの肉をとってきて、おいしい食べ物を作り、わたしに食べさせよ。わたしは死ぬ前に、主の前であなたを祝福しよう』と言いました。"}, "8": {"en": "Now therefore, my son, obey my voice according to that which I command you.", "zh": "現在，我兒，你要照着我所吩咐你的，聽從我的話。", "ja": "それで、子よ、わたしの言葉にしたがい、わたしの言うとおりにしなさい。"}, "9": {"en": "Go now to the flock and get me two good young goats from there. I will make them savory food for your father, such as he loves.", "zh": "你到羊群裏去，給我拿兩隻肥山羊羔來，我便照你父親所愛的給他做成美味。", "ja": "群れの所へ行って、そこからやぎの子の良いのを二頭わたしの所に取ってきなさい。わたしはそれで父のために、父の好きなおいしい食べ物を作りましょう。"}, "10": {"en": "You shall bring it to your father, that he may eat, so that he may bless you before his death.”", "zh": "你拿到你父親那裏給他吃，使他在未死之先給你祝福。」", "ja": "あなたはそれを持って行って父に食べさせなさい。父は死ぬ前にあなたを祝福するでしょう」。"}, "11": {"en": "Jacob said to Rebekah his mother, “Behold, Esau my brother is a hairy man, and I am a smooth man.", "zh": "雅各對他母親利百加說：「我哥哥以掃渾身是有毛的，我身上是光滑的；", "ja": "ヤコブは母リベカに言った、「兄エサウは毛深い人ですが、わたしはなめらかです。"}, "12": {"en": "What if my father touches me? I will seem to him as a deceiver, and I would bring a curse on myself, and not a blessing.”", "zh": "倘若我父親摸着我，必以我為欺哄人的，我就招咒詛，不得祝福。」", "ja": "おそらく父はわたしにさわってみるでしょう。そうすればわたしは父を欺く者と思われ、祝福を受けず、かえってのろいを受けるでしょう」。"}, "13": {"en": "His mother said to him, “Let your curse be on me, my son. Only obey my voice, and go get them for me.”", "zh": "他母親對他說：「我兒，你招的咒詛歸到我身上；你只管聽我的話，去把羊羔給我拿來。」", "ja": "母は彼に言った、「子よ、あなたがうけるのろいはわたしが受けます。ただ、わたしの言葉に従い、行って取ってきなさい」。"}, "14": {"en": "He went, and got them, and brought them to his mother. His mother made savory food, such as his father loved.", "zh": "他便去拿來，交給他母親；他母親就照他父親所愛的做成美味。", "ja": "そこで彼は行ってやぎの子を取り、母の所に持ってきたので、母は父の好きなおいしい食べ物を作った。"}, "15": {"en": "Rebekah took the good clothes of Esau, her elder son, which were with her in the house, and put them on Jacob, her younger son.", "zh": "利百加又把家裏所存大兒子以掃上好的衣服給她小兒子雅各穿上，", "ja": "リベカは家にあった長子エサウの晴着を取って、弟ヤコブに着せ、"}, "16": {"en": "She put the skins of the young goats on his hands, and on the smooth of his neck.", "zh": "又用山羊羔皮包在雅各的手上和頸項的光滑處，", "ja": "また子やぎの皮を手と首のなめらかな所とにつけさせ、"}, "17": {"en": "She gave the savory food and the bread, which she had prepared, into the hand of her son Jacob.", "zh": "就把所做的美味和餅交在她兒子雅各的手裏。", "ja": "彼女が作ったおいしい食べ物とパンとをその子ヤコブの手にわたした。"}, "18": {"en": "He came to his father, and said, “My father?” He said, “Here I am. Who are you, my son?”", "zh": "雅各到他父親那裏說：「我父親！」他說：「我在這裏。我兒，你是誰？」", "ja": "そこでヤコブは父の所へ行って言った、「父よ」。すると父は言った、「わたしはここにいる。子よ、あなたはだれか」。"}, "19": {"en": "Jacob said to his father, “I am Esau your firstborn. I have done what you asked me to do. Please arise, sit and eat of my venison, that your soul may bless me.”", "zh": "雅各對他父親說：「我是你的長子以掃；我已照你所吩咐我的行了。請起來坐着，吃我的野味，好給我祝福。」", "ja": "ヤコブは父に言った、「長子エサウです。あなたがわたしに言われたとおりにいたしました。どうぞ起きて、すわってわたしのしかの肉を食べ、あなたみずからわたしを祝福してください」。"}, "20": {"en": "Isaac said to his son, “How is it that you have found it so quickly, my son?” He said, “Because the LORD your God gave me success.”", "zh": "以撒對他兒子說：「我兒，你如何找得這麼快呢？」他說：「因為耶和華－你的上帝使我遇見好機會得着的。」", "ja": "イサクはその子に言った、「子よ、どうしてあなたはこんなに早く手に入れたのか」。彼は言った、「あなたの神、主がわたしにしあわせを授けられたからです」。"}, "21": {"en": "Isaac said to Jacob, “Please come near, that I may feel you, my son, whether you are really my son Esau or not.”", "zh": "以撒對雅各說：「我兒，你近前來，我摸摸你，知道你真是我的兒子以掃不是。」", "ja": "イサクはヤコブに言った、「子よ、近寄りなさい。わたしは、さわってみて、あなたが確かにわが子エサウであるかどうかをみよう」。"}, "22": {"en": "Jacob went near to Isaac his father. He felt him, and said, “The voice is Jacob’s voice, but the hands are the hands of Esau.”", "zh": "雅各就挨近他父親以撒。以撒摸着他，說：「聲音是雅各的聲音，手卻是以掃的手。」", "ja": "ヤコブが、父イサクに近寄ったので、イサクは彼にさわってみて言った、「声はヤコブの声だが、手はエサウの手だ」。"}, "23": {"en": "He didn’t recognize him, because his hands were hairy, like his brother Esau’s hands. So he blessed him.", "zh": "以撒就辨不出他來；因為他手上有毛，像他哥哥以掃的手一樣，就給他祝福；", "ja": "ヤコブの手が兄エサウの手のように毛深かったため、イサクはヤコブを見わけることができなかったので、彼を祝福した。"}, "24": {"en": "He said, “Are you really my son Esau?” He said, “I am.”", "zh": "又說：「你真是我兒子以掃嗎？」他說：「我是。」", "ja": "イサクは言った、「あなたは確かにわが子エサウですか」。彼は言った、「そうです」。"}, "25": {"en": "He said, “Bring it near to me, and I will eat of my son’s venison, that my soul may bless you.”", "zh": "以撒說：「你遞給我，我好吃我兒子的野味，給你祝福。」雅各就遞給他，他便吃了，又拿酒給他，他也喝了。", "ja": "イサクは言った、「わたしの所へ持ってきなさい。わが子のしかの肉を食べて、わたしみずから、あなたを祝福しよう」。ヤコブがそれを彼の所に持ってきたので、彼は食べた。またぶどう酒を持ってきたので、彼は飲んだ。"}, "26": {"en": "He brought it near to him, and he ate. He brought him wine, and he drank.   His father Isaac said to him, “Come near now, and kiss me, my son.”", "zh": "他父親以撒對他說：「我兒，你上前來與我親嘴。」", "ja": "そして父イサクは彼に言った、「子よ、さあ、近寄ってわたしに口づけしなさい」。"}, "27": {"en": "He came near, and kissed him. He smelled the smell of his clothing, and blessed him, and said, “Behold, the smell of my son is as the smell of a field which the LORD has blessed.", "zh": "他就上前與父親親嘴。他父親一聞他衣服上的香氣，就給他祝福，說： 我兒的香氣 如同耶和華賜福之田地的香氣一樣。", "ja": "彼が近寄って口づけした時、イサクはその着物のかおりをかぎ、彼を祝福して言った、「ああ、わが子のかおりは、主が祝福された野のかおりのようだ。"}, "28": {"en": "God give you of the dew of the sky, of the fatness of the earth, and plenty of grain and new wine.", "zh": "願上帝賜你天上的甘露， 地上的肥土， 並許多五穀新酒。", "ja": "どうか神が、天の露と、地の肥えたところと、多くの穀物と、新しいぶどう酒とをあなたに賜わるように。"}, "29": {"en": "Let peoples serve you, and nations bow down to you. Be lord over your brothers. Let your mother’s sons bow down to you. Cursed be everyone who curses you. Blessed be everyone who blesses you.”", "zh": "願多民事奉你， 多國跪拜你。 願你作你弟兄的主； 你母親的兒子向你跪拜。 凡咒詛你的，願他受咒詛； 為你祝福的，願他蒙福。", "ja": "もろもろの民はあなたに仕え、もろもろの国はあなたに身をかがめる。あなたは兄弟たちの主となり、あなたの母の子らは、あなたに身をかがめるであろう。あなたをのろう者はのろわれ、あなたを祝福する者は祝福される」。"}, "30": {"en": "As soon as Isaac had finished blessing Jacob, and Jacob had just gone out from the presence of Isaac his father, Esau his brother came in from his hunting.", "zh": "以撒為雅各祝福已畢，雅各從他父親那裏才出來，他哥哥以掃正打獵回來，", "ja": "イサクがヤコブを祝福し終って、ヤコブが父イサクの前から出て行くとすぐ、兄エサウが狩から帰ってきた。"}, "31": {"en": "He also made savory food, and brought it to his father. He said to his father, “Let my father arise, and eat of his son’s venison, that your soul may bless me.”", "zh": "也做了美味，拿來給他父親，說：「請父親起來，吃你兒子的野味，好給我祝福。」", "ja": "彼もまたおいしい食べ物を作って、父の所に持ってきて、言った、「父よ、起きてあなたの子のしかの肉を食べ、あなたみずから、わたしを祝福してください」。"}, "32": {"en": "Isaac his father said to him, “Who are you?” He said, “I am your son, your firstborn, Esau.”", "zh": "他父親以撒對他說：「你是誰？」他說：「我是你的長子以掃。」", "ja": "父イサクは彼に言った、「あなたは、だれか」。彼は言った、「わたしはあなたの子、長子エサウです」。"}, "33": {"en": "Isaac trembled violently, and said, “Who, then, is he who has taken venison, and brought it to me, and I have eaten of all before you came, and have blessed him? Yes, he will be blessed.”", "zh": "以撒就大大地戰兢，說：「你未來之先，是誰得了野味拿來給我呢？我已經吃了，為他祝福；他將來也必蒙福。」", "ja": "イサクは激しくふるえて言った、「それでは、あのしかの肉を取って、わたしに持ってきた者はだれか。わたしはあなたが来る前に、みんな食べて彼を祝福した。ゆえに彼が祝福を得るであろう」。"}, "34": {"en": "When Esau heard the words of his father, he cried with an exceedingly great and bitter cry, and said to his father, “Bless me, even me also, my father.”", "zh": "以掃聽了他父親的話，就放聲痛哭，說：「我父啊，求你也為我祝福！」", "ja": "エサウは父の言葉を聞いた時、大声をあげ、激しく叫んで、父に言った、「父よ、わたしを、わたしをも祝福してください」。"}, "35": {"en": "He said, “Your brother came with deceit, and has taken away your blessing.”", "zh": "以撒說：「你兄弟已經用詭計來將你的福分奪去了。」", "ja": "イサクは言った、「あなたの弟が偽ってやってきて、あなたの祝福を奪ってしまった」。"}, "36": {"en": "He said, “Isn’t he rightly named Jacob? For he has supplanted me these two times. He took away my birthright. See, now he has taken away my blessing.” He said, “Haven’t you reserved a blessing for me?”", "zh": "以掃說：「他名雅各，豈不是正對嗎？因為他欺騙了我兩次：他從前奪了我長子的名分，你看，他現在又奪了我的福分。」以掃又說：「你沒有留下為我可祝的福嗎？」", "ja": "エサウは言った、「よくもヤコブと名づけたものだ。彼は二度までもわたしをおしのけた。さきには、わたしの長子の特権を奪い、こんどはわたしの祝福を奪った」。また言った、「あなたはわたしのために祝福を残しておかれませんでしたか」。"}, "37": {"en": "Isaac answered Esau, “Behold, I have made him your lord, and all his brothers I have given to him for servants. I have sustained him with grain and new wine. What then will I do for you, my son?”", "zh": "以撒回答以掃說：「我已立他為你的主，使他的弟兄都給他作僕人，並賜他五穀新酒可以養生。我兒，現在我還能為你做甚麼呢？」", "ja": "イサクは答えてエサウに言った、「わたしは彼をあなたの主人とし、兄弟たちを皆しもべとして彼に与え、また穀物とぶどう酒を彼に授けた。わが子よ、今となっては、あなたのために何ができようか」。"}, "38": {"en": "Esau said to his father, “Do you have just one blessing, my father? Bless me, even me also, my father.” Esau lifted up his voice, and wept.", "zh": "以掃對他父親說：「父啊，你只有一樣可祝的福嗎？我父啊，求你也為我祝福！」以掃就放聲而哭。", "ja": "エサウは父に言った、「父よ、あなたの祝福はただ一つだけですか。父よ、わたしを、わたしをも祝福してください」。エサウは声をあげて泣いた。"}, "39": {"en": "Isaac his father answered him, “Behold, your dwelling will be of the fatness of the earth, and of the dew of the sky from above.", "zh": "他父親以撒說： 地上的肥土必為你所住； 天上的甘露必為你所得。", "ja": "父イサクは答えて彼に言った、「あなたのすみかは地の肥えた所から離れ、また上なる天の露から離れるであろう。"}, "40": {"en": "You will live by your sword, and you will serve your brother. It will happen, when you will break loose, that you will shake his yoke from off your neck.”", "zh": "你必倚靠刀劍度日， 又必事奉你的兄弟； 到你強盛的時候， 必從你頸項上掙開他的軛。", "ja": "あなたはつるぎをもって世を渡り、あなたの弟に仕えるであろう。しかし、あなたが勇み立つ時、首から、そのくびきを振り落すであろう」。"}, "41": {"en": "Esau hated Jacob because of the blessing with which his father blessed him. Esau said in his heart, “The days of mourning for my father are at hand. Then I will kill my brother Jacob.”", "zh": "以掃因他父親給雅各祝的福，就怨恨雅各，心裏說：「為我父親居喪的日子近了，到那時候，我要殺我的兄弟雅各。」", "ja": "こうしてエサウは父がヤコブに与えた祝福のゆえにヤコブを憎んだ。エサウは心の内で言った、「父の喪の日も遠くはないであろう。その時、弟ヤコブを殺そう」。"}, "42": {"en": "The words of Esau, her elder son, were told to Rebekah. She sent and called Jacob, her younger son, and said to him, “Behold, your brother Esau comforts himself about you by planning to kill you.", "zh": "有人把利百加大兒子以掃的話告訴利百加，她就打發人去，叫了她小兒子雅各來，對他說：「你哥哥以掃想要殺你，報仇雪恨。", "ja": "しかしリベカは長子エサウのこの言葉を人づてに聞いたので、人をやり、弟ヤコブを呼んで言った、「兄エサウはあなたを殺そうと考えて、みずから慰めています。"}, "43": {"en": "Now therefore, my son, obey my voice. Arise, flee to Laban, my brother, in Haran.", "zh": "現在，我兒，你要聽我的話：起來，逃往哈蘭、我哥哥拉班那裏去，", "ja": "子よ、今わたしの言葉に従って、すぐハランにいるわたしの兄ラバンのもとにのがれ、"}, "44": {"en": "Stay with him a few days, until your brother’s fury turns away—", "zh": "同他住些日子，直等你哥哥的怒氣消了。", "ja": "あなたの兄の怒りが解けるまで、しばらく彼の所にいなさい。"}, "45": {"en": "until your brother’s anger turns away from you, and he forgets what you have done to him. Then I will send, and get you from there. Why should I be bereaved of you both in one day?”", "zh": "你哥哥向你消了怒氣，忘了你向他所做的事，我便打發人去把你從那裏帶回來。為甚麼一日喪你們二人呢？」", "ja": "兄の憤りが解けて、あなたのした事を兄が忘れるようになったならば、わたしは人をやって、あなたをそこから迎えましょう。どうして、わたしは一日のうちにあなたがたふたりを失ってよいでしょうか」。"}, "46": {"en": "Rebekah said to Isaac, “I am weary of my life because of the daughters of Heth. If Jacob takes a wife of the daughters of Heth, such as these, of the daughters of the land, what good will my life do me?”", "zh": "利百加對以撒說：「我因這赫人的女子連性命都厭煩了；倘若雅各也娶赫人的女子為妻，像這些一樣，我活着還有甚麼益處呢？」", "ja": "リベカはイサクに言った、「わたしはヘテびとの娘どものことで、生きているのがいやになりました。もしヤコブがこの地の、あの娘どものようなヘテびとの娘を妻にめとるなら、わたしは生きていて、何になりましょう」。"}}}, "28": {"verses": {"1": {"en": "Isaac called Jacob, blessed him, and commanded him, “You shall not take a wife of the daughters of Canaan.", "zh": "以撒叫了雅各來，給他祝福，並囑咐他說：「你不要娶迦南的女子為妻。", "ja": "イサクはヤコブを呼んで、これを祝福し、命じて言った、「あなたはカナンの娘を妻にめとってはならない。"}, "2": {"en": "Arise, go to Paddan Aram, to the house of Bethuel your mother’s father. Take a wife from there from the daughters of Laban, your mother’s brother.", "zh": "你起身往巴旦‧亞蘭去，到你外祖彼土利家裏，在你母舅拉班的女兒中娶一女為妻。", "ja": "立ってパダンアラムへ行き、あなたの母の父ベトエルの家に行って、そこであなたの母の兄ラバンの娘を妻にめとりなさい。"}, "3": {"en": "May God Almighty bless you, and make you fruitful, and multiply you, that you may be a company of peoples,", "zh": "願全能的上帝賜福給你，使你生養眾多，成為多族，", "ja": "全能の神が、あなたを祝福し、多くの子を得させ、かつふえさせて、多くの国民とし、"}, "4": {"en": "and give you the blessing of Abraham, to you and to your offspring with you, that you may inherit the land where you travel, which God gave to Abraham.”", "zh": "將應許亞伯拉罕的福賜給你和你的後裔，使你承受你所寄居的地為業，就是上帝賜給亞伯拉罕的地。」", "ja": "またアブラハムの祝福をあなたと子孫とに与えて、神がアブラハムに授けられたあなたの寄留の地を継がせてくださるように」。"}, "5": {"en": "Isaac sent Jacob away. He went to Paddan Aram to Laban, son of Bethuel the Syrian, the brother of Rebekah, Jacob’s and Esau’s mother.", "zh": "以撒打發雅各走了，他就往巴旦‧亞蘭去，到亞蘭人彼土利的兒子拉班那裏。拉班是雅各、以掃的母舅。", "ja": "こうしてイサクはヤコブを送り出した。ヤコブはパダンアラムに向かい、アラムびとベトエルの子で、ヤコブとエサウとの母リベカの兄ラバンのもとへ行った。"}, "6": {"en": "Now Esau saw that Isaac had blessed Jacob and sent him away to Paddan Aram, to take him a wife from there, and that as he blessed him he gave him a command, saying, “You shall not take a wife of the daughters of Canaan;”", "zh": "以掃見以撒已經給雅各祝福，而且打發他往巴旦‧亞蘭去，在那裏娶妻，並見祝福的時候囑咐他說：「不要娶迦南的女子為妻」，", "ja": "さてエサウは、イサクがヤコブを祝福して、パダンアラムにつかわし、そこから妻をめとらせようとしたこと、彼を祝福し、命じて「あなたはカナンの娘を妻にめとってはならない」と言ったこと、"}, "7": {"en": "and that Jacob obeyed his father and his mother, and was gone to Paddan Aram.", "zh": "又見雅各聽從父母的話往巴旦‧亞蘭去了，", "ja": "そしてヤコブが父母の言葉に従って、パダンアラムへ行ったことを知ったとき、"}, "8": {"en": "Esau saw that the daughters of Canaan didn’t please Isaac, his father.", "zh": "以掃就曉得他父親以撒看不中迦南的女子，", "ja": "彼はカナンの娘が父イサクの心にかなわないのを見た。"}, "9": {"en": "So Esau went to Ishmael, and took, in addition to the wives that he had, Mahalath the daughter of Ishmael, Abraham’s son, the sister of Nebaioth, to be his wife.", "zh": "便往以實瑪利那裏去，在他二妻之外又娶了瑪哈拉為妻。她是亞伯拉罕兒子以實瑪利的女兒，尼拜約的妹子。", "ja": "そこでエサウはイシマエルの所に行き、すでにある妻たちのほかにアブラハムの子イシマエルの娘で、ネバヨテの妹マハラテを妻にめとった。"}, "10": {"en": "Jacob went out from Beersheba, and went toward Haran.", "zh": "雅各出了別是巴，向哈蘭走去；", "ja": "さてヤコブはベエルシバを立って、ハランへ向かったが、"}, "11": {"en": "He came to a certain place, and stayed there all night, because the sun had set. He took one of the stones of the place, and put it under his head, and lay down in that place to sleep.", "zh": "到了一個地方，因為太陽落了，就在那裏住宿，便拾起那地方的一塊石頭枕在頭下，在那裏躺臥睡了，", "ja": "一つの所に着いた時、日が暮れたので、そこに一夜を過ごし、その所の石を取ってまくらとし、そこに伏して寝た。"}, "12": {"en": "He dreamed and saw a stairway set upon the earth, and its top reached to heaven. Behold, the angels of God were ascending and descending on it.", "zh": "夢見一個梯子立在地上，梯子的頭頂着天，有上帝的使者在梯子上，上去下來。", "ja": "時に彼は夢をみた。一つのはしごが地の上に立っていて、その頂は天に達し、神の使たちがそれを上り下りしているのを見た。"}, "13": {"en": "Behold, the LORD stood above it, and said, “I am the LORD, the God of Abraham your father, and the God of Isaac. I will give the land you lie on to you and to your offspring.", "zh": "耶和華站在梯子以上，說：「我是耶和華－你祖亞伯拉罕的上帝，也是以撒的上帝；我要將你現在所躺臥之地賜給你和你的後裔。", "ja": "そして主は彼のそばに立って言われた、「わたしはあなたの父アブラハムの神、イサクの神、主である。あなたが伏している地を、あなたと子孫とに与えよう。"}, "14": {"en": "Your offspring will be as the dust of the earth, and you will spread abroad to the west, and to the east, and to the north, and to the south. In you and in your offspring, all the families of the earth will be blessed.", "zh": "你的後裔必像地上的塵沙那樣多，必向東西南北開展；地上萬族必因你和你的後裔得福。", "ja": "あなたの子孫は地のちりのように多くなって、西、東、北、南にひろがり、地の諸族はあなたと子孫とによって祝福をうけるであろう。"}, "15": {"en": "Behold, I am with you, and will keep you, wherever you go, and will bring you again into this land. For I will not leave you until I have done that which I have spoken of to you.”", "zh": "我也與你同在。你無論往哪裏去，我必保佑你，領你歸回這地，總不離棄你，直到我成全了向你所應許的。」", "ja": "わたしはあなたと共にいて、あなたがどこへ行くにもあなたを守り、あなたをこの地に連れ帰るであろう。わたしは決してあなたを捨てず、あなたに語った事を行うであろう」。"}, "16": {"en": "Jacob awakened out of his sleep, and he said, “Surely the LORD is in this place, and I didn’t know it.”", "zh": "雅各睡醒了，說：「耶和華真在這裏，我竟不知道！」", "ja": "ヤコブは眠りからさめて言った、「まことに主がこの所におられるのに、わたしは知らなかった」。"}, "17": {"en": "He was afraid, and said, “How awesome this place is! This is none other than God’s house, and this is the gate of heaven.”", "zh": "就懼怕，說：「這地方何等可畏！這不是別的，乃是上帝的殿，也是天的門。」", "ja": "そして彼は恐れて言った、「これはなんという恐るべき所だろう。これは神の家である。これは天の門だ」。"}, "18": {"en": "Jacob rose up early in the morning, and took the stone that he had put under his head, and set it up for a pillar, and poured oil on its top.", "zh": "雅各清早起來，把所枕的石頭立作柱子，澆油在上面。", "ja": "ヤコブは朝はやく起きて、まくらとしていた石を取り、それを立てて柱とし、その頂に油を注いで、"}, "19": {"en": "He called the name of that place Bethel, but the name of the city was Luz at the first.", "zh": "他就給那地方起名叫伯特利；但那地方起先名叫路斯。", "ja": "その所の名をベテルと名づけた。その町の名は初めはルズといった。"}, "20": {"en": "Jacob vowed a vow, saying, “If God will be with me, and will keep me in this way that I go, and will give me bread to eat, and clothing to put on,", "zh": "雅各許願說：「上帝若與我同在，在我所行的路上保佑我，又給我食物吃，衣服穿，", "ja": "ヤコブは誓いを立てて言った、「神がわたしと共にいまし、わたしの行くこの道でわたしを守り、食べるパンと着る着物を賜い、"}, "21": {"en": "so that I come again to my father’s house in peace, and the LORD will be my God,", "zh": "使我平平安安地回到我父親的家，我就必以耶和華為我的上帝。", "ja": "安らかに父の家に帰らせてくださるなら、主をわたしの神といたしましょう。"}, "22": {"en": "then this stone, which I have set up for a pillar, will be God’s house. Of all that you will give me I will surely give a tenth to you.”", "zh": "我所立為柱子的石頭也必作上帝的殿；凡你所賜給我的，我必將十分之一獻給你。」", "ja": "またわたしが柱に立てたこの石を神の家といたしましょう。そしてあなたがくださるすべての物の十分の一を、わたしは必ずあなたにささげます」。"}}}, "29": {"verses": {"1": {"en": "Then Jacob went on his journey, and came to the land of the children of the east.", "zh": "雅各起行，到了東方人之地，", "ja": "ヤコブはその旅を続けて東の民の地へ行った。"}, "2": {"en": "He looked, and saw a well in the field, and saw three flocks of sheep lying there by it. For out of that well they watered the flocks. The stone on the well’s mouth was large.", "zh": "看見田間有一口井，有三群羊臥在井旁；因為人飲羊群都是用那井裏的水。井口上的石頭是大的。", "ja": "見ると野に一つの井戸があって、そのかたわらに羊の三つの群れが伏していた。人々はその井戸から群れに水を飲ませるのであったが、井戸の口には大きな石があった。"}, "3": {"en": "There all the flocks were gathered. They rolled the stone from the well’s mouth, and watered the sheep, and put the stone back on the well’s mouth in its place.", "zh": "常有羊群在那裏聚集，牧人把石頭轉離井口飲羊，隨後又把石頭放在井口的原處。", "ja": "群れが皆そこに集まると、人々は井戸の口から石をころがして羊に水を飲ませ、その石をまた井戸の口の元のところに返しておくのである。"}, "4": {"en": "Jacob said to them, “My relatives, where are you from?” They said, “We are from Haran.”", "zh": "雅各對牧人說：「弟兄們，你們是哪裏來的？」他們說：「我們是哈蘭來的。」", "ja": "ヤコブは人々に言った、「兄弟たちよ、あなたがたはどこからこられたのですか」。彼らは言った、「わたしたちはハランからです」。"}, "5": {"en": "He said to them, “Do you know Laban, the son of Nahor?” They said, “We know him.”", "zh": "他問他們說：「拿鶴的孫子拉班，你們認識嗎？」他們說：「我們認識。」", "ja": "ヤコブは彼らに言った、「あなたがたはナホルの子ラバンを知っていますか」。彼らは言った、「知っています」。"}, "6": {"en": "He said to them, “Is it well with him?” They said, “It is well. See, Rachel, his daughter, is coming with the sheep.”", "zh": "雅各說：「他平安嗎？」他們說：「平安。看哪，他女兒拉結領着羊來了。」", "ja": "ヤコブはまた彼らに言った、「彼は無事ですか」。彼らは言った、「無事です。御覧なさい。彼の娘ラケルはいま羊と一緒にここへきます」。"}, "7": {"en": "He said, “Behold, it is still the middle of the day, not time to gather the livestock together. Water the sheep, and go and feed them.”", "zh": "雅各說：「日頭還高，不是羊群聚集的時候，你們不如飲羊，再去放一放。」", "ja": "ヤコブは言った、「日はまだ高いし、家畜を集める時でもない。あなたがたは羊に水を飲ませてから、また行って飼いなさい」。"}, "8": {"en": "They said, “We can’t, until all the flocks are gathered together, and they roll the stone from the well’s mouth. Then we will water the sheep.”", "zh": "他們說：「我們不能，必等羊群聚齊，人把石頭轉離井口才可飲羊。」", "ja": "彼らは言った、「わたしたちはそれはできないのです。群れがみな集まった上で、井戸の口から石をころがし、それから羊に水を飲ませるのです」。"}, "9": {"en": "While he was yet speaking with them, Rachel came with her father’s sheep, for she kept them.", "zh": "雅各正和他們說話的時候，拉結領着她父親的羊來了，因為那些羊是她牧放的。", "ja": "ヤコブがなお彼らと語っている時に、ラケルは父の羊と一緒にきた。彼女は羊を飼っていたからである。"}, "10": {"en": "When Jacob saw Rachel the daughter of Laban, his mother’s brother, and the sheep of Laban, his mother’s brother, Jacob went near, and rolled the stone from the well’s mouth, and watered the flock of Laban his mother’s brother.", "zh": "雅各看見母舅拉班的女兒拉結和母舅拉班的羊群，就上前把石頭轉離井口，飲他母舅拉班的羊群。", "ja": "ヤコブは母の兄ラバンの娘ラケルと母の兄ラバンの羊とを見た。そしてヤコブは進み寄って井戸の口から石をころがし、母の兄ラバンの羊に水を飲ませた。"}, "11": {"en": "Jacob kissed Rachel, and lifted up his voice, and wept.", "zh": "雅各與拉結親嘴，就放聲而哭。", "ja": "ヤコブはラケルに口づけし、声をあげて泣いた。"}, "12": {"en": "Jacob told Rachel that he was her father’s relative, and that he was Rebekah’s son. She ran and told her father.", "zh": "雅各告訴拉結，自己是她父親的外甥，是利百加的兒子，拉結就跑去告訴她父親。", "ja": "ヤコブはラケルに、自分がラケルの父のおいであり、リベカの子であることを告げたので、彼女は走って行って父に話した。"}, "13": {"en": "When Laban heard the news of Jacob, his sister’s son, he ran to meet Jacob, and embraced him, and kissed him, and brought him to his house. Jacob told Laban all these things.", "zh": "拉班聽見外甥雅各的信息，就跑去迎接，抱着他，與他親嘴，領他到自己的家。雅各將一切的情由告訴拉班。", "ja": "ラバンは妹の子ヤコブがきたという知らせを聞くとすぐ、走って行ってヤコブを迎え、これを抱いて口づけし、家に連れてきた。そこでヤコブはすべての事をラバンに話した。"}, "14": {"en": "Laban said to him, “Surely you are my bone and my flesh.” Jacob stayed with him for a month.", "zh": "拉班對他說：「你實在是我的骨肉。」雅各就和他同住了一個月。", "ja": "ラバンは彼に言った、「あなたはほんとうにわたしの骨肉です」。ヤコブは一か月の間彼と共にいた。"}, "15": {"en": "Laban said to Jacob, “Because you are my relative, should you therefore serve me for nothing? Tell me, what will your wages be?”", "zh": "拉班對雅各說：「你雖是我的骨肉，豈可白白地服事我？請告訴我，你要甚麼為工價？」", "ja": "時にラバンはヤコブに言った、「あなたはわたしのおいだからといって、ただでわたしのために働くこともないでしょう。どんな報酬を望みますか、わたしに言ってください」。"}, "16": {"en": "Laban had two daughters. The name of the elder was Leah, and the name of the younger was Rachel.", "zh": "拉班有兩個女兒，大的名叫利亞，小的名叫拉結。", "ja": "さてラバンにはふたりの娘があった。姉の名はレアといい、妹の名はラケルといった。"}, "17": {"en": "Leah’s eyes were weak, but Rachel was beautiful in form and attractive.", "zh": "利亞的眼睛沒有神氣，拉結卻生得美貌俊秀。", "ja": "レアは目が弱かったが、ラケルは美しくて愛らしかった。"}, "18": {"en": "Jacob loved Rachel. He said, “I will serve you seven years for Rachel, your younger daughter.”", "zh": "雅各愛拉結，就說：「我願為你小女兒拉結服事你七年。」", "ja": "ヤコブはラケルを愛したので、「わたしは、あなたの妹娘ラケルのために七年あなたに仕えましょう」と言った。"}, "19": {"en": "Laban said, “It is better that I give her to you, than that I should give her to another man. Stay with me.”", "zh": "拉班說：「我把她給你，勝似給別人，你與我同住吧！」", "ja": "ラバンは言った、「彼女を他人にやるよりもあなたにやる方がよい。わたしと一緒にいなさい」。"}, "20": {"en": "Jacob served seven years for Rachel. They seemed to him but a few days, for the love he had for her.", "zh": "雅各就為拉結服事了七年；他因為深愛拉結，就看這七年如同幾天。", "ja": "こうして、ヤコブは七年の間ラケルのために働いたが、彼女を愛したので、ただ数日のように思われた。"}, "21": {"en": "Jacob said to Laban, “Give me my wife, for my days are fulfilled, that I may go in to her.”", "zh": "雅各對拉班說：「日期已經滿了，求你把我的妻子給我，我好與她同房。」", "ja": "ヤコブはラバンに言った、「期日が満ちたから、わたしの妻を与えて、妻の所にはいらせてください」。"}, "22": {"en": "Laban gathered together all the men of the place, and made a feast.", "zh": "拉班就擺設筵席，請齊了那地方的眾人。", "ja": "そこでラバンはその所の人々をみな集めて、ふるまいを設けた。"}, "23": {"en": "In the evening, he took Leah his daughter, and brought her to Jacob. He went in to her.", "zh": "到晚上，拉班將女兒利亞送來給雅各，雅各就與她同房。", "ja": "夕暮となったとき、娘レアをヤコブのもとに連れてきたので、ヤコブは彼女の所にはいった。"}, "24": {"en": "Laban gave Zilpah his servant to his daughter Leah for a servant.", "zh": "拉班又將婢女悉帕給女兒利亞作使女。", "ja": "ラバンはまた自分のつかえめジルパを娘レアにつかえめとして与えた。"}, "25": {"en": "In the morning, behold, it was Leah! He said to Laban, “What is this you have done to me? Didn’t I serve with you for Rachel? Why then have you deceived me?”", "zh": "到了早晨，雅各一看是利亞，就對拉班說：「你向我做的是甚麼事呢？我服事你，不是為拉結嗎？你為甚麼欺哄我呢？」", "ja": "朝になって、見ると、それはレアであったので、ヤコブはラバンに言った、「あなたはどうしてこんな事をわたしにされたのですか。わたしはラケルのために働いたのではありませんか。どうしてあなたはわたしを欺いたのですか」。"}, "26": {"en": "Laban said, “It is not done so in our place, to give the younger before the firstborn.", "zh": "拉班說：「大女兒還沒有給人，先把小女兒給人，在我們這地方沒有這規矩。", "ja": "ラバンは言った、「妹を姉より先にとつがせる事はわれわれの国ではしません。"}, "27": {"en": "Fulfill the week of this one, and we will give you the other also for the service which you will serve with me for seven more years.”", "zh": "你為這個滿了七日，我就把那個也給你，你再為她服事我七年。」", "ja": "まずこの娘のために一週間を過ごしなさい。そうすればあの娘もあなたにあげよう。あなたは、そのため更に七年わたしに仕えなければならない」。"}, "28": {"en": "Jacob did so, and fulfilled her week. He gave him Rachel his daughter as wife.", "zh": "雅各就如此行。滿了利亞的七日，拉班便將女兒拉結給雅各為妻。", "ja": "ヤコブはそのとおりにして、その一週間が終ったので、ラバンは娘ラケルをも妻として彼に与えた。"}, "29": {"en": "Laban gave Bilhah, his servant, to his daughter Rachel to be her servant.", "zh": "拉班又將婢女辟拉給女兒拉結作使女。", "ja": "ラバンはまた自分のつかえめビルハを娘ラケルにつかえめとして与えた。"}, "30": {"en": "He went in also to Rachel, and he loved also Rachel more than Leah, and served with him seven more years.", "zh": "雅各也與拉結同房，並且愛拉結勝似愛利亞，於是又服事了拉班七年。", "ja": "ヤコブはまたラケルの所にはいった。彼はレアよりもラケルを愛して、更に七年ラバンに仕えた。"}, "31": {"en": "The LORD saw that Leah was hated, and he opened her womb, but Rachel was barren.", "zh": "耶和華見利亞失寵，就使她生育，拉結卻不生育。", "ja": "主はレアがきらわれるのを見て、その胎を開かれたが、ラケルは、みごもらなかった。"}, "32": {"en": "Leah conceived, and bore a son, and she named him Reuben. For she said, “Because the LORD has looked at my affliction; for now my husband will love me.”", "zh": "利亞懷孕生子，就給他起名叫呂便，因而說：「耶和華看見我的苦情，如今我的丈夫必愛我。」", "ja": "レアは、みごもって子を産み、名をルベンと名づけて、言った、「主がわたしの悩みを顧みられたから、今は夫もわたしを愛するだろう」。"}, "33": {"en": "She conceived again, and bore a son, and said, “Because the LORD has heard that I am hated, he has therefore given me this son also.” She named him Simeon.", "zh": "她又懷孕生子，就說：「耶和華因為聽見我失寵，所以又賜給我這個兒子」，於是給他起名叫西緬。", "ja": "彼女はまた、みごもって子を産み、「主はわたしが嫌われるのをお聞きになって、わたしにこの子をも賜わった」と言って、名をシメオンと名づけた。"}, "34": {"en": "She conceived again, and bore a son. She said, “Now this time my husband will be joined to me, because I have borne him three sons.” Therefore his name was called Levi.", "zh": "她又懷孕生子，起名叫利未，說：「我給丈夫生了三個兒子，他必與我聯合。」", "ja": "彼女はまた、みごもって子を産み、「わたしは彼に三人の子を産んだから、こんどこそは夫もわたしに親しむだろう」と言って、名をレビと名づけた。"}, "35": {"en": "She conceived again, and bore a son. She said, “This time I will praise the LORD.” Therefore she named him Judah. Then she stopped bearing.", "zh": "她又懷孕生子，說：「這回我要讚美耶和華」，因此給他起名叫猶大。這才停了生育。", "ja": "彼女はまた、みごもって子を産み、「わたしは今、主をほめたたえる」と言って名をユダと名づけた。そこで彼女の、子を産むことはやんだ。"}}}, "30": {"verses": {"1": {"en": "When Rachel saw that she bore Jacob no children, Rachel envied her sister. She said to Jacob, “Give me children, or else I will die.”", "zh": "拉結見自己不給雅各生子，就嫉妒她姊姊，對雅各說：「你給我孩子，不然我就死了。」", "ja": "ラケルは自分がヤコブに子を産まないのを知った時、姉をねたんでヤコブに言った、「わたしに子どもをください。さもないと、わたしは死にます」。"}, "2": {"en": "Jacob’s anger burned against Rachel, and he said, “Am I in God’s place, who has withheld from you the fruit of the womb?”", "zh": "雅各向拉結生氣，說：「叫你不生育的是上帝，我豈能代替他作主呢？」", "ja": "ヤコブはラケルに向かい怒って言った、「あなたの胎に子どもをやどらせないのは神です。わたしが神に代ることができようか」。"}, "3": {"en": "She said, “Behold, my maid Bilhah. Go in to her, that she may bear on my knees, and I also may obtain children by her.”", "zh": "拉結說：「有我的使女辟拉在這裏，你可以與她同房，使她生子在我膝下，我便因她也得孩子。」", "ja": "ラケルは言った、「わたしのつかえめビルハがいます。彼女の所におはいりなさい。彼女が子を産んで、わたしのひざに置きます。そうすれば、わたしもまた彼女によって子を持つでしょう」。"}, "4": {"en": "She gave him Bilhah her servant as wife, and Jacob went in to her.", "zh": "拉結就把她的使女辟拉給丈夫為妾；雅各便與她同房，", "ja": "ラケルはつかえめビルハを彼に与えて、妻とさせたので、ヤコブは彼女の所にはいった。"}, "5": {"en": "Bilhah conceived, and bore Jacob a son.", "zh": "辟拉就懷孕，給雅各生了一個兒子。", "ja": "ビルハは、みごもってヤコブに子を産んだ。"}, "6": {"en": "Rachel said, “God has judged me, and has also heard my voice, and has given me a son.” Therefore she called his name Dan.", "zh": "拉結說：「上帝伸了我的冤，也聽了我的聲音，賜我一個兒子」，因此給他起名叫但。", "ja": "そこでラケルは、「神はわたしの訴えに答え、またわたしの声を聞いて、わたしに子を賜わった」と言って、名をダンと名づけた。"}, "7": {"en": "Bilhah, Rachel’s servant, conceived again, and bore Jacob a second son.", "zh": "拉結的使女辟拉又懷孕，給雅各生了第二個兒子。", "ja": "ラケルのつかえめビルハはまた、みごもって第二の子をヤコブに産んだ。"}, "8": {"en": "Rachel said, “I have wrestled with my sister with mighty wrestlings, and have prevailed.” She named him Naphtali.", "zh": "拉結說：「我與我姊姊大大相爭，並且得勝」，於是給他起名叫拿弗他利。", "ja": "そこでラケルは、「わたしは激しい争いで、姉と争って勝った」と言って、名をナフタリと名づけた。"}, "9": {"en": "When Leah saw that she had finished bearing, she took Zilpah, her servant, and gave her to Jacob as a wife.", "zh": "利亞見自己停了生育，就把使女悉帕給雅各為妾。", "ja": "さてレアは自分が子を産むことのやんだのを見たとき、つかえめジルパを取り、妻としてヤコブに与えた。"}, "10": {"en": "Zilpah, Leah’s servant, bore Jacob a son.", "zh": "利亞的使女悉帕給雅各生了一個兒子。", "ja": "レアのつかえめジルパはヤコブに子を産んだ。"}, "11": {"en": "Leah said, “How fortunate!” She named him Gad.", "zh": "利亞說：「萬幸！」於是給他起名叫迦得 。", "ja": "そこでレアは、「幸運がきた」と言って、名をガドと名づけた。"}, "12": {"en": "Zilpah, Leah’s servant, bore Jacob a second son.", "zh": "利亞的使女悉帕又給雅各生了第二個兒子。", "ja": "レアのつかえめジルパは第二の子をヤコブに産んだ。"}, "13": {"en": "Leah said, “Happy am I, for the daughters will call me happy.” She named him Asher.", "zh": "利亞說：「我有福啊，眾女子都要稱我是有福的」，於是給他起名叫亞設。", "ja": "そこでレアは、「わたしは、しあわせです。娘たちはわたしをしあわせな者と言うでしょう」と言って、名をアセルと名づけた。"}, "14": {"en": "Reuben went in the days of wheat harvest, and found mandrakes in the field, and brought them to his mother, Leah. Then Rachel said to Leah, “Please give me some of your son’s mandrakes.”", "zh": "割麥子的時候，呂便往田裏去，尋見風茄，拿來給他母親利亞。拉結對利亞說：「請你把你兒子的風茄給我些。」", "ja": "さてルベンは麦刈りの日に野に出て、野で恋なすびを見つけ、それを母レアのもとに持ってきた。ラケルはレアに言った、「あなたの子の恋なすびをどうぞわたしにください」。"}, "15": {"en": "Leah said to her, “Is it a small matter that you have taken away my husband? Would you take away my son’s mandrakes, also?” Rachel said, “Therefore he will lie with you tonight for your son’s mandrakes.”", "zh": "利亞說：「你奪了我的丈夫還算小事嗎？你又要奪我兒子的風茄嗎？」拉結說：「為你兒子的風茄，今夜他可以與你同寢。」", "ja": "レアはラケルに言った、「あなたがわたしの夫を取ったのは小さな事でしょうか。その上、あなたはまたわたしの子の恋なすびをも取ろうとするのですか」。ラケルは言った、「それではあなたの子の恋なすびに換えて、今夜彼をあなたと共に寝させましょう」。"}, "16": {"en": "Jacob came from the field in the evening, and Leah went out to meet him, and said, “You must come in to me; for I have surely hired you with my son’s mandrakes.”", "zh": "到了晚上，雅各從田裏回來，利亞出來迎接他，說：「你要與我同寢，因為我實在用我兒子的風茄把你雇下了。」那一夜，雅各就與她同寢。", "ja": "夕方になって、ヤコブが野から帰ってきたので、レアは彼を出迎えて言った、「わたしの子の恋なすびをもって、わたしがあなたを雇ったのですから、あなたはわたしの所に、はいらなければなりません」。ヤコブはその夜レアと共に寝た。"}, "17": {"en": "He lay with her that night.   God listened to Leah, and she conceived, and bore Jacob a fifth son.", "zh": "上帝應允了利亞，她就懷孕，給雅各生了第五個兒子。", "ja": "神はレアの願いを聞かれたので、彼女はみごもって五番目の子をヤコブに産んだ。"}, "18": {"en": "Leah said, “God has given me my hire, because I gave my servant to my husband.” She named him Issachar.", "zh": "利亞說：「上帝給了我價值，因為我把使女給了我丈夫」，於是給他起名叫以薩迦。", "ja": "そこでレアは、「わたしがつかえめを夫に与えたから、神がわたしにその価を賜わったのです」と言って、名をイッサカルと名づけた。"}, "19": {"en": "Leah conceived again, and bore a sixth son to Jacob.", "zh": "利亞又懷孕，給雅各生了第六個兒子。", "ja": "レアはまた、みごもって六番目の子をヤコブに産んだ。"}, "20": {"en": "Leah said, “God has endowed me with a good dowry. Now my husband will live with me, because I have borne him six sons.” She named him Zebulun.", "zh": "利亞說：「上帝賜我厚賞；我丈夫必與我同住，因我給他生了六個兒子」，於是給他起名西布倫。", "ja": "そこでレアは、「神はわたしに良い賜物をたまわった。わたしは六人の子を夫に産んだから、今こそ彼はわたしと一緒に住むでしょう」と言って、その名をゼブルンと名づけた。"}, "21": {"en": "Afterwards, she bore a daughter, and named her Dinah.", "zh": "後來又生了一個女兒，給她起名叫底拿。", "ja": "その後、彼女はひとりの娘を産んで、名をデナと名づけた。"}, "22": {"en": "God remembered Rachel, and God listened to her, and opened her womb.", "zh": "上帝顧念拉結，應允了她，使她能生育。", "ja": "次に神はラケルを心にとめられ、彼女の願いを聞き、その胎を開かれたので、"}, "23": {"en": "She conceived, bore a son, and said, “God has taken away my reproach.”", "zh": "拉結懷孕生子，說：「上帝除去了我的羞恥」，", "ja": "彼女は、みごもって男の子を産み、「神はわたしの恥をすすいでくださった」と言って、"}, "24": {"en": "She named him Joseph, saying, “May the LORD add another son to me.”", "zh": "就給他起名叫約瑟，意思說：「願耶和華再增添我一個兒子。」", "ja": "名をヨセフと名づけ、「主がわたしに、なおひとりの子を加えられるように」と言った。"}, "25": {"en": "When Rachel had borne Joseph, Jacob said to Laban, “Send me away, that I may go to my own place, and to my country.", "zh": "拉結生約瑟之後，雅各對拉班說：「請打發我走，叫我回到我本鄉本土去。", "ja": "ラケルがヨセフを産んだ時、ヤコブはラバンに言った、「わたしを去らせて、わたしの故郷、わたしの国へ行かせてください。"}, "26": {"en": "Give me my wives and my children for whom I have served you, and let me go; for you know my service with which I have served you.”", "zh": "請你把我服事你所得的妻子和兒女給我，讓我走；我怎樣服事你，你都知道。」", "ja": "あなたに仕えて得たわたしの妻子を、わたしに与えて行かせてください。わたしがあなたのために働いた骨折りは、あなたがごぞんじです」。"}, "27": {"en": "Laban said to him, “If now I have found favor in your eyes, stay here, for I have divined that the LORD has blessed me for your sake.”", "zh": "拉班對他說：「我若在你眼前蒙恩，請你仍與我同住，因為我已算定，耶和華賜福與我是為你的緣故」；", "ja": "ラバンは彼に言った、「もし、あなたの心にかなうなら、とどまってください。わたしは主があなたのゆえに、わたしを恵まれるしるしを見ました」。"}, "28": {"en": "He said, “Appoint me your wages, and I will give it.”", "zh": "又說：「請你定你的工價，我就給你。」", "ja": "また言った、「あなたの報酬を申し出てください。わたしはそれを払います」。"}, "29": {"en": "Jacob said to him, “You know how I have served you, and how your livestock have fared with me.", "zh": "雅各對他說：「我怎樣服事你，你的牲畜在我手裏怎樣，是你知道的。", "ja": "ヤコブは彼に言った、「わたしがどのようにあなたに仕えたか、またどのようにあなたの家畜を飼ったかは、あなたがごぞんじです。"}, "30": {"en": "For it was little which you had before I came, and it has increased to a multitude. The LORD has blessed you wherever I turned. Now when will I provide for my own house also?”", "zh": "我未來之先，你所有的很少，現今卻發大眾多，耶和華隨我的腳步賜福與你。如今，我甚麼時候才為自己興家立業呢？」", "ja": "わたしが来る前には、あなたの持っておられたものはわずかでしたが、ふえて多くなりました。主はわたしの行く所どこでも、あなたを恵まれました。しかし、いつになったらわたしも自分の家を成すようになるでしょうか」。"}, "31": {"en": "Laban said, “What shall I give you?”", "zh": "拉班說：「我當給你甚麼呢？」雅各說：「甚麼你也不必給我，只有一件事，你若應承，我便仍舊牧放你的羊群。", "ja": "彼は言った、「何をあなたにあげようか」。ヤコブは言った、「なにもわたしにくださるに及びません。もしあなたが、わたしのためにこの一つの事をしてくださるなら、わたしは今一度あなたの群れを飼い、守りましょう。"}, "32": {"en": "Jacob said, “You shall not give me anything. If you will do this thing for me, I will again feed your flock and keep it.   I will pass through all your flock today, removing from there every speckled and spotted one, and every black one among the sheep, and the spotted and speckled among the goats. This will be my hire.", "zh": "今天我要走遍你的羊群，把綿羊中凡有點的、有斑的，和黑色的，並山羊中凡有斑的、有點的，都挑出來；將來這一等的就算我的工價。", "ja": "わたしはきょう、あなたの群れをみな回ってみて、その中からすべてぶちとまだらの羊、およびすべて黒い小羊と、やぎの中のまだらのものと、ぶちのものとを移しますが、これをわたしの報酬としましょう。"}, "33": {"en": "So my righteousness will answer for me hereafter, when you come concerning my hire that is before you. Every one that is not speckled and spotted among the goats, and black among the sheep, that might be with me, will be considered stolen.”", "zh": "以後你來查看我的工價，凡在我手裏的山羊不是有點有斑的，綿羊不是黑色的，那就算是我偷的；這樣便可證出我的公義來。」", "ja": "あとで、あなたがきて、あなたの前でわたしの報酬をしらべる時、わたしの正しい事が証明されるでしょう。もしも、やぎの中にぶちのないもの、まだらでないものがあったり、小羊の中に黒くないものがあれば、それはみなわたしが盗んだものとなるでしょう」。"}, "34": {"en": "Laban said, “Behold, let it be according to your word.”", "zh": "拉班說：「好啊！我情願照着你的話行。」", "ja": "ラバンは言った、「よろしい。あなたの言われるとおりにしましょう」。"}, "35": {"en": "That day, he removed the male goats that were streaked and spotted, and all the female goats that were speckled and spotted, every one that had white in it, and all the black ones among the sheep, and gave them into the hand of his sons.", "zh": "當日，拉班把有紋的、有斑的公山羊，有點的、有斑的、有雜白紋的母山羊，並黑色的綿羊，都挑出來，交在他兒子們的手下，", "ja": "そこでラバンはその日、雄やぎのしまのあるもの、まだらのもの、すべて雌やぎのぶちのもの、まだらのもの、すべて白みをおびているもの、またすべて小羊の中の黒いものを移して子らの手にわたし、"}, "36": {"en": "He set three days’ journey between himself and Jacob, and Jacob fed the rest of Laban’s flocks.", "zh": "又使自己和雅各相離三天的路程。雅各就牧養拉班其餘的羊。", "ja": "ヤコブとの間に三日路の隔たりを設けた。ヤコブはラバンの残りの群れを飼った。"}, "37": {"en": "Jacob took to himself rods of fresh poplar, almond, and plane tree, peeled white streaks in them, and made the white appear which was in the rods.", "zh": "雅各拿楊樹、杏樹、楓樹的嫩枝，將皮剝成白紋，使枝子露出白的來，", "ja": "ヤコブは、はこやなぎと、あめんどうと、すずかけの木のなまの枝を取り、皮をはいでそれに白い筋をつくり、枝の白い所を表わし、"}, "38": {"en": "He set the rods which he had peeled opposite the flocks in the watering troughs where the flocks came to drink. They conceived when they came to drink.", "zh": "將剝了皮的枝子，對着羊群，插在飲羊的水溝裏和水槽裏，羊來喝的時候，牝牡配合。", "ja": "皮をはいだ枝を、群れがきて水を飲む鉢、すなわち水ぶねの中に、群れに向かわせて置いた。群れは水を飲みにきた時に、はらんだ。"}, "39": {"en": "The flocks conceived before the rods, and the flocks produced streaked, speckled, and spotted.", "zh": "羊對着枝子配合，就生下有紋的、有點的、有斑的來。", "ja": "すなわち群れは枝の前で、はらんで、しまのあるもの、ぶちのもの、まだらのものを産んだ。"}, "40": {"en": "Jacob separated the lambs, and set the faces of the flocks toward the streaked and all the black in Laban’s flock. He put his own droves apart, and didn’t put them into Laban’s flock.", "zh": "雅各把羊羔分出來，使拉班的羊與這有紋和黑色的羊相對，把自己的羊另放一處，不叫他和拉班的羊混雜。", "ja": "ヤコブはその小羊を別においた。彼はまた群れの顔をラバンの群れのしまのあるものと、すべて黒いものとに向かわせた。そして自分の群れを別にまとめておいて、ラバンの群れには、入れなかった。"}, "41": {"en": "Whenever the stronger of the flock conceived, Jacob laid the rods in front of the eyes of the flock in the watering troughs, that they might conceive among the rods;", "zh": "到羊群肥壯配合的時候，雅各就把枝子插在水溝裏，使羊對着枝子配合。", "ja": "また群れの強いものが発情した時には、ヤコブは水ぶねの中に、その群れの目の前に、かの枝を置いて、枝の間で、はらませた。"}, "42": {"en": "but when the flock were feeble, he didn’t put them in. So the feebler were Laban’s, and the stronger Jacob’s.", "zh": "只是到羊瘦弱配合的時候就不插枝子。這樣，瘦弱的就歸拉班，肥壯的就歸雅各。", "ja": "けれども群れの弱いものの時には、それを置かなかった。こうして弱いものはラバンのものとなり、強いものはヤコブのものとなったので、"}, "43": {"en": "The man increased exceedingly, and had large flocks, female servants and male servants, and camels and donkeys.", "zh": "於是雅各極其發大，得了許多的羊群、僕婢、駱駝，和驢。", "ja": "この人は大いに富み、多くの群れと、男女の奴隷、およびらくだ、ろばを持つようになった。"}}}, "31": {"verses": {"1": {"en": "Jacob heard Laban’s sons’ words, saying, “Jacob has taken away all that was our father’s. He has obtained all this wealth from that which was our father’s.”", "zh": "雅各聽見拉班的兒子們有話說：「雅各把我們父親所有的都奪了去，並藉着我們父親的，得了這一切的榮耀。」", "ja": "さてヤコブはラバンの子らが、「ヤコブはわれわれの父の物をことごとく奪い、父の物によってあのすべての富を獲たのだ」と言っているのを聞いた。"}, "2": {"en": "Jacob saw the expression on Laban’s face, and, behold, it was not toward him as before.", "zh": "雅各見拉班的氣色向他不如從前了。", "ja": "またヤコブがラバンの顔を見るのに、それは自分に対して以前のようではなかった。"}, "3": {"en": "The LORD said to Jacob, “Return to the land of your fathers, and to your relatives, and I will be with you.”", "zh": "耶和華對雅各說：「你要回你祖、你父之地，到你親族那裏去，我必與你同在。」", "ja": "主はヤコブに言われた、「あなたの先祖の国へ帰り、親族のもとに行きなさい。わたしはあなたと共にいるであろう」。"}, "4": {"en": "Jacob sent and called Rachel and Leah to the field to his flock,", "zh": "雅各就打發人，叫拉結和利亞到田野羊群那裏來，", "ja": "そこでヤコブは人をやって、ラケルとレアとを、野にいる自分の群れのところに招き、"}, "5": {"en": "and said to them, “I see the expression on your father’s face, that it is not toward me as before; but the God of my father has been with me.", "zh": "對她們說：「我看你們父親的氣色向我不如從前了；但我父親的上帝向來與我同在。", "ja": "彼女らに言った、「わたしがあなたがたの父の顔を見るのに、わたしに対して以前のようではない。しかし、わたしの父の神はわたしと共におられる。"}, "6": {"en": "You know that I have served your father with all of my strength.", "zh": "你們也知道，我盡了我的力量服事你們的父親。", "ja": "あなたがたが知っているように、わたしは力のかぎり、あなたがたの父に仕えてきた。"}, "7": {"en": "Your father has deceived me, and changed my wages ten times, but God didn’t allow him to hurt me.", "zh": "你們的父親欺哄我，十次改了我的工價；然而上帝不容他害我。", "ja": "しかし、あなたがたの父はわたしを欺いて、十度もわたしの報酬を変えた。けれども神は彼がわたしに害を加えることをお許しにならなかった。"}, "8": {"en": "If he said, ‘The speckled will be your wages,’ then all the flock bore speckled. If he said, ‘The streaked will be your wages,’ then all the flock bore streaked.", "zh": "他若說：『有點的歸你作工價』，羊群所生的都有點；他若說：『有紋的歸你作工價』，羊群所生的都有紋。", "ja": "もし彼が、『ぶちのものはあなたの報酬だ』と言えば、群れは皆ぶちのものを産んだ。もし彼が、『しまのあるものはあなたの報酬だ』と言えば、群れは皆しまのあるものを産んだ。"}, "9": {"en": "Thus God has taken away your father’s livestock, and given them to me.", "zh": "這樣，上帝把你們父親的牲畜奪來賜給我了。", "ja": "こうして神はあなたがたの父の家畜をとってわたしに与えられた。"}, "10": {"en": "During mating season, I lifted up my eyes, and saw in a dream, and behold, the male goats which leaped on the flock were streaked, speckled, and grizzled.", "zh": "羊配合的時候，我夢中舉目一看，見跳母羊的公羊都是有紋的、有點的、有花斑的。", "ja": "また群れが発情した時、わたしが夢に目をあげて見ると、群れの上に乗っている雄やぎは皆しまのあるもの、ぶちのもの、霜ふりのものであった。"}, "11": {"en": "The angel of God said to me in the dream, ‘Jacob,’ and I said, ‘Here I am.’", "zh": "上帝的使者在那夢中呼叫我說：『雅各。』我說：『我在這裏。』", "ja": "その時、神の使が夢の中でわたしに言った、『ヤコブよ』。わたしは答えた、『ここにおります』。"}, "12": {"en": "He said, ‘Now lift up your eyes, and behold, all the male goats which leap on the flock are streaked, speckled, and grizzled, for I have seen all that Laban does to you.", "zh": "他說：『你舉目觀看，跳母羊的公羊都是有紋的、有點的、有花斑的；凡拉班向你所做的，我都看見了。", "ja": "神の使は言った、『目を上げて見てごらん。群れの上に乗っている雄やぎは皆しまのあるもの、ぶちのもの、霜ふりのものです。わたしはラバンがあなたにしたことをみな見ています。"}, "13": {"en": "I am the God of Bethel, where you anointed a pillar, where you vowed a vow to me. Now arise, get out from this land, and return to the land of your birth.’ ”", "zh": "我是伯特利的上帝；你在那裏用油澆過柱子，向我許過願。現今你起來，離開這地，回你本地去吧！』」", "ja": "わたしはベテルの神です。かつてあなたはあそこで柱に油を注いで、わたしに誓いを立てましたが、いま立ってこの地を出て、あなたの生れた国へ帰りなさい』」。"}, "14": {"en": "Rachel and Leah answered him, “Is there yet any portion or inheritance for us in our father’s house?", "zh": "拉結和利亞回答雅各說：「在我們父親的家裏還有我們可得的分嗎？還有我們的產業嗎？", "ja": "ラケルとレアは答えて言った、「わたしたちの父の家に、なおわたしたちの受くべき分、また嗣業がありましょうか。"}, "15": {"en": "Aren’t we considered as foreigners by him? For he has sold us, and has also used up our money.", "zh": "我們不是被他當作外人嗎？因為他賣了我們，吞了我們的價值。", "ja": "わたしたちは父に他人のように思われているではありませんか。彼はわたしたちを売ったばかりでなく、わたしたちのその金をさえ使い果たしたのです。"}, "16": {"en": "For all the riches which God has taken away from our father are ours and our children’s. Now then, whatever God has said to you, do.”", "zh": "上帝從我們父親所奪出來的一切財物，那就是我們和我們孩子們的。現今凡上帝所吩咐你的，你只管去行吧！」", "ja": "神がわたしたちの父から取りあげられた富は、みなわたしたちとわたしたちの子どものものです。だから何事でも神があなたにお告げになった事をしてください」。"}, "17": {"en": "Then Jacob rose up, and set his sons and his wives on the camels,", "zh": "雅各起來，使他的兒子和妻子都騎上駱駝，", "ja": "そこでヤコブは立って、子らと妻たちをらくだに乗せ、"}, "18": {"en": "and he took away all his livestock, and all his possessions which he had gathered, including the livestock which he had gained in Paddan Aram, to go to Isaac his father, to the land of Canaan.", "zh": "又帶着他在巴旦‧亞蘭所得的一切牲畜和財物，往迦南地、他父親以撒那裏去了。", "ja": "またすべての家畜、すなわち彼がパダンアラムで獲た家畜と、すべての財産を携えて、カナンの地におる父イサクのもとへ赴いた。"}, "19": {"en": "Now Laban had gone to shear his sheep; and Rachel stole the teraphim that were her father’s.", "zh": "當時拉班剪羊毛去了，拉結偷了他父親家中的神像。", "ja": "その時ラバンは羊の毛を切るために出ていたので、ラケルは父の所有のテラピムを盗み出した。"}, "20": {"en": "Jacob deceived Laban the Syrian, in that he didn’t tell him that he was running away.", "zh": "雅各背着亞蘭人拉班偷走了，並不告訴他，", "ja": "またヤコブはアラムびとラバンを欺き、自分の逃げ去るのを彼に告げなかった。"}, "21": {"en": "So he fled with all that he had. He rose up, passed over the River, and set his face toward the mountain of Gilead.", "zh": "就帶着所有的逃跑。他起身過大河，面向基列山行去。", "ja": "こうして彼はすべての持ち物を携えて逃げ、立って川を渡り、ギレアデの山地へ向かった。"}, "22": {"en": "Laban was told on the third day that Jacob had fled.", "zh": "到第三日，有人告訴拉班，雅各逃跑了。", "ja": "三日目になって、ヤコブの逃げ去ったことが、ラバンに聞えたので、"}, "23": {"en": "He took his relatives with him, and pursued him seven days’ journey. He overtook him in the mountain of Gilead.", "zh": "拉班帶領他的眾弟兄去追趕，追了七日，在基列山就追上了。", "ja": "彼は一族を率いて、七日の間そのあとを追い、ギレアデの山地で追いついた。"}, "24": {"en": "God came to Laban the Syrian in a dream of the night, and said to him, “Be careful that you don’t speak to Jacob either good or bad.”", "zh": "夜間，上帝到亞蘭人拉班那裏，在夢中對他說：「你要小心，不可與雅各說好說歹。」", "ja": "しかし、神は夜の夢にアラムびとラバンに現れて言われた、「あなたは心してヤコブに、よしあしを言ってはなりません」。"}, "25": {"en": "Laban caught up with Jacob. Now Jacob had pitched his tent in the mountain, and Laban with his relatives encamped in the mountain of Gilead.", "zh": "拉班追上雅各。雅各在山上支搭帳棚；拉班和他的眾弟兄也在基列山上支搭帳棚。", "ja": "ラバンはついにヤコブに追いついたが、ヤコブが山に天幕を張っていたので、ラバンも一族と共にギレアデの山に天幕を張った。"}, "26": {"en": "Laban said to Jacob, “What have you done, that you have deceived me, and carried away my daughters like captives of the sword?", "zh": "拉班對雅各說：「你做的是甚麼事呢？你背着我偷走了，又把我的女兒們帶了去，如同用刀劍擄去的一般。", "ja": "ラバンはヤコブに言った、「あなたはなんという事をしたのですか。あなたはわたしを欺いてわたしの娘たちをいくさのとりこのように引いて行きました。"}, "27": {"en": "Why did you flee secretly, and deceive me, and didn’t tell me, that I might have sent you away with mirth and with songs, with tambourine and with harp;", "zh": "你為甚麼暗暗地逃跑，偷着走，並不告訴我，叫我可以歡樂、唱歌、擊鼓、彈琴地送你回去？", "ja": "なぜあなたはわたしに告げずに、ひそかに逃げ去ってわたしを欺いたのですか。わたしは手鼓や琴で喜び歌ってあなたを送りだそうとしていたのに。"}, "28": {"en": "and didn’t allow me to kiss my sons and my daughters? Now you have done foolishly.", "zh": "又不容我與外孫和女兒親嘴？你所行的真是愚昧！", "ja": "なぜわたしの孫や娘にわたしが口づけするのを許さなかったのですか。あなたは愚かな事をしました。"}, "29": {"en": "It is in the power of my hand to hurt you, but the God of your father spoke to me last night, saying, ‘Be careful that you don’t speak to Jacob either good or bad.’", "zh": "我手中原有能力害你，只是你父親的上帝昨夜對我說：『你要小心，不可與雅各說好說歹。』", "ja": "わたしはあなたがたに害を加える力をもっているが、あなたがたの父の神が昨夜わたしに告げて、『おまえは心して、ヤコブによしあしを言うな』と言われました。"}, "30": {"en": "Now, you want to be gone, because you greatly longed for your father’s house, but why have you stolen my gods?”", "zh": "現在你雖然想你父家，不得不去，為甚麼又偷了我的神像呢？」", "ja": "今あなたが逃げ出したのは父の家が非常に恋しくなったからでしょうが、なぜあなたはわたしの神を盗んだのですか」。"}, "31": {"en": "Jacob answered Laban, “Because I was afraid, for I said, ‘Lest you should take your daughters from me by force.’", "zh": "雅各回答拉班說：「恐怕你把你的女兒從我奪去，所以我逃跑。", "ja": "ヤコブはラバンに答えた、「たぶんあなたが娘たちをわたしから奪いとるだろうと思ってわたしは恐れたからです。"}, "32": {"en": "Anyone you find your gods with shall not live. Before our relatives, discern what is yours with me, and take it.” For Jacob didn’t know that Rachel had stolen them.", "zh": "至於你的神像，你在誰那裏搜出來，就不容誰存活。當着我們的眾弟兄，你認一認，在我這裏有甚麼東西是你的，就拿去。」原來雅各不知道拉結偷了那些神像。", "ja": "だれの所にでもあなたの神が見つかったら、その者を生かしてはおきません。何かあなたの物がわたしのところにあるか、われわれの一族の前で、調べてみて、それをお取りください」。ラケルが神を盗んだことをヤコブは知らなかったからである。"}, "33": {"en": "Laban went into Jacob’s tent, into Leah’s tent, and into the tent of the two female servants; but he didn’t find them. He went out of Leah’s tent, and entered into Rachel’s tent.", "zh": "拉班進了雅各、利亞，並兩個使女的帳棚，都沒有搜出來，就從利亞的帳棚出來，進了拉結的帳棚。", "ja": "そこでラバンはヤコブの天幕にはいり、またレアの天幕にはいり、更にふたりのはしための天幕にはいってみたが、見つからなかったので、レアの天幕を出てラケルの天幕にはいった。"}, "34": {"en": "Now Rachel had taken the teraphim, put them in the camel’s saddle, and sat on them. Laban felt around all the tent, but didn’t find them.", "zh": "拉結已經把神像藏在駱駝的馱簍裏，便坐在上頭。拉班摸遍了那帳棚，並沒有摸着。", "ja": "しかし、ラケルはすでにテラピムを取って、らくだのくらの下に入れ、その上にすわっていたので、ラバンは、くまなく天幕の中を捜したが、見つからなかった。"}, "35": {"en": "She said to her father, “Don’t let my lord be angry that I can’t rise up before you; for I’m having my period.” He searched, but didn’t find the teraphim.", "zh": "拉結對她父親說：「現在我身上不便，不能在你面前起來，求我主不要生氣。」這樣，拉班搜尋神像，竟沒有搜出來。", "ja": "その時ラケルは父に言った、「わたしは女の常のことがあって、あなたの前に立ち上がることができません。わが主よ、どうかお怒りにならぬよう」。彼は捜したがテラピムは見つからなかった。"}, "36": {"en": "Jacob was angry, and argued with Laban. Jacob answered Laban, “What is my trespass? What is my sin, that you have hotly pursued me?", "zh": "雅各就發怒斥責拉班說：「我有甚麼過犯，有甚麼罪惡，你竟這樣火速地追我？", "ja": "そこでヤコブは怒ってラバンを責めた。そしてヤコブはラバンに言った、「わたしにどんなあやまちがあり、どんな罪があって、あなたはわたしのあとを激しく追ったのですか。"}, "37": {"en": "Now that you have felt around in all my stuff, what have you found of all your household stuff? Set it here before my relatives and your relatives, that they may judge between us two.", "zh": "你摸遍了我一切的家具，你搜出甚麼來呢？可以放在你我弟兄面前，叫他們在你我中間辨別辨別。", "ja": "あなたはわたしの物をことごとく探られたが、何かあなたの家の物が見つかりましたか。それを、ここに、わたしの一族と、あなたの一族の前に置いて、われわれふたりの間をさばかせましょう。"}, "38": {"en": "“These twenty years I have been with you. Your ewes and your female goats have not cast their young, and I haven’t eaten the rams of your flocks.", "zh": "我在你家這二十年，你的母綿羊、母山羊沒有掉過胎。你群中的公羊，我沒有吃過；", "ja": "わたしはこの二十年、あなたと一緒にいましたが、その間あなたの雌羊も雌やぎも子を産みそこねたことはなく、またわたしはあなたの群れの雄羊を食べたこともありませんでした。"}, "39": {"en": "That which was torn of animals, I didn’t bring to you. I bore its loss. Of my hand you required it, whether stolen by day or stolen by night.", "zh": "被野獸撕裂的，我沒有帶來給你，是我自己賠上。無論是白日，是黑夜，被偷去的，你都向我索要。", "ja": "また野獣が、かみ裂いたものは、あなたのもとに持ってこないで、自分でそれを償いました。また昼盗まれたものも、夜盗まれたものも、あなたはわたしにその償いを求められました。"}, "40": {"en": "This was my situation: in the day the drought consumed me, and the frost by night; and my sleep fled from my eyes.", "zh": "我白日受盡乾熱，黑夜受盡寒霜，不得合眼睡着，我常是這樣。", "ja": "わたしのことを言えば、昼は暑さに、夜は寒さに悩まされて、眠ることもできませんでした。"}, "41": {"en": "These twenty years I have been in your house. I served you fourteen years for your two daughters, and six years for your flock, and you have changed my wages ten times.", "zh": "我這二十年在你家裏，為你的兩個女兒服事你十四年，為你的羊群服事你六年，你又十次改了我的工價。", "ja": "わたしはこの二十年あなたの家族のひとりでありました。わたしはあなたのふたりの娘のために十四年、またあなたの群れのために六年、あなたに仕えましたが、あなたは十度もわたしの報酬を変えられました。"}, "42": {"en": "Unless the God of my father, the God of Abraham, and the fear of Isaac, had been with me, surely now you would have sent me away empty. God has seen my affliction and the labor of my hands, and rebuked you last night.”", "zh": "若不是我父親以撒所敬畏的上帝，就是亞伯拉罕的上帝與我同在，你如今必定打發我空手而去。上帝看見我的苦情和我的勞碌，就在昨夜責備你。」", "ja": "もし、わたしの父の神、アブラハムの神、イサクのかしこむ者がわたしと共におられなかったなら、あなたはきっとわたしを、から手で去らせたでしょう。神はわたしの悩みと、わたしの労苦とを顧みられて昨夜あなたを戒められたのです」。"}, "43": {"en": "Laban answered Jacob, “The daughters are my daughters, the children are my children, the flocks are my flocks, and all that you see is mine! What can I do today to these my daughters, or to their children whom they have borne?", "zh": "拉班回答雅各說：「這女兒是我的女兒，這些孩子是我的孩子，這些羊群也是我的羊群；凡在你眼前的都是我的。我的女兒並她們所生的孩子，我今日能向他們做甚麼呢？", "ja": "ラバンは答えてヤコブに言った、「娘たちはわたしの娘、子どもたちはわたしの孫です。また群れはわたしの群れ、あなたの見るものはみなわたしのものです。これらのわたしの娘たちのため、また彼らが産んだ子どもたちのため、きょうわたしは何をすることができましょうか。"}, "44": {"en": "Now come, let’s make a covenant, you and I. Let it be for a witness between me and you.”", "zh": "來吧！你我二人可以立約，作你我中間的證據。」", "ja": "さあ、それではわたしとあなたと契約を結んで、これをわたしとあなたとの間の証拠としましょう」。"}, "45": {"en": "Jacob took a stone, and set it up for a pillar.", "zh": "雅各就拿一塊石頭立作柱子，", "ja": "そこでヤコブは石を取り、それを立てて柱とした。"}, "46": {"en": "Jacob said to his relatives, “Gather stones.” They took stones, and made a heap. They ate there by the heap.", "zh": "又對眾弟兄說：「你們堆聚石頭。」他們就拿石頭來堆成一堆，大家便在旁邊吃喝。", "ja": "ヤコブはまた一族の者に言った、「石を集めてください」。彼らは石を取って、一つの石塚を造った。こうして彼らはその石塚のかたわらで食事をした。"}, "47": {"en": "Laban called it Jegar Sahadutha, but Jacob called it Galeed.", "zh": "拉班稱那石堆為伊迦爾‧撒哈杜他，雅各卻稱那石堆為迦累得。", "ja": "ラバンはこれをエガル・サハドタと名づけ、ヤコブはこれをガルエドと名づけた。"}, "48": {"en": "Laban said, “This heap is witness between me and you today.” Therefore it was named Galeed", "zh": "拉班說：「今日這石堆作你我中間的證據。」因此這地方名叫迦累得，", "ja": "そしてラバンは言った、「この石塚はきょうわたしとあなたとの間の証拠となります」。それでその名はガルエドと呼ばれた。"}, "49": {"en": "and Mizpah, for he said, “The LORD watch between me and you, when we are absent one from another.", "zh": "又叫米斯巴，意思說：「我們彼此離別以後，願耶和華在你我中間鑒察。", "ja": "またミズパとも呼ばれた。彼がこう言ったからである、「われわれが互に別れたのちも、どうか主がわたしとあなたとの間を見守られるように。"}, "50": {"en": "If you afflict my daughters, or if you take wives in addition to my daughters, no man is with us; behold, God is witness between me and you.”", "zh": "你若苦待我的女兒，又在我的女兒以外另娶妻，雖沒有人知道，卻有上帝在你我中間作見證。」", "ja": "もしあなたがわたしの娘を虐待したり、わたしの娘のほかに妻をめとることがあれば、たといそこにだれひとりいなくても、神はわたしとあなたとの間の証人でいらせられる」。"}, "51": {"en": "Laban said to Jacob, “See this heap, and see the pillar, which I have set between me and you.", "zh": "拉班又說：「你看我在你我中間所立的這石堆和柱子。", "ja": "更にラバンはヤコブに言った、「あなたとわたしとの間にわたしが建てたこの石塚をごらんなさい、この柱をごらんなさい。"}, "52": {"en": "May this heap be a witness, and the pillar be a witness, that I will not pass over this heap to you, and that you will not pass over this heap and this pillar to me, for harm.", "zh": "這石堆作證據，這柱子也作證據。我必不過這石堆去害你；你也不可過這石堆和柱子來害我。", "ja": "この石塚を越えてわたしがあなたに害を加えず、またこの石塚とこの柱を越えてあなたがわたしに害を加えないように、どうかこの石塚があかしとなり、この柱があかしとなるように。"}, "53": {"en": "The God of Abraham, and the God of Nahor, the God of their father, judge between us.” Then Jacob swore by the fear of his father, Isaac.", "zh": "但願亞伯拉罕的上帝和拿鶴的上帝，就是他們父親的上帝，在你我中間判斷。」雅各就指着他父親以撒所敬畏的上帝起誓，", "ja": "どうかアブラハムの神、ナホルの神、彼らの父の神がわれわれの間をさばかれるように」。ヤコブは父イサクのかしこむ者によって誓った。"}, "54": {"en": "Jacob offered a sacrifice in the mountain, and called his relatives to eat bread. They ate bread, and stayed all night in the mountain.", "zh": "又在山上獻祭，請眾弟兄來吃飯。他們吃了飯，便在山上住宿。", "ja": "そしてヤコブは山で犠牲をささげ、一族を招いて、食事をした。彼らは食事をして山に宿った。"}, "55": {"en": "Early in the morning, Laban rose up, and kissed his sons and his daughters, and blessed them. Laban departed and returned to his place.", "zh": "拉班清早起來，與他外孫和女兒親嘴，給他們祝福，回往自己的地方去了。", "ja": "あくる朝ラバンは早く起き、孫と娘たちに口づけして彼らを祝福し、去って家に帰った。"}}}, "32": {"verses": {"1": {"en": "Jacob went on his way, and the angels of God met him.", "zh": "雅各仍舊行路，上帝的使者遇見他。", "ja": "さて、ヤコブが旅路に進んだとき、神の使たちが彼に会った。"}, "2": {"en": "When he saw them, Jacob said, “This is God’s army.” He called the name of that place Mahanaim.", "zh": "雅各看見他們就說：「這是上帝的軍兵」，於是給那地方起名叫瑪哈念。", "ja": "ヤコブは彼らを見て、「これは神の陣営です」と言って、その所の名をマハナイムと名づけた。"}, "3": {"en": "Jacob sent messengers in front of him to Esau, his brother, to the land of Seir, the field of Edom.", "zh": "雅各打發人先往西珥地去，就是以東地，見他哥哥以掃，", "ja": "ヤコブはセイルの地、エドムの野に住む兄エサウのもとに、さきだって使者をつかわした。"}, "4": {"en": "He commanded them, saying, “This is what you shall tell my lord, Esau: ‘This is what your servant, Jacob, says. I have lived as a foreigner with Laban, and stayed until now.", "zh": "吩咐他們說：「你們對我主以掃說：『你的僕人雅各這樣說：我在拉班那裏寄居，直到如今。", "ja": "すなわちそれに命じて言った、「あなたがたはわたしの主人エサウにこう言いなさい、『あなたのしもべヤコブはこう言いました。わたしはラバンのもとに寄留して今までとどまりました。"}, "5": {"en": "I have cattle, donkeys, flocks, male servants, and female servants. I have sent to tell my lord, that I may find favor in your sight.’ ”", "zh": "我有牛、驢、羊群、僕婢，現在打發人來報告我主，為要在你眼前蒙恩。』」", "ja": "わたしは牛、ろば、羊、男女の奴隷を持っています。それでわが主に申し上げて、あなたの前に恵みを得ようと人をつかわしたのです』」。"}, "6": {"en": "The messengers returned to Jacob, saying, “We came to your brother Esau. He is coming to meet you, and four hundred men are with him.”", "zh": "所打發的人回到雅各那裏，說：「我們到了你哥哥以掃那裏，他帶着四百人，正迎着你來。」", "ja": "使者はヤコブのもとに帰って言った、「わたしたちはあなたの兄エサウのもとへ行きました。彼もまたあなたを迎えようと四百人を率いてきます」。"}, "7": {"en": "Then Jacob was greatly afraid and was distressed. He divided the people who were with him, along with the flocks, the herds, and the camels, into two companies.", "zh": "雅各就甚懼怕，而且愁煩，便把那與他同在的人口和羊群、牛群、駱駝分做兩隊，", "ja": "そこでヤコブは大いに恐れ、苦しみ、共にいる民および羊、牛、らくだを二つの組に分けて、"}, "8": {"en": "He said, “If Esau comes to the one company, and strikes it, then the company which is left will escape.”", "zh": "說：「以掃若來擊殺這一隊，剩下的那一隊還可以逃避。」", "ja": "言った、「たとい、エサウがきて、一つの組を撃っても、残りの組はのがれるであろう」。"}, "9": {"en": "Jacob said, “God of my father Abraham, and God of my father Isaac, the LORD, who said to me, ‘Return to your country, and to your relatives, and I will do you good,’", "zh": "雅各說：「耶和華－我祖亞伯拉罕的上帝，我父親以撒的上帝啊，你曾對我說：『回你本地本族去，我要厚待你。』", "ja": "ヤコブはまた言った、「父アブラハムの神、父イサクの神よ、かつてわたしに『おまえの国へ帰り、おまえの親族に行け。わたしはおまえを恵もう』と言われた主よ、"}, "10": {"en": "I am not worthy of the least of all the loving kindnesses, and of all the truth, which you have shown to your servant; for with just my staff I crossed over this Jordan; and now I have become two companies.", "zh": "你向僕人所施的一切慈愛和誠實，我一點也不配得；我先前只拿着我的杖過這約旦河，如今我卻成了兩隊了。", "ja": "あなたがしもべに施されたすべての恵みとまことをわたしは受けるに足りない者です。わたしは、つえのほか何も持たないでこのヨルダンを渡りましたが、今は二つの組にもなりました。"}, "11": {"en": "Please deliver me from the hand of my brother, from the hand of Esau; for I fear him, lest he come and strike me and the mothers with the children.", "zh": "求你救我脫離我哥哥以掃的手；因為我怕他來殺我，連妻子帶兒女一同殺了。", "ja": "どうぞ、兄エサウの手からわたしをお救いください。わたしは彼がきて、わたしを撃ち、母や子供たちにまで及ぶのを恐れます。"}, "12": {"en": "You said, ‘I will surely do you good, and make your offspring as the sand of the sea, which can’t be counted because there are so many.’ ”", "zh": "你曾說：『我必定厚待你，使你的後裔如同海邊的沙，多得不可勝數。』」", "ja": "あなたは、かつて、『わたしは必ずおまえを恵み、おまえの子孫を海の砂の数えがたいほど多くしよう』と言われました」。"}, "13": {"en": "He stayed there that night, and took from that which he had with him a present for Esau, his brother:", "zh": "當夜，雅各在那裏住宿，就從他所有的物中拿禮物要送給他哥哥以掃：", "ja": "彼はその夜そこに宿り、持ち物のうちから兄エサウへの贈り物を選んだ。"}, "14": {"en": "two hundred female goats and twenty male goats, two hundred ewes and twenty rams,", "zh": "母山羊二百隻，公山羊二十隻，母綿羊二百隻，公綿羊二十隻，", "ja": "すなわち雌やぎ二百、雄やぎ二十、雌羊二百、雄羊二十、"}, "15": {"en": "thirty milk camels and their colts, forty cows, ten bulls, twenty female donkeys and ten foals.", "zh": "奶崽子的駱駝三十隻－各帶着崽子，母牛四十隻，公牛十隻，母驢二十匹，驢駒十匹；", "ja": "乳らくだ三十とその子、雌牛四十、雄牛十、雌ろば二十、雄ろば十。"}, "16": {"en": "He delivered them into the hands of his servants, every herd by itself, and said to his servants, “Pass over before me, and put a space between herd and herd.”", "zh": "每樣各分一群，交在僕人手下，就對僕人說：「你們要在我前頭過去，使群群相離，有空閒的地方」；", "ja": "彼はこれらをそれぞれの群れに分けて、しもべたちの手にわたし、しもべたちに言った、「あなたがたはわたしの先に進みなさい、そして群れと群れとの間には隔たりをおきなさい」。"}, "17": {"en": "He commanded the foremost, saying, “When Esau, my brother, meets you, and asks you, saying, ‘Whose are you? Where are you going? Whose are these before you?’", "zh": "又吩咐儘先走的說：「我哥哥以掃遇見你的時候，問你說：『你是哪家的人？要往哪裏去？你前頭這些是誰的？』", "ja": "また先頭の者に命じて言った、「もし、兄エサウがあなたに会って『だれのしもべで、どこへ行くのか。あなたの前にあるこれらのものはだれの物か』と尋ねたら、"}, "18": {"en": "Then you shall say, ‘They are your servant, Jacob’s. It is a present sent to my lord, Esau. Behold, he also is behind us.’ ”", "zh": "你就說：『是你僕人雅各的，是送給我主以掃的禮物；他自己也在我們後邊。』」", "ja": "『あなたのしもべヤコブの物で、わが主エサウにおくる贈り物です。彼もわたしたちのうしろにおります』と言いなさい」。"}, "19": {"en": "He commanded also the second, and the third, and all that followed the herds, saying, “This is how you shall speak to Esau, when you find him.", "zh": "又吩咐第二、第三，和一切趕群畜的人說：「你們遇見以掃的時候也要這樣對他說；", "ja": "彼は第二の者にも、第三の者にも、また群れ群れについて行くすべての者にも命じて言った、「あなたがたがエサウに会うときは、同じように彼に告げて、"}, "20": {"en": "You shall say, ‘Not only that, but behold, your servant, Jacob, is behind us.’ ” For, he said, “I will appease him with the present that goes before me, and afterward I will see his face. Perhaps he will accept me.”", "zh": "並且你們要說：『你僕人雅各在我們後邊。』」因雅各心裏說：「我藉着在我前頭去的禮物解他的恨，然後再見他的面，或者他容納我。」", "ja": "『あなたのしもべヤコブもわれわれのうしろにおります』と言いなさい」。ヤコブは、「わたしがさきに送る贈り物をもってまず彼をなだめ、それから、彼の顔を見よう。そうすれば、彼はわたしを迎えてくれるであろう」と思ったからである。"}, "21": {"en": "So the present passed over before him, and he himself stayed that night in the camp.", "zh": "於是禮物先過去了；那夜，雅各在隊中住宿。", "ja": "こうして贈り物は彼に先立って渡り、彼はその夜、宿営にやどった。"}, "22": {"en": "He rose up that night, and took his two wives, and his two servants, and his eleven sons, and crossed over the ford of the Jabbok.", "zh": "他夜間起來，帶着兩個妻子，兩個使女，並十一個兒子，都過了雅博渡口，", "ja": "彼はその夜起きて、ふたりの妻とふたりのつかえめと十一人の子どもとを連れてヤボクの渡しをわたった。"}, "23": {"en": "He took them, and sent them over the stream, and sent over that which he had.", "zh": "先打發他們過河，又打發所有的都過去，", "ja": "すなわち彼らを導いて川を渡らせ、また彼の持ち物を渡らせた。"}, "24": {"en": "Jacob was left alone, and wrestled with a man there until the breaking of the day.", "zh": "只剩下雅各一人。有一個人來和他摔跤，直到黎明。", "ja": "ヤコブはひとりあとに残ったが、ひとりの人が、夜明けまで彼と組打ちした。"}, "25": {"en": "When he saw that he didn’t prevail against him, the man touched the hollow of his thigh, and the hollow of Jacob’s thigh was strained as he wrestled.", "zh": "那人見自己勝不過他，就將他的大腿窩摸了一把，雅各的大腿窩正在摔跤的時候就扭了。", "ja": "ところでその人はヤコブに勝てないのを見て、ヤコブのもものつがいにさわったので、ヤコブのもものつがいが、その人と組打ちするあいだにはずれた。"}, "26": {"en": "The man said, “Let me go, for the day breaks.” Jacob said, “I won’t let you go unless you bless me.”", "zh": "那人說：「天黎明了，容我去吧！」雅各說：「你不給我祝福，我就不容你去。」", "ja": "その人は言った、「夜が明けるからわたしを去らせてください」。ヤコブは答えた、「わたしを祝福してくださらないなら、あなたを去らせません」。"}, "27": {"en": "He said to him, “What is your name?” He said, “Jacob”.", "zh": "那人說：「你名叫甚麼？」他說：「我名叫雅各。」", "ja": "その人は彼に言った、「あなたの名はなんと言いますか」。彼は答えた、「ヤコブです」。"}, "28": {"en": "He said, “Your name will no longer be called Jacob, but Israel; for you have fought with God and with men, and have prevailed.”", "zh": "那人說：「你的名不要再叫雅各，要叫以色列；因為你與上帝與人較力，都得了勝。」", "ja": "その人は言った、「あなたはもはや名をヤコブと言わず、イスラエルと言いなさい。あなたが神と人とに、力を争って勝ったからです」。"}, "29": {"en": "Jacob asked him, “Please tell me your name.” He said, “Why is it that you ask what my name is?” So he blessed him there.", "zh": "雅各問他說：「請將你的名告訴我。」那人說：「何必問我的名？」於是在那裏給雅各祝福。", "ja": "ヤコブは尋ねて言った、「どうかわたしにあなたの名を知らせてください」。するとその人は、「なぜあなたはわたしの名をきくのですか」と言ったが、その所で彼を祝福した。"}, "30": {"en": "Jacob called the name of the place Peniel; for he said, “I have seen God face to face, and my life is preserved.”", "zh": "雅各便給那地方起名叫毗努伊勒，意思說：「我面對面見了上帝，我的性命仍得保全。」", "ja": "そこでヤコブはその所の名をペニエルと名づけて言った、「わたしは顔と顔をあわせて神を見たが、なお生きている」。"}, "31": {"en": "The sun rose on him as he passed over Peniel, and he limped because of his thigh.", "zh": "日頭剛出來的時候，雅各經過毗努伊勒，他的大腿就瘸了。", "ja": "こうして彼がペニエルを過ぎる時、日は彼の上にのぼったが、彼はそのもものゆえにびっこを引いていた。"}, "32": {"en": "Therefore the children of Israel don’t eat the sinew of the hip, which is on the hollow of the thigh, to this day, because he touched the hollow of Jacob’s thigh in the sinew of the hip.", "zh": "故此，以色列人不吃大腿窩的筋，直到今日，因為那人摸了雅各大腿窩的筋。", "ja": "そのため、イスラエルの子らは今日まで、もものつがいの上にある腰の筋を食べない。かの人がヤコブのもものつがい、すなわち腰の筋にさわったからである。"}}}, "33": {"verses": {"1": {"en": "Jacob lifted up his eyes, and looked, and, behold, Esau was coming, and with him four hundred men. He divided the children between Leah, Rachel, and the two servants.", "zh": "雅各舉目觀看，見以掃來了，後頭跟着四百人，他就把孩子們分開交給利亞、拉結，和兩個使女，", "ja": "さてヤコブは目をあげ、エサウが四百人を率いて来るのを見た。そこで彼は子供たちを分けてレアとラケルとふたりのつかえめとにわたし、"}, "2": {"en": "He put the servants and their children in front, Leah and her children after, and Rachel and Joseph at the rear.", "zh": "並且叫兩個使女和她們的孩子在前頭，利亞和她的孩子在後頭，拉結和約瑟在儘後頭。", "ja": "つかえめとその子供たちをまっ先に置き、レアとその子供たちを次に置き、ラケルとヨセフを最後に置いて、"}, "3": {"en": "He himself passed over in front of them, and bowed himself to the ground seven times, until he came near to his brother.", "zh": "他自己在他們前頭過去，一連七次俯伏在地才就近他哥哥。", "ja": "みずから彼らの前に進み、七たび身を地にかがめて、兄に近づいた。"}, "4": {"en": "Esau ran to meet him, embraced him, fell on his neck, kissed him, and they wept.", "zh": "以掃跑來迎接他，將他抱住，又摟着他的頸項，與他親嘴，兩個人就哭了。", "ja": "するとエサウは走ってきて迎え、彼を抱き、そのくびをかかえて口づけし、共に泣いた。"}, "5": {"en": "He lifted up his eyes, and saw the women and the children; and said, “Who are these with you?”", "zh": "以掃舉目看見婦人孩子，就說：「這些和你同行的是誰呢？」雅各說：「這些孩子是上帝施恩給你的僕人的。」", "ja": "エサウは目をあげて女と子供たちを見て言った、「あなたと一緒にいるこれらの者はだれですか」。ヤコブは言った、「神がしもべに授けられた子供たちです」。"}, "6": {"en": "He said, “The children whom God has graciously given your servant.”   Then the servants came near with their children, and they bowed themselves.", "zh": "於是兩個使女和她們的孩子前來下拜；", "ja": "そこでつかえめたちはその子供たちと共に近寄ってお辞儀した。"}, "7": {"en": "Leah also and her children came near, and bowed themselves. After them, Joseph came near with Rachel, and they bowed themselves.", "zh": "利亞和她的孩子也前來下拜；隨後約瑟和拉結也前來下拜。", "ja": "レアもまたその子供たちと共に近寄ってお辞儀し、それからヨセフとラケルが近寄ってお辞儀した。"}, "8": {"en": "Esau said, “What do you mean by all this company which I met?” Jacob said, “To find favor in the sight of my lord.”", "zh": "以掃說：「我所遇見的這些群畜是甚麼意思呢？」雅各說：「是要在我主面前蒙恩的。」", "ja": "するとエサウは言った、「わたしが出会ったあのすべての群れはどうしたのですか」。ヤコブは言った、「わが主の前に恵みを得るためです」。"}, "9": {"en": "Esau said, “I have enough, my brother; let that which you have be yours.”", "zh": "以掃說：「兄弟啊，我的已經夠了，你的仍歸你吧！」", "ja": "エサウは言った、「弟よ、わたしはじゅうぶんもっている。あなたの物はあなたのものにしなさい」。"}, "10": {"en": "Jacob said, “Please, no, if I have now found favor in your sight, then receive my present at my hand, because I have seen your face, as one sees the face of God, and you were pleased with me.", "zh": "雅各說：「不然，我若在你眼前蒙恩，就求你從我手裏收下這禮物；因為我見了你的面，如同見了上帝的面，並且你容納了我。", "ja": "ヤコブは言った、「いいえ、もしわたしがあなたの前に恵みを得るなら、どうか、わたしの手から贈り物を受けてください。あなたが喜んでわたしを迎えてくださるので、あなたの顔を見て、神の顔を見るように思います。"}, "11": {"en": "Please take the gift that I brought to you, because God has dealt graciously with me, and because I have enough.” He urged him, and he took it.", "zh": "求你收下我帶來給你的禮物；因為上帝恩待我，使我充足。」雅各再三地求他，他才收下了。", "ja": "どうかわたしが持ってきた贈り物を受けてください。神がわたしを恵まれたので、わたしはじゅうぶんもっていますから」。こうして彼がしいたので、彼は受け取った。"}, "12": {"en": "Esau said, “Let’s take our journey, and let’s go, and I will go before you.”", "zh": "以掃說：「我們可以起身前往，我在你前頭走。」", "ja": "そしてエサウは言った、「さあ、立って行こう。わたしが先に行く」。"}, "13": {"en": "Jacob said to him, “My lord knows that the children are tender, and that the flocks and herds with me have their young, and if they overdrive them one day, all the flocks will die.", "zh": "雅各對他說：「我主知道孩子們年幼嬌嫩，牛羊也正在乳養的時候，若是催趕一天，群畜都必死了。", "ja": "ヤコブは彼に言った、「ごぞんじのように、子供たちは、かよわく、また乳を飲ませている羊や牛をわたしが世話をしています。もし一日でも歩かせ過ぎたら群れはみな死んでしまいます。"}, "14": {"en": "Please let my lord pass over before his servant, and I will lead on gently, according to the pace of the livestock that are before me and according to the pace of the children, until I come to my lord to Seir.”", "zh": "求我主在僕人前頭走，我要量着在我面前群畜和孩子的力量慢慢地前行，直走到西珥我主那裏。」", "ja": "わが主よ、どうか、しもべの先においでください。わたしはわたしの前にいる家畜と子供たちの歩みに合わせて、ゆっくり歩いて行き、セイルでわが主と一緒になりましょう」。"}, "15": {"en": "Esau said, “Let me now leave with you some of the people who are with me.” He said, “Why? Let me find favor in the sight of my lord.”", "zh": "以掃說：「容我把跟隨我的人留幾個在你這裏。」雅各說：「何必呢？只要在我主眼前蒙恩就是了。」", "ja": "エサウは言った、「それならわたしが連れている者どものうち幾人かをあなたのもとに残しましょう」。ヤコブは言った、「いいえ、それには及びません。わが主の前に恵みを得させてください」。"}, "16": {"en": "So Esau returned that day on his way to Seir.", "zh": "於是，以掃當日起行，回往西珥去了。", "ja": "その日エサウはセイルへの帰途についた。"}, "17": {"en": "Jacob traveled to Succoth, built himself a house, and made shelters for his livestock. Therefore the name of the place is called Succoth.", "zh": "雅各就往疏割去，在那裏為自己蓋造房屋，又為牲畜搭棚；因此那地方名叫疏割。", "ja": "ヤコブは立ってスコテに行き、自分のために家を建て、また家畜のために小屋を造った。これによってその所の名はスコテと呼ばれている。"}, "18": {"en": "Jacob came in peace to the city of Shechem, which is in the land of Canaan, when he came from Paddan Aram; and encamped before the city.", "zh": "雅各從巴旦‧亞蘭回來的時候，平平安安地到了迦南地的示劍城，在城東支搭帳棚，", "ja": "こうしてヤコブはパダンアラムからきて、無事カナンの地のシケムの町に着き、町の前に宿営した。"}, "19": {"en": "He bought the parcel of ground where he had spread his tent, at the hand of the children of Hamor, Shechem’s father, for one hundred pieces of money.", "zh": "就用一百塊銀子向示劍的父親、哈抹的子孫買了支帳棚的那塊地，", "ja": "彼は天幕を張った野の一部をシケムの父ハモルの子らの手から百ケシタで買い取り、"}, "20": {"en": "He erected an altar there, and called it El Elohe Israel.", "zh": "在那裏築了一座壇，起名叫伊利‧伊羅伊‧以色列 。", "ja": "そこに祭壇を建てて、これをエル・エロヘ・イスラエルと名づけた。"}}}, "34": {"verses": {"1": {"en": "Dinah, the daughter of Leah, whom she bore to Jacob, went out to see the daughters of the land.", "zh": "利亞給雅各所生的女兒底拿出去，要見那地的女子們。", "ja": "レアがヤコブに産んだ娘デナはその地の女たちに会おうと出かけて行ったが、"}, "2": {"en": "Shechem the son of Hamor the Hivite, the prince of the land, saw her. He took her, lay with her, and humbled her.", "zh": "那地的主－希未人、哈抹的兒子示劍看見她，就拉住她，與她行淫，玷辱她。", "ja": "その地のつかさ、ヒビびとハモルの子シケムが彼女を見て、引き入れ、これと寝てはずかしめた。"}, "3": {"en": "His soul joined to Dinah, the daughter of Jacob, and he loved the young lady, and spoke kindly to the young lady.", "zh": "示劍的心繫戀雅各的女兒底拿，喜愛這女子，甜言蜜語地安慰她。", "ja": "彼は深くヤコブの娘デナを慕い、この娘を愛して、ねんごろに娘に語った。"}, "4": {"en": "Shechem spoke to his father, Hamor, saying, “Get me this young lady as a wife.”", "zh": "示劍對他父親哈抹說：「求你為我聘這女子為妻。」", "ja": "シケムは父ハモルに言った、「この娘をわたしの妻にめとってください」。"}, "5": {"en": "Now Jacob heard that he had defiled Dinah, his daughter; and his sons were with his livestock in the field. Jacob held his peace until they came.", "zh": "雅各聽見示劍玷污了他的女兒底拿。那時他的兒子們正和群畜在田野，雅各就閉口不言，等他們回來。", "ja": "さてヤコブはシケムが、娘デナを汚したことを聞いたけれども、その子らが家畜を連れて野にいたので、彼らの帰るまで黙っていた。"}, "6": {"en": "Hamor the father of Shechem went out to Jacob to talk with him.", "zh": "示劍的父親哈抹出來見雅各，要和他商議。", "ja": "シケムの父ハモルはヤコブと話し合おうと、ヤコブの所に出てきた。"}, "7": {"en": "The sons of Jacob came in from the field when they heard it. The men were grieved, and they were very angry, because he had done folly in Israel in lying with Jacob’s daughter, a thing that ought not to be done.", "zh": "雅各的兒子們聽見這事，就從田野回來，人人忿恨，十分惱怒；因示劍在以色列家做了醜事，與雅各的女兒行淫，這本是不該做的事。", "ja": "ヤコブの子らは野から帰り、この事を聞いて、悲しみ、かつ非常に怒った。シケムがヤコブの娘と寝て、イスラエルに愚かなことをしたためで、こんなことは、してはならぬ事だからである。"}, "8": {"en": "Hamor talked with them, saying, “The soul of my son, Shechem, longs for your daughter. Please give her to him as a wife.", "zh": "哈抹和他們商議說：「我兒子示劍的心戀慕這女子，求你們將她給我的兒子為妻。", "ja": "ハモルは彼らと語って言った、「わたしの子シケムはあなたがたの娘を心に慕っています。どうか彼女を彼の妻にください。"}, "9": {"en": "Make marriages with us. Give your daughters to us, and take our daughters for yourselves.", "zh": "你們與我們彼此結親；你們可以把女兒給我們，也可以娶我們的女兒。", "ja": "あなたがたはわたしたちと婚姻し、あなたがたの娘をわたしたちに与え、わたしたちの娘をあなたがたにめとってください。"}, "10": {"en": "You shall dwell with us, and the land will be before you. Live and trade in it, and get possessions in it.”", "zh": "你們與我們同住吧！這地都在你們面前，只管在此居住，做買賣，置產業。」", "ja": "こうしてあなたがたとわたしたちとは一緒に住みましょう。地はあなたがたの前にあります。ここに住んで取引し、ここで財産を獲なさい」。"}, "11": {"en": "Shechem said to her father and to her brothers, “Let me find favor in your eyes, and whatever you will tell me I will give.", "zh": "示劍對女兒的父親和弟兄們說：「但願我在你們眼前蒙恩，你們向我要甚麼，我必給你們。", "ja": "シケムはまたデナの父と兄弟たちとに言った、「あなたがたの前に恵みを得させてください。あなたがたがわたしに言われるものは、なんでもさしあげましょう。"}, "12": {"en": "Ask me a great amount for a dowry, and I will give whatever you ask of me, but give me the young lady as a wife.”", "zh": "任憑向我要多重的聘金和禮物，我必照你們所說的給你們；只要把女子給我為妻。」", "ja": "たくさんの結納金と贈り物とをお求めになっても、あなたがたの言われるとおりさしあげます。ただこの娘はわたしの妻にください」。"}, "13": {"en": "The sons of Jacob answered Shechem and Hamor his father with deceit when they spoke, because he had defiled Dinah their sister,", "zh": "雅各的兒子們因為示劍玷污了他們的妹子底拿，就用詭詐的話回答示劍和他父親哈抹，", "ja": "しかし、ヤコブの子らはシケムが彼らの妹デナを汚したので、シケムとその父ハモルに偽って答え、"}, "14": {"en": "and said to them, “We can’t do this thing, to give our sister to one who is uncircumcised; for that is a reproach to us.", "zh": "對他們說：「我們不能把我們的妹子給沒有受割禮的人為妻，因為那是我們的羞辱。", "ja": "彼らに言った、「われわれは割礼を受けない者に妹をやる事はできません。それはわれわれの恥とするところですから。"}, "15": {"en": "Only on this condition will we consent to you. If you will be as we are, that every male of you be circumcised,", "zh": "惟有一件才可以應允：若你們所有的男丁都受割禮，和我們一樣，", "ja": "ただ、こうなさればわれわれはあなたがたに同意します。もしあなたがたのうち男子がみな割礼を受けて、われわれのようになるなら、"}, "16": {"en": "then will we give our daughters to you; and we will take your daughters to us, and we will dwell with you, and we will become one people.", "zh": "我們就把女兒給你們，也娶你們的女兒；我們便與你們同住，兩下成為一樣的人民。", "ja": "われわれの娘をあなたがたに与え、あなたがたの娘をわれわれにめとりましょう。そしてわれわれはあなたがたと一緒に住んで一つの民となりましょう。"}, "17": {"en": "But if you will not listen to us and be circumcised, then we will take our sister, and we will be gone.”", "zh": "倘若你們不聽從我們受割禮，我們就帶着妹子走了。」", "ja": "けれども、もしあなたがたがわれわれに聞かず、割礼を受けないなら、われわれは娘を連れて行きます」。"}, "18": {"en": "Their words pleased Hamor and Shechem, Hamor’s son.", "zh": "哈抹和他的兒子示劍喜歡這話。", "ja": "彼らの言葉がハモルとハモルの子シケムとの心にかなったので、"}, "19": {"en": "The young man didn’t wait to do this thing, because he had delight in Jacob’s daughter, and he was honored above all the house of his father.", "zh": "那少年人做這事並不遲延，因為他喜愛雅各的女兒；他在他父親家中也是人最尊重的。", "ja": "若者は、ためらわずにこの事をした。彼がヤコブの娘を愛したからである。また彼は父の家のうちで一番重んじられた者であった。"}, "20": {"en": "Hamor and Shechem, his son, came to the gate of their city, and talked with the men of their city, saying,", "zh": "哈抹和他兒子示劍到本城的門口，對本城的人說：", "ja": "そこでハモルとその子シケムとは町の門に行き、町の人々に語って言った、"}, "21": {"en": "“These men are peaceful with us. Therefore let them live in the land and trade in it. For behold, the land is large enough for them. Let’s take their daughters to us for wives, and let’s give them our daughters.", "zh": "「這些人與我們和睦，不如許他們在這地居住，做買賣；這地也寬闊，足可容下他們。我們可以娶他們的女兒為妻，也可以把我們的女兒嫁給他們。", "ja": "「この人々はわれわれと親しいから、この地に住まわせて、ここで取引をさせよう。地は広く、彼らをいれるにじゅうぶんである。そしてわれわれは彼らの娘を妻にめとり、われわれの娘を彼らに与えよう。"}, "22": {"en": "Only on this condition will the men consent to us to live with us, to become one people, if every male among us is circumcised, as they are circumcised.", "zh": "惟有一件事我們必須做，他們才肯應允和我們同住，成為一樣的人民：就是我們中間所有的男丁都要受割禮，和他們一樣。", "ja": "彼らが割礼を受けているように、もしわれわれのうちの男子が皆、割礼を受けるなら、ただこの事だけで、この人々はわれわれに同意し、われわれと一緒に住んで一つの民となるのだ。"}, "23": {"en": "Won’t their livestock and their possessions and all their animals be ours? Only let’s give our consent to them, and they will dwell with us.”", "zh": "他們的群畜、貨財，和一切的牲口豈不都歸我們嗎？只要依從他們，他們就與我們同住。」", "ja": "そうすれば彼らの家畜と財産とすべての獣とは、われわれのものとなるではないか。ただわれわれが彼らに同意すれば、彼らはわれわれと一緒に住むであろう」。"}, "24": {"en": "All who went out of the gate of his city listened to Hamor, and to Shechem his son; and every male was circumcised, all who went out of the gate of his city.", "zh": "凡從城門出入的人就都聽從哈抹和他兒子示劍的話；於是凡從城門出入的男丁都受了割禮。", "ja": "そこで町の門に出入りする者はみなハモルとその子シケムとに聞き従って、町の門に出入りするすべての男子は割礼を受けた。"}, "25": {"en": "On the third day, when they were sore, two of Jacob’s sons, Simeon and Levi, Dinah’s brothers, each took his sword, came upon the unsuspecting city, and killed all the males.", "zh": "到第三天，眾人正在疼痛的時候，雅各的兩個兒子，就是底拿的哥哥西緬和利未，各拿刀劍，趁着眾人想不到的時候來到城中，把一切男丁都殺了，", "ja": "三日目になって彼らが痛みを覚えている時、ヤコブのふたりの子、すなわちデナの兄弟シメオンとレビとは、おのおのつるぎを取って、不意に町を襲い、男子をことごとく殺し、"}, "26": {"en": "They killed Hamor and Shechem, his son, with the edge of the sword, and took Dinah out of Shechem’s house, and went away.", "zh": "又用刀殺了哈抹和他兒子示劍，把底拿從示劍家裏帶出來就走了。", "ja": "またつるぎの刃にかけてハモルとその子シケムとを殺し、シケムの家からデナを連れ出した。"}, "27": {"en": "Jacob’s sons came on the dead, and plundered the city, because they had defiled their sister.", "zh": "雅各的兒子們因為他們的妹子受了玷污，就來到被殺的人那裏，擄掠那城，", "ja": "そしてヤコブの子らは殺された人々をはぎ、町をかすめた。彼らが妹を汚したからである。"}, "28": {"en": "They took their flocks, their herds, their donkeys, that which was in the city, that which was in the field,", "zh": "奪了他們的羊群、牛群，和驢，並城裏田間所有的；", "ja": "すなわち羊、牛、ろば及び町にあるものと、野にあるもの、"}, "29": {"en": "and all their wealth. They took captive all their little ones and their wives, and took as plunder everything that was in the house.", "zh": "又把他們一切貨財、孩子、婦女，並各房中所有的，都擄掠去了。", "ja": "並びにすべての貨財を奪い、その子女と妻たちを皆とりこにし、家の中にある物をことごとくかすめた。"}, "30": {"en": "Jacob said to Simeon and Levi, “You have troubled me, to make me odious to the inhabitants of the land, among the Canaanites and the Perizzites. I am few in number. They will gather themselves together against me and strike me, and I will be destroyed, I and my house.”", "zh": "雅各對西緬和利未說：「你們連累我，使我在這地的居民中，就是在迦南人和比利洗人中，有了臭名。我的人丁既然稀少，他們必聚集來擊殺我，我和全家的人都必滅絕。」", "ja": "そこでヤコブはシメオンとレビとに言った、「あなたがたはわたしをこの地の住民、カナンびととペリジびとに忌みきらわせ、わたしに迷惑をかけた。わたしは、人数が少ないから、彼らが集まってわたしを攻め撃つならば、わたしも家族も滅ぼされるであろう」。"}, "31": {"en": "They said, “Should he deal with our sister as with a prostitute?”", "zh": "他們說：「他豈可待我們的妹子如同妓女嗎？」", "ja": "彼らは言った、「わたしたちの妹を遊女のように彼が扱ってよいのですか」。"}}}, "35": {"verses": {"1": {"en": "God said to Jacob, “Arise, go up to Bethel, and live there. Make there an altar to God, who appeared to you when you fled from the face of Esau your brother.”", "zh": "上帝對雅各說：「起來！上伯特利去，住在那裏；要在那裏築一座壇給上帝，就是你逃避你哥哥以掃的時候向你顯現的那位。」", "ja": "ときに神はヤコブに言われた、「あなたは立ってベテルに上り、そこに住んで、あなたがさきに兄エサウの顔を避けてのがれる時、あなたに現れた神に祭壇を造りなさい」。"}, "2": {"en": "Then Jacob said to his household, and to all who were with him, “Put away the foreign gods that are among you, purify yourselves, and change your garments.", "zh": "雅各就對他家中的人並一切與他同在的人說：「你們要除掉你們中間的外邦神，也要自潔，更換衣裳。", "ja": "ヤコブは、その家族および共にいるすべての者に言った、「あなたがたのうちにある異なる神々を捨て、身を清めて着物を着替えなさい。"}, "3": {"en": "Let’s arise, and go up to Bethel. I will make there an altar to God, who answered me in the day of my distress, and was with me on the way which I went.”", "zh": "我們要起來，上伯特利去，在那裏我要築一座壇給上帝，就是在我遭難的日子應允我的禱告、在我行的路上保佑我的那位。」", "ja": "われわれは立ってベテルに上り、その所でわたしの苦難の日にわたしにこたえ、かつわたしの行く道で共におられた神に祭壇を造ろう」。"}, "4": {"en": "They gave to Jacob all the foreign gods which were in their hands, and the rings which were in their ears; and Jacob hid them under the oak which was by Shechem.", "zh": "他們就把外邦人的神像和他們耳朵上的環子交給雅各；雅各都藏在示劍那裏的橡樹底下。", "ja": "そこで彼らは持っている異なる神々と、耳につけている耳輪をことごとくヤコブに与えたので、ヤコブはこれをシケムのほとりにあるテレビンの木の下に埋めた。"}, "5": {"en": "They traveled, and a terror of God was on the cities that were around them, and they didn’t pursue the sons of Jacob.", "zh": "他們便起行前往。上帝使那周圍城邑的人都甚驚懼，就不追趕雅各的眾子了。", "ja": "そして彼らは、いで立ったが、大いなる恐れが周囲の町々に起ったので、ヤコブの子らのあとを追う者はなかった。"}, "6": {"en": "So Jacob came to Luz (that is, Bethel), which is in the land of Canaan, he and all the people who were with him.", "zh": "於是雅各和一切與他同在的人到了迦南地的路斯，就是伯特利。", "ja": "こうしてヤコブは共にいたすべての人々と一緒にカナンの地にあるルズ、すなわちベテルにきた。"}, "7": {"en": "He built an altar there, and called the place El Beth El; because there God was revealed to him, when he fled from the face of his brother.", "zh": "他在那裏築了一座壇，就給那地方起名叫伊勒‧伯特利；因為他逃避他哥哥的時候，上帝在那裏向他顯現。", "ja": "彼はそこに祭壇を築き、その所をエル・ベテルと名づけた。彼が兄の顔を避けてのがれる時、神がそこで彼に現れたからである。"}, "8": {"en": "Deborah, Rebekah’s nurse, died, and she was buried below Bethel under the oak; and its name was called Allon Bacuth.", "zh": "利百加的奶母底波拉死了，就葬在伯特利下邊橡樹底下；那棵樹名叫亞倫‧巴古。", "ja": "時にリベカのうばデボラが死んで、ベテルのしもの、かしの木の下に葬られた。これによってその木の名をアロン・バクテと呼ばれた。"}, "9": {"en": "God appeared to Jacob again, when he came from Paddan Aram, and blessed him.", "zh": "雅各從巴旦‧亞蘭回來，上帝又向他顯現，賜福與他，", "ja": "さてヤコブがパダンアラムから帰ってきた時、神は再び彼に現れて彼を祝福された。"}, "10": {"en": "God said to him, “Your name is Jacob. Your name shall not be Jacob any more, but your name will be Israel.” He named him Israel.", "zh": "且對他說：「你的名原是雅各，從今以後不要再叫雅各，要叫以色列。」這樣，他就改名叫以色列。", "ja": "神は彼に言われた、「あなたの名はヤコブである。しかしあなたの名をもはやヤコブと呼んではならない。あなたの名をイスラエルとしなさい」。こうして彼をイスラエルと名づけられた。"}, "11": {"en": "God said to him, “I am God Almighty. Be fruitful and multiply. A nation and a company of nations will be from you, and kings will come out of your body.", "zh": "上帝又對他說：「我是全能的上帝；你要生養眾多，將來有一族和多國的民從你而生，又有君王從你而出。", "ja": "神はまた彼に言われた、「わたしは全能の神である。あなたは生めよ、またふえよ。一つの国民、また多くの国民があなたから出て、王たちがあなたの身から出るであろう。"}, "12": {"en": "The land which I gave to Abraham and Isaac, I will give it to you, and to your offspring after you I will give the land.”", "zh": "我所賜給亞伯拉罕和以撒的地，我要賜給你與你的後裔。」", "ja": "わたしはアブラハムとイサクとに与えた地を、あなたに与えよう。またあなたの後の子孫にその地を与えよう」。"}, "13": {"en": "God went up from him in the place where he spoke with him.", "zh": "上帝就從那與雅各說話的地方升上去了。", "ja": "神は彼と語っておられたその場所から彼を離れてのぼられた。"}, "14": {"en": "Jacob set up a pillar in the place where he spoke with him, a pillar of stone. He poured out a drink offering on it, and poured oil on it.", "zh": "雅各便在那裏立了一根石柱，在柱子上奠酒，澆油。", "ja": "そこでヤコブは神が自分と語られたその場所に、一本の石の柱を立て、その上に灌祭をささげ、また油を注いだ。"}, "15": {"en": "Jacob called the name of the place where God spoke with him “Bethel”.", "zh": "雅各就給那地方起名叫伯特利。", "ja": "そしてヤコブは神が自分と語られたその場所をベテルと名づけた。"}, "16": {"en": "They traveled from Bethel. There was still some distance to come to Ephrath, and Rachel travailed. She had hard labor.", "zh": "他們從伯特利起行，離以法他還有一段路程，拉結臨產甚是艱難。", "ja": "こうして彼らはベテルを立ったが、エフラタに行き着くまでに、なお隔たりのある所でラケルは産気づき、その産は重かった。"}, "17": {"en": "When she was in hard labor, the midwife said to her, “Don’t be afraid, for now you will have another son.”", "zh": "正在艱難的時候，收生婆對她說：「不要怕，你又要得一個兒子了。」", "ja": "その難産に当って、産婆は彼女に言った、「心配することはありません。今度も男の子です」。"}, "18": {"en": "As her soul was departing (for she died), she named him Benoni, but his father named him Benjamin.", "zh": "她將近於死，靈魂要走的時候，就給她兒子起名叫便‧俄尼；他父親卻給他起名叫便雅憫。", "ja": "彼女は死にのぞみ、魂の去ろうとする時、子の名をベノニと呼んだ。しかし、父はこれをベニヤミンと名づけた。"}, "19": {"en": "Rachel died, and was buried on the way to Ephrath (also called Bethlehem).", "zh": "拉結死了，葬在以法他的路旁；以法他就是伯利恆。", "ja": "ラケルは死んでエフラタ、すなわちベツレヘムの道に葬られた。"}, "20": {"en": "Jacob set up a pillar on her grave. The same is the Pillar of Rachel’s grave to this day.", "zh": "雅各在她的墳上立了一統碑，就是拉結的墓碑，到今日還在。", "ja": "ヤコブはその墓に柱を立てた。これはラケルの墓の柱であって、今日に至っている。"}, "21": {"en": "Israel traveled, and spread his tent beyond the tower of Eder.", "zh": "以色列起行前往，在以得臺那邊支搭帳棚。", "ja": "イスラエルはまた、いで立ってミグダル・エダルの向こうに天幕を張った。"}, "22": {"en": "While Israel lived in that land, Reuben went and lay with Bilhah, his father’s concubine, and Israel heard of it.", "zh": "以色列住在那地的時候，呂便去與他父親的妾辟拉同寢，以色列也聽見了。", "ja": "イスラエルがその地に住んでいた時、ルベンは父のそばめビルハのところへ行って、これと寝た。イスラエルはこれを聞いた。さてヤコブの子らは十二人であった。"}, "23": {"en": "Now the sons of Jacob were twelve.   The sons of Leah: Reuben (Jacob’s firstborn), Simeon, Levi, Judah, Issachar, and Zebulun.", "zh": "雅各共有十二個兒子。   利亞所生的是雅各的長子呂便，還有西緬、利未、猶大、以薩迦、西布倫。", "ja": "すなわちレアの子らはヤコブの長子ルベンとシメオン、レビ、ユダ、イッサカル、ゼブルン。"}, "24": {"en": "The sons of Rachel: Joseph and Benjamin.", "zh": "拉結所生的是約瑟、便雅憫。", "ja": "ラケルの子らはヨセフとベニヤミン。"}, "25": {"en": "The sons of Bilhah (Rachel’s servant): Dan and Naphtali.", "zh": "拉結的使女辟拉所生的是但、拿弗他利。", "ja": "ラケルのつかえめビルハの子らはダンとナフタリ。"}, "26": {"en": "The sons of Zilpah (Leah’s servant): Gad and Asher. These are the sons of Jacob, who were born to him in Paddan Aram.", "zh": "利亞的使女悉帕所生的是迦得、亞設。這是雅各在巴旦‧亞蘭所生的兒子。", "ja": "レアのつかえめジルパの子らはガドとアセル。これらはヤコブの子らであって、パダンアラムで彼に生れた者である。"}, "27": {"en": "Jacob came to Isaac his father, to Mamre, to Kiriath Arba (which is Hebron), where Abraham and Isaac lived as foreigners.", "zh": "雅各來到他父親以撒那裏，到了基列‧亞巴的幔利，乃是亞伯拉罕和以撒寄居的地方；基列‧亞巴就是希伯崙。", "ja": "ヤコブはキリアテ・アルバ、すなわちヘブロンのマムレにいる父イサクのもとへ行った。ここはアブラハムとイサクとが寄留した所である。"}, "28": {"en": "The days of Isaac were one hundred eighty years.", "zh": "以撒共活了一百八十歲。", "ja": "イサクの年は百八十歳であった。"}, "29": {"en": "Isaac gave up the spirit and died, and was gathered to his people, old and full of days. Esau and Jacob, his sons, buried him.", "zh": "以撒年紀老邁，日子滿足，氣絕而死，歸到他列祖那裏。他兩個兒子以掃、雅各把他埋葬了。", "ja": "イサクは年老い、日満ちて息絶え、死んで、その民に加えられた。その子エサウとヤコブとは、これを葬った。"}}}, "36": {"verses": {"1": {"en": "Now this is the history of the generations of Esau (that is, Edom).", "zh": "以掃就是以東，他的後代記在下面。", "ja": "エサウ、すなわちエドムの系図は次のとおりである。"}, "2": {"en": "Esau took his wives from the daughters of Canaan: Adah the daughter of Elon, the Hittite; and Oholibamah the daughter of Anah, the daughter of Zibeon, the Hivite;", "zh": "以掃娶迦南的女子為妻，就是赫人以倫的女兒亞大和希未人祭便的孫女、亞拿的女兒阿何利巴瑪，", "ja": "エサウはカナンの娘たちのうちから妻をめとった。すなわちヘテびとエロンの娘アダと、ヒビびとヂベオンの子アナの娘アホリバマとである。"}, "3": {"en": "and Basemath, Ishmael’s daughter, sister of Nebaioth.", "zh": "又娶了以實瑪利的女兒、尼拜約的妹子巴實抹。", "ja": "また、イシマエルの娘ネバヨテの妹バスマテをめとった。"}, "4": {"en": "Adah bore to Esau Eliphaz. Basemath bore Reuel.", "zh": "亞大給以掃生了以利法；巴實抹生了流珥；", "ja": "アダはエリパズをエサウに産み、バスマテはリウエルを産み、"}, "5": {"en": "Oholibamah bore Jeush, Jalam, and Korah. These are the sons of Esau, who were born to him in the land of Canaan.", "zh": "阿何利巴瑪生了耶烏施、雅蘭、可拉。這都是以掃的兒子，是在迦南地生的。", "ja": "アホリバマはエウシ、ヤラム、コラを産んだ。これらはエサウの子であって、カナンの地で彼に生れた者である。"}, "6": {"en": "Esau took his wives, his sons, his daughters, and all the members of his household, with his livestock, all his animals, and all his possessions, which he had gathered in the land of Canaan, and went into a land away from his brother Jacob.", "zh": "以掃帶着他的妻子、兒女，與家中一切的人口，並他的牛羊、牲畜，和一切貨財，就是他在迦南地所得的，往別處去，離了他兄弟雅各。", "ja": "エサウは妻と子と娘と家のすべての人、家畜とすべての獣、またカナンの地で獲たすべての財産を携え、兄弟ヤコブを離れてほかの地へ行った。"}, "7": {"en": "For their substance was too great for them to dwell together, and the land of their travels couldn’t bear them because of their livestock.", "zh": "因為二人的財物群畜甚多，寄居的地方容不下他們，所以不能同居。", "ja": "彼らの財産が多くて、一緒にいることができなかったからである。すなわち彼らが寄留した地は彼らの家畜のゆえに、彼らをささえることができなかったのである。"}, "8": {"en": "Esau lived in the hill country of Seir. Esau is Edom.", "zh": "於是以掃住在西珥山裏；以掃就是以東。", "ja": "こうしてエサウはセイルの山地に住んだ。エサウはすなわちエドムである。"}, "9": {"en": "This is the history of the generations of Esau the father of the Edomites in the hill country of Seir:", "zh": "以掃是西珥山裏以東人的始祖，他的後代記在下面。", "ja": "セイルの山地におったエドムびとの先祖エサウの系図は次のとおりである。"}, "10": {"en": "these are the names of Esau’s sons: Eliphaz, the son of Adah, the wife of Esau; and Reuel, the son of Basemath, the wife of Esau.", "zh": "以掃眾子的名字如下。以掃的妻子亞大生以利法；以掃的妻子巴實抹生流珥。", "ja": "エサウの子らの名は次のとおりである。すなわちエサウの妻アダの子はエリパズ。エサウの妻バスマテの子はリウエル。"}, "11": {"en": "The sons of Eliphaz were Teman, Omar, Zepho, and Gatam, and Kenaz.", "zh": "以利法的兒子是提幔、阿抹、洗玻、迦坦、基納斯。", "ja": "エリパズの子らはテマン、オマル、ゼポ、ガタム、ケナズである。"}, "12": {"en": "Timna was concubine to Eliphaz, Esau’s son; and she bore to Eliphaz Amalek. These are the descendants of Adah, Esau’s wife.", "zh": "亭納是以掃兒子以利法的妾；她給以利法生了亞瑪力。這是以掃的妻子亞大的子孫。", "ja": "テムナはエサウの子エリパズのそばめで、アマレクをエリパズに産んだ。これらはエサウの妻アダの子らである。"}, "13": {"en": "These are the sons of Reuel: Nahath, Zerah, Shammah, and Mizzah. These were the descendants of Basemath, Esau’s wife.", "zh": "流珥的兒子是拿哈、謝拉、沙瑪、米撒。這是以掃妻子巴實抹的子孫。", "ja": "リウエルの子らは次のとおりである。すなわちナハテ、ゼラ、シャンマ、ミザであって、これらはエサウの妻バスマテの子らである。"}, "14": {"en": "These were the sons of Oholibamah, the daughter of Anah, the daughter of Zibeon, Esau’s wife: she bore to Esau Jeush, Jalam, and Korah.", "zh": "以掃的妻子阿何利巴瑪是祭便的孫女，亞拿的女兒；她給以掃生了耶烏施、雅蘭、可拉。", "ja": "ヂベオンの子アナの娘で、エサウの妻アホリバマの子らは次のとおりである。すなわち彼女はエウシ、ヤラム、コラをエサウに産んだ。"}, "15": {"en": "These are the chiefs of the sons of Esau: the sons of Eliphaz the firstborn of Esau: chief Teman, chief Omar, chief Zepho, chief Kenaz,", "zh": "以掃子孫中作族長的記在下面。以掃的長子以利法的子孫中，有提幔族長、阿抹族長、洗玻族長、基納斯族長、", "ja": "エサウの子らの中で、族長たる者は次のとおりである。すなわちエサウの長子エリパズの子らはテマンの族長、オマルの族長、ゼポの族長、ケナズの族長、"}, "16": {"en": "chief Korah, chief Gatam, chief Amalek. These are the chiefs who came of Eliphaz in the land of Edom. These are the sons of Adah.", "zh": "可拉族長、迦坦族長、亞瑪力族長。這是在以東地從以利法所出的族長，都是亞大的子孫。", "ja": "コラの族長、ガタムの族長、アマレクの族長である。これらはエリパズから出た族長で、エドムの地におった。これらはアダの子らである。"}, "17": {"en": "These are the sons of Reuel, Esau’s son: chief Nahath, chief Zerah, chief Shammah, chief Mizzah. These are the chiefs who came of Reuel in the land of Edom. These are the sons of Basemath, Esau’s wife.", "zh": "以掃的兒子流珥的子孫中，有拿哈族長、謝拉族長、沙瑪族長、米撒族長。這是在以東地從流珥所出的族長，都是以掃妻子巴實抹的子孫。", "ja": "エサウの子リウエルの子らは次のとおりである。すなわちナハテの族長、ゼラの族長、シャンマの族長、ミザの族長。これらはリウエルから出た族長で、エドムの地におった。これらはエサウの妻バスマテの子らである。"}, "18": {"en": "These are the sons of Oholibamah, Esau’s wife: chief Jeush, chief Jalam, chief Korah. These are the chiefs who came of Oholibamah the daughter of Anah, Esau’s wife.", "zh": "以掃的妻子阿何利巴瑪的子孫中，有耶烏施族長、雅蘭族長、可拉族長。這是從以掃妻子，亞拿的女兒，阿何利巴瑪子孫中所出的族長。", "ja": "エサウの妻アホリバマの子らは次のとおりである。すなわちエウシの族長、ヤラムの族長、コラの族長。これらはアナの娘で、エサウの妻アホリバマから出た族長である。"}, "19": {"en": "These are the sons of Esau (that is, Edom), and these are their chiefs.", "zh": "以上的族長都是以掃的子孫；以掃就是以東。", "ja": "これらはエサウすなわちエドムの子らで、族長たる者である。"}, "20": {"en": "These are the sons of Seir the Horite, the inhabitants of the land: Lotan, Shobal, Zibeon, Anah,", "zh": "那地原有的居民－何利人西珥的子孫記在下面：就是羅坍、朔巴、祭便、亞拿、", "ja": "この地の住民ホリびとセイルの子らは次のとおりである。すなわちロタン、ショバル、ヂベオン、アナ、"}, "21": {"en": "Dishon, Ezer, and Dishan. These are the chiefs who came of the Horites, the children of Seir in the land of Edom.", "zh": "底順、以察、底珊。這是從以東地的何利人西珥子孫中所出的族長。", "ja": "デション、エゼル、デシャン。これらはセイルの子ホリびとから出た族長で、エドムの地におった。"}, "22": {"en": "The children of Lotan were Hori and Heman. Lotan’s sister was Timna.", "zh": "羅坍的兒子是何利、希幔；羅坍的妹子是亭納。", "ja": "ロタンの子らはホリ、ヘマムであり、ロタンの妹はテムナであった。"}, "23": {"en": "These are the children of Shobal: Alvan, Manahath, Ebal, Shepho, and Onam.", "zh": "朔巴的兒子是亞勒文、瑪拿轄、以巴錄、示玻、阿南。", "ja": "ショバルの子らは次のとおりである。すなわちアルワン、マナハテ、エバル、シポ、オナム。"}, "24": {"en": "These are the children of Zibeon: Aiah and Anah. This is Anah who found the hot springs in the wilderness, as he fed the donkeys of Zibeon his father.", "zh": "祭便的兒子是亞雅、亞拿（當時在曠野放他父親祭便的驢，遇着溫泉的，就是這亞拿）。", "ja": "ヂベオンの子らは次のとおりである。すなわちアヤとアナ。このアナは父ヂベオンのろばを飼っていた時、荒野で温泉を発見した者である。"}, "25": {"en": "These are the children of Anah: Dishon and Oholibamah, the daughter of Anah.", "zh": "亞拿的兒子是底順；亞拿的女兒是阿何利巴瑪。", "ja": "アナの子らは次のとおりである。すなわちデションとアホリバマ。アホリバマはアナの娘である。"}, "26": {"en": "These are the children of Dishon: Hemdan, Eshban, Ithran, and Cheran.", "zh": "底順的兒子是欣但、伊是班、益蘭、基蘭。", "ja": "デションの子らは次のとおりである。すなわちヘムダン、エシバン、イテラン、ケラン。"}, "27": {"en": "These are the children of Ezer: Bilhan, Zaavan, and Akan.", "zh": "以察的兒子是辟罕、撒番、亞干。", "ja": "エゼルの子らは次のとおりである。すなわちビルハン、ザワン、アカン。"}, "28": {"en": "These are the children of Dishan: Uz and Aran.", "zh": "底珊的兒子是烏斯、亞蘭。", "ja": "デシャンの子らは次のとおりである。すなわちウズとアラン。"}, "29": {"en": "These are the chiefs who came of the Horites: chief Lotan, chief Shobal, chief Zibeon, chief Anah,", "zh": "從何利人所出的族長記在下面：就是羅坍族長、朔巴族長、祭便族長、亞拿族長、", "ja": "ホリびとから出た族長は次のとおりである。すなわちロタンの族長、ショバルの族長、ヂベオンの族長、アナの族長、"}, "30": {"en": "chief Dishon, chief Ezer, and chief Dishan. These are the chiefs who came of the Horites, according to their chiefs in the land of Seir.", "zh": "底順族長、以察族長、底珊族長。這是從何利人所出的族長，都在西珥地，按着宗族作族長。", "ja": "デションの族長、エゼルの族長、デシャンの族長。これらはホリびとから出た族長であって、その氏族に従ってセイルの地におった者である。"}, "31": {"en": "These are the kings who reigned in the land of Edom, before any king reigned over the children of Israel.", "zh": "以色列人未有君王治理以先，在以東地作王的記在下面。", "ja": "イスラエルの人々を治める王がまだなかった時、エドムの地を治めた王たちは次のとおりである。"}, "32": {"en": "Bela, the son of Beor, reigned in Edom. The name of his city was Dinhabah.", "zh": "比珥的兒子比拉在以東作王，他的京城名叫亭哈巴。", "ja": "ベオルの子ベラはエドムを治め、その都の名はデナバであった。"}, "33": {"en": "Bela died, and Jobab, the son of Zerah of Bozrah, reigned in his place.", "zh": "比拉死了，波斯拉人謝拉的兒子約巴接續他作王。", "ja": "ベラが死んで、ボズラのゼラの子ヨバブがこれに代って王となった。"}, "34": {"en": "Jobab died, and Husham of the land of the Temanites reigned in his place.", "zh": "約巴死了，提幔地的人戶珊接續他作王。", "ja": "ヨバブが死んで、テマンびとの地のホシャムがこれに代って王となった。"}, "35": {"en": "Husham died, and Hadad, the son of Bedad, who struck Midian in the field of Moab, reigned in his place. The name of his city was Avith.", "zh": "戶珊死了，比達的兒子哈達接續他作王；這哈達就是在摩押地殺敗米甸人的，他的京城名叫亞未得。", "ja": "ホシャムが死んで、ベダデの子ハダデがこれに代って王となった。彼はモアブの野でミデアンを撃った者である。その都の名はアビテであった。"}, "36": {"en": "Hadad died, and Samlah of Masrekah reigned in his place.", "zh": "哈達死了，瑪士利加人桑拉接續他作王。", "ja": "ハダデが死んで、マスレカのサムラがこれに代って王となった。"}, "37": {"en": "Samlah died, and Shaul of Rehoboth by the river, reigned in his place.", "zh": "桑拉死了，大河邊的利河伯人掃羅接續他作王。", "ja": "サムラが死んでユフラテ川のほとりにあるレホボテのサウルがこれに代って王となった。"}, "38": {"en": "Shaul died, and Baal Hanan the son of Achbor reigned in his place.", "zh": "掃羅死了，亞革波的兒子巴勒‧哈南接續他作王。", "ja": "サウルが死んでアクボルの子バアル・ハナンがこれに代って王となった。"}, "39": {"en": "Baal Hanan the son of Achbor died, and Hadar reigned in his place. The name of his city was Pau. His wife’s name was Mehetabel, the daughter of Matred, the daughter of Mezahab.", "zh": "亞革波的兒子巴勒‧哈南死了，哈達接續他作王，他的京城名叫巴烏；他的妻子名叫米希她別，是米‧薩合的孫女，瑪特列的女兒。", "ja": "アクボルの子バアル・ハナンが死んで、ハダルがこれに代って王となった。その都の名はパウであった。その妻の名はメヘタベルといって、メザハブの娘マテレデの娘であった。"}, "40": {"en": "These are the names of the chiefs who came from Esau, according to their families, after their places, and by their names: chief Timna, chief Alvah, chief Jetheth,", "zh": "從以掃所出的族長，按着他們的宗族、住處、名字記在下面：就是亭納族長、亞勒瓦族長、耶帖族長、", "ja": "エサウから出た族長の名は、その氏族と住所と名に従って言えば次のとおりである。すなわちテムナの族長、アルワの族長、エテテの族長、"}, "41": {"en": "chief Oholibamah, chief Elah, chief Pinon,", "zh": "阿何利巴瑪族長、以拉族長、比嫩族長、", "ja": "アホリバマの族長、エラの族長、ピノンの族長、"}, "42": {"en": "chief Kenaz, chief Teman, chief Mibzar,", "zh": "基納斯族長、提幔族長、米比薩族長、", "ja": "ケナズの族長、テマンの族長、ミブザルの族長、"}, "43": {"en": "chief Magdiel, and chief Iram. These are the chiefs of Edom, according to their habitations in the land of their possession. This is Esau, the father of the Edomites.", "zh": "瑪基疊族長、以蘭族長。這是以東人在所得為業的地上，按着他們的住處。（所有的族長都是以東人的始祖以掃的後代。）", "ja": "マグデエルの族長、イラムの族長。これらはエドムの族長たちであって、その領地内の住所に従っていったものである。エドムびとの先祖はエサウである。"}}}, "37": {"verses": {"1": {"en": "Jacob lived in the land of his father’s travels, in the land of Canaan.", "zh": "雅各住在迦南地，就是他父親寄居的地。", "ja": "ヤコブは父の寄留の地、すなわちカナンの地に住んだ。"}, "2": {"en": "This is the history of the generations of Jacob. Joseph, being seventeen years old, was feeding the flock with his brothers. He was a boy with the sons of Bilhah and Zilpah, his father’s wives. Joseph brought an evil report of them to their father.", "zh": "雅各的記略如下。", "ja": "ヤコブの子孫は次のとおりである。ヨセフは十七歳の時、兄弟たちと共に羊の群れを飼っていた。彼はまだ子供で、父の妻たちビルハとジルパとの子らと共にいたが、ヨセフは彼らの悪いうわさを父に告げた。"}, "3": {"en": "Now Israel loved Joseph more than all his children, because he was the son of his old age, and he made him a tunic of many colors.", "zh": "約瑟十七歲與他哥哥們一同牧羊。他是個童子，與他父親的妾辟拉、悉帕的兒子們常在一處。約瑟將他哥哥們的惡行報給他們的父親。   以色列原來愛約瑟過於愛他的眾子，因為約瑟是他年老生的；他給約瑟做了一件彩衣。", "ja": "ヨセフは年寄り子であったから、イスラエルは他のどの子よりも彼を愛して、彼のために長そでの着物をつくった。"}, "4": {"en": "His brothers saw that their father loved him more than all his brothers, and they hated him, and couldn’t speak peaceably to him.", "zh": "約瑟的哥哥們見父親愛約瑟過於愛他們，就恨約瑟，不與他說和睦的話。", "ja": "兄弟たちは父がどの兄弟よりも彼を愛するのを見て、彼を憎み、穏やかに彼に語ることができなかった。"}, "5": {"en": "Joseph dreamed a dream, and he told it to his brothers, and they hated him all the more.", "zh": "約瑟做了一夢，告訴他哥哥們，他們就越發恨他。", "ja": "ある時、ヨセフは夢を見て、それを兄弟たちに話したので、彼らは、ますます彼を憎んだ。"}, "6": {"en": "He said to them, “Please hear this dream which I have dreamed:", "zh": "約瑟對他們說：「請聽我所做的夢：", "ja": "ヨセフは彼らに言った、「どうぞわたしが見た夢を聞いてください。"}, "7": {"en": "for behold, we were binding sheaves in the field, and behold, my sheaf arose and also stood upright; and behold, your sheaves came around, and bowed down to my sheaf.”", "zh": "我們在田裏捆禾稼，我的捆起來站着，你們的捆來圍着我的捆下拜。」", "ja": "わたしたちが畑の中で束を結わえていたとき、わたしの束が起きて立つと、あなたがたの束がまわりにきて、わたしの束を拝みました」。"}, "8": {"en": "His brothers asked him, “Will you indeed reign over us? Will you indeed have dominion over us?” They hated him all the more for his dreams and for his words.", "zh": "他的哥哥們回答說：「難道你真要作我們的王嗎？難道你真要管轄我們嗎？」他們就因為他的夢和他的話越發恨他。", "ja": "すると兄弟たちは彼に向かって、「あなたはほんとうにわたしたちの王になるのか。あなたは実際わたしたちを治めるのか」と言って、彼の夢とその言葉のゆえにますます彼を憎んだ。"}, "9": {"en": "He dreamed yet another dream, and told it to his brothers, and said, “Behold, I have dreamed yet another dream: and behold, the sun and the moon and eleven stars bowed down to me.”", "zh": "後來他又做了一夢，也告訴他的哥哥們說：「看哪，我又做了一夢，夢見太陽、月亮，與十一個星向我下拜。」", "ja": "ヨセフはまた一つの夢を見て、それを兄弟たちに語って言った、「わたしはまた夢を見ました。日と月と十一の星とがわたしを拝みました」。"}, "10": {"en": "He told it to his father and to his brothers. His father rebuked him, and said to him, “What is this dream that you have dreamed? Will I and your mother and your brothers indeed come to bow ourselves down to the earth before you?”", "zh": "約瑟將這夢告訴他父親和他哥哥們，他父親就責備他說：「你做的這是甚麼夢！難道我和你母親、你弟兄果然要來俯伏在地，向你下拜嗎？」", "ja": "彼はこれを父と兄弟たちに語ったので、父は彼をとがめて言った、「あなたが見たその夢はどういうのか。ほんとうにわたしとあなたの母と、兄弟たちとが行って地に伏し、あなたを拝むのか」。"}, "11": {"en": "His brothers envied him, but his father kept this saying in mind.", "zh": "他哥哥們都嫉妒他，他父親卻把這話存在心裏。", "ja": "兄弟たちは彼をねたんだ。しかし父はこの言葉を心にとめた。"}, "12": {"en": "His brothers went to feed their father’s flock in Shechem.", "zh": "約瑟的哥哥們往示劍去放他們父親的羊。", "ja": "さて兄弟たちがシケムに行って、父の羊の群れを飼っていたとき、"}, "13": {"en": "Israel said to Joseph, “Aren’t your brothers feeding the flock in Shechem? Come, and I will send you to them.” He said to him, “Here I am.”", "zh": "以色列對約瑟說：「你哥哥們不是在示劍放羊嗎？你來，我要打發你往他們那裏去。」約瑟說：「我在這裏。」", "ja": "イスラエルはヨセフに言った、「あなたの兄弟たちはシケムで羊を飼っているではないか。さあ、あなたを彼らの所へつかわそう」。ヨセフは父に言った、「はい、行きます」。"}, "14": {"en": "He said to him, “Go now, see whether it is well with your brothers, and well with the flock; and bring me word again.” So he sent him out of the valley of Hebron, and he came to Shechem.", "zh": "以色列說：「你去看看你哥哥們平安不平安，群羊平安不平安，就回來報信給我」；於是打發他出希伯崙谷，他就往示劍去了。", "ja": "父は彼に言った、「どうか、行って、あなたの兄弟たちは無事であるか、また群れは無事であるか見てきて、わたしに知らせてください」。父が彼をヘブロンの谷からつかわしたので、彼はシケムに行った。"}, "15": {"en": "A certain man found him, and behold, he was wandering in the field. The man asked him, “What are you looking for?”", "zh": "有人遇見他在田野走迷了路，就問他說：「你找甚麼？」", "ja": "ひとりの人が彼に会い、彼が野をさまよっていたので、その人は彼に尋ねて言った、「あなたは何を捜しているのですか」。"}, "16": {"en": "He said, “I am looking for my brothers. Tell me, please, where they are feeding the flock.”", "zh": "他說：「我找我的哥哥們，求你告訴我，他們在何處放羊。」", "ja": "彼は言った、「兄弟たちを捜しているのです。彼らが、どこで羊を飼っているのか、どうぞわたしに知らせてください」。"}, "17": {"en": "The man said, “They have left here, for I heard them say, ‘Let’s go to Dothan.’ ”", "zh": "那人說：「他們已經走了，我聽見他們說要往多坍去。」約瑟就去追趕他哥哥們，遇見他們在多坍。", "ja": "その人は言った、「彼らはここを去りました。彼らが『ドタンへ行こう』と言うのをわたしは聞きました」。そこでヨセフは兄弟たちのあとを追って行って、ドタンで彼らに会った。"}, "18": {"en": "Joseph went after his brothers, and found them in Dothan.   They saw him afar off, and before he came near to them, they conspired against him to kill him.", "zh": "他們遠遠地看見他，趁他還沒有走到跟前，大家就同謀要害死他，", "ja": "ヨセフが彼らに近づかないうちに、彼らははるかにヨセフを見て、これを殺そうと計り、"}, "19": {"en": "They said to one another, “Behold, this dreamer comes.", "zh": "彼此說：「你看！那做夢的來了。", "ja": "互に言った、「あの夢見る者がやって来る。"}, "20": {"en": "Come now therefore, and let’s kill him, and cast him into one of the pits, and we will say, ‘An evil animal has devoured him.’ We will see what will become of his dreams.”", "zh": "來吧！我們將他殺了，丟在一個坑裏，就說有惡獸把他吃了。我們且看他的夢將來怎麼樣。」", "ja": "さあ、彼を殺して穴に投げ入れ、悪い獣が彼を食ったと言おう。そして彼の夢がどうなるか見よう」。"}, "21": {"en": "Reuben heard it, and delivered him out of their hand, and said, “Let’s not take his life.”", "zh": "呂便聽見了，要救他脫離他們的手，說：「我們不可害他的性命」；", "ja": "ルベンはこれを聞いて、ヨセフを彼らの手から救い出そうとして言った、「われわれは彼の命を取ってはならない」。"}, "22": {"en": "Reuben said to them, “Shed no blood. Throw him into this pit that is in the wilderness, but lay no hand on him”—that he might deliver him out of their hand, to restore him to his father.", "zh": "又說：「不可流他的血，可以把他丟在這野地的坑裏，不可下手害他。」呂便的意思是要救他脫離他們的手，把他歸還他的父親。", "ja": "ルベンはまた彼らに言った、「血を流してはいけない。彼を荒野のこの穴に投げ入れよう。彼に手をくだしてはならない」。これはヨセフを彼らの手から救いだして父に返すためであった。"}, "23": {"en": "When Joseph came to his brothers, they stripped Joseph of his tunic, the tunic of many colors that was on him;", "zh": "約瑟到了他哥哥們那裏，他們就剝了他的外衣，就是他穿的那件彩衣，", "ja": "さて、ヨセフが兄弟たちのもとへ行くと、彼らはヨセフの着物、彼が着ていた長そでの着物をはぎとり、"}, "24": {"en": "and they took him, and threw him into the pit. The pit was empty. There was no water in it.", "zh": "把他丟在坑裏；那坑是空的，裏頭沒有水。", "ja": "彼を捕えて穴に投げ入れた。その穴はからで、その中に水はなかった。"}, "25": {"en": "They sat down to eat bread, and they lifted up their eyes and looked, and saw a caravan of Ishmaelites coming from Gilead, with their camels bearing spices and balm and myrrh, going to carry it down to Egypt.", "zh": "他們坐下吃飯，舉目觀看，見有一夥米甸 的以實瑪利人從基列來，用駱駝馱着香料、乳香、沒藥，要帶下埃及去。", "ja": "こうして彼らはすわってパンを食べた。時に彼らが目をあげて見ると、イシマエルびとの隊商が、らくだに香料と、乳香と、もつやくとを負わせてエジプトへ下り行こうとギレアデからやってきた。"}, "26": {"en": "Judah said to his brothers, “What profit is it if we kill our brother and conceal his blood?", "zh": "猶大對眾弟兄說：「我們殺我們的兄弟，藏了他的血有甚麼益處呢？", "ja": "そこでユダは兄弟たちに言った、「われわれが弟を殺し、その血を隠して何の益があろう。"}, "27": {"en": "Come, and let’s sell him to the Ishmaelites, and not let our hand be on him; for he is our brother, our flesh.” His brothers listened to him.", "zh": "我們不如將他賣給以實瑪利人，不可下手害他；因為他是我們的兄弟，我們的骨肉。」眾弟兄就聽從了他。", "ja": "さあ、われわれは彼をイシマエルびとに売ろう。彼はわれわれの兄弟、われわれの肉身だから、彼に手を下してはならない」。兄弟たちはこれを聞き入れた。"}, "28": {"en": "Midianites who were merchants passed by, and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmaelites for twenty pieces of silver. The merchants brought Joseph into Egypt.", "zh": "有些米甸的商人從那裏經過，哥哥們就把約瑟從坑裏拉上來，講定二十舍客勒銀子，把約瑟賣給以實瑪利人。他們就把約瑟帶到埃及去了。", "ja": "時にミデアンびとの商人たちが通りかかったので、彼らはヨセフを穴から引き上げ、銀二十シケルでヨセフをイシマエルびとに売った。彼らはヨセフをエジプトへ連れて行った。"}, "29": {"en": "Reuben returned to the pit, and saw that Joseph wasn’t in the pit; and he tore his clothes.", "zh": "呂便回到坑邊，見約瑟不在坑裏，就撕裂衣服，", "ja": "さてルベンは穴に帰って見たが、ヨセフが穴の中にいなかったので、彼は衣服を裂き、"}, "30": {"en": "He returned to his brothers, and said, “The child is no more; and I, where will I go?”", "zh": "回到兄弟們那裏，說：「童子沒有了。我往哪裏去才好呢？」", "ja": "兄弟たちのもとに帰って言った、「あの子はいない。ああ、わたしはどこへ行くことができよう」。"}, "31": {"en": "They took Joseph’s tunic, and killed a male goat, and dipped the tunic in the blood.", "zh": "他們宰了一隻公山羊，把約瑟的那件彩衣染了血，", "ja": "彼らはヨセフの着物を取り、雄やぎを殺して、着物をその血に浸し、"}, "32": {"en": "They took the tunic of many colors, and they brought it to their father, and said, “We have found this. Examine it, now, and see if it is your son’s tunic or not.”", "zh": "打發人送到他們的父親那裏，說：「我們撿了這個；請認一認是你兒子的外衣不是？」", "ja": "その長そでの着物を父に持ち帰って言った、「わたしたちはこれを見つけましたが、これはあなたの子の着物か、どうか見さだめてください」。"}, "33": {"en": "He recognized it, and said, “It is my son’s tunic. An evil animal has devoured him. Joseph is without doubt torn in pieces.”", "zh": "他認得，就說：「這是我兒子的外衣。有惡獸把他吃了，約瑟被撕碎了！撕碎了！」", "ja": "父はこれを見さだめて言った、「わが子の着物だ。悪い獣が彼を食ったのだ。確かにヨセフはかみ裂かれたのだ」。"}, "34": {"en": "Jacob tore his clothes, and put sackcloth on his waist, and mourned for his son many days.", "zh": "雅各便撕裂衣服，腰間圍上麻布，為他兒子悲哀了多日。", "ja": "そこでヤコブは衣服を裂き、荒布を腰にまとって、長い間その子のために嘆いた。"}, "35": {"en": "All his sons and all his daughters rose up to comfort him, but he refused to be comforted. He said, “For I will go down to Sheol to my son, mourning.” His father wept for him.", "zh": "他的兒女都起來安慰他，他卻不肯受安慰，說：「我必悲哀着下陰間，到我兒子那裏。」約瑟的父親就為他哀哭。", "ja": "子らと娘らとは皆立って彼を慰めようとしたが、彼は慰められるのを拒んで言った、「いや、わたしは嘆きながら陰府に下って、わが子のもとへ行こう」。こうして父は彼のために泣いた。"}, "36": {"en": "The Midianites sold him into Egypt to Potiphar, an officer of Pharaoh’s, the captain of the guard.", "zh": "米甸人帶約瑟到埃及，把他賣給法老的內臣－護衛長波提乏。", "ja": "さて、かのミデアンびとらはエジプトでパロの役人、侍衛長ポテパルにヨセフを売った。"}}}, "38": {"verses": {"1": {"en": "At that time, Judah went down from his brothers, and visited a certain Adullamite, whose name was Hirah.", "zh": "那時，猶大離開他弟兄下去，到一個亞杜蘭人名叫希拉的家裏去。", "ja": "そのころユダは兄弟たちを離れて下り、アドラムびとで、名をヒラという者の所へ行った。"}, "2": {"en": "There, Judah saw the daughter of a certain Canaanite man named Shua. He took her, and went in to her.", "zh": "猶大在那裏看見一個迦南人名叫書亞的女兒，就娶她為妻，與她同房，", "ja": "ユダはその所で、名をシュアというカナンびとの娘を見て、これをめとり、その所にはいった。"}, "3": {"en": "She conceived, and bore a son; and he named him Er.", "zh": "她就懷孕生了兒子，猶大給他起名叫珥。", "ja": "彼女はみごもって男の子を産んだので、ユダは名をエルと名づけた。"}, "4": {"en": "She conceived again, and bore a son; and she named him Onan.", "zh": "她又懷孕生了兒子，母親給他起名叫俄南。", "ja": "彼女は再びみごもって男の子を産み、名をオナンと名づけた。"}, "5": {"en": "She yet again bore a son, and named him Shelah. He was at Chezib when she bore him.", "zh": "她復又生了兒子，給他起名叫示拉。她生示拉的時候，猶大正在基悉。", "ja": "また重ねて、男の子を産み、名をシラと名づけた。彼女はこの男の子を産んだとき、クジブにおった。"}, "6": {"en": "Judah took a wife for Er, his firstborn, and her name was Tamar.", "zh": "猶大為長子珥娶妻，名叫她瑪。", "ja": "ユダは長子エルのために、名をタマルという妻を迎えた。"}, "7": {"en": "Er, Judah’s firstborn, was wicked in the LORD’s sight. So the LORD killed him.", "zh": "猶大的長子珥在耶和華眼中看為惡，耶和華就叫他死了。", "ja": "しかしユダの長子エルは主の前に悪い者であったので、主は彼を殺された。"}, "8": {"en": "Judah said to Onan, “Go in to your brother’s wife, and perform the duty of a husband’s brother to her, and raise up offspring for your brother.”", "zh": "猶大對俄南說：「你當與你哥哥的妻子同房，向她盡你為弟的本分，為你哥哥生子立後。」", "ja": "そこでユダはオナンに言った、「兄の妻の所にはいって、彼女をめとり、兄に子供を得させなさい」。"}, "9": {"en": "Onan knew that the offspring wouldn’t be his; and when he went in to his brother’s wife, he spilled his semen on the ground, lest he should give offspring to his brother.", "zh": "俄南知道生子不歸自己，所以同房的時候便遺在地，免得給他哥哥留後。", "ja": "しかしオナンはその子が自分のものとならないのを知っていたので、兄の妻の所にはいった時、兄に子を得させないために地に洩らした。"}, "10": {"en": "The thing which he did was evil in the LORD’s sight, and he killed him also.", "zh": "俄南所做的在耶和華眼中看為惡，耶和華也就叫他死了。", "ja": "彼のした事は主の前に悪かったので、主は彼をも殺された。"}, "11": {"en": "Then Judah said to Tamar, his daughter-in-law, “Remain a widow in your father’s house, until Shelah, my son, is grown up;” for he said, “Lest he also die, like his brothers.” Tamar went and lived in her father’s house.", "zh": "猶大心裏說：「恐怕示拉也死，像他兩個哥哥一樣」，就對他兒婦她瑪說：「你去，在你父親家裏守寡，等我兒子示拉長大。」她瑪就回去，住在她父親家裏。", "ja": "そこでユダはその子の妻タマルに言った、「わたしの子シラが成人するまで、寡婦のままで、あなたの父の家にいなさい」。彼は、シラもまた兄弟たちのように死ぬかもしれないと、思ったからである。それでタマルは行って父の家におった。"}, "12": {"en": "After many days, Shua’s daughter, the wife of Judah, died. Judah was comforted, and went up to his sheep shearers to Timnah, he and his friend Hirah, the Adullamite.", "zh": "過了許久，猶大的妻子書亞的女兒死了。猶大得了安慰，就和他朋友亞杜蘭人希拉上亭拿去，到他剪羊毛的人那裏。", "ja": "日がたってシュアの娘ユダの妻は死んだ。その後、ユダは喪を終ってその友アドラムびとヒラと共にテムナに上り、自分の羊の毛を切る者のところへ行った。"}, "13": {"en": "Tamar was told, “Behold, your father-in-law is going up to Timnah to shear his sheep.”", "zh": "有人告訴她瑪說：「你的公公上亭拿剪羊毛去了。」", "ja": "時に、ひとりの人がタマルに告げて、「あなたのしゅうとが羊の毛を切るためにテムナに上って来る」と言ったので、"}, "14": {"en": "She took off the garments of her widowhood, and covered herself with her veil, and wrapped herself, and sat in the gate of Enaim, which is on the way to Timnah; for she saw that Shelah was grown up, and she wasn’t given to him as a wife.", "zh": "她瑪見示拉已經長大，還沒有娶她為妻，就脫了她作寡婦的衣裳，用帕子蒙着臉，又遮住身體，坐在亭拿路上的伊拿印城門口。", "ja": "彼女は寡婦の衣服を脱ぎすて、被衣で身をおおい隠して、テムナへ行く道のかたわらにあるエナイムの入口にすわっていた。彼女はシラが成人したのに、自分がその妻にされないのを知ったからである。"}, "15": {"en": "When Judah saw her, he thought that she was a prostitute, for she had covered her face.", "zh": "猶大看見她，以為是妓女，因為她蒙着臉。", "ja": "ユダは彼女を見たとき、彼女が顔をおおっていたため、遊女だと思い、"}, "16": {"en": "He turned to her by the way, and said, “Please come, let me come in to you,” for he didn’t know that she was his daughter-in-law. She said, “What will you give me, that you may come in to me?”", "zh": "猶大就轉到她那裏去，說：「來吧！讓我與你同寢。」他原不知道是他的兒婦。她瑪說：「你要與我同寢，把甚麼給我呢？」", "ja": "道のかたわらで彼女に向かって言った、「さあ、あなたの所にはいらせておくれ」。彼はこの女がわが子の妻であることを知らなかったからである。彼女は言った、「わたしの所にはいるため、何をくださいますか」。"}, "17": {"en": "He said, “I will send you a young goat from the flock.” She said, “Will you give me a pledge, until you send it?”", "zh": "猶大說：「我從羊群裏取一隻山羊羔，打發人送來給你。」她瑪說：「在未送以先，你願意給我一個當頭嗎？」", "ja": "ユダは言った、「群れのうちのやぎの子をあなたにあげよう」。彼女は言った、「それをくださるまで、しるしをわたしにくださいますか」。"}, "18": {"en": "He said, “What pledge will I give you?” She said, “Your signet and your cord, and your staff that is in your hand.”", "zh": "他說：「我給你甚麼當頭呢？」她瑪說：「你的印、你的帶子，和你手裏的杖。」猶大就給了她，與她同寢，她就從猶大懷了孕。", "ja": "ユダは言った、「どんなしるしをあげようか」。彼女は言った、「あなたの印と紐と、あなたの手にあるつえとを」。彼はこれらを与えて彼女の所にはいった。彼女はユダによってみごもった。"}, "19": {"en": "He gave them to her, and came in to her, and she conceived by him.   She arose, and went away, and put off her veil from her, and put on the garments of her widowhood.", "zh": "她瑪起來走了，除去帕子，仍舊穿上作寡婦的衣裳。", "ja": "彼女は起きて去り、被衣を脱いで寡婦の衣服を着た。"}, "20": {"en": "Judah sent the young goat by the hand of his friend, the Adullamite, to receive the pledge from the woman’s hand, but he didn’t find her.", "zh": "猶大託他朋友亞杜蘭人送一隻山羊羔去，要從那女人手裏取回當頭來，卻找不着她，", "ja": "やがてユダはその女からしるしを取りもどそうと、その友アドラムびとに託してやぎの子を送ったけれども、その女を見いだせなかった。"}, "21": {"en": "Then he asked the men of her place, saying, “Where is the prostitute, that was at Enaim by the road?” They said, “There has been no prostitute here.”", "zh": "就問那地方的人說：「伊拿印路旁的妓女在哪裏？」他們說：「這裏並沒有妓女。」", "ja": "そこで彼はその所の人々に尋ねて言った、「エナイムで道のかたわらにいた遊女はどこにいますか」。彼らは言った、「ここには遊女はいません」。"}, "22": {"en": "He returned to Judah, and said, “I haven’t found her; and also the men of the place said, ‘There has been no prostitute here.’ ”", "zh": "他回去見猶大說：「我沒有找着她，並且那地方的人說：『這裏沒有妓女。』」", "ja": "彼はユダのもとに帰って言った、「わたしは彼女を見いだせませんでした。またその所の人々は、『ここには遊女はいない』と言いました」。"}, "23": {"en": "Judah said, “Let her keep it, lest we be shamed. Behold, I sent this young goat, and you haven’t found her.”", "zh": "猶大說：「我把這山羊羔送去了，你竟找不着她。任憑她拿去吧，免得我們被羞辱。」", "ja": "そこでユダは言った、「女に持たせておこう。わたしたちは恥をかくといけないから。とにかく、わたしはこのやぎの子を送ったが、あなたは彼女を見いだせなかったのだ」。"}, "24": {"en": "About three months later, Judah was told, “Tamar, your daughter-in-law, has played the prostitute. Moreover, behold, she is with child by prostitution.”", "zh": "約過了三個月，有人告訴猶大說：「你的兒婦她瑪作了妓女，且因行淫有了身孕。」猶大說：「拉出她來，把她燒了！」", "ja": "ところが三月ほどたって、ひとりの人がユダに言った、「あなたの嫁タマルは姦淫しました。そのうえ、彼女は姦淫によってみごもりました」。ユダは言った、「彼女を引き出して焼いてしまえ」。"}, "25": {"en": "Judah said, “Bring her out, and let her be burned.”   When she was brought out, she sent to her father-in-law, saying, “I am with child by the man who owns these.” She also said, “Please discern whose these are—the signet, and the cords, and the staff.”", "zh": "她瑪被拉出來的時候便打發人去見她公公，對他說：「這些東西是誰的，我就是從誰懷的孕。請你認一認，這印和帶子並杖都是誰的？」", "ja": "彼女は引き出された時、そのしゅうとに人をつかわして言った、「わたしはこれをもっている人によって、みごもりました」。彼女はまた言った、「どうか、この印と、紐と、つえとはだれのものか、見定めてください」。"}, "26": {"en": "Judah acknowledged them, and said, “She is more righteous than I, because I didn’t give her to Shelah, my son.”", "zh": "猶大承認說：「她比我更有義，因為我沒有將她給我的兒子示拉。」從此猶大不再與她同寢了。", "ja": "ユダはこれを見定めて言った、「彼女はわたしよりも正しい。わたしが彼女をわが子シラに与えなかったためである」。彼は再び彼女を知らなかった。"}, "27": {"en": "He knew her again no more.   In the time of her travail, behold, twins were in her womb.", "zh": "她瑪將要生產，不料她腹裏是一對雙生。", "ja": "さて彼女の出産の時がきたが、胎内には、ふたごがあった。"}, "28": {"en": "When she travailed, one put out a hand, and the midwife took and tied a scarlet thread on his hand, saying, “This came out first.”", "zh": "到生產的時候，一個孩子伸出一隻手來；收生婆拿紅線拴在他手上，說：「這是頭生的。」", "ja": "出産の時に、ひとりの子が手を出したので、産婆は、「これがさきに出た」と言い、緋の糸を取って、その手に結んだ。"}, "29": {"en": "As he drew back his hand, behold, his brother came out, and she said, “Why have you made a breach for yourself?” Therefore his name was called Perez.", "zh": "隨後這孩子把手收回去，他哥哥生出來了；收生婆說：「你為甚麼搶着來呢？」因此給他起名叫法勒斯。", "ja": "そして、その子が手をひっこめると、その弟が出たので、「どうしてあなたは自分で破って出るのか」と言った。これによって名はペレヅと呼ばれた。"}, "30": {"en": "Afterward his brother came out, who had the scarlet thread on his hand, and his name was called Zerah.", "zh": "後來，他兄弟那手上有紅線的也生出來，就給他起名叫謝拉。", "ja": "その後、手に緋の糸のある兄が出たので、名はゼラと呼ばれた。"}}}, "39": {"verses": {"1": {"en": "Joseph was brought down to Egypt. Potiphar, an officer of Pharaoh’s, the captain of the guard, an Egyptian, bought him from the hand of the Ishmaelites that had brought him down there.", "zh": "約瑟被帶下埃及去。有一個埃及人，是法老的內臣－護衛長波提乏，從那些帶下他來的以實瑪利人手下買了他去。", "ja": "さてヨセフは連れられてエジプトに下ったが、パロの役人で侍衛長であったエジプトびとポテパルは、彼をそこに連れ下ったイシマエルびとらの手から買い取った。"}, "2": {"en": "The LORD was with Joseph, and he was a prosperous man. He was in the house of his master the Egyptian.", "zh": "約瑟住在他主人埃及人的家中，耶和華與他同在，他就百事順利。", "ja": "主がヨセフと共におられたので、彼は幸運な者となり、その主人エジプトびとの家におった。"}, "3": {"en": "His master saw that the LORD was with him, and that the LORD made all that he did prosper in his hand.", "zh": "他主人見耶和華與他同在，又見耶和華使他手裏所辦的盡都順利，", "ja": "その主人は主が彼とともにおられることと、主が彼の手のすることをすべて栄えさせられるのを見た。"}, "4": {"en": "Joseph found favor in his sight. He ministered to him, and Potiphar made him overseer over his house, and all that he had he put into his hand.", "zh": "約瑟就在主人眼前蒙恩，伺候他主人，並且主人派他管理家務，把一切所有的都交在他手裏。", "ja": "そこで、ヨセフは彼の前に恵みを得、そのそば近く仕えた。彼はヨセフに家をつかさどらせ、持ち物をみな彼の手にゆだねた。"}, "5": {"en": "From the time that he made him overseer in his house, and over all that he had, the LORD blessed the Egyptian’s house for Joseph’s sake. The LORD’s blessing was on all that he had, in the house and in the field.", "zh": "自從主人派約瑟管理家務和他一切所有的，耶和華就因約瑟的緣故賜福與那埃及人的家；凡家裏和田間一切所有的都蒙耶和華賜福。", "ja": "彼がヨセフに家とすべての持ち物をつかさどらせた時から、主はヨセフのゆえにそのエジプトびとの家を恵まれたので、主の恵みは彼の家と畑とにあるすべての持ち物に及んだ。"}, "6": {"en": "He left all that he had in Joseph’s hand. He didn’t concern himself with anything, except for the food which he ate.", "zh": "波提乏將一切所有的都交在約瑟的手中，除了自己所吃的飯，別的事一概不知。", "ja": "そこで彼は持ち物をみなヨセフの手にゆだねて、自分が食べる物のほかは、何をも顧みなかった。さてヨセフは姿がよく、顔が美しかった。"}, "7": {"en": "Joseph was well-built and handsome.   After these things, his master’s wife set her eyes on Joseph; and she said, “Lie with me.”", "zh": "約瑟原來秀雅俊美。   這事以後，約瑟主人的妻以目送情給約瑟，說：「你與我同寢吧！」", "ja": "これらの事の後、主人の妻はヨセフに目をつけて言った、「わたしと寝なさい」。"}, "8": {"en": "But he refused, and said to his master’s wife, “Behold, my master doesn’t know what is with me in the house, and he has put all that he has into my hand.", "zh": "約瑟不從，對他主人的妻說：「看哪，一切家務，我主人都不知道；他把所有的都交在我手裏。", "ja": "ヨセフは拒んで、主人の妻に言った、「御主人はわたしがいるので家の中の何をも顧みず、その持ち物をみなわたしの手にゆだねられました。"}, "9": {"en": "No one is greater in this house than I am, and he has not kept back anything from me but you, because you are his wife. How then can I do this great wickedness, and sin against God?”", "zh": "在這家裏沒有比我大的；並且他沒有留下一樣不交給我，只留下了你，因為你是他的妻子。我怎能作這大惡，得罪上帝呢？」", "ja": "この家にはわたしよりも大いなる者はありません。また御主人はあなたを除いては、何をもわたしに禁じられませんでした。あなたが御主人の妻であるからです。どうしてわたしはこの大きな悪をおこなって、神に罪を犯すことができましょう」。"}, "10": {"en": "As she spoke to Joseph day by day, he didn’t listen to her, to lie by her, or to be with her.", "zh": "後來她天天和約瑟說，約瑟卻不聽從她，不與她同寢，也不和她在一處。", "ja": "彼女は毎日ヨセフに言い寄ったけれども、ヨセフは聞きいれず、彼女と寝なかった。また共にいなかった。"}, "11": {"en": "About this time, he went into the house to do his work, and there were none of the men of the house inside.", "zh": "有一天，約瑟進屋裏去辦事，家中人沒有一個在那屋裏，", "ja": "ある日ヨセフが務をするために家にはいった時、家の者がひとりもそこにいなかったので、"}, "12": {"en": "She caught him by his garment, saying, “Lie with me!”", "zh": "婦人就拉住他的衣裳，說：「你與我同寢吧！」約瑟把衣裳丟在婦人手裏，跑到外邊去了。", "ja": "彼女はヨセフの着物を捕えて、「わたしと寝なさい」と言った。ヨセフは着物を彼女の手に残して外にのがれ出た。"}, "13": {"en": "He left his garment in her hand, and ran outside.   When she saw that he had left his garment in her hand, and had run outside,", "zh": "婦人看見約瑟把衣裳丟在她手裏跑出去了，", "ja": "彼女はヨセフが着物を自分の手に残して外にのがれたのを見て、"}, "14": {"en": "she called to the men of her house, and spoke to them, saying, “Behold, he has brought a Hebrew in to us to mock us. He came in to me to lie with me, and I cried with a loud voice.", "zh": "就叫了家裏的人來，對他們說：「你們看！他帶了一個希伯來人進入我們家裏，要戲弄我們。他到我這裏來，要與我同寢，我就大聲喊叫。", "ja": "その家の者どもを呼び、彼らに告げて言った、「主人がわたしたちの所に連れてきたヘブルびとは、わたしたちに戯れます。彼はわたしと寝ようとして、わたしの所にはいったので、わたしは大声で叫びました。"}, "15": {"en": "When he heard that I lifted up my voice and cried, he left his garment by me, and ran outside.”", "zh": "他聽見我放聲喊起來，就把衣裳丟在我這裏，跑到外邊去了。」", "ja": "彼はわたしが声をあげて叫ぶのを聞くと、着物をわたしの所に残して外にのがれ出ました」。"}, "16": {"en": "She laid up his garment by her, until his master came home.", "zh": "婦人把約瑟的衣裳放在自己那裏，等着他主人回家，", "ja": "彼女はその着物をかたわらに置いて、主人の帰って来るのを待った。"}, "17": {"en": "She spoke to him according to these words, saying, “The Hebrew servant, whom you have brought to us, came in to me to mock me,", "zh": "就對他如此如此說：「你所帶到我們這裏的那希伯來僕人進來要戲弄我，", "ja": "そして彼女は次のように主人に告げた、「あなたがわたしたちに連れてこられたヘブルのしもべはわたしに戯れようとして、わたしの所にはいってきました。"}, "18": {"en": "and as I lifted up my voice and cried, he left his garment by me, and ran outside.”", "zh": "我放聲喊起來，他就把衣裳丟在我這裏，跑出去了。」", "ja": "わたしが声をあげて叫んだので、彼は着物をわたしの所に残して外にのがれました」。"}, "19": {"en": "When his master heard the words of his wife, which she spoke to him, saying, “This is what your servant did to me,” his wrath was kindled.", "zh": "約瑟的主人聽見他妻子對他所說的話，說「你的僕人如此如此待我」，他就生氣，", "ja": "主人はその妻が「あなたのしもべは、わたしにこんな事をした」と告げる言葉を聞いて、激しく怒った。"}, "20": {"en": "Joseph’s master took him, and put him into the prison, the place where the king’s prisoners were bound, and he was there in custody.", "zh": "把約瑟下在監裏，就是王的囚犯被囚的地方。於是約瑟在那裏坐監。", "ja": "そしてヨセフの主人は彼を捕えて、王の囚人をつなぐ獄屋に投げ入れた。こうしてヨセフは獄屋の中におったが、"}, "21": {"en": "But the LORD was with Joseph, and showed kindness to him, and gave him favor in the sight of the keeper of the prison.", "zh": "但耶和華與約瑟同在，向他施恩，使他在司獄的眼前蒙恩。", "ja": "主はヨセフと共におられて彼にいつくしみを垂れ、獄屋番の恵みをうけさせられた。"}, "22": {"en": "The keeper of the prison committed to Joseph’s hand all the prisoners who were in the prison. Whatever they did there, he was responsible for it.", "zh": "司獄就把監裏所有的囚犯都交在約瑟的手下；他們在那裏所辦的事都是經他的手。", "ja": "獄屋番は獄屋におるすべての囚人をヨセフの手にゆだねたので、彼はそこでするすべての事をおこなった。"}, "23": {"en": "The keeper of the prison didn’t look after anything that was under his hand, because the LORD was with him; and that which he did, the LORD made it prosper.", "zh": "凡在約瑟手下的事，司獄一概不察，因為耶和華與約瑟同在；耶和華使他所做的盡都順利。", "ja": "獄屋番は彼の手にゆだねた事はいっさい顧みなかった。主がヨセフと共におられたからである。主は彼のなす事を栄えさせられた。"}}}, "40": {"verses": {"1": {"en": "After these things, the butler of the king of Egypt and his baker offended their lord, the king of Egypt.", "zh": "這事以後，埃及王的酒政和膳長得罪了他們的主－埃及王，", "ja": "これらの事の後、エジプト王の給仕役と料理役とがその主君エジプト王に罪を犯した。"}, "2": {"en": "Pharaoh was angry with his two officers, the chief cup bearer and the chief baker.", "zh": "法老就惱怒酒政和膳長這二臣，", "ja": "パロはふたりの役人、すなわち給仕役の長と料理役の長に向かって憤り、"}, "3": {"en": "He put them in custody in the house of the captain of the guard, into the prison, the place where Joseph was bound.", "zh": "把他們下在護衛長府內的監裏，就是約瑟被囚的地方。", "ja": "侍衛長の家の監禁所、すなわちヨセフがつながれている獄屋に入れた。"}, "4": {"en": "The captain of the guard assigned them to Joseph, and he took care of them. They stayed in prison many days.", "zh": "護衛長把他們交給約瑟，約瑟便伺候他們；他們有些日子在監裏。", "ja": "侍衛長はヨセフに命じて彼らと共におらせたので、ヨセフは彼らに仕えた。こうして彼らは監禁所で幾日かを過ごした。"}, "5": {"en": "They both dreamed a dream, each man his dream, in one night, each man according to the interpretation of his dream, the cup bearer and the baker of the king of Egypt, who were bound in the prison.", "zh": "被囚在監之埃及王的酒政和膳長二人同夜各做一夢，各夢都有講解。", "ja": "さて獄屋につながれたエジプト王の給仕役と料理役のふたりは一夜のうちにそれぞれ意味のある夢を見た。"}, "6": {"en": "Joseph came in to them in the morning, and saw them, and saw that they were sad.", "zh": "到了早晨，約瑟進到他們那裏，見他們有愁悶的樣子。", "ja": "ヨセフが朝、彼らのところへ行って見ると、彼らは悲しみに沈んでいた。"}, "7": {"en": "He asked Pharaoh’s officers who were with him in custody in his master’s house, saying, “Why do you look so sad today?”", "zh": "他便問法老的二臣，就是與他同囚在他主人府裏的，說：「你們今日為甚麼面帶愁容呢？」", "ja": "そこでヨセフは自分と一緒に主人の家の監禁所にいるパロの役人たちに尋ねて言った、「どうして、きょう、あなたがたの顔色が悪いのですか」。"}, "8": {"en": "They said to him, “We have dreamed a dream, and there is no one who can interpret it.” Joseph said to them, “Don’t interpretations belong to God? Please tell it to me.”", "zh": "他們對他說：「我們各人做了一夢，沒有人能解。」約瑟說：「解夢不是出於上帝嗎？請你們將夢告訴我。」", "ja": "彼らは言った、「わたしたちは夢を見ましたが、解いてくれる者がいません」。ヨセフは彼らに言った、「解くことは神によるのではありませんか。どうぞ、わたしに話してください」。"}, "9": {"en": "The chief cup bearer told his dream to Joseph, and said to him, “In my dream, behold, a vine was in front of me,", "zh": "酒政便將他的夢告訴約瑟說：「我夢見在我面前有一棵葡萄樹，", "ja": "給仕役の長はその夢をヨセフに話して言った、「わたしが見た夢で、わたしの前に一本のぶどうの木がありました。"}, "10": {"en": "and in the vine were three branches. It was as though it budded, it blossomed, and its clusters produced ripe grapes.", "zh": "樹上有三根枝子，好像發了芽，開了花，上頭的葡萄都成熟了。", "ja": "そのぶどうの木に三つの枝があって、芽を出し、花が咲き、ぶどうのふさが熟しました。"}, "11": {"en": "Pharaoh’s cup was in my hand; and I took the grapes, and pressed them into Pharaoh’s cup, and I gave the cup into Pharaoh’s hand.”", "zh": "法老的杯在我手中，我就拿葡萄擠在法老的杯裏，將杯遞在他手中。」", "ja": "時にわたしの手に、パロの杯があって、わたしはそのぶどうを取り、それをパロの杯にしぼり、その杯をパロの手にささげました」。"}, "12": {"en": "Joseph said to him, “This is its interpretation: the three branches are three days.", "zh": "約瑟對他說：「你所做的夢是這樣解：三根枝子就是三天；", "ja": "ヨセフは言った、「その解き明かしはこうです。三つの枝は三日です。"}, "13": {"en": "Within three more days, Pharaoh will lift up your head, and restore you to your office. You will give Pharaoh’s cup into his hand, the way you did when you were his cup bearer.", "zh": "三天之內，法老必提你出監，叫你官復原職，你仍要遞杯在法老的手中，和先前作他的酒政一樣。", "ja": "今から三日のうちにパロはあなたの頭を上げて、あなたを元の役目に返すでしょう。あなたはさきに給仕役だった時にされたように、パロの手に杯をささげられるでしょう。"}, "14": {"en": "But remember me when it is well with you. Please show kindness to me, and make mention of me to Pharaoh, and bring me out of this house.", "zh": "但你得好處的時候，求你記念我，施恩與我，在法老面前提說我，救我出這監牢。", "ja": "それで、あなたがしあわせになられたら、わたしを覚えていて、どうかわたしに恵みを施し、わたしの事をパロに話して、この家からわたしを出してください。"}, "15": {"en": "For indeed, I was stolen away out of the land of the Hebrews, and here also I have done nothing that they should put me into the dungeon.”", "zh": "我實在是從希伯來人之地被拐來的；我在這裏也沒有做過甚麼，叫他們把我下在監裏。」", "ja": "わたしは、実はヘブルびとの地からさらわれてきた者です。またここでもわたしは地下の獄屋に入れられるような事はしなかったのです」。"}, "16": {"en": "When the chief baker saw that the interpretation was good, he said to Joseph, “I also was in my dream, and behold, three baskets of white bread were on my head.", "zh": "膳長見夢解得好，就對約瑟說：「我在夢中見我頭上頂着三筐白餅；", "ja": "料理役の長はその解き明かしの良かったのを見て、ヨセフに言った、「わたしも夢を見たが、白いパンのかごが三つ、わたしの頭の上にあった。"}, "17": {"en": "In the uppermost basket there were all kinds of baked food for Pharaoh, and the birds ate them out of the basket on my head.”", "zh": "極上的筐子裏有為法老烤的各樣食物，有飛鳥來吃我頭上筐子裏的食物。」", "ja": "一番上のかごには料理役がパロのために作ったさまざまの食物があったが、鳥がわたしの頭の上のかごからそれを食べていた」。"}, "18": {"en": "Joseph answered, “This is its interpretation. The three baskets are three days.", "zh": "約瑟說：「你的夢是這樣解：三個筐子就是三天；", "ja": "ヨセフは答えて言った、「その解き明かしはこうです。三つのかごは三日です。"}, "19": {"en": "Within three more days, Pharaoh will lift up your head from off you, and will hang you on a tree; and the birds will eat your flesh from off you.”", "zh": "三天之內，法老必斬斷你的頭，把你掛在木頭上，必有飛鳥來吃你身上的肉。」", "ja": "今から三日のうちにパロはあなたの頭を上げ離して、あなたを木に掛けるでしょう。そして鳥があなたの肉を食い取るでしょう」。"}, "20": {"en": "On the third day, which was Pharaoh’s birthday, he made a feast for all his servants, and he lifted up the head of the chief cup bearer and the head of the chief baker among his servants.", "zh": "到了第三天，是法老的生日，他為眾臣僕設擺筵席，把酒政和膳長提出監來，", "ja": "さて三日目はパロの誕生日であったので、パロはすべての家来のためにふるまいを設け、家来のうちの給仕役の長の頭と、料理役の長の頭を上げた。"}, "21": {"en": "He restored the chief cup bearer to his position again, and he gave the cup into Pharaoh’s hand;", "zh": "使酒政官復原職，他仍舊遞杯在法老手中；", "ja": "すなわちパロは給仕役の長を給仕役の職に返したので、彼はパロの手に杯をささげた。"}, "22": {"en": "but he hanged the chief baker, as Joseph had interpreted to them.", "zh": "但把膳長掛起來，正如約瑟向他們所解的話。", "ja": "しかしパロは料理役の長を木に掛けた。ヨセフが彼らに解き明かしたとおりである。"}, "23": {"en": "Yet the chief cup bearer didn’t remember Joseph, but forgot him.", "zh": "酒政卻不記念約瑟，竟忘了他。", "ja": "ところが、給仕役の長はヨセフを思い出さず、忘れてしまった。"}}}, "41": {"verses": {"1": {"en": "At the end of two full years, Pharaoh dreamed, and behold, he stood by the river.", "zh": "過了兩年，法老做夢，夢見自己站在河邊，", "ja": "二年の後パロは夢を見た。夢に、彼はナイル川のほとりに立っていた。"}, "2": {"en": "Behold, seven cattle came up out of the river. They were sleek and fat, and they fed in the marsh grass.", "zh": "有七隻母牛從河裏上來，又美好又肥壯，在蘆荻中吃草。", "ja": "すると、その川から美しい、肥え太った七頭の雌牛が上がってきて葦を食っていた。"}, "3": {"en": "Behold, seven other cattle came up after them out of the river, ugly and thin, and stood by the other cattle on the brink of the river.", "zh": "隨後又有七隻母牛從河裏上來，又醜陋又乾瘦，與那七隻母牛一同站在河邊。", "ja": "その後、また醜い、やせ細った他の七頭の雌牛が川から上がってきて、川の岸にいた雌牛のそばに立ち、"}, "4": {"en": "The ugly and thin cattle ate up the seven sleek and fat cattle. So Pharaoh awoke.", "zh": "這又醜陋又乾瘦的七隻母牛吃盡了那又美好又肥壯的七隻母牛。法老就醒了。", "ja": "その醜い、やせ細った雌牛が、あの美しい、肥えた七頭の雌牛を食いつくした。ここでパロは目が覚めた。"}, "5": {"en": "He slept and dreamed a second time; and behold, seven heads of grain came up on one stalk, healthy and good.", "zh": "他又睡着，第二回做夢，夢見一棵麥子長了七個穗子，又肥大又佳美，", "ja": "彼はまた眠って、再び夢を見た。夢に、一本の茎に太った良い七つの穂が出てきた。"}, "6": {"en": "Behold, seven heads of grain, thin and blasted with the east wind, sprung up after them.", "zh": "隨後又長了七個穗子，又細弱又被東風吹焦了。", "ja": "その後また、やせて、東風に焼けた七つの穂が出てきて、"}, "7": {"en": "The thin heads of grain swallowed up the seven healthy and full ears. Pharaoh awoke, and behold, it was a dream.", "zh": "這細弱的穗子吞了那七個又肥大又飽滿的穗子。法老醒了，不料是個夢。", "ja": "そのやせた穂が、あの太って実った七つの穂をのみつくした。ここでパロは目が覚めたが、それは夢であった。"}, "8": {"en": "In the morning, his spirit was troubled, and he sent and called for all of Egypt’s magicians and wise men. Pharaoh told them his dreams, but there was no one who could interpret them to Pharaoh.", "zh": "到了早晨，法老心裏不安，就差人召了埃及所有的術士和博士來；法老就把所做的夢告訴他們，卻沒有人能給法老圓解。", "ja": "朝になって、パロは心が騒ぎ、人をつかわして、エジプトのすべての魔術師とすべての知者とを呼び寄せ、彼らに夢を告げたが、これをパロに解き明かしうる者がなかった。"}, "9": {"en": "Then the chief cup bearer spoke to Pharaoh, saying, “I remember my faults today.", "zh": "那時酒政對法老說：「我今日想起我的罪來。", "ja": "そのとき給仕役の長はパロに告げて言った、「わたしはきょう、自分のあやまちを思い出しました。"}, "10": {"en": "Pharaoh was angry with his servants, and put me in custody in the house of the captain of the guard, with the chief baker.", "zh": "從前法老惱怒臣僕，把我和膳長下在護衛長府內的監裏。", "ja": "かつてパロがしもべらに向かって憤り、わたしと料理役の長とを侍衛長の家の監禁所にお入れになった時、"}, "11": {"en": "We dreamed a dream in one night, he and I. Each man dreamed according to the interpretation of his dream.", "zh": "我們二人同夜各做一夢，各夢都有講解。", "ja": "わたしも彼も一夜のうちに夢を見、それぞれ意味のある夢を見ましたが、"}, "12": {"en": "There was with us there a young man, a Hebrew, servant to the captain of the guard, and we told him, and he interpreted to us our dreams. He interpreted to each man according to his dream.", "zh": "在那裏同着我們有一個希伯來的少年人，是護衛長的僕人，我們告訴他，他就把我們的夢圓解，是按着各人的夢圓解的。", "ja": "そこに侍衛長のしもべで、ひとりの若いヘブルびとがわれわれと共にいたので、彼に話したところ、彼はわれわれの夢を解き明かし、その夢によって、それぞれ解き明かしをしました。"}, "13": {"en": "As he interpreted to us, so it was. He restored me to my office, and he hanged him.”", "zh": "後來正如他給我們圓解的成就了：我官復原職，膳長被掛起來了。」", "ja": "そして彼が解き明かしたとおりになって、パロはわたしを職に返し、彼を木に掛けられました」。"}, "14": {"en": "Then Pharaoh sent and called Joseph, and they brought him hastily out of the dungeon. He shaved himself, changed his clothing, and came in to Pharaoh.", "zh": "法老遂即差人去召約瑟，他們便急忙帶他出監，他就剃頭，刮臉，換衣裳，進到法老面前。", "ja": "そこでパロは人をつかわしてヨセフを呼んだ。人々は急いで彼を地下の獄屋から出した。ヨセフは、ひげをそり、着物を着替えてパロのもとに行った。"}, "15": {"en": "Pharaoh said to Joseph, “I have dreamed a dream, and there is no one who can interpret it. I have heard it said of you, that when you hear a dream you can interpret it.”", "zh": "法老對約瑟說：「我做了一夢，沒有人能解；我聽見人說，你聽了夢就能解。」", "ja": "パロはヨセフに言った、「わたしは夢を見たが、これを解き明かす者がない。聞くところによると、あなたは夢を聞いて、解き明かしができるそうだ」。"}, "16": {"en": "Joseph answered Pharaoh, saying, “It isn’t in me. God will give Pharaoh an answer of peace.”", "zh": "約瑟回答法老說：「這不在乎我，上帝必將平安的話回答法老。」", "ja": "ヨセフはパロに答えて言った、「いいえ、わたしではありません。神がパロに平安をお告げになりましょう」。"}, "17": {"en": "Pharaoh spoke to Joseph, “In my dream, behold, I stood on the brink of the river;", "zh": "法老對約瑟說：「我夢見我站在河邊，", "ja": "パロはヨセフに言った、「夢にわたしは川の岸に立っていた。"}, "18": {"en": "and behold, seven fat and sleek cattle came up out of the river. They fed in the marsh grass;", "zh": "有七隻母牛從河裏上來，又肥壯又美好，在蘆荻中吃草。", "ja": "その川から肥え太った、美しい七頭の雌牛が上がってきて葦を食っていた。"}, "19": {"en": "and behold, seven other cattle came up after them, poor and very ugly and thin, such as I never saw in all the land of Egypt for ugliness.", "zh": "隨後又有七隻母牛上來，又軟弱又醜陋又乾瘦，在埃及遍地，我沒有見過這樣不好的。", "ja": "その後、弱く、非常に醜い、やせ細った他の七頭の雌牛がまた上がってきた。わたしはエジプト全国で、このような醜いものをまだ見たことがない。"}, "20": {"en": "The thin and ugly cattle ate up the first seven fat cattle;", "zh": "這又乾瘦又醜陋的母牛吃盡了那以先的七隻肥母牛，", "ja": "ところがそのやせた醜い雌牛が、初めの七頭の肥えた雌牛を食いつくしたが、"}, "21": {"en": "and when they had eaten them up, it couldn’t be known that they had eaten them, but they were still ugly, as at the beginning. So I awoke.", "zh": "吃了以後卻看不出是吃了，那醜陋的樣子仍舊和先前一樣。我就醒了。", "ja": "腹にはいっても、腹にはいった事が知れず、やはり初めのように醜かった。ここでわたしは目が覚めた。"}, "22": {"en": "I saw in my dream, and behold, seven heads of grain came up on one stalk, full and good;", "zh": "我又夢見一棵麥子，長了七個穗子，又飽滿又佳美，", "ja": "わたしはまた夢をみた。一本の茎に七つの実った良い穂が出てきた。"}, "23": {"en": "and behold, seven heads of grain, withered, thin, and blasted with the east wind, sprung up after them.", "zh": "隨後又長了七個穗子，枯槁細弱，被東風吹焦了。", "ja": "その後、やせ衰えて、東風に焼けた七つの穂が出てきたが、"}, "24": {"en": "The thin heads of grain swallowed up the seven good heads of grain. I told it to the magicians, but there was no one who could explain it to me.”", "zh": "這些細弱的穗子吞了那七個佳美的穗子。我將這夢告訴了術士，卻沒有人能給我解說。」", "ja": "そのやせた穂が、あの七つの良い穂をのみつくした。わたしは魔術師に話したが、わたしにそのわけを示しうる者はなかった」。"}, "25": {"en": "Joseph said to Pharaoh, “The dream of Pharaoh is one. What God is about to do he has declared to Pharaoh.", "zh": "約瑟對法老說：「法老的夢乃是一個。上帝已將所要做的事指示法老了。", "ja": "ヨセフはパロに言った、「パロの夢は一つです。神がこれからしようとすることをパロに示されたのです。"}, "26": {"en": "The seven good cattle are seven years; and the seven good heads of grain are seven years. The dream is one.", "zh": "七隻好母牛是七年，七個好穗子也是七年；這夢乃是一個。", "ja": "七頭の良い雌牛は七年です。七つの良い穂も七年で、夢は一つです。"}, "27": {"en": "The seven thin and ugly cattle that came up after them are seven years, and also the seven empty heads of grain blasted with the east wind; they will be seven years of famine.", "zh": "那隨後上來的七隻又乾瘦又醜陋的母牛是七年，那七個虛空、被東風吹焦的穗子也是七年，都是七個荒年。", "ja": "あとに続いて、上がってきた七頭のやせた醜い雌牛は七年で、東風に焼けた実の入らない七つの穂は七年のききんです。"}, "28": {"en": "That is the thing which I have spoken to Pharaoh. God has shown Pharaoh what he is about to do.", "zh": "這就是我對法老所說，上帝已將所要做的事顯明給法老了。", "ja": "わたしがパロに申し上げたように、神がこれからしようとすることをパロに示されたのです。"}, "29": {"en": "Behold, seven years of great plenty throughout all the land of Egypt are coming.", "zh": "埃及遍地必來七個大豐年，", "ja": "エジプト全国に七年の大豊作があり、"}, "30": {"en": "Seven years of famine will arise after them, and all the plenty will be forgotten in the land of Egypt. The famine will consume the land,", "zh": "隨後又要來七個荒年，甚至在埃及地都忘了先前的豐收，全地必被饑荒所滅。", "ja": "その後七年のききんが起り、その豊作はみなエジプトの国で忘れられて、そのききんは国を滅ぼすでしょう。"}, "31": {"en": "and the plenty will not be known in the land by reason of that famine which follows; for it will be very grievous.", "zh": "因那以後的饑荒甚大，便不覺得先前的豐收了。", "ja": "後に来るそのききんが、非常に激しいから、その豊作は国のうちで記憶されなくなるでしょう。"}, "32": {"en": "The dream was doubled to Pharaoh, because the thing is established by God, and God will shortly bring it to pass.", "zh": "至於法老兩回做夢，是因上帝命定這事，而且必速速成就。", "ja": "パロが二度重ねて夢を見られたのは、この事が神によって定められ、神がすみやかにこれをされるからです。"}, "33": {"en": "“Now therefore let Pharaoh look for a discreet and wise man, and set him over the land of Egypt.", "zh": "所以，法老當揀選一個有聰明有智慧的人，派他治理埃及地。", "ja": "それゆえパロは今、さとく、かつ賢い人を尋ね出してエジプトの国を治めさせなさい。"}, "34": {"en": "Let Pharaoh do this, and let him appoint overseers over the land, and take up the fifth part of the land of Egypt’s produce in the seven plenteous years.", "zh": "法老當這樣行，又派官員管理這地。當七個豐年的時候，征收埃及地的五分之一，", "ja": "パロはこうして国中に監督を置き、その七年の豊作のうちに、エジプトの国の産物の五分の一を取り、"}, "35": {"en": "Let them gather all the food of these good years that come, and store grain under the hand of Pharaoh for food in the cities, and let them keep it.", "zh": "叫他們把將來豐年一切的糧食聚斂起來，積蓄五穀，收存在各城裏做食物，歸於法老的手下。", "ja": "続いて来る良い年々のすべての食糧を彼らに集めさせ、穀物を食糧として、パロの手で町々にたくわえ守らせなさい。"}, "36": {"en": "The food will be to supply the land against the seven years of famine, which will be in the land of Egypt; so that the land will not perish through the famine.”", "zh": "所積蓄的糧食可以防備埃及地將來的七個荒年，免得這地被饑荒所滅。」", "ja": "こうすれば食糧は、エジプトの国に臨む七年のききんに備えて、この国のためにたくわえとなり、この国はききんによって滅びることがないでしょう」。"}, "37": {"en": "The thing was good in the eyes of Pharaoh, and in the eyes of all his servants.", "zh": "法老和他一切臣僕都以這事為妙。", "ja": "この事はパロとそのすべての家来たちの目にかなった。"}, "38": {"en": "Pharaoh said to his servants, “Can we find such a one as this, a man in whom is the Spirit of God?”", "zh": "法老對臣僕說：「像這樣的人，有上帝的靈在他裏頭，我們豈能找得着呢？」", "ja": "そこでパロは家来たちに言った、「われわれは神の霊をもつこのような人を、ほかに見いだし得ようか」。"}, "39": {"en": "Pharaoh said to Joseph, “Because God has shown you all of this, there is no one so discreet and wise as you.", "zh": "法老對約瑟說：「上帝既將這事都指示你，可見沒有人像你這樣有聰明有智慧。", "ja": "またパロはヨセフに言った、「神がこれを皆あなたに示された。あなたのようにさとく賢い者はない。"}, "40": {"en": "You shall be over my house. All my people will be ruled according to your word. Only in the throne I will be greater than you.”", "zh": "你可以掌管我的家；我的民都必聽從你的話。惟獨在寶座上我比你大。」", "ja": "あなたはわたしの家を治めてください。わたしの民はみなあなたの言葉に従うでしょう。わたしはただ王の位でだけあなたにまさる」。"}, "41": {"en": "Pharaoh said to Joseph, “Behold, I have set you over all the land of Egypt.”", "zh": "法老又對約瑟說：「我派你治理埃及全地。」", "ja": "パロは更にヨセフに言った、「わたしはあなたをエジプト全国のつかさとする」。"}, "42": {"en": "Pharaoh took off his signet ring from his hand, and put it on Joseph’s hand, and arrayed him in robes of fine linen, and put a gold chain about his neck.", "zh": "法老就摘下手上打印的戒指，戴在約瑟的手上，給他穿上細麻衣，把金鍊戴在他的頸項上，", "ja": "そしてパロは指輪を手からはずして、ヨセフの手にはめ、亜麻布の衣服を着せ、金の鎖をくびにかけ、"}, "43": {"en": "He made him ride in the second chariot which he had. They cried before him, “Bow the knee!” He set him over all the land of Egypt.", "zh": "又叫約瑟坐他的副車，喝道的在前呼叫說：「跪下。」這樣，法老派他治理埃及全地。", "ja": "自分の第二の車に彼を乗せ、「ひざまずけ」とその前に呼ばわらせ、こうして彼をエジプト全国のつかさとした。"}, "44": {"en": "Pharaoh said to Joseph, “I am Pharaoh. Without you, no man shall lift up his hand or his foot in all the land of Egypt.”", "zh": "法老對約瑟說：「我是法老，在埃及全地，若沒有你的命令，不許人擅自辦事。」", "ja": "ついでパロはヨセフに言った、「わたしはパロである。あなたの許しがなければエジプト全国で、だれも手足を上げることはできない」。"}, "45": {"en": "Pharaoh called Joseph’s name Zaphenath-Paneah. He gave him Asenath, the daughter of Potiphera priest of On as a wife. Joseph went out over the land of Egypt.", "zh": "法老賜名給約瑟，叫撒發那忒‧巴內亞，又將安城的祭司波提非拉的女兒亞西納給他為妻。約瑟就出去巡行埃及地。", "ja": "パロはヨセフの名をザフナテ・パネアと呼び、オンの祭司ポテペラの娘アセナテを妻として彼に与えた。ヨセフはエジプトの国を巡った。"}, "46": {"en": "Joseph was thirty years old when he stood before Pharaoh king of Egypt. Joseph went out from the presence of Pharaoh, and went throughout all the land of Egypt.", "zh": "約瑟見埃及王法老的時候年三十歲。他從法老面前出去，遍行埃及全地。", "ja": "ヨセフがエジプトの王パロの前に立った時は三十歳であった。ヨセフはパロの前を出て、エジプト全国をあまねく巡った。"}, "47": {"en": "In the seven plenteous years the earth produced abundantly.", "zh": "七個豐年之內，地的出產極豐極盛，", "ja": "さて七年の豊作のうちに地は豊かに物を産した。"}, "48": {"en": "He gathered up all the food of the seven years which were in the land of Egypt, and laid up the food in the cities. He stored food in each city from the fields around that city.", "zh": "約瑟聚斂埃及地七個豐年一切的糧食，把糧食積存在各城裏；各城周圍田地的糧食都積存在本城裏。", "ja": "そこでヨセフはエジプトの国にできたその七年間の食糧をことごとく集め、その食糧を町々に納めさせた。すなわち町の周囲にある畑の食糧をその町の中に納めさせた。"}, "49": {"en": "Joseph laid up grain as the sand of the sea, very much, until he stopped counting, for it was without number.", "zh": "約瑟積蓄五穀甚多，如同海邊的沙，無法計算，因為穀不可勝數。", "ja": "ヨセフは穀物を海の砂のように、非常に多くたくわえ、量りきれなくなったので、ついに量ることをやめた。"}, "50": {"en": "To Joseph were born two sons before the year of famine came, whom Asenath, the daughter of Potiphera priest of On, bore to him.", "zh": "荒年未到以前，安城的祭司波提非拉的女兒亞西納給約瑟生了兩個兒子。", "ja": "ききんの年の来る前にヨセフにふたりの子が生れた。これらはオンの祭司ポテペラの娘アセナテが産んだのである。"}, "51": {"en": "Joseph called the name of the firstborn Manasseh, “For”, he said, “God has made me forget all my toil, and all my father’s house.”", "zh": "約瑟給長子起名叫瑪拿西，因為他說：「上帝使我忘了一切的困苦和我父的全家。」", "ja": "ヨセフは長子の名をマナセと名づけて言った、「神がわたしにすべての苦難と父の家のすべての事を忘れさせられた」。"}, "52": {"en": "The name of the second, he called Ephraim: “For God has made me fruitful in the land of my affliction.”", "zh": "他給次子起名叫以法蓮，因為他說：「上帝使我在受苦的地方昌盛。」", "ja": "また次の子の名をエフライムと名づけて言った、「神がわたしを悩みの地で豊かにせられた」。"}, "53": {"en": "The seven years of plenty, that were in the land of Egypt, came to an end.", "zh": "埃及地的七個豐年一完，", "ja": "エジプトの国にあった七年の豊作が終り、"}, "54": {"en": "The seven years of famine began to come, just as Joseph had said. There was famine in all lands, but in all the land of Egypt there was bread.", "zh": "七個荒年就來了。正如約瑟所說的，各地都有饑荒；惟獨埃及全地有糧食。", "ja": "ヨセフの言ったように七年のききんが始まった。そのききんはすべての国にあったが、エジプト全国には食物があった。"}, "55": {"en": "When all the land of Egypt was famished, the people cried to Pharaoh for bread, and Pharaoh said to all the Egyptians, “Go to Joseph. What he says to you, do.”", "zh": "及至埃及全地有了饑荒，眾民向法老哀求糧食，法老對他們說：「你們往約瑟那裏去，凡他所說的，你們都要做。」", "ja": "やがてエジプト全国が飢えた時、民はパロに食物を叫び求めた。そこでパロはすべてのエジプトびとに言った、「ヨセフのもとに行き、彼の言うようにせよ」。"}, "56": {"en": "The famine was over all the surface of the earth. Joseph opened all the store houses, and sold to the Egyptians. The famine was severe in the land of Egypt.", "zh": "當時饑荒遍滿天下，約瑟開了各處的倉，糶糧給埃及人；在埃及地饑荒甚大。", "ja": "ききんが地の全面にあったので、ヨセフはすべての穀倉を開いて、エジプトびとに売った。ききんはますますエジプトの国に激しくなった。"}, "57": {"en": "All countries came into Egypt, to Joseph, to buy grain, because the famine was severe in all the earth.", "zh": "各地的人都往埃及去，到約瑟那裏糴糧，因為天下的饑荒甚大。", "ja": "ききんが全地に激しくなったので、諸国の人々がエジプトのヨセフのもとに穀物を買うためにきた。"}}}, "42": {"verses": {"1": {"en": "Now Jacob saw that there was grain in Egypt, and Jacob said to his sons, “Why do you look at one another?”", "zh": "雅各見埃及有糧，就對兒子們說：「你們為甚麼彼此觀望呢？", "ja": "ヤコブはエジプトに穀物があると知って、むすこたちに言った、「あなたがたはなぜ顔を見合わせているのですか」。"}, "2": {"en": "He said, “Behold, I have heard that there is grain in Egypt. Go down there, and buy for us from there, so that we may live, and not die.”", "zh": "我聽見埃及有糧，你們可以下去，從那裏為我們糴些來，使我們可以存活，不至於死。」", "ja": "また言った、「エジプトに穀物があるということだが、あなたがたはそこへ下って行って、そこから、われわれのため穀物を買ってきなさい。そうすれば、われわれは生きながらえて、死を免れるであろう」。"}, "3": {"en": "Joseph’s ten brothers went down to buy grain from Egypt.", "zh": "於是，約瑟的十個哥哥都下埃及糴糧去了。", "ja": "そこでヨセフの十人の兄弟は穀物を買うためにエジプトへ下った。"}, "4": {"en": "But Jacob didn’t send Benjamin, Joseph’s brother, with his brothers; for he said, “Lest perhaps harm happen to him.”", "zh": "但約瑟的兄弟便雅憫，雅各沒有打發他和哥哥們同去，因為雅各說：「恐怕他遭害。」", "ja": "しかし、ヤコブはヨセフの弟ベニヤミンを兄弟たちと一緒にやらなかった。彼が災に会うのを恐れたからである。"}, "5": {"en": "The sons of Israel came to buy among those who came, for the famine was in the land of Canaan.", "zh": "來糴糧的人中有以色列的兒子們，因為迦南地也有饑荒。", "ja": "こうしてイスラエルの子らは穀物を買おうと人々に交じってやってきた。カナンの地にききんがあったからである。"}, "6": {"en": "Joseph was the governor over the land. It was he who sold to all the people of the land. Joseph’s brothers came, and bowed themselves down to him with their faces to the earth.", "zh": "當時治理埃及地的是約瑟；糶糧給那地眾民的就是他。約瑟的哥哥們來了，臉伏於地，向他下拜。", "ja": "ときにヨセフは国のつかさであって、国のすべての民に穀物を売ることをしていた。ヨセフの兄弟たちはきて、地にひれ伏し、彼を拝した。"}, "7": {"en": "Joseph saw his brothers, and he recognized them, but acted like a stranger to them, and spoke roughly with them. He said to them, “Where did you come from?” They said, “From the land of Canaan, to buy food.”", "zh": "約瑟看見他哥哥們，就認得他們，卻裝作生人，向他們說些嚴厲話，問他們說：「你們從哪裏來？」他們說：「我們從迦南地來糴糧。」", "ja": "ヨセフは兄弟たちを見て、それと知ったが、彼らに向かっては知らぬ者のようにし、荒々しく語った。すなわち彼らに言った、「あなたがたはどこからきたのか」。彼らは答えた、「食糧を買うためにカナンの地からきました」。"}, "8": {"en": "Joseph recognized his brothers, but they didn’t recognize him.", "zh": "約瑟認得他哥哥們，他們卻不認得他。", "ja": "ヨセフは、兄弟たちであるのを知っていたが、彼らはヨセフとは知らなかった。"}, "9": {"en": "Joseph remembered the dreams which he dreamed about them, and said to them, “You are spies! You have come to see the nakedness of the land.”", "zh": "約瑟想起從前所做的那兩個夢，就對他們說：「你們是奸細，來窺探這地的虛實。」", "ja": "ヨセフはかつて彼らについて見た夢を思い出して、彼らに言った、「あなたがたは回し者で、この国のすきをうかがうためにきたのです」。"}, "10": {"en": "They said to him, “No, my lord, but your servants have come to buy food.", "zh": "他們對他說：「我主啊，不是的。僕人們是糴糧來的。", "ja": "彼らはヨセフに答えた、「いいえ、わが主よ、しもべらはただ食糧を買うためにきたのです。"}, "11": {"en": "We are all one man’s sons; we are honest men. Your servants are not spies.”", "zh": "我們都是一個人的兒子，是誠實人；僕人們並不是奸細。」", "ja": "われわれは皆、ひとりの人の子で、真実な者です。しもべらは回し者ではありません」。"}, "12": {"en": "He said to them, “No, but you have come to see the nakedness of the land!”", "zh": "約瑟說：「不然，你們必是窺探這地的虛實來的。」", "ja": "ヨセフは彼らに言った、「いや、あなたがたはこの国のすきをうかがうためにきたのです」。"}, "13": {"en": "They said, “We, your servants, are twelve brothers, the sons of one man in the land of Canaan; and behold, the youngest is today with our father, and one is no more.”", "zh": "他們說：「僕人們本是弟兄十二人，是迦南地一個人的兒子，頂小的現今在我們的父親那裏，有一個沒有了。」", "ja": "彼らは言った、「しもべらは十二人兄弟で、カナンの地にいるひとりの人の子です。末の弟は今、父と一緒にいますが、他のひとりはいなくなりました」。"}, "14": {"en": "Joseph said to them, “It is like I told you, saying, ‘You are spies!’", "zh": "約瑟說：「我才說你們是奸細，這話實在不錯。", "ja": "ヨセフは彼らに言った、「わたしが言ったとおり、あなたがたは回し者です。"}, "15": {"en": "By this you shall be tested. By the life of Pharaoh, you shall not go out from here, unless your youngest brother comes here.", "zh": "我指着法老的性命起誓，若是你們的小兄弟不到這裏來，你們就不得出這地方，從此就可以把你們證驗出來了。", "ja": "あなたがたをこうしてためしてみよう。パロのいのちにかけて誓います。末の弟がここにこなければ、あなたがたはここを出ることはできません。"}, "16": {"en": "Send one of you, and let him get your brother, and you shall be bound, that your words may be tested, whether there is truth in you, or else by the life of Pharaoh surely you are spies.”", "zh": "須要打發你們中間一個人去，把你們的兄弟帶來。至於你們，都要囚在這裏，好證驗你們的話真不真，若不真，我指着法老的性命起誓，你們一定是奸細。」", "ja": "あなたがたのひとりをやって弟を連れてこさせなさい。それまであなたがたをつないでおいて、あなたがたに誠実があるかどうか、あなたがたの言葉をためしてみよう。パロのいのちにかけて誓います。あなたがたは確かに回し者です」。"}, "17": {"en": "He put them all together into custody for three days.", "zh": "於是約瑟把他們都下在監裏三天。", "ja": "ヨセフは彼らをみな一緒に三日の間、監禁所に入れた。"}, "18": {"en": "Joseph said to them the third day, “Do this, and live, for I fear God.", "zh": "到第三天，約瑟對他們說：「我是敬畏上帝的；你們照我的話行就可以存活。", "ja": "三日目にヨセフは彼らに言った、「こうすればあなたがたは助かるでしょう。わたしは神を恐れます。"}, "19": {"en": "If you are honest men, then let one of your brothers be bound in your prison; but you go, carry grain for the famine of your houses.", "zh": "你們如果是誠實人，可以留你們中間的一個人囚在監裏，但你們可以帶着糧食回去，救你們家裏的饑荒。", "ja": "もしあなたがたが真実な者なら、兄弟のひとりをあなたがたのいる監禁所に残し、あなたがたは穀物を携えて行って、家族の飢えを救いなさい。"}, "20": {"en": "Bring your youngest brother to me; so will your words be verified, and you won’t die.”", "zh": "把你們的小兄弟帶到我這裏來，如此，你們的話便有證據，你們也不至於死。」他們就照樣而行。", "ja": "そして末の弟をわたしのもとに連れてきなさい。そうすればあなたがたの言葉のほんとうであることがわかって、死を免れるでしょう」。彼らはそのようにした。"}, "21": {"en": "They did so.   They said to one another, “We are certainly guilty concerning our brother, in that we saw the distress of his soul, when he begged us, and we wouldn’t listen. Therefore this distress has come upon us.”", "zh": "他們彼此說：「我們在兄弟身上實在有罪。他哀求我們的時候，我們見他心裏的愁苦，卻不肯聽，所以這場苦難臨到我們身上。」", "ja": "彼らは互に言った、「確かにわれわれは弟の事で罪がある。彼がしきりに願った時、その心の苦しみを見ながら、われわれは聞き入れなかった。それでこの苦しみに会うのだ」。"}, "22": {"en": "Reuben answered them, saying, “Didn’t I tell you, saying, ‘Don’t sin against the child,’ and you wouldn’t listen? Therefore also, behold, his blood is required.”", "zh": "呂便說：「我豈不是對你們說過，不可傷害那孩子嗎？只是你們不肯聽，所以流他血的罪向我們追討。」", "ja": "ルベンが彼らに答えて言った、「わたしはあなたがたに、この子供に罪を犯すなと言ったではないか。それにもかかわらず、あなたがたは聞き入れなかった。それで彼の血の報いを受けるのです」。"}, "23": {"en": "They didn’t know that Joseph understood them; for there was an interpreter between them.", "zh": "他們不知道約瑟聽得出來，因為在他們中間用通事傳話。", "ja": "彼らはヨセフが聞きわけているのを知らなかった。相互の間に通訳者がいたからである。"}, "24": {"en": "He turned himself away from them, and wept. Then he returned to them, and spoke to them, and took Simeon from among them, and bound him before their eyes.", "zh": "約瑟轉身退去，哭了一場，又回來對他們說話，就從他們中間挑出西緬來，在他們眼前把他捆綁。", "ja": "ヨセフは彼らを離れて行って泣き、また帰ってきて彼らと語り、そのひとりシメオンを捕えて、彼らの目の前で縛った。"}, "25": {"en": "Then Joseph gave a command to fill their bags with grain, and to restore each man’s money into his sack, and to give them food for the way. So it was done to them.", "zh": "約瑟吩咐人把糧食裝滿他們的器具，把各人的銀子歸還在各人的口袋裏，又給他們路上用的食物，人就照他的話辦了。", "ja": "そしてヨセフは人々に命じて、彼らの袋に穀物を満たし、めいめいの銀を袋に返し、道中の食料を与えさせた。ヨセフはこのように彼らにした。"}, "26": {"en": "They loaded their donkeys with their grain, and departed from there.", "zh": "他們就把糧食馱在驢上，離開那裏去了。", "ja": "彼らは穀物をろばに負わせてそこを去った。"}, "27": {"en": "As one of them opened his sack to give his donkey food in the lodging place, he saw his money. Behold, it was in the mouth of his sack.", "zh": "到了住宿的地方，他們中間有一個人打開口袋，要拿料餵驢，才看見自己的銀子仍在口袋裏，", "ja": "そのひとりが宿で、ろばに飼葉をやるため袋をあけて見ると、袋の口に自分の銀があった。"}, "28": {"en": "He said to his brothers, “My money is restored! Behold, it is in my sack!” Their hearts failed them, and they turned trembling to one another, saying, “What is this that God has done to us?”", "zh": "就對弟兄們說：「我的銀子歸還了，看哪，仍在我口袋裏！」他們就提心吊膽，戰戰兢兢地彼此說：「這是上帝向我們做甚麼呢？」", "ja": "彼は兄弟たちに言った、「わたしの銀は返してある。しかも見よ、それは袋の中にある」。そこで彼らは非常に驚き、互に震えながら言った、「神がわれわれにされたこのことは何事だろう」。"}, "29": {"en": "They came to Jacob their father, to the land of Canaan, and told him all that had happened to them, saying,", "zh": "他們來到迦南地、他們的父親雅各那裏，將所遭遇的事都告訴他，說：", "ja": "こうして彼らはカナンの地にいる父ヤコブのもとに帰り、その身に起った事をことごとく告げて言った、"}, "30": {"en": "“The man, the lord of the land, spoke roughly with us, and took us for spies of the country.", "zh": "「那地的主對我們說嚴厲的話，把我們當作窺探那地的奸細。", "ja": "「あの国の君は、われわれに荒々しく語り、国をうかがう回し者だと言いました。"}, "31": {"en": "We said to him, ‘We are honest men. We are no spies.", "zh": "我們對他說：『我們是誠實人，並不是奸細。", "ja": "われわれは彼に答えました、『われわれは真実な者であって回し者ではない。"}, "32": {"en": "We are twelve brothers, sons of our father; one is no more, and the youngest is today with our father in the land of Canaan.’", "zh": "我們本是弟兄十二人，都是一個父親的兒子，有一個沒有了，頂小的如今同我們的父親在迦南地。』", "ja": "われわれは十二人兄弟で、同じ父の子である。ひとりはいなくなり、末の弟は今父と共にカナンの地にいる』。"}, "33": {"en": "The man, the lord of the land, said to us, ‘By this I will know that you are honest men: leave one of your brothers with me, and take grain for the famine of your houses, and go your way.", "zh": "那地的主對我們說：『若要我知道你們是誠實人，可以留下你們中間的一個人在我這裏，你們可以帶着糧食回去，救你們家裏的饑荒。", "ja": "その国の君であるその人はわれわれに言いました、『わたしはこうしてあなたがたの真実な者であるのを知ろう。あなたがたは兄弟のひとりをわたしのもとに残し、穀物を携えて行って、家族の飢えを救いなさい。"}, "34": {"en": "Bring your youngest brother to me. Then I will know that you are not spies, but that you are honest men. So I will deliver your brother to you, and you shall trade in the land.’ ”", "zh": "把你們的小兄弟帶到我這裏來，我便知道你們不是奸細，乃是誠實人。這樣，我就把你們的弟兄交給你們，你們也可以在這地做買賣。』」", "ja": "そして末の弟をわたしのもとに連れてきなさい。そうすればあなたがたが回し者ではなく、真実な者であるのを知って、あなたがたの兄弟を返し、この国であなたがたに取引させましょう』」。"}, "35": {"en": "As they emptied their sacks, behold, each man’s bundle of money was in his sack. When they and their father saw their bundles of money, they were afraid.", "zh": "後來他們倒口袋，不料，各人的銀包都在口袋裏；他們和父親看見銀包就都害怕。", "ja": "彼らが袋のものを出して見ると、めいめいの金包みが袋の中にあったので、彼らも父も金包みを見て恐れた。"}, "36": {"en": "Jacob, their father, said to them, “You have bereaved me of my children! Joseph is no more, Simeon is no more, and you want to take Benjamin away. All these things are against me.”", "zh": "他們的父親雅各對他們說：「你們使我喪失我的兒子：約瑟沒有了，西緬也沒有了，你們又要將便雅憫帶去；這些事都歸到我身上了。」", "ja": "父ヤコブは彼らに言った、「あなたがたはわたしに子を失わせた。ヨセフはいなくなり、シメオンもいなくなった。今度はベニヤミンをも取り去る。これらはみなわたしの身にふりかかって来るのだ」。"}, "37": {"en": "Reuben spoke to his father, saying, “Kill my two sons, if I don’t bring him to you. Entrust him to my care, and I will bring him to you again.”", "zh": "呂便對他父親說：「我若不帶他回來交給你，你可以殺我的兩個兒子。只管把他交在我手裏，我必帶他回來交給你。」", "ja": "ルベンは父に言った、「もしわたしが彼をあなたのもとに連れて帰らなかったら、わたしのふたりの子を殺してください。ただ彼をわたしの手にまかせてください。わたしはきっと、あなたのもとに彼を連れて帰ります」。"}, "38": {"en": "He said, “My son shall not go down with you; for his brother is dead, and he only is left. If harm happens to him along the way in which you go, then you will bring down my gray hairs with sorrow to Sheol.”", "zh": "雅各說：「我的兒子不可與你們一同下去；他哥哥死了，只剩下他，他若在你們所行的路上遭害，那便是你們使我白髮蒼蒼、悲悲慘慘地下陰間去了。」", "ja": "ヤコブは言った、「わたしの子はあなたがたと共に下って行ってはならない。彼の兄は死に、ただひとり彼が残っているのだから。もしあなたがたの行く道で彼が災に会えば、あなたがたは、しらがのわたしを悲しんで陰府に下らせるであろう」。"}}}, "43": {"verses": {"1": {"en": "The famine was severe in the land.", "zh": "那地的饑荒甚大。", "ja": "ききんはその地に激しかった。"}, "2": {"en": "When they had eaten up the grain which they had brought out of Egypt, their father said to them, “Go again, buy us a little more food.”", "zh": "他們從埃及帶來的糧食吃盡了，他們的父親就對他們說：「你們再去給我糴些糧來。」", "ja": "彼らがエジプトから携えてきた穀物を食い尽した時、父は彼らに言った、「また行って、われわれのために少しの食糧を買ってきなさい」。"}, "3": {"en": "Judah spoke to him, saying, “The man solemnly warned us, saying, ‘You shall not see my face, unless your brother is with you.’", "zh": "猶大對他說：「那人諄諄地告誡我們說：『你們的兄弟若不與你們同來，你們就不得見我的面。』", "ja": "ユダは父に答えて言った、「あの人はわれわれをきびしく戒めて、弟が一緒でなければ、わたしの顔を見てはならないと言いました。"}, "4": {"en": "If you’ll send our brother with us, we’ll go down and buy you food;", "zh": "你若打發我們的兄弟與我們同去，我們就下去給你糴糧；", "ja": "もしあなたが弟をわれわれと一緒にやってくださるなら、われわれは下って行って、あなたのために食糧を買ってきましょう。"}, "5": {"en": "but if you don’t send him, we won’t go down, for the man said to us, ‘You shall not see my face, unless your brother is with you.’ ”", "zh": "你若不打發他去，我們就不下去，因為那人對我們說：『你們的兄弟若不與你們同來，你們就不得見我的面。』」", "ja": "しかし、もし彼をやられないなら、われわれは下って行きません。あの人がわれわれに、弟が一緒でなければわたしの顔を見てはならないと言ったのですから」。"}, "6": {"en": "Israel said, “Why did you treat me so badly, telling the man that you had another brother?”", "zh": "以色列說：「你們為甚麼這樣害我，告訴那人你們還有兄弟呢？」", "ja": "イスラエルは言った、「なぜ、もうひとりの弟があるとあの人に言って、わたしを苦しめるのか」。"}, "7": {"en": "They said, “The man asked directly concerning ourselves, and concerning our relatives, saying, ‘Is your father still alive? Have you another brother?’ We just answered his questions. Is there any way we could know that he would say, ‘Bring your brother down’?”", "zh": "他們回答說：「那人詳細問到我們和我們的親屬，說：『你們的父親還在嗎？你們還有兄弟嗎？』我們就按着他所問的告訴他，焉能知道他要說『必須把你們的兄弟帶下來』呢？」", "ja": "彼らは言った、「あの人がわれわれと一族とのことを問いただして、父はまだ生きているか、もうひとりの弟があるかと言ったので、問われるままに答えましたが、その人が、弟を連れてこいと言おうとは、どうして知ることができたでしょう」。"}, "8": {"en": "Judah said to Israel, his father, “Send the boy with me, and we’ll get up and go, so that we may live, and not die, both we, and you, and also our little ones.", "zh": "猶大又對他父親以色列說：「你打發童子與我同去，我們就起身下去，好叫我們和你，並我們的婦人孩子，都得存活，不至於死。", "ja": "ユダは父イスラエルに言った、「あの子をわたしと一緒にやってくだされば、われわれは立って行きましょう。そしてわれわれもあなたも、われわれの子供らも生きながらえ、死を免れましょう。"}, "9": {"en": "I’ll be collateral for him. From my hand will you require him. If I don’t bring him to you, and set him before you, then let me bear the blame forever;", "zh": "我為他作保；你可以從我手中追討，我若不帶他回來交在你面前，我情願永遠擔罪。", "ja": "わたしが彼の身を請け合います。わたしの手から彼を求めなさい。もしわたしが彼をあなたのもとに連れ帰って、あなたの前に置かなかったら、わたしはあなたに対して永久に罪を負いましょう。"}, "10": {"en": "for if we hadn’t delayed, surely we would have returned a second time by now.”", "zh": "我們若沒有耽擱，如今第二次都回來了。」", "ja": "もしわれわれがこんなにためらわなかったら、今ごろは二度も行ってきたでしょう」。"}, "11": {"en": "Their father, Israel, said to them, “If it must be so, then do this: Take from the choice fruits of the land in your bags, and carry down a present for the man, a little balm, a little honey, spices and myrrh, nuts, and almonds;", "zh": "他們的父親以色列說：「若必須如此，你們就當這樣行：可以將這地土產中最好的乳香、蜂蜜、香料、沒藥、榧子、杏仁都取一點，收在器具裏，帶下去送給那人作禮物，", "ja": "父イスラエルは彼らに言った、「それではこうしなさい。この国の名産を器に入れ、携え下ってその人に贈り物にしなさい。すなわち少しの乳香、少しの蜜、香料、もつやく、ふすだしう、あめんどう。"}, "12": {"en": "and take double money in your hand, and take back the money that was returned in the mouth of your sacks. Perhaps it was an oversight.", "zh": "又要手裏加倍地帶銀子，並將歸還在你們口袋內的銀子仍帶在手裏；那或者是錯了。", "ja": "そしてその上に、倍額の銀を手に持って行きなさい。また袋の口に返してあった銀は持って行って返しなさい。たぶんそれは誤りであったのでしょう。"}, "13": {"en": "Take your brother also, get up, and return to the man.", "zh": "也帶着你們的兄弟，起身去見那人。", "ja": "弟も連れ、立って、またその人の所へ行きなさい。"}, "14": {"en": "May God Almighty give you mercy before the man, that he may release to you your other brother and Benjamin. If I am bereaved of my children, I am bereaved.”", "zh": "但願全能的上帝使你們在那人面前蒙憐憫，釋放你們的那弟兄和便雅憫回來。我若喪了兒子，就喪了吧！」", "ja": "どうか全能の神がその人の前であなたがたをあわれみ、もうひとりの兄弟とベニヤミンとを、返させてくださるように。もしわたしが子を失わなければならないのなら、失ってもよい」。"}, "15": {"en": "The men took that present, and they took double money in their hand, and Benjamin; and got up, went down to Egypt, and stood before Joseph.", "zh": "於是，他們拿着那禮物，又手裏加倍地帶銀子，並且帶着便雅憫，起身下到埃及，站在約瑟面前。", "ja": "そこでその人々は贈り物を取り、また倍額の銀を携え、ベニヤミンを連れ、立ってエジプトへ下り、ヨセフの前に立った。"}, "16": {"en": "When Joseph saw Benjamin with them, he said to the steward of his house, “Bring the men into the house, and butcher an animal, and prepare; for the men will dine with me at noon.”", "zh": "約瑟見便雅憫和他們同來，就對家宰說：「將這些人領到屋裏。要宰殺牲畜，預備筵席，因為晌午這些人同我吃飯。」", "ja": "ヨセフはベニヤミンが彼らと共にいるのを見て、家づかさに言った、「この人々を家に連れて行き、獣をほふって、したくするように。この人々は昼、わたしと一緒に食事をします」。"}, "17": {"en": "The man did as Joseph commanded, and the man brought the men to Joseph’s house.", "zh": "家宰就遵着約瑟的命去行，領他們進約瑟的屋裏。", "ja": "その人はヨセフの言ったようにして、この人々をヨセフの家へ連れて行った。"}, "18": {"en": "The men were afraid, because they were brought to Joseph’s house; and they said, “Because of the money that was returned in our sacks the first time, we’re brought in; that he may seek occasion against us, attack us, and seize us as slaves, along with our donkeys.”", "zh": "他們因為被領到約瑟的屋裏，就害怕，說：「領我們到這裏來，必是因為頭次歸還在我們口袋裏的銀子，找我們的錯縫，下手害我們，強取我們為奴僕，搶奪我們的驢。」", "ja": "ところがこの人々はヨセフの家へ連れて行かれたので恐れて言った、「初めの時に袋に返してあったあの銀のゆえに、われわれを引き入れたのです。そしてわれわれを襲い、攻め、捕えて奴隷とし、われわれのろばをも奪うのです」。"}, "19": {"en": "They came near to the steward of Joseph’s house, and they spoke to him at the door of the house,", "zh": "他們就挨近約瑟的家宰，在屋門口和他說話，", "ja": "彼らはヨセフの家づかさに近づいて、家の入口で、言った、"}, "20": {"en": "and said, “Oh, my lord, we indeed came down the first time to buy food.", "zh": "說：「我主啊，我們頭次下來實在是要糴糧。", "ja": "「ああ、わが主よ、われわれは最初、食糧を買うために下ってきたのです。"}, "21": {"en": "When we came to the lodging place, we opened our sacks, and behold, each man’s money was in the mouth of his sack, our money in full weight. We have brought it back in our hand.", "zh": "後來到了住宿的地方，我們打開口袋，不料，各人的銀子，分量足數，仍在各人的口袋內，現在我們手裏又帶回來了。", "ja": "ところが宿に行って袋をあけて見ると、めいめいの銀は袋の口にあって、銀の重さは元のままでした。それでわれわれはそれを持って参りました。"}, "22": {"en": "We have brought down other money in our hand to buy food. We don’t know who put our money in our sacks.”", "zh": "另外又帶下銀子來糴糧。不知道先前誰把銀子放在我們的口袋裏。」", "ja": "そして食糧を買うために、ほかの銀をも持って下ってきました。われわれの銀を袋に入れた者が、だれであるかは分りません」。"}, "23": {"en": "He said, “Peace be to you. Don’t be afraid. Your God, and the God of your father, has given you treasure in your sacks. I received your money.” He brought Simeon out to them.", "zh": "家宰說：「你們可以放心，不要害怕，是你們的上帝和你們父親的上帝賜給你們財寶在你們的口袋裏；你們的銀子，我早已收了。」他就把西緬帶出來，交給他們。", "ja": "彼は言った、「安心しなさい。恐れてはいけません。その宝はあなたがたの神、あなたがたの父の神が、あなたがたの袋に入れてあなたがたに賜わったのです。あなたがたの銀はわたしが受け取りました」。そして彼はシメオンを彼らの所へ連れてきた。"}, "24": {"en": "The man brought the men into Joseph’s house, and gave them water, and they washed their feet. He gave their donkeys fodder.", "zh": "家宰就領他們進約瑟的屋裏，給他們水洗腳，又給他們草料餵驢。", "ja": "こうしてその人はこの人々をヨセフの家へ導き、水を与えて足を洗わせ、また、ろばに飼葉を与えた。"}, "25": {"en": "They prepared the present for Joseph’s coming at noon, for they heard that they should eat bread there.", "zh": "他們就預備那禮物，等候約瑟晌午來，因為他們聽見要在那裏吃飯。", "ja": "彼らはその所で食事をするのだと聞き、贈り物を整えて、昼にヨセフの来るのを待った。"}, "26": {"en": "When Joseph came home, they brought him the present which was in their hand into the house, and bowed themselves down to the earth before him.", "zh": "約瑟來到家裏，他們就把手中的禮物拿進屋去給他，又俯伏在地，向他下拜。", "ja": "さてヨセフが家に帰ってきたので、彼らはその家に携えてきた贈り物をヨセフにささげ、地に伏して、彼を拝した。"}, "27": {"en": "He asked them of their welfare, and said, “Is your father well, the old man of whom you spoke? Is he yet alive?”", "zh": "約瑟問他們好，又問：「你們的父親－就是你們所說的那老人家平安嗎？他還在嗎？」", "ja": "ヨセフは彼らの安否を問うて言った、「あなたがたの父、あなたがたがさきに話していたその老人は無事ですか。なお生きながらえておられますか」。"}, "28": {"en": "They said, “Your servant, our father, is well. He is still alive.” They bowed down humbly.", "zh": "他們回答說：「你僕人－我們的父親平安；他還在。」於是他們低頭下拜。", "ja": "彼らは答えた、「あなたのしもべ、われわれの父は無事で、なお生きながらえています」。そして彼らは、頭をさげて拝した。"}, "29": {"en": "He lifted up his eyes, and saw Benjamin, his brother, his mother’s son, and said, “Is this your youngest brother, of whom you spoke to me?” He said, “God be gracious to you, my son.”", "zh": "約瑟舉目看見他同母的兄弟便雅憫，就說：「你們向我所說那頂小的兄弟就是這位嗎？」又說：「小兒啊，願上帝賜恩給你！」", "ja": "ヨセフは目をあげて同じ母の子である弟ベニヤミンを見て言った、「これはあなたがたが前にわたしに話した末の弟ですか」。また言った、「わが子よ、どうか神があなたを恵まれるように」。"}, "30": {"en": "Joseph hurried, for his heart yearned over his brother; and he sought a place to weep. He entered into his room, and wept there.", "zh": "約瑟愛弟之情發動，就急忙尋找可哭之地，進入自己的屋裏，哭了一場。", "ja": "ヨセフは弟なつかしさに心がせまり、急いで泣く場所をたずね、へやにはいって泣いた。"}, "31": {"en": "He washed his face, and came out. He controlled himself, and said, “Serve the meal.”", "zh": "他洗了臉出來，勉強隱忍，吩咐人擺飯。", "ja": "やがて彼は顔を洗って出てきた。そして自分を制して言った、「食事にしよう」。"}, "32": {"en": "They served him by himself, and them by themselves, and the Egyptians who ate with him by themselves, because the Egyptians don’t eat with the Hebrews, for that is an abomination to the Egyptians.", "zh": "他們就為約瑟單擺了一席，為那些人又擺了一席，也為和約瑟同吃飯的埃及人另擺了一席，因為埃及人不可和希伯來人一同吃飯；那原是埃及人所厭惡的。", "ja": "そこでヨセフはヨセフ、彼らは彼ら、陪食のエジプトびとはエジプトびと、と別々に席に着いた。エジプトびとはヘブルびとと共に食事することができなかった。それはエジプトびとの忌むところであったからである。"}, "33": {"en": "They sat before him, the firstborn according to his birthright, and the youngest according to his youth, and the men marveled with one another.", "zh": "約瑟使眾弟兄在他面前排列坐席，都按着長幼的次序，眾弟兄就彼此詫異。", "ja": "こうして彼らはヨセフの前に、長子は長子として、弟は弟としてすわらせられたので、その人々は互に驚いた。"}, "34": {"en": "He sent portions to them from before him, but Benjamin’s portion was five times as much as any of theirs. They drank, and were merry with him.", "zh": "約瑟把他面前的食物分出來，送給他們；但便雅憫所得的比別人多五倍。他們就飲酒，和約瑟一同宴樂。", "ja": "またヨセフの前から、めいめいの分が運ばれたが、ベニヤミンの分は他のいずれの者の分よりも五倍多かった。こうして彼らは飲み、ヨセフと共に楽しんだ。"}}}, "44": {"verses": {"1": {"en": "He commanded the steward of his house, saying, “Fill the men’s sacks with food, as much as they can carry, and put each man’s money in his sack’s mouth.", "zh": "約瑟吩咐家宰說：「把糧食裝滿這些人的口袋，儘着他們的驢所能馱的，又把各人的銀子放在各人的口袋裏，", "ja": "さてヨセフは家づかさに命じて言った、「この人々の袋に、運べるだけ多くの食糧を満たし、めいめいの銀を袋の口に入れておきなさい。"}, "2": {"en": "Put my cup, the silver cup, in the sack’s mouth of the youngest, with his grain money.” He did according to the word that Joseph had spoken.", "zh": "並將我的銀杯和那少年人糴糧的銀子一同裝在他的口袋裏。」家宰就照約瑟所說的話行了；", "ja": "またわたしの杯、銀の杯をあの年下の者の袋の口に、穀物の代金と共に入れておきなさい」。家づかさはヨセフの言葉のとおりにした。"}, "3": {"en": "As soon as the morning was light, the men were sent away, they and their donkeys.", "zh": "天一亮就打發那些人帶着驢走了。", "ja": "夜が明けると、その人々と、ろばとは送り出されたが、"}, "4": {"en": "When they had gone out of the city, and were not yet far off, Joseph said to his steward, “Up, follow after the men. When you overtake them, ask them, ‘Why have you rewarded evil for good?", "zh": "他們出城走了不遠，約瑟對家宰說：「起來，追那些人去，追上了就對他們說：『你們為甚麼以惡報善呢？", "ja": "町を出て、まだ遠くへ行かないうちに、ヨセフは家づかさに言った、「立って、あの人々のあとを追いなさい。追いついて、彼らに言いなさい、『あなたがたはなぜ悪をもって善に報いるのですか。なぜわたしの銀の杯を盗んだのですか。"}, "5": {"en": "Isn’t this that from which my lord drinks, and by which he indeed divines? You have done evil in so doing.’ ”", "zh": "這不是我主人飲酒的杯嗎？豈不是他占卜用的嗎？你們這樣行是作惡了。』」", "ja": "これはわたしの主人が飲む時に使い、またいつも占いに用いるものではありませんか。あなたがたのした事は悪いことです』」。"}, "6": {"en": "He overtook them, and he spoke these words to them.", "zh": "家宰追上他們，將這些話對他們說了。", "ja": "家づかさが彼らに追いついて、これらの言葉を彼らに告げたとき、"}, "7": {"en": "They said to him, “Why does my lord speak such words as these? Far be it from your servants that they should do such a thing!", "zh": "他們回答說：「我主為甚麼說這樣的話呢？你僕人斷不能做這樣的事。", "ja": "彼らは言った、「わが主は、どうしてそのようなことを言われるのですか。しもべらは決してそのようなことはいたしません。"}, "8": {"en": "Behold, the money, which we found in our sacks’ mouths, we brought again to you out of the land of Canaan. How then should we steal silver or gold out of your lord’s house?", "zh": "你看，我們從前在口袋裏所見的銀子，尚且從迦南地帶來還你，我們怎能從你主人家裏偷竊金銀呢？", "ja": "袋の口で見つけた銀でさえ、カナンの地からあなたの所に持ち帰ったほどです。どうして、われわれは御主人の家から銀や金を盗みましょう。"}, "9": {"en": "With whomever of your servants it is found, let him die, and we also will be my lord’s slaves.”", "zh": "你僕人中無論在誰那裏搜出來，就叫他死，我們也作我主的奴僕。」", "ja": "しもべらのうちのだれの所でそれが見つかっても、その者は死に、またわれわれはわが主の奴隷となりましょう」。"}, "10": {"en": "He said, “Now also let it be according to your words. He with whom it is found will be my slave; and you will be blameless.”", "zh": "家宰說：「現在就照你們的話行吧！在誰那裏搜出來，誰就作我的奴僕；其餘的都沒有罪。」", "ja": "家づかさは言った、「それではあなたがたの言葉のようにしよう。杯の見つかった者はわたしの奴隷とならなければならない。ほかの者は無罪です」。"}, "11": {"en": "Then they hurried, and each man took his sack down to the ground, and each man opened his sack.", "zh": "於是他們各人急忙把口袋卸在地下，各人打開口袋。", "ja": "そこで彼らは、めいめい急いで袋を地におろし、ひとりひとりその袋を開いた。"}, "12": {"en": "He searched, beginning with the oldest, and ending at the youngest. The cup was found in Benjamin’s sack.", "zh": "家宰就搜查，從年長的起到年幼的為止，那杯竟在便雅憫的口袋裏搜出來。", "ja": "家づかさは年上から捜し始めて年下に終ったが、杯はベニヤミンの袋の中にあった。"}, "13": {"en": "Then they tore their clothes, and each man loaded his donkey, and returned to the city.", "zh": "他們就撕裂衣服，各人把馱子抬在驢上，回城去了。", "ja": "そこで彼らは衣服を裂き、おのおの、ろばに荷を負わせて町に引き返した。"}, "14": {"en": "Judah and his brothers came to Joseph’s house, and he was still there. They fell on the ground before him.", "zh": "猶大和他弟兄們來到約瑟的屋中，約瑟還在那裏，他們就在他面前俯伏於地。", "ja": "ユダと兄弟たちとは、ヨセフの家にはいったが、ヨセフがなおそこにいたので、彼らはその前で地にひれ伏した。"}, "15": {"en": "Joseph said to them, “What deed is this that you have done? Don’t you know that such a man as I can indeed do divination?”", "zh": "約瑟對他們說：「你們做的是甚麼事呢？你們豈不知像我這樣的人必能占卜嗎？」", "ja": "ヨセフは彼らに言った、「あなたがたのこのしわざは何事ですか。わたしのような人は、必ず占い当てることを知らないのですか」。"}, "16": {"en": "Judah said, “What will we tell my lord? What will we speak? How will we clear ourselves? God has found out the iniquity of your servants. Behold, we are my lord’s slaves, both we and he also in whose hand the cup is found.”", "zh": "猶大說：「我們對我主說甚麼呢？還有甚麼話可說呢？我們怎能自己表白出來呢？上帝已經查出僕人的罪孽了。我們與那在他手中搜出杯來的都是我主的奴僕。」", "ja": "ユダは言った、「われわれはわが主に何を言い、何を述べ得ましょう。どうしてわれわれは身の潔白をあらわし得ましょう。神がしもべらの罪をあばかれました。われわれと、杯を持っていた者とは共にわが主の奴隷となりましょう」。"}, "17": {"en": "He said, “Far be it from me that I should do so. The man in whose hand the cup is found, he will be my slave; but as for you, go up in peace to your father.”", "zh": "約瑟說：「我斷不能這樣行！在誰的手中搜出杯來，誰就作我的奴僕；至於你們，可以平平安安地上你們父親那裏去。」", "ja": "ヨセフは言った、「わたしは決してそのようなことはしない。杯を持っている者だけがわたしの奴隷とならなければならない。ほかの者は安全に父のもとへ上って行きなさい」。"}, "18": {"en": "Then Judah came near to him, and said, “Oh, my lord, please let your servant speak a word in my lord’s ears, and don’t let your anger burn against your servant; for you are even as Pharaoh.", "zh": "猶大挨近他，說：「我主啊，求你容僕人說一句話給我主聽，不要向僕人發烈怒，因為你如同法老一樣。", "ja": "この時ユダは彼に近づいて言った、「ああ、わが主よ、どうぞわが主の耳にひとこと言わせてください。しもべをおこらないでください。あなたはパロのようなかたです。"}, "19": {"en": "My lord asked his servants, saying, ‘Have you a father, or a brother?’", "zh": "我主曾問僕人們說：『你們有父親有兄弟沒有？』", "ja": "わが主はしもべらに尋ねて、『父があるか、また弟があるか』と言われたので、"}, "20": {"en": "We said to my lord, ‘We have a father, an old man, and a child of his old age, a little one; and his brother is dead, and he alone is left of his mother; and his father loves him.’", "zh": "我們對我主說：『我們有父親，已經年老，還有他老年所生的一個小孩子。他哥哥死了，他母親只撇下他一人，他父親疼愛他。』", "ja": "われわれはわが主に言いました、『われわれには老齢の父があり、また年寄り子の弟があります。その兄は死んで、同じ母の子で残っているのは、ただこれだけですから父はこれを愛しています』。"}, "21": {"en": "You said to your servants, ‘Bring him down to me, that I may set my eyes on him.’", "zh": "你對僕人說：『把他帶到我這裏來，叫我親眼看看他。』", "ja": "その時あなたはしもべらに言われました、『その者をわたしの所へ連れてきなさい。わたしはこの目で彼を見よう』。"}, "22": {"en": "We said to my lord, ‘The boy can’t leave his father, for if he should leave his father, his father would die.’", "zh": "我們對我主說：『童子不能離開他父親，若是離開，他父親必死。』", "ja": "われわれはわが主に言いました。『その子供は父を離れることができません。もし父を離れたら父は死ぬでしょう』。"}, "23": {"en": "You said to your servants, ‘Unless your youngest brother comes down with you, you will see my face no more.’", "zh": "你對僕人說：『你們的小兄弟若不與你們一同下來，你們就不得再見我的面。』", "ja": "しかし、あなたはしもべらに言われました、『末の弟が一緒に下ってこなければ、おまえたちは再びわたしの顔を見ることはできない』。"}, "24": {"en": "When we came up to your servant my father, we told him the words of my lord.", "zh": "我們上到你僕人－我們父親那裏，就把我主的話告訴了他。", "ja": "それであなたのしもべである父のもとに上って、わが主の言葉を彼に告げました。"}, "25": {"en": "Our father said, ‘Go again and buy us a little food.’", "zh": "我們的父親說：『你們再去給我糴些糧來。』", "ja": "ところで、父が『おまえたちは再び行って、われわれのために少しの食糧を買ってくるように』と言ったので、"}, "26": {"en": "We said, ‘We can’t go down. If our youngest brother is with us, then we will go down: for we may not see the man’s face, unless our youngest brother is with us.’", "zh": "我們就說：『我們不能下去。我們的小兄弟若和我們同往，我們就可以下去。因為，小兄弟若不與我們同往，我們必不得見那人的面。』", "ja": "われわれは言いました、『われわれは下って行けません。もし末の弟が一緒であれば行きましょう。末の弟が一緒でなければ、あの人の顔を見ることができません』。"}, "27": {"en": "Your servant, my father, said to us, ‘You know that my wife bore me two sons.", "zh": "你僕人－我父親對我們說：『你們知道我的妻子給我生了兩個兒子。", "ja": "あなたのしもべである父は言いました、『おまえたちの知っているとおり、妻はわたしにふたりの子を産んだ。"}, "28": {"en": "One went out from me, and I said, “Surely he is torn in pieces;” and I haven’t seen him since.", "zh": "一個離開我出去了；我說他必是被撕碎了，直到如今我也沒有見他。", "ja": "ひとりは外へ出たが、きっと裂き殺されたのだと思う。わたしは今になっても彼を見ない。"}, "29": {"en": "If you take this one also from me, and harm happens to him, you will bring down my gray hairs with sorrow to Sheol.’", "zh": "現在你們又要把這個帶去離開我，倘若他遭害，那便是你們使我白髮蒼蒼、悲悲慘慘地下陰間去了。』", "ja": "もしおまえたちがこの子をもわたしから取って行って、彼が災に会えば、おまえたちは、しらがのわたしを悲しんで陰府に下らせるであろう』。"}, "30": {"en": "Now therefore when I come to your servant my father, and the boy is not with us; since his life is bound up in the boy’s life;", "zh": "我父親的命與這童子的命相連。如今我回到你僕人－我父親那裏，若沒有童子與我們同在，", "ja": "わたしがあなたのしもべである父のもとに帰って行くとき、もしこの子供が一緒にいなかったら、どうなるでしょう。父の魂は子供の魂に結ばれているのです。"}, "31": {"en": "it will happen, when he sees that the boy is no more, that he will die. Your servants will bring down the gray hairs of your servant, our father, with sorrow to Sheol.", "zh": "我們的父親見沒有童子，他就必死。這便是我們使你僕人－我們的父親白髮蒼蒼、悲悲慘慘地下陰間去了。", "ja": "この子供がわれわれと一緒にいないのを見たら、父は死ぬでしょう。そうすればしもべらは、あなたのしもべであるしらがの父を悲しんで陰府に下らせることになるでしょう。"}, "32": {"en": "For your servant became collateral for the boy to my father, saying, ‘If I don’t bring him to you, then I will bear the blame to my father forever.’", "zh": "因為僕人曾向我父親為這童子作保，說：『我若不帶他回來交給父親，我便在父親面前永遠擔罪。』", "ja": "しもべは父にこの子供の身を請け合って『もしわたしがこの子をあなたのもとに連れ帰らなかったら、わたしは父に対して永久に罪を負いましょう』と言ったのです。"}, "33": {"en": "Now therefore, please let your servant stay instead of the boy, my lord’s slave; and let the boy go up with his brothers.", "zh": "現在求你容僕人住下，替這童子作我主的奴僕，叫童子和他哥哥們一同上去。", "ja": "どうか、しもべをこの子供の代りに、わが主の奴隷としてとどまらせ、この子供を兄弟たちと一緒に上り行かせてください、"}, "34": {"en": "For how will I go up to my father, if the boy isn’t with me?—lest I see the evil that will come on my father.”", "zh": "若童子不和我同去，我怎能上去見我父親呢？恐怕我看見災禍臨到我父親身上。」", "ja": "この子供を連れずに、どうしてわたしは父のもとに上り行くことができましょう。父が災に会うのを見るに忍びません」。"}}}, "45": {"verses": {"1": {"en": "Then Joseph couldn’t control himself before all those who stood before him, and he called out, “Cause everyone to go out from me!” No one else stood with him, while Joseph made himself known to his brothers.", "zh": "約瑟在左右站着的人面前情不自禁，吩咐一聲說：「人都要離開我出去！」約瑟和弟兄們相認的時候並沒有一人站在他面前。", "ja": "そこでヨセフはそばに立っているすべての人の前で、自分を制しきれなくなったので、「人は皆ここから出てください」と呼ばわった。それゆえヨセフが兄弟たちに自分のことを明かした時、ひとりも彼のそばに立っている者はなかった。"}, "2": {"en": "He wept aloud. The Egyptians heard, and the house of Pharaoh heard.", "zh": "他就放聲大哭；埃及人和法老家中的人都聽見了。", "ja": "ヨセフは声をあげて泣いた。エジプトびとはこれを聞き、パロの家もこれを聞いた。"}, "3": {"en": "Joseph said to his brothers, “I am Joseph! Does my father still live?”", "zh": "約瑟對他弟兄們說：「我是約瑟。我的父親還在嗎？」他弟兄不能回答，因為在他面前都驚惶。", "ja": "ヨセフは兄弟たちに言った、「わたしはヨセフです。父はまだ生きながらえていますか」。兄弟たちは答えることができなかった。彼らは驚き恐れたからである。"}, "4": {"en": "His brothers couldn’t answer him; for they were terrified at his presence.   Joseph said to his brothers, “Come near to me, please.”", "zh": "約瑟又對他弟兄們說：「請你們近前來。」他們就近前來。他說：「我是你們的兄弟約瑟，就是你們所賣到埃及的。", "ja": "ヨセフは兄弟たちに言った、「わたしに近寄ってください」。彼らが近寄ったので彼は言った、「わたしはあなたがたの弟ヨセフです。あなたがたがエジプトに売った者です。"}, "5": {"en": "They came near. He said, “I am Joseph, your brother, whom you sold into Egypt.   Now don’t be grieved, nor angry with yourselves, that you sold me here, for God sent me before you to preserve life.", "zh": "現在，不要因為把我賣到這裏自憂自恨。這是上帝差我在你們以先來，為要保全生命。", "ja": "しかしわたしをここに売ったのを嘆くことも、悔むこともいりません。神は命を救うために、あなたがたよりさきにわたしをつかわされたのです。"}, "6": {"en": "For these two years the famine has been in the land, and there are yet five years, in which there will be no plowing and no harvest.", "zh": "現在這地的饑荒已經二年了，還有五年不能耕種，不能收成。", "ja": "この二年の間、国中にききんがあったが、なお五年の間は耕すことも刈り入れることもないでしょう。"}, "7": {"en": "God sent me before you to preserve for you a remnant on the earth, and to save you alive by a great deliverance.", "zh": "上帝差我在你們以先來，為要給你們存留餘種在世上，又要大施拯救，保全你們的生命。", "ja": "神は、あなたがたのすえを地に残すため、また大いなる救をもってあなたがたの命を助けるために、わたしをあなたがたよりさきにつかわされたのです。"}, "8": {"en": "So now it wasn’t you who sent me here, but God, and he has made me a father to Pharaoh, lord of all his house, and ruler over all the land of Egypt.", "zh": "這樣看來，差我到這裏來的不是你們，乃是上帝。他又使我如法老的父，作他全家的主，並埃及全地的宰相。", "ja": "それゆえわたしをここにつかわしたのはあなたがたではなく、神です。神はわたしをパロの父とし、その全家の主とし、またエジプト全国のつかさとされました。"}, "9": {"en": "Hurry, and go up to my father, and tell him, ‘This is what your son Joseph says, “God has made me lord of all Egypt. Come down to me. Don’t wait.", "zh": "你們要趕緊上到我父親那裏，對他說：『你兒子約瑟這樣說：上帝使我作全埃及的主，請你下到我這裏來，不要耽延。", "ja": "あなたがたは父のもとに急ぎ上って言いなさい、『あなたの子ヨセフが、こう言いました。神がわたしをエジプト全国の主とされたから、ためらわずにわたしの所へ下ってきなさい。"}, "10": {"en": "You shall dwell in the land of Goshen, and you will be near to me, you, your children, your children’s children, your flocks, your herds, and all that you have.", "zh": "你和你的兒子孫子，連牛群羊群，並一切所有的，都可以住在歌珊地，與我相近。", "ja": "あなたはゴセンの地に住み、あなたも、あなたの子らも、孫たちも、羊も牛も、その他のものもみな、わたしの近くにおらせます。"}, "11": {"en": "There I will provide for you; for there are yet five years of famine; lest you come to poverty, you, and your household, and all that you have.” ’", "zh": "我要在那裏奉養你；因為還有五年的饑荒，免得你和你的眷屬，並一切所有的，都敗落了。』", "ja": "ききんはなお五年つづきますから、あなたも、家族も、その他のものも、みな困らないように、わたしはそこで養いましょう』。"}, "12": {"en": "Behold, your eyes see, and the eyes of my brother Benjamin, that it is my mouth that speaks to you.", "zh": "況且你們的眼和我兄弟便雅憫的眼都看見是我親口對你們說話。", "ja": "あなたがたと弟ベニヤミンが目に見るとおり、あなたがたに口ら語っているのはこのわたしです。"}, "13": {"en": "You shall tell my father of all my glory in Egypt, and of all that you have seen. You shall hurry and bring my father down here.”", "zh": "你們也要將我在埃及一切的榮耀和你們所看見的事都告訴我父親，又要趕緊地將我父親搬到我這裏來。」", "ja": "あなたがたはエジプトでの、わたしのいっさいの栄えと、あなたがたが見るいっさいの事をわたしの父に告げ、急いでわたしの父をここへ連れ下りなさい」。"}, "14": {"en": "He fell on his brother Benjamin’s neck and wept, and Benjamin wept on his neck.", "zh": "於是約瑟伏在他兄弟便雅憫的頸項上哭，便雅憫也在他的頸項上哭。", "ja": "そしてヨセフは弟ベニヤミンのくびを抱いて泣き、ベニヤミンも彼のくびを抱いて泣いた。"}, "15": {"en": "He kissed all his brothers, and wept on them. After that his brothers talked with him.", "zh": "他又與眾弟兄親嘴，抱着他們哭，隨後他弟兄們就和他說話。", "ja": "またヨセフはすべての兄弟たちに口づけし、彼らを抱いて泣いた。そして後、兄弟たちは彼と語った。"}, "16": {"en": "The report of it was heard in Pharaoh’s house, saying, “Joseph’s brothers have come.” It pleased Pharaoh well, and his servants.", "zh": "這風聲傳到法老的宮裏，說：「約瑟的弟兄們來了。」法老和他的臣僕都很喜歡。", "ja": "時に、「ヨセフの兄弟たちがきた」と言ううわさがパロの家に聞えたので、パロとその家来たちとは喜んだ。"}, "17": {"en": "Pharaoh said to Joseph, “Tell your brothers, ‘Do this: Load your animals, and go, travel to the land of Canaan.", "zh": "法老對約瑟說：「你吩咐你的弟兄們說：『你們要這樣行：把馱子抬在牲口上，起身往迦南地去。", "ja": "パロはヨセフに言った、「兄弟たちに言いなさい、『あなたがたは、こうしなさい。獣に荷を負わせてカナンの地へ行き、"}, "18": {"en": "Take your father and your households, and come to me, and I will give you the good of the land of Egypt, and you will eat the fat of the land.’", "zh": "將你們的父親和你們的眷屬都搬到我這裏來，我要把埃及地的美物賜給你們，你們也要吃這地肥美的出產。", "ja": "父と家族とを連れてわたしのもとへきなさい。わたしはあなたがたに、エジプトの地の良い物を与えます。あなたがたは、この国の最も良いものを食べるでしょう』。"}, "19": {"en": "Now you are commanded to do this: Take wagons out of the land of Egypt for your little ones, and for your wives, and bring your father, and come.", "zh": "現在我吩咐你們要這樣行：從埃及地帶着車輛去，把你們的孩子和妻子，並你們的父親都搬來。", "ja": "また彼らに命じなさい、『あなたがたは、こうしなさい。幼な子たちと妻たちのためにエジプトの地から車をもって行き、父を連れてきなさい。"}, "20": {"en": "Also, don’t concern yourselves about your belongings, for the good of all the land of Egypt is yours.”", "zh": "你們眼中不要愛惜你們的家具，因為埃及全地的美物都是你們的。』」", "ja": "家財に心を引かれてはなりません。エジプト全国の良い物は、あなたがたのものだからです』」。"}, "21": {"en": "The sons of Israel did so. Joseph gave them wagons, according to the commandment of Pharaoh, and gave them provision for the way.", "zh": "以色列的兒子們就如此行。約瑟照着法老的吩咐給他們車輛和路上用的食物，", "ja": "イスラエルの子らはそのようにした。ヨセフはパロの命に従って彼らに車を与え、また途中の食料をも与えた。"}, "22": {"en": "He gave each one of them changes of clothing, but to Benjamin he gave three hundred pieces of silver and five changes of clothing.", "zh": "又給他們各人一套衣服，惟獨給便雅憫三百銀子，五套衣服；", "ja": "まためいめいに晴着を与えたが、ベニヤミンには銀三百シケルと晴着五着とを与えた。"}, "23": {"en": "He sent the following to his father: ten donkeys loaded with the good things of Egypt, and ten female donkeys loaded with grain and bread and provision for his father by the way.", "zh": "送給他父親公驢十匹，馱着埃及的美物，母驢十匹，馱着糧食與餅和菜，為他父親路上用。", "ja": "また彼は父に次のようなものを贈った。すなわちエジプトの良い物を負わせたろば十頭と、穀物、パン及び父の道中の食料を負わせた雌ろば十頭。"}, "24": {"en": "So he sent his brothers away, and they departed. He said to them, “See that you don’t quarrel on the way.”", "zh": "於是約瑟打發他弟兄們回去，又對他們說：「你們不要在路上相爭。」", "ja": "こうしてヨセフは兄弟たちを送り去らせ、彼らに言った、「途中で争ってはなりません」。"}, "25": {"en": "They went up out of Egypt, and came into the land of Canaan, to Jacob their father.", "zh": "他們從埃及上去，來到迦南地、他們的父親雅各那裏，", "ja": "彼らはエジプトから上ってカナンの地に入り、父ヤコブのもとへ行って、"}, "26": {"en": "They told him, saying, “Joseph is still alive, and he is ruler over all the land of Egypt.” His heart fainted, for he didn’t believe them.", "zh": "告訴他說：「約瑟還在，並且作埃及全地的宰相。」雅各心裏冰涼，因為不信他們。", "ja": "彼に言った、「ヨセフはなお生きていてエジプト全国のつかさです」。ヤコブは気が遠くなった。彼らの言うことが信じられなかったからである。"}, "27": {"en": "They told him all the words of Joseph, which he had said to them. When he saw the wagons which Joseph had sent to carry him, the spirit of Jacob, their father, revived.", "zh": "他們便將約瑟對他們說的一切話都告訴了他。他們父親雅各又看見約瑟打發來接他的車輛，心就甦醒了。", "ja": "そこで彼らはヨセフが語った言葉を残らず彼に告げた。父ヤコブはヨセフが自分を乗せるために送った車を見て元気づいた。"}, "28": {"en": "Israel said, “It is enough. Joseph my son is still alive. I will go and see him before I die.”", "zh": "以色列說：「罷了！罷了！我的兒子約瑟還在，趁我未死以先，我要去見他一面。」", "ja": "そしてイスラエルは言った、「満足だ。わが子ヨセフがまだ生きている。わたしは死ぬ前に行って彼を見よう」。"}}}, "46": {"verses": {"1": {"en": "Israel traveled with all that he had, and came to Beersheba, and offered sacrifices to the God of his father, Isaac.", "zh": "以色列帶着一切所有的，起身來到別是巴，就獻祭給他父親以撒的上帝。", "ja": "イスラエルはその持ち物をことごとく携えて旅立ち、ベエルシバに行って、父イサクの神に犠牲をささげた。"}, "2": {"en": "God spoke to Israel in the visions of the night, and said, “Jacob, Jacob!” He said, “Here I am.”", "zh": "夜間，上帝在異象中對以色列說：「雅各！雅各！」他說：「我在這裏。」", "ja": "この時、神は夜の幻のうちにイスラエルに語って言われた、「ヤコブよ、ヤコブよ」。彼は言った、「ここにいます」。"}, "3": {"en": "He said, “I am God, the God of your father. Don’t be afraid to go down into Egypt, for there I will make of you a great nation.", "zh": "上帝說：「我是上帝，就是你父親的上帝。你下埃及去不要害怕，因為我必使你在那裏成為大族。", "ja": "神は言われた、「わたしは神、あなたの父の神である。エジプトに下るのを恐れてはならない。わたしはあそこであなたを大いなる国民にする。"}, "4": {"en": "I will go down with you into Egypt. I will also surely bring you up again. Joseph’s hand will close your eyes.”", "zh": "我要和你同下埃及去，也必定帶你上來；約瑟必給你送終。」", "ja": "わたしはあなたと一緒にエジプトに下り、また必ずあなたを導き上るであろう。ヨセフが手ずからあなたの目を閉じるであろう」。"}, "5": {"en": "Jacob rose up from Beersheba, and the sons of Israel carried Jacob, their father, their little ones, and their wives, in the wagons which Pharaoh had sent to carry him.", "zh": "雅各就從別是巴起行。以色列的兒子們使他們的父親雅各和他們的妻子、兒女都坐在法老為雅各送來的車上。", "ja": "そしてヤコブはベエルシバを立った。イスラエルの子らはヤコブを乗せるためにパロの送った車に、父ヤコブと幼な子たちと妻たちを乗せ、"}, "6": {"en": "They took their livestock, and their goods, which they had gotten in the land of Canaan, and came into Egypt—Jacob, and all his offspring with him,", "zh": "他們又帶着迦南地所得的牲畜、貨財來到埃及。雅各和他的一切子孫都一同來了。", "ja": "またその家畜とカナンの地で得た財産を携え、ヤコブとその子孫は皆ともにエジプトへ行った。"}, "7": {"en": "his sons, and his sons’ sons with him, his daughters, and his sons’ daughters, and he brought all his offspring with him into Egypt.", "zh": "雅各把他的兒子、孫子、女兒、孫女，並他的子子孫孫，一同帶到埃及。", "ja": "こうしてヤコブはその子と、孫および娘と孫娘などその子孫をみな連れて、エジプトへ行った。"}, "8": {"en": "These are the names of the children of Israel, who came into Egypt, Jacob and his sons: Reuben, Jacob’s firstborn.", "zh": "來到埃及的以色列人名字記在下面。雅各和他的兒孫：雅各的長子是呂便。", "ja": "イスラエルの子らでエジプトへ行った者の名は次のとおりである。すなわちヤコブとその子らであるが、ヤコブの長子はルベン。"}, "9": {"en": "The sons of Reuben: Hanoch, Pallu, Hezron, and Carmi.", "zh": "呂便的兒子是哈諾、法路、希斯倫、迦米。", "ja": "ルベンの子らはハノク、パル、ヘヅロン、カルミ。"}, "10": {"en": "The sons of Simeon: Jemuel, Jamin, Ohad, Jachin, Zohar, and Shaul the son of a Canaanite woman.", "zh": "西緬的兒子是耶母利、雅憫、阿轄、雅斤、瑣轄，還有迦南女子所生的掃羅。", "ja": "シメオンの子らはエムエル、ヤミン、オハデ、ヤキン、ゾハル及びカナンの女の産んだ子シャウル。"}, "11": {"en": "The sons of Levi: Gershon, Kohath, and Merari.", "zh": "利未的兒子是革順、哥轄、米拉利。", "ja": "レビの子らはゲルション、コハテ、メラリ。"}, "12": {"en": "The sons of Judah: Er, Onan, Shelah, Perez, and Zerah; but Er and Onan died in the land of Canaan. The sons of Perez were Hezron and Hamul.", "zh": "猶大的兒子是珥、俄南、示拉、法勒斯、謝拉；惟有珥與俄南死在迦南地。法勒斯的兒子是希斯崙、哈母勒。", "ja": "ユダの子らはエル、オナン、シラ、ペレヅ、ゼラ。エルとオナンはカナンの地で死んだ。ペレヅの子らはヘヅロンとハムル。"}, "13": {"en": "The sons of Issachar: Tola, Puvah, Iob, and Shimron.", "zh": "以薩迦的兒子是陀拉、普瓦、約伯、伸崙。", "ja": "イッサカルの子らはトラ、プワ、ヨブ、シムロン。"}, "14": {"en": "The sons of Zebulun: Sered, Elon, and Jahleel.", "zh": "西布倫的兒子是西烈、以倫、雅利。", "ja": "ゼブルンの子らはセレデ、エロン、ヤリエル。"}, "15": {"en": "These are the sons of Leah, whom she bore to Jacob in Paddan Aram, with his daughter Dinah. All the souls of his sons and his daughters were thirty-three.", "zh": "這是利亞在巴旦‧亞蘭給雅各所生的兒子，還有女兒底拿。兒孫共有三十三人。", "ja": "これらと娘デナとはレアがパダンアラムでヤコブに産んだ子らである。その子らと娘らは合わせて三十三人。"}, "16": {"en": "The sons of Gad: Ziphion, Haggi, Shuni, Ezbon, Eri, Arodi, and Areli.", "zh": "迦得的兒子是洗非芸、哈基、書尼、以斯本、以利、亞羅底、亞列利。", "ja": "ガドの子らはゼポン、ハギ、シュニ、エヅボン、エリ、アロデ、アレリ。"}, "17": {"en": "The sons of Asher: Imnah, Ishvah, Ishvi, Beriah, and Serah their sister. The sons of Beriah: Heber and Malchiel.", "zh": "亞設的兒子是音拿、亦施瓦、亦施韋、比利亞，還有他們的妹子西拉。比利亞的兒子是希別、瑪結。", "ja": "アセルの子らはエムナ、イシワ、イスイ、ベリアおよび妹サラ。ベリアの子らはヘベルとマルキエル。"}, "18": {"en": "These are the sons of Zilpah, whom Laban gave to Leah, his daughter, and these she bore to Jacob, even sixteen souls.", "zh": "這是拉班給他女兒利亞的婢女悉帕從雅各所生的兒孫，共有十六人。", "ja": "これらはラバンが娘レアに与えたジルパの子らである。彼女はこれらをヤコブに産んだ。合わせて十六人。"}, "19": {"en": "The sons of Rachel, Jacob’s wife: Joseph and Benjamin.", "zh": "雅各之妻拉結的兒子是約瑟和便雅憫。", "ja": "ヤコブの妻ラケルの子らはヨセフとベニヤミンとである。"}, "20": {"en": "To Joseph in the land of Egypt were born Manasseh and Ephraim, whom Asenath, the daughter of Potiphera, priest of On, bore to him.", "zh": "約瑟在埃及地生了瑪拿西和以法蓮，就是安城的祭司波提非拉的女兒亞西納給約瑟生的。", "ja": "エジプトの国でヨセフにマナセとエフライムとが生れた。これはオンの祭司ポテペラの娘アセナテが彼に産んだ者である。"}, "21": {"en": "The sons of Benjamin: Bela, Becher, Ashbel, Gera, Naaman, Ehi, Rosh, Muppim, Huppim, and Ard.", "zh": "便雅憫的兒子是比拉、比結、亞實別、基拉、乃幔、以希、羅實、母平、戶平、亞勒。", "ja": "ベニヤミンの子らはベラ、ベケル、アシベル、ゲラ、ナアマン、エヒ、ロシ、ムッピム、ホパム、アルデ。"}, "22": {"en": "These are the sons of Rachel, who were born to Jacob: all the souls were fourteen.", "zh": "這是拉結給雅各所生的兒孫，共有十四人。", "ja": "これらはラケルがヤコブに産んだ子らである。合わせて十四人。"}, "23": {"en": "The son of Dan: Hushim.", "zh": "但的兒子是戶伸。", "ja": "ダンの子はホシム。"}, "24": {"en": "The sons of Naphtali: Jahzeel, Guni, Jezer, and Shillem.", "zh": "拿弗他利的兒子是雅薛、沽尼、耶色、示冷。", "ja": "ナフタリの子らはヤジエル、グニ、エゼル、シレム。"}, "25": {"en": "These are the sons of Bilhah, whom Laban gave to Rachel, his daughter, and these she bore to Jacob: all the souls were seven.", "zh": "這是拉班給他女兒拉結的婢女辟拉從雅各所生的兒孫，共有七人。", "ja": "これらはラバンが娘ラケルに与えたビルハの子らである。彼女はこれらをヤコブに産んだ。合わせて七人。"}, "26": {"en": "All the souls who came with Jacob into Egypt, who were his direct offspring, in addition to Jacob’s sons’ wives, all the souls were sixty-six.", "zh": "那與雅各同到埃及的，除了他兒婦之外，凡從他所生的，共有六十六人。", "ja": "ヤコブと共にエジプトへ行ったすべての者、すなわち彼の身から出た者はヤコブの子らの妻をのぞいて、合わせて六十六人であった。"}, "27": {"en": "The sons of Joseph, who were born to him in Egypt, were two souls. All the souls of the house of Jacob, who came into Egypt, were seventy.", "zh": "還有約瑟在埃及所生的兩個兒子。雅各家來到埃及的共有七十人。", "ja": "エジプトでヨセフに生れた子がふたりあった。エジプトへ行ったヤコブの家の者は合わせて七十人であった。"}, "28": {"en": "Jacob sent Judah before him to Joseph, to show the way before him to Goshen, and they came into the land of Goshen.", "zh": "雅各打發猶大先去見約瑟，請派人引路往歌珊去；於是他們來到歌珊地。", "ja": "さてヤコブはユダをさきにヨセフにつかわして、ゴセンで会おうと言わせた。そして彼らはゴセンの地へ行った。"}, "29": {"en": "Joseph prepared his chariot, and went up to meet Israel, his father, in Goshen. He presented himself to him, and fell on his neck, and wept on his neck a good while.", "zh": "約瑟套車往歌珊去，迎接他父親以色列，及至見了面，就伏在父親的頸項上，哭了許久。", "ja": "ヨセフは車を整えて、父イスラエルを迎えるためにゴセンに上り、父に会い、そのくびを抱き、くびをかかえて久しく泣いた。"}, "30": {"en": "Israel said to Joseph, “Now let me die, since I have seen your face, that you are still alive.”", "zh": "以色列對約瑟說：「我既得見你的面，知道你還在，就是死我也甘心。」", "ja": "時に、イスラエルはヨセフに言った、「あなたがなお生きていて、わたしはあなたの顔を見たので今は死んでもよい」。"}, "31": {"en": "Joseph said to his brothers, and to his father’s house, “I will go up, and speak with Pharaoh, and will tell him, ‘My brothers, and my father’s house, who were in the land of Canaan, have come to me.", "zh": "約瑟對他的弟兄和他父的全家說：「我要上去告訴法老，對他說：『我的弟兄和我父的全家從前在迦南地，現今都到我這裏來了。", "ja": "ヨセフは兄弟たちと父の家族とに言った、「わたしは上ってパロに言おう、『カナンの地にいたわたしの兄弟たちと父の家族とがわたしの所へきました。"}, "32": {"en": "These men are shepherds, for they have been keepers of livestock, and they have brought their flocks, and their herds, and all that they have.’", "zh": "他們本是牧羊的人，以養牲畜為業；他們把羊群牛群和一切所有的都帶來了。』", "ja": "この者らは羊を飼う者、家畜の牧者で、その羊、牛および持ち物をみな携えてきました』。"}, "33": {"en": "It will happen, when Pharaoh summons you, and will say, ‘What is your occupation?’", "zh": "等法老召你們的時候，問你們說：『你們以何事為業？』", "ja": "もしパロがあなたがたを召して、『あなたがたの職業は何か』と言われたら、"}, "34": {"en": "that you shall say, ‘Your servants have been keepers of livestock from our youth even until now, both we, and our fathers:’ that you may dwell in the land of Goshen; for every shepherd is an abomination to the Egyptians.”", "zh": "你們要說：『你的僕人，從幼年直到如今，都以養牲畜為業，連我們的祖宗也都以此為業。』這樣，你們可以住在歌珊地，因為凡牧羊的都被埃及人所厭惡。」", "ja": "『しもべらは幼い時から、ずっと家畜の牧者です。われわれも、われわれの先祖もそうです』と言いなさい。そうすればあなたがたはゴセンの地に住むことができましょう。羊飼はすべて、エジプトびとの忌む者だからです」。"}}}, "47": {"verses": {"1": {"en": "Then Joseph went in and told Pharaoh, and said, “My father and my brothers, with their flocks, their herds, and all that they own, have come out of the land of Canaan; and behold, they are in the land of Goshen.”", "zh": "約瑟進去告訴法老說：「我的父親和我的弟兄帶着羊群牛群，並一切所有的，從迦南地來了，如今在歌珊地。」", "ja": "ヨセフは行って、パロに言った、「わたしの父と兄弟たち、その羊、牛およびすべての持ち物がカナンの地からきて、今ゴセンの地におります」。"}, "2": {"en": "From among his brothers he took five men, and presented them to Pharaoh.", "zh": "約瑟從他弟兄中挑出五個人來，引他們去見法老。", "ja": "そしてその兄弟のうちの五人を連れて行って、パロに会わせた。"}, "3": {"en": "Pharaoh said to his brothers, “What is your occupation?”", "zh": "法老問約瑟的弟兄說：「你們以何事為業？」他們對法老說：「你僕人是牧羊的，連我們的祖宗也是牧羊的。」", "ja": "パロはヨセフの兄弟たちに言った、「あなたがたの職業は何か」。彼らはパロに言った、「しもべらは羊を飼う者です。われわれも、われわれの先祖もそうです」。"}, "4": {"en": "They said to Pharaoh, “Your servants are shepherds, both we, and our fathers.”   They also said to Pharaoh, “We have come to live as foreigners in the land, for there is no pasture for your servants’ flocks. For the famine is severe in the land of Canaan. Now therefore, please let your servants dwell in the land of Goshen.”", "zh": "他們又對法老說：「迦南地的饑荒甚大，僕人的羊群沒有草吃，所以我們來到這地寄居。現在求你容僕人住在歌珊地。」", "ja": "彼らはまたパロに言った、「この国に寄留しようとしてきました。カナンの地はききんが激しく、しもべらの群れのための牧草がないのです。どうかしもべらをゴセンの地に住ませてください」。"}, "5": {"en": "Pharaoh spoke to Joseph, saying, “Your father and your brothers have come to you.", "zh": "法老對約瑟說：「你父親和你弟兄到你這裏來了，", "ja": "パロはヨセフに言った、「あなたの父と兄弟たちとがあなたのところにきた。"}, "6": {"en": "The land of Egypt is before you. Make your father and your brothers dwell in the best of the land. Let them dwell in the land of Goshen. If you know any able men among them, then put them in charge of my livestock.”", "zh": "埃及地都在你面前，只管叫你父親和你弟兄住在國中最好的地；他們可以住在歌珊地。你若知道他們中間有甚麼能人，就派他們看管我的牲畜。」", "ja": "エジプトの地はあなたの前にある。地の最も良い所にあなたの父と兄弟たちとを住ませなさい。ゴセンの地に彼らを住ませなさい。もしあなたが彼らのうちに有能な者があるのを知っているなら、その者にわたしの家畜をつかさどらせなさい」。"}, "7": {"en": "Joseph brought in Jacob, his father, and set him before Pharaoh; and Jacob blessed Pharaoh.", "zh": "約瑟領他父親雅各進到法老面前，雅各就給法老祝福。", "ja": "そこでヨセフは父ヤコブを導いてパロの前に立たせた。ヤコブはパロを祝福した。"}, "8": {"en": "Pharaoh said to Jacob, “How old are you?”", "zh": "法老問雅各說：「你平生的年日是多少呢？」", "ja": "パロはヤコブに言った、「あなたの年はいくつか」。"}, "9": {"en": "Jacob said to Pharaoh, “The years of my pilgrimage are one hundred thirty years. The days of the years of my life have been few and evil. They have not attained to the days of the years of the life of my fathers in the days of their pilgrimage.”", "zh": "雅各對法老說：「我寄居在世的年日是一百三十歲，我平生的年日又少又苦，不及我列祖在世寄居的年日。」", "ja": "ヤコブはパロに言った、「わたしの旅路のとしつきは、百三十年です。わたしのよわいの日はわずかで、ふしあわせで、わたしの先祖たちのよわいの日と旅路の日には及びません」。"}, "10": {"en": "Jacob blessed Pharaoh, and went out from the presence of Pharaoh.", "zh": "雅各又給法老祝福，就從法老面前出去了。", "ja": "ヤコブはパロを祝福し、パロの前を去った。"}, "11": {"en": "Joseph placed his father and his brothers, and gave them a possession in the land of Egypt, in the best of the land, in the land of Rameses, as Pharaoh had commanded.", "zh": "約瑟遵着法老的命，把埃及國最好的地，就是蘭塞境內的地，給他父親和弟兄居住，作為產業。", "ja": "ヨセフはパロの命じたように、父と兄弟たちとのすまいを定め、彼らにエジプトの国で最も良い地、ラメセスの地を所有として与えた。"}, "12": {"en": "Joseph provided his father, his brothers, and all of his father’s household with bread, according to the sizes of their families.", "zh": "約瑟用糧食奉養他父親和他弟兄，並他父親全家的眷屬，都是照各家的人口奉養他們。", "ja": "またヨセフは父と兄弟たちと父の全家とに、家族の数にしたがい、食物を与えて養った。"}, "13": {"en": "There was no bread in all the land; for the famine was very severe, so that the land of Egypt and the land of Canaan fainted by reason of the famine.", "zh": "饑荒甚大，全地都絕了糧，甚至埃及地和迦南地的人因那饑荒的緣故都餓昏了。", "ja": "さて、ききんが非常に激しかったので、全地に食物がなく、エジプトの国もカナンの国も、ききんのために衰えた。"}, "14": {"en": "Joseph gathered up all the money that was found in the land of Egypt, and in the land of Canaan, for the grain which they bought: and Joseph brought the money into Pharaoh’s house.", "zh": "約瑟收聚了埃及地和迦南地所有的銀子，就是眾人糴糧的銀子，約瑟就把那銀子帶到法老的宮裏。", "ja": "それでヨセフは人々が買った穀物の代金としてエジプトの国とカナンの国にあった銀をみな集め、その銀をパロの家に納めた。"}, "15": {"en": "When the money was all spent in the land of Egypt, and in the land of Canaan, all the Egyptians came to Joseph, and said, “Give us bread, for why should we die in your presence? For our money fails.”", "zh": "埃及地和迦南地的銀子都花盡了，埃及眾人都來見約瑟，說：「我們的銀子都用盡了，求你給我們糧食，我們為甚麼死在你面前呢？」", "ja": "こうしてエジプトの国とカナンの国に銀が尽きたとき、エジプトびとはみなヨセフのもとにきて言った、「食物をください。銀が尽きたからとて、どうしてあなたの前で死んでよいでしょう」。"}, "16": {"en": "Joseph said, “Give me your livestock; and I will give you food for your livestock, if your money is gone.”", "zh": "約瑟說：「若是銀子用盡了，可以把你們的牲畜給我，我就為你們的牲畜給你們糧食。」", "ja": "ヨセフは言った、「あなたがたの家畜を出しなさい。銀が尽きたのなら、あなたがたの家畜と引き替えで食物をわたそう」。"}, "17": {"en": "They brought their livestock to Joseph, and Joseph gave them bread in exchange for the horses, and for the flocks, and for the herds, and for the donkeys: and he fed them with bread in exchange for all their livestock for that year.", "zh": "於是他們把牲畜趕到約瑟那裏，約瑟就拿糧食換了他們的牛、羊、驢、馬；那一年因換他們一切的牲畜，就用糧食養活他們。", "ja": "彼らはヨセフの所へ家畜をひいてきたので、ヨセフは馬と羊の群れと牛の群れ及びろばと引き替えで、食物を彼らにわたした。こうして彼はその年、すべての家畜と引き替えた食物で彼らを養った。"}, "18": {"en": "When that year was ended, they came to him the second year, and said to him, “We will not hide from my lord how our money is all spent, and the herds of livestock are my lord’s. There is nothing left in the sight of my lord, but our bodies, and our lands.", "zh": "那一年過去，第二年他們又來見約瑟，說：「我們不瞞我主，我們的銀子都花盡了，牲畜也都歸了我主。我們在我主眼前，除了我們的身體和田地之外，一無所剩。", "ja": "やがてその年は暮れ、次の年、人々はまたヨセフの所へきて言った、「わが主には何事も隠しません。われわれの銀は尽き、獣の群れもわが主のものになって、われわれのからだと田地のほかはわが主の前に何も残っていません。"}, "19": {"en": "Why should we die before your eyes, both we and our land? Buy us and our land for bread, and we and our land will be servants to Pharaoh. Give us seed, that we may live, and not die, and that the land won’t be desolate.”", "zh": "你何忍見我們人死地荒呢？求你用糧食買我們和我們的地，我們和我們的地就要給法老效力。又求你給我們種子，使我們得以存活，不致死亡，地土也不致荒涼。」", "ja": "われわれはどうして田地と一緒に、あなたの目の前で滅んでよいでしょう。われわれと田地とを食物と引き替えで買ってください。われわれは田地と一緒にパロの奴隷となりましょう。また種をください。そうすればわれわれは生きながらえ、死を免れて、田地も荒れないでしょう」。"}, "20": {"en": "So Joseph bought all the land of Egypt for Pharaoh, for every man of the Egyptians sold his field, because the famine was severe on them, and the land became Pharaoh’s.", "zh": "於是，約瑟為法老買了埃及所有的地，埃及人因被饑荒所迫，各都賣了自己的田地；那地就都歸了法老。", "ja": "そこでヨセフはエジプトの田地をみなパロのために買い取った。ききんがエジプトびとに、きびしかったので、めいめいその田畑を売ったからである。こうして地はパロのものとなった。"}, "21": {"en": "As for the people, he moved them to the cities from one end of the border of Egypt even to the other end of it.", "zh": "至於百姓，約瑟叫他們，從埃及這邊直到埃及那邊，都各歸各城。", "ja": "そしてヨセフはエジプトの国境のこの端からかの端まで民を奴隷とした。"}, "22": {"en": "Only he didn’t buy the land of the priests, for the priests had a portion from Pharaoh, and ate their portion which Pharaoh gave them. That is why they didn’t sell their land.", "zh": "惟有祭司的地，約瑟沒有買，因為祭司有從法老所得的常俸。他們吃法老所給的常俸，所以他們不賣自己的地。", "ja": "ただ祭司の田地は買い取らなかった。祭司にはパロの給与があって、パロが与える給与で生活していたので、その田地を売らなかったからである。"}, "23": {"en": "Then Joseph said to the people, “Behold, I have bought you and your land today for Pharaoh. Behold, here is seed for you, and you shall sow the land.", "zh": "約瑟對百姓說：「我今日為法老買了你們和你們的地，看哪，這裏有種子給你們，你們可以種地。", "ja": "ヨセフは民に言った、「わたしはきょう、あなたがたとその田地とを買い取って、パロのものとした。あなたがたに種をあげるから地にまきなさい。"}, "24": {"en": "It will happen at the harvests, that you shall give a fifth to Pharaoh, and four parts will be your own, for seed of the field, for your food, for them of your households, and for food for your little ones.”", "zh": "後來打糧食的時候，你們要把五分之一納給法老，四分可以歸你們做地裏的種子，也做你們和你們家口孩童的食物。」", "ja": "収穫の時は、その五分の一をパロに納め、五分の四を自分のものとして田畑の種とし、自分と家族の食糧とし、また子供の食糧としなさい」。"}, "25": {"en": "They said, “You have saved our lives! Let us find favor in the sight of my lord, and we will be Pharaoh’s servants.”", "zh": "他們說：「你救了我們的性命。但願我們在我主眼前蒙恩，我們就作法老的僕人。」", "ja": "彼らは言った、「あなたはわれわれの命をお救いくださった。どうかわが主の前に恵みを得させてください。われわれはパロの奴隷になりましょう」。"}, "26": {"en": "Joseph made it a statute concerning the land of Egypt to this day, that Pharaoh should have the fifth. Only the land of the priests alone didn’t become Pharaoh’s.", "zh": "於是約瑟為埃及地定下常例，直到今日：法老必得五分之一，惟獨祭司的地不歸法老。", "ja": "ヨセフはエジプトの田地について、収穫の五分の一をパロに納めることをおきてとしたが、それは今日に及んでいる。ただし祭司の田地だけはパロのものとならなかった。"}, "27": {"en": "Israel lived in the land of Egypt, in the land of Goshen; and they got themselves possessions therein, and were fruitful, and multiplied exceedingly.", "zh": "以色列人住在埃及的歌珊地。他們在那裏置了產業，並且生育甚多。", "ja": "さてイスラエルはエジプトの国でゴセンの地に住み、そこで財産を得、子を生み、大いにふえた。"}, "28": {"en": "Jacob lived in the land of Egypt seventeen years. So the days of Jacob, the years of his life, were one hundred forty-seven years.", "zh": "雅各住在埃及地十七年，雅各平生的年日是一百四十七歲。", "ja": "ヤコブはエジプトの国で十七年生きながらえた。ヤコブのよわいの日は百四十七年であった。"}, "29": {"en": "The time came near that Israel must die, and he called his son Joseph, and said to him, “If now I have found favor in your sight, please put your hand under my thigh, and deal kindly and truly with me. Please don’t bury me in Egypt,", "zh": "以色列的死期臨近了，他就叫了他兒子約瑟來，說：「我若在你眼前蒙恩，請你把手放在我大腿底下，用慈愛和誠實待我，請你不要將我葬在埃及。", "ja": "イスラエルは死ぬ時が近づいたので、その子ヨセフを呼んで言った、「もしわたしがあなたの前に恵みを得るなら、どうか手をわたしのももの下に入れて誓い、親切と誠実とをもってわたしを取り扱ってください。どうかわたしをエジプトには葬らないでください。"}, "30": {"en": "but when I sleep with my fathers, you shall carry me out of Egypt, and bury me in their burying place.” Joseph said, “I will do as you have said.”", "zh": "我與我祖我父同睡的時候，你要將我帶出埃及，葬在他們所葬的地方。」約瑟說：「我必遵着你的命而行。」", "ja": "わたしが先祖たちと共に眠るときには、わたしをエジプトから運び出して先祖たちの墓に葬ってください」。ヨセフは言った、「あなたの言われたようにいたします」。"}, "31": {"en": "Israel said, “Swear to me,” and he swore to him. Then Israel bowed himself on the bed’s head.", "zh": "雅各說：「你要向我起誓。」約瑟就向他起了誓，於是以色列在床頭上敬拜上帝。", "ja": "ヤコブがまた、「わたしに誓ってください」と言ったので、彼は誓った。イスラエルは床のかしらで拝んだ。"}}}, "48": {"verses": {"1": {"en": "After these things, someone said to Joseph, “Behold, your father is sick.” He took with him his two sons, Manasseh and Ephraim.", "zh": "這事以後，有人告訴約瑟說：「你的父親病了。」他就帶着兩個兒子瑪拿西和以法蓮同去。", "ja": "これらの事の後に、「あなたの父は、いま病気です」とヨセフに告げる者があったので、彼はふたりの子、マナセとエフライムとを連れて行った。"}, "2": {"en": "Someone told Jacob, and said, “Behold, your son Joseph comes to you,” and Israel strengthened himself, and sat on the bed.", "zh": "有人告訴雅各說：「請看，你兒子約瑟到你這裏來了。」以色列就勉強在床上坐起來。", "ja": "時に人がヤコブに告げて、「あなたの子ヨセフがあなたのもとにきました」と言ったので、イスラエルは努めて床の上にすわった。"}, "3": {"en": "Jacob said to Joseph, “God Almighty appeared to me at Luz in the land of Canaan, and blessed me,", "zh": "雅各對約瑟說：「全能的上帝曾在迦南地的路斯向我顯現，賜福與我，", "ja": "そしてヤコブはヨセフに言った、「先に全能の神がカナンの地ルズでわたしに現れ、わたしを祝福して、"}, "4": {"en": "and said to me, ‘Behold, I will make you fruitful, and multiply you, and I will make of you a company of peoples, and will give this land to your offspring after you for an everlasting possession.’", "zh": "對我說：『我必使你生養眾多，成為多民，又要把這地賜給你的後裔，永遠為業。』", "ja": "言われた、『わたしはおまえに多くの子を得させ、おまえをふやし、おまえを多くの国民としよう。また、この地をおまえの後の子孫に与えて永久の所有とさせる』。"}, "5": {"en": "Now your two sons, who were born to you in the land of Egypt before I came to you into Egypt, are mine; Ephraim and Manasseh, even as Reuben and Simeon, will be mine.", "zh": "我未到埃及見你之先，你在埃及地所生的以法蓮和瑪拿西這兩個兒子是我的，正如呂便和西緬是我的一樣。", "ja": "エジプトにいるあなたの所にわたしが来る前に、エジプトの国で生れたあなたのふたりの子はいまわたしの子とします。すなわちエフライムとマナセとはルベンとシメオンと同じようにわたしの子とします。"}, "6": {"en": "Your offspring, whom you become the father of after them, will be yours. They will be called after the name of their brothers in their inheritance.", "zh": "你在他們以後所生的就是你的，他們可以歸於他們弟兄的名下得產業。", "ja": "ただし彼らの後にあなたに生れた子らはあなたのものとなります。しかし、その嗣業はその兄弟の名で呼ばれるでしょう。"}, "7": {"en": "As for me, when I came from Paddan, Rachel died beside me in the land of Canaan on the way, when there was still some distance to come to Ephrath, and I buried her there on the way to Ephrath (also called Bethlehem).”", "zh": "至於我，我從巴旦來的時候，拉結死在我眼前，在迦南地的路上，離以法他還有一段路程，我就把她葬在以法他的路上（以法他就是伯利恆）。」", "ja": "わたしがパダンから帰って来る途中ラケルはカナンの地で死に、わたしは悲しんだ。そこはエフラタに行くまでには、なお隔たりがあった。わたしはエフラタ、すなわちベツレヘムへ行く道のかたわらに彼女を葬った」。"}, "8": {"en": "Israel saw Joseph’s sons, and said, “Who are these?”", "zh": "以色列看見約瑟的兩個兒子，就說：「這是誰？」", "ja": "ところで、イスラエルはヨセフの子らを見て言った、「これはだれですか」。"}, "9": {"en": "Joseph said to his father, “They are my sons, whom God has given me here.”", "zh": "約瑟對他父親說：「這是上帝在這裏賜給我的兒子。」以色列說：「請你領他們到我跟前，我要給他們祝福。」", "ja": "ヨセフは父に言った、「神がここでわたしにくださった子どもです」。父は言った、「彼らをわたしの所に連れてきて、わたしに祝福させてください」。"}, "10": {"en": "He said, “Please bring them to me, and I will bless them.”   Now the eyes of Israel were dim for age, so that he couldn’t see well. Joseph brought them near to him; and he kissed them, and embraced them.", "zh": "以色列年紀老邁，眼睛昏花，不能看見。約瑟領他們到他跟前，他就和他們親嘴，抱着他們。", "ja": "イスラエルの目は老齢のゆえに、かすんで見えなかったが、ヨセフが彼らを父の所に近寄らせたので、父は彼らに口づけし、彼らを抱いた。"}, "11": {"en": "Israel said to Joseph, “I didn’t think I would see your face, and behold, God has let me see your offspring also.”", "zh": "以色列對約瑟說：「我想不到得見你的面，不料，上帝又使我得見你的兒子。」", "ja": "そしてイスラエルはヨセフに言った、「あなたの顔が見られようとは思わなかったのに、神はあなたの子らをもわたしに見させてくださった」。"}, "12": {"en": "Joseph brought them out from between his knees, and he bowed himself with his face to the earth.", "zh": "約瑟把兩個兒子從以色列兩膝中領出來，自己就臉伏於地下拜。", "ja": "そこでヨセフは彼らをヤコブのひざの間から取り出し、地に伏して拝した。"}, "13": {"en": "Joseph took them both, Ephraim in his right hand toward Israel’s left hand, and Manasseh in his left hand toward Israel’s right hand, and brought them near to him.", "zh": "隨後，約瑟又拉着他們兩個，以法蓮在他的右手裏，對着以色列的左手，瑪拿西在他的左手裏，對着以色列的右手，領他們到以色列的跟前。", "ja": "ヨセフはエフライムを右の手に取ってイスラエルの左の手に向かわせ、マナセを左の手に取ってイスラエルの右の手に向かわせ、ふたりを近寄らせた。"}, "14": {"en": "Israel stretched out his right hand, and laid it on Ephraim’s head, who was the younger, and his left hand on Manasseh’s head, guiding his hands knowingly, for Manasseh was the firstborn.", "zh": "以色列伸出右手來，按在以法蓮的頭上（以法蓮乃是次子），又剪搭過左手來，按在瑪拿西的頭上（瑪拿西原是長子）。", "ja": "すると、イスラエルは右の手を伸べて弟エフライムの頭に置き、左の手をマナセの頭に置いた。マナセは長子であるが、ことさらそのように手を置いたのである。"}, "15": {"en": "He blessed Joseph, and said, “The God before whom my fathers Abraham and Isaac walked, the God who has fed me all my life long to this day,", "zh": "他就給約瑟祝福說：「願我祖亞伯拉罕和我父以撒所事奉的上帝，就是一生牧養我直到今日的上帝，", "ja": "そしてヨセフを祝福して言った、「わが先祖アブラハムとイサクの仕えた神、生れてからきょうまでわたしを養われた神、"}, "16": {"en": "the angel who has redeemed me from all evil, bless the lads, and let my name be named on them, and the name of my fathers Abraham and Isaac. Let them grow into a multitude upon the earth.”", "zh": "救贖我脫離一切患難的那使者，賜福與這兩個童子。願他們歸在我的名下和我祖亞伯拉罕、我父以撒的名下。又願他們在世界中生養眾多。」", "ja": "すべての災からわたしをあがなわれたみ使よ、この子供たちを祝福してください。またわが名と先祖アブラハムとイサクの名とが、彼らによって唱えられますように、また彼らが地の上にふえひろがりますように」。"}, "17": {"en": "When Joseph saw that his father laid his right hand on the head of Ephraim, it displeased him. He held up his father’s hand, to remove it from Ephraim’s head to Manasseh’s head.", "zh": "約瑟見他父親把右手按在以法蓮的頭上，就不喜悅，便提起他父親的手，要從以法蓮頭上挪到瑪拿西的頭上。", "ja": "ヨセフは父が右の手をエフライムの頭に置いているのを見て不満に思い、父の手を取ってエフライムの頭からマナセの頭へ移そうとした。"}, "18": {"en": "Joseph said to his father, “Not so, my father, for this is the firstborn. Put your right hand on his head.”", "zh": "約瑟對他父親說：「我父，不是這樣。這本是長子，求你把右手按在他的頭上。」", "ja": "そしてヨセフは父に言った、「父よ、そうではありません。こちらが長子です。その頭に右の手を置いてください」。"}, "19": {"en": "His father refused, and said, “I know, my son, I know. He also will become a people, and he also will be great. However, his younger brother will be greater than he, and his offspring will become a multitude of nations.”", "zh": "他父親不從，說：「我知道，我兒，我知道。他也必成為一族，也必昌大。只是他的兄弟將來比他還大；他兄弟的後裔要成為多族。」", "ja": "父は拒んで言った、「わかっている。子よ、わたしにはわかっている。彼もまた一つの民となり、また大いなる者となるであろう。しかし弟は彼よりも大いなる者となり、その子孫は多くの国民となるであろう」。"}, "20": {"en": "He blessed them that day, saying, “Israel will bless in your name, saying, ‘God make you as Ephraim and as Manasseh’ ” He set Ephraim before Manasseh.", "zh": "當日就給他們祝福說：「以色列人要指着你們祝福說：『願上帝使你如以法蓮、瑪拿西一樣。』」於是立以法蓮在瑪拿西以上。", "ja": "こうして彼はこの日、彼らを祝福して言った、「あなたを指して、イスラエルは、人を祝福して言うであろう、『神があなたをエフライムのごとく、またマナセのごとくにせられるように』」。このように、彼はエフライムをマナセの先に立てた。"}, "21": {"en": "Israel said to Joseph, “Behold, I am dying, but God will be with you, and bring you again to the land of your fathers.", "zh": "以色列又對約瑟說：「我要死了，但上帝必與你們同在，領你們回到你們列祖之地。", "ja": "イスラエルはまたヨセフに言った、「わたしはやがて死にます。しかし、神はあなたがたと共におられて、あなたがたを先祖の国に導き返されるであろう。"}, "22": {"en": "Moreover I have given to you one portion above your brothers, which I took out of the hand of the Amorite with my sword and with my bow.”", "zh": "並且我從前用弓用刀從亞摩利人手下奪的那塊地，我都賜給你，使你比眾弟兄多得一分。」", "ja": "なおわたしは一つの分を兄弟よりも多くあなたに与える。これはわたしがつるぎと弓とを持ってアモリびとの手から取ったものである」。"}}}, "49": {"verses": {"1": {"en": "Jacob called to his sons, and said: “Gather yourselves together, that I may tell you that which will happen to you in the days to come.", "zh": "雅各叫了他的兒子們來，說：「你們都來聚集，我好把你們日後必遇的事告訴你們。", "ja": "ヤコブはその子らを呼んで言った、「集まりなさい。後の日に、あなたがたの上に起ることを、告げましょう、"}, "2": {"en": "Assemble yourselves, and hear, you sons of Jacob. Listen to Israel, your father.", "zh": "雅各的兒子們，你們要聚集而聽， 要聽你們父親以色列的話。", "ja": "ヤコブの子らよ、集まって聞け。父イスラエルのことばを聞け。"}, "3": {"en": "“Reuben, you are my firstborn, my might, and the beginning of my strength, excelling in dignity, and excelling in power.", "zh": "呂便哪，你是我的長子， 是我力量強壯的時候生的， 本當大有尊榮，權力超眾。", "ja": "ルベンよ、あなたはわが長子、わが勢い、わが力のはじめ、威光のすぐれた者、権力のすぐれた者。"}, "4": {"en": "Boiling over like water, you shall not excel, because you went up to your father’s bed, then defiled it. He went up to my couch.", "zh": "但你放縱情慾，滾沸如水， 必不得居首位； 因為你上了你父親的床， 污穢了我的榻。", "ja": "しかし、沸き立つ水のようだから、もはや、すぐれた者ではあり得ない。あなたは父の床に上って汚した。ああ、あなたはわが寝床に上った。"}, "5": {"en": "“Simeon and Levi are brothers. Their swords are weapons of violence.", "zh": "西緬和利未是弟兄； 他們的刀劍是殘忍的器具。", "ja": "シメオンとレビとは兄弟。彼らのつるぎは暴虐の武器。"}, "6": {"en": "My soul, don’t come into their council. My glory, don’t be united to their assembly; for in their anger they killed men. In their self-will they hamstrung cattle.", "zh": "我的靈啊，不要與他們同謀； 我的心哪，不要與他們聯絡； 因為他們趁怒殺害人命， 任意砍斷牛腿大筋。", "ja": "わが魂よ、彼らの会議に臨むな。わが栄えよ、彼らのつどいに連なるな。彼らは怒りに任せて人を殺し、ほしいままに雄牛の足の筋を切った。"}, "7": {"en": "Cursed be their anger, for it was fierce; and their wrath, for it was cruel. I will divide them in Jacob, and scatter them in Israel.", "zh": "他們的怒氣暴烈可咒； 他們的忿恨殘忍可詛。 我要使他們分居在雅各家裏， 散住在以色列地中。", "ja": "彼らの怒りは、激しいゆえにのろわれ、彼らの憤りは、はなはだしいゆえにのろわれる。わたしは彼らをヤコブのうちに分け、イスラエルのうちに散らそう。"}, "8": {"en": "“Judah, your brothers will praise you. Your hand will be on the neck of your enemies. Your father’s sons will bow down before you.", "zh": "猶大啊，你弟兄們必讚美你； 你手必掐住仇敵的頸項； 你父親的兒子們必向你下拜。", "ja": "ユダよ、兄弟たちはあなたをほめる。あなたの手は敵のくびを押え、父の子らはあなたの前に身をかがめるであろう。"}, "9": {"en": "Judah is a lion’s cub. From the prey, my son, you have gone up. He stooped down, he crouched as a lion, as a lioness. Who will rouse him up?", "zh": "猶大是個小獅子； 我兒啊，你抓了食便上去。 你屈下身去，臥如公獅， 蹲如母獅，誰敢惹你？", "ja": "ユダは、ししの子。わが子よ、あなたは獲物をもって上って来る。彼は雄じしのようにうずくまり、雌じしのように身を伏せる。だれがこれを起すことができよう。"}, "10": {"en": "The scepter will not depart from Judah, nor the ruler’s staff from between his feet, until he comes to whom it belongs. The obedience of the peoples will be to him.", "zh": "圭必不離猶大， 杖必不離他兩腳之間， 直等細羅來到， 萬民都必歸順。", "ja": "つえはユダを離れず、立法者のつえはその足の間を離れることなく、シロの来る時までに及ぶであろう。もろもろの民は彼に従う。"}, "11": {"en": "Binding his foal to the vine, his donkey’s colt to the choice vine, he has washed his garments in wine, his robes in the blood of grapes.", "zh": "猶大把小驢拴在葡萄樹上， 把驢駒拴在美好的葡萄樹上。 他在葡萄酒中洗了衣服， 在葡萄汁中洗了袍褂。", "ja": "彼はそのろばの子をぶどうの木につなぎ、その雌ろばの子を良きぶどうの木につなぐ。彼はその衣服をぶどう酒で洗い、その着物をぶどうの汁で洗うであろう。"}, "12": {"en": "His eyes will be red with wine, his teeth white with milk.", "zh": "他的眼睛必因酒紅潤； 他的牙齒必因奶白亮。", "ja": "その目はぶどう酒によって赤く、その歯は乳によって白い。"}, "13": {"en": "“Zebulun will dwell at the haven of the sea. He will be for a haven of ships. His border will be on Sidon.", "zh": "西布倫必住在海口， 必成為停船的海口； 他的境界必延到西頓。", "ja": "ゼブルンは海べに住み、舟の泊まる港となって、その境はシドンに及ぶであろう。"}, "14": {"en": "“Issachar is a strong donkey, lying down between the saddlebags.", "zh": "以薩迦是個強壯的驢， 臥在羊圈之中。", "ja": "イッサカルはたくましいろば、彼は羊のおりの間に伏している。"}, "15": {"en": "He saw a resting place, that it was good, the land, that it was pleasant. He bows his shoulder to the burden, and becomes a servant doing forced labor.", "zh": "他以安靜為佳，以肥地為美， 便低肩背重，成為服苦的僕人。", "ja": "彼は定住の地を見て良しとし、その国を見て楽しとした。彼はその肩を下げてにない、奴隷となって追い使われる。"}, "16": {"en": "“Dan will judge his people, as one of the tribes of Israel.", "zh": "但必判斷他的民， 作以色列支派之一。", "ja": "ダンはおのれの民をさばくであろう、イスラエルのほかの部族のように。"}, "17": {"en": "Dan will be a serpent on the trail, an adder in the path, that bites the horse’s heels, so that his rider falls backward.", "zh": "但必作道上的蛇，路中的虺， 咬傷馬蹄，使騎馬的墜落於後。", "ja": "ダンは道のかたわらのへび、道のほとりのまむし。馬のかかとをかんで、乗る者をうしろに落すであろう。"}, "18": {"en": "I have waited for your salvation, LORD.", "zh": "耶和華啊，我向來等候你的救恩。", "ja": "主よ、わたしはあなたの救を待ち望む。"}, "19": {"en": "“A troop will press on Gad, but he will press on their heel.", "zh": "迦得必被敵軍追逼， 他卻要追逼他們的腳跟。", "ja": "ガドには略奪者が迫る。しかし彼はかえって敵のかかとに迫るであろう。"}, "20": {"en": "“Asher’s food will be rich. He will produce royal dainties.", "zh": "亞設之地必出肥美的糧食， 且出君王的美味。", "ja": "アセルはその食物がゆたかで、王の美味をいだすであろう。"}, "21": {"en": "“Naphtali is a doe set free, who bears beautiful fawns.", "zh": "拿弗他利是被釋放的母鹿； 他出嘉美的言語。", "ja": "ナフタリは放たれた雌じか、彼は美しい子じかを生むであろう。"}, "22": {"en": "“Joseph is a fruitful vine, a fruitful vine by a spring. His branches run over the wall.", "zh": "約瑟是多結果子的樹枝， 是泉旁多結果的枝子； 他的枝條探出牆外。", "ja": "ヨセフは実を結ぶ若木、泉のほとりの実を結ぶ若木。その枝は、かきねを越えるであろう。"}, "23": {"en": "The archers have severely grieved him, shot at him, and persecuted him:", "zh": "弓箭手將他苦害， 向他射箭，逼迫他。", "ja": "射る者は彼を激しく攻め、彼を射、彼をいたく悩ました。"}, "24": {"en": "But his bow remained strong. The arms of his hands were made strong, by the hands of the Mighty One of Jacob, (from there is the shepherd, the stone of Israel),", "zh": "但他的弓仍舊堅硬； 他的手健壯敏捷。 這是因以色列的牧者，以色列的磐石－ 就是雅各的大能者。", "ja": "しかし彼の弓はなお強く、彼の腕は素早い。これはヤコブの全能者の手により、イスラエルの岩なる牧者の名により、"}, "25": {"en": "even by the God of your father, who will help you, by the Almighty, who will bless you, with blessings of heaven above, blessings of the deep that lies below, blessings of the breasts, and of the womb.", "zh": "你父親的上帝必幫助你； 那全能者必將天上所有的福， 地裏所藏的福，以及生產乳養的福，都賜給你。", "ja": "あなたを助ける父の神により、また上なる天の祝福、下に横たわる淵の祝福、乳ぶさと胎の祝福をもって、あなたを恵まれる全能者による。"}, "26": {"en": "The blessings of your father have prevailed above the blessings of my ancestors, above the boundaries of the ancient hills. They will be on the head of Joseph, on the crown of the head of him who is separated from his brothers.", "zh": "你父親所祝的福 勝過我祖先所祝的福， 如永世的山嶺，至極的邊界； 這些福必降在約瑟的頭上， 臨到那與弟兄迥別之人的頂上。", "ja": "あなたの父の祝福は永遠の山の祝福にまさり、永久の丘の賜物にまさる。これらの祝福はヨセフのかしらに帰し、その兄弟たちの君たる者の頭の頂に帰する。"}, "27": {"en": "“Benjamin is a ravenous wolf. In the morning he will devour the prey. At evening he will divide the plunder.”", "zh": "便雅憫是個撕掠的狼， 早晨要吃他所抓的， 晚上要分他所奪的。」", "ja": "ベニヤミンはかき裂くおおかみ、朝にその獲物を食らい、夕にその分捕物を分けるであろう」。"}, "28": {"en": "All these are the twelve tribes of Israel, and this is what their father spoke to them, and blessed them. He blessed everyone according to his own blessing.", "zh": "這一切是以色列的十二支派；這也是他們的父親對他們所說的話，為他們所祝的福，都是按着各人的福分為他們祝福。", "ja": "すべてこれらはイスラエルの十二の部族である。そしてこれは彼らの父が彼らに語り、彼らを祝福したもので、彼は祝福すべきところに従って、彼らおのおのを祝福した。"}, "29": {"en": "He instructed them, and said to them, “I am to be gathered to my people. Bury me with my fathers in the cave that is in the field of Ephron the Hittite,", "zh": "他又囑咐他們說：「我將要歸到我列祖那裏，你們要將我葬在赫人以弗崙田間的洞裏，與我祖我父在一處，", "ja": "彼はまた彼らに命じて言った、「わたしはわが民に加えられようとしている。あなたがたはヘテびとエフロンの畑にあるほら穴に、わたしの先祖たちと共にわたしを葬ってください。"}, "30": {"en": "in the cave that is in the field of Machpelah, which is before Mamre, in the land of Canaan, which Abraham bought with the field from Ephron the Hittite as a burial place.", "zh": "就是在迦南地幔利前、麥比拉田間的洞；那洞和田是亞伯拉罕向赫人以弗崙買來為業，作墳地的。", "ja": "そのほら穴はカナンの地のマムレの東にあるマクペラの畑にあり、アブラハムがヘテびとエフロンから畑と共に買い取り、所有の墓地としたもので、"}, "31": {"en": "There they buried Abraham and Sarah, his wife. There they buried Isaac and Rebekah, his wife, and there I buried Leah:", "zh": "他們在那裏葬了亞伯拉罕和他妻子撒拉，又在那裏葬了以撒和他的妻子利百加；我也在那裏葬了利亞。", "ja": "そこにアブラハムと妻サラとが葬られ、イサクと妻リベカもそこに葬られたが、わたしはまたそこにレアを葬った。"}, "32": {"en": "the field and the cave that is therein, which was purchased from the children of Heth.”", "zh": "那塊田和田間的洞原是向赫人買的。」", "ja": "あの畑とその中にあるほら穴とはヘテの人々から買ったものです」。"}, "33": {"en": "When Jacob finished charging his sons, he gathered up his feet into the bed, breathed his last breath, and was gathered to his people.", "zh": "雅各囑咐眾子已畢，就把腳收在床上，氣絕而死，歸他列祖那裏去了。", "ja": "こうしてヤコブは子らに命じ終って、足を床におさめ、息絶えて、その民に加えられた。"}}}, "50": {"verses": {"1": {"en": "", "zh": "約瑟伏在他父親的面上哀哭，與他親嘴。", "ja": "ヨセフは父の顔に伏して泣き、口づけした。"}, "2": {"en": "", "zh": "約瑟吩咐伺候他的醫生用香料薰他父親，醫生就用香料薰了以色列。", "ja": "そしてヨセフは彼のしもべである医者たちに、父に薬を塗ることを命じたので、医者たちはイスラエルに薬を塗った。"}, "3": {"en": "", "zh": "薰屍的常例是四十天；那四十天滿了，埃及人為他哀哭了七十天。", "ja": "このために四十日を費した。薬を塗るにはこれほどの日数を要するのである。エジプトびとは七十日の間、彼のために泣いた。"}, "4": {"en": "When the days of weeping for him were past, Joseph spoke to Pharaoh’s staff, saying, “If now I have found favor in your eyes, please speak in the ears of Pharaoh, saying,", "zh": "為他哀哭的日子過了，約瑟對法老家中的人說：「我若在你們眼前蒙恩，請你們報告法老說：", "ja": "彼のために泣く日が過ぎて、ヨセフはパロの家の者に言った、「今もしわたしがあなたがたの前に恵みを得るなら、どうかパロに伝えてください。"}, "5": {"en": "‘My father made me swear, saying, “Behold, I am dying. Bury me in my grave which I have dug for myself in the land of Canaan.” Now therefore, please let me go up and bury my father, and I will come again.’ ”", "zh": "『我父親要死的時候叫我起誓說：你要將我葬在迦南地，在我為自己所掘的墳墓裏。』現在求你讓我上去葬我父親，以後我必回來。」", "ja": "『わたしの父はわたしに誓わせて言いました「わたしはやがて死にます。カナンの地に、わたしが掘って置いた墓に葬ってください」。それで、どうかわたしを上って行かせ、父を葬らせてください。そうすれば、わたしはまた帰ってきます』」。"}, "6": {"en": "Pharaoh said, “Go up, and bury your father, just like he made you swear.”", "zh": "法老說：「你可以上去，照着你父親叫你起的誓，將他葬埋。」", "ja": "パロは言った、「あなたの父があなたに誓わせたように上って行って彼を葬りなさい」。"}, "7": {"en": "Joseph went up to bury his father; and with him went up all the servants of Pharaoh, the elders of his house, all the elders of the land of Egypt,", "zh": "於是約瑟上去葬他父親。與他一同上去的，有法老的臣僕和法老家中的長老，並埃及國的長老，", "ja": "そこでヨセフは父を葬るために上って行った。彼と共に上った者はパロのもろもろの家来たち、パロの家の長老たち、エジプトの国のもろもろの長老たち、"}, "8": {"en": "all the house of Joseph, his brothers, and his father’s house. Only their little ones, their flocks, and their herds, they left in the land of Goshen.", "zh": "還有約瑟的全家和他的弟兄們，並他父親的眷屬；只有他們的婦人孩子，和羊群牛群，都留在歌珊地。", "ja": "ヨセフの全家とその兄弟たち及びその父の家族であった。ただ子供と羊と牛はゴセンの地に残した。"}, "9": {"en": "Both chariots and horsemen went up with him. It was a very great company.", "zh": "又有車輛馬兵，和他一同上去；那一幫人甚多。", "ja": "また戦車と騎兵も彼と共に上ったので、その行列はたいそう盛んであった。"}, "10": {"en": "They came to the threshing floor of Atad, which is beyond the Jordan, and there they lamented with a very great and severe lamentation. He mourned for his father seven days.", "zh": "他們到了約旦河外、亞達的禾場，就在那裏大大地號咷痛哭。約瑟為他父親哀哭了七天。", "ja": "彼らはヨルダンの向こうのアタデの打ち場に行き着いて、そこで大いに嘆き、非常に悲しんだ。そしてヨセフは七日の間父のために嘆いた。"}, "11": {"en": "When the inhabitants of the land, the Canaanites, saw the mourning in the floor of Atad, they said, “This is a grievous mourning by the Egyptians.” Therefore its name was called Abel Mizraim, which is beyond the Jordan.", "zh": "迦南的居民見亞達禾場上的哀哭，就說：「這是埃及人一場極大的哀哭。」因此那地方名叫亞伯‧麥西，是在約旦河東。", "ja": "その地の住民、カナンびとがアタデの打ち場の嘆きを見て、「これはエジプトびとの大いなる嘆きだ」と言ったので、その所の名はアベル・ミツライムと呼ばれた。これはヨルダンの向こうにある。"}, "12": {"en": "His sons did to him just as he commanded them,", "zh": "雅各的兒子們就遵着他父親所吩咐的辦了，", "ja": "ヤコブの子らは命じられたようにヤコブにおこなった。"}, "13": {"en": "for his sons carried him into the land of Canaan, and buried him in the cave of the field of Machpelah, which Abraham bought with the field, as a possession for a burial site, from Ephron the Hittite, near Mamre.", "zh": "把他搬到迦南地，葬在幔利前、麥比拉田間的洞裏；那洞和田是亞伯拉罕向赫人以弗崙買來為業，作墳地的。", "ja": "すなわちその子らは彼をカナンの地へ運んで行って、マクペラの畑のほら穴に葬った。このほら穴はマムレの東にあって、アブラハムがヘテびとエフロンから畑と共に買って、所有の墓地としたものである。"}, "14": {"en": "Joseph returned into Egypt—he, and his brothers, and all that went up with him to bury his father, after he had buried his father.", "zh": "約瑟葬了他父親以後，就和眾弟兄，並一切同他上去葬他父親的人，都回埃及去了。", "ja": "ヨセフは父を葬った後、その兄弟たち及びすべて父を葬るために一緒に上った者と共にエジプトに帰った。"}, "15": {"en": "When Joseph’s brothers saw that their father was dead, they said, “It may be that Joseph will hate us, and will fully pay us back for all the evil which we did to him.”", "zh": "約瑟的哥哥們見父親死了，就說：「或者約瑟懷恨我們，照着我們從前待他一切的惡足足地報復我們。」", "ja": "ヨセフの兄弟たちは父の死んだのを見て言った、「ヨセフはことによるとわれわれを憎んで、われわれが彼にしたすべての悪に、仕返しするに違いない」。"}, "16": {"en": "They sent a message to Joseph, saying, “Your father commanded before he died, saying,", "zh": "他們就打發人去見約瑟，說：「你父親未死以先吩咐說：", "ja": "そこで彼らはことづけしてヨセフに言った、「あなたの父は死ぬ前に命じて言われました、"}, "17": {"en": "‘You shall tell Joseph, “Now please forgive the disobedience of your brothers, and their sin, because they did evil to you.” ’ Now, please forgive the disobedience of the servants of the God of your father.” Joseph wept when they spoke to him.", "zh": "『你們要對約瑟這樣說：從前你哥哥們惡待你，求你饒恕他們的過犯和罪惡。』如今求你饒恕你父親上帝之僕人的過犯。」他們對約瑟說這話，約瑟就哭了。", "ja": "『おまえたちはヨセフに言いなさい、「あなたの兄弟たちはあなたに悪をおこなったが、どうかそのとがと罪をゆるしてやってください」』。今どうかあなたの父の神に仕えるしもべらのとがをゆるしてください」。ヨセフはこの言葉を聞いて泣いた。"}, "18": {"en": "His brothers also went and fell down before his face; and they said, “Behold, we are your servants.”", "zh": "他的哥哥們又來俯伏在他面前，說：「我們是你的僕人。」", "ja": "やがて兄弟たちもきて、彼の前に伏して言った、「このとおり、わたしたちはあなたのしもべです」。"}, "19": {"en": "Joseph said to them, “Don’t be afraid, for am I in the place of God?", "zh": "約瑟對他們說：「不要害怕，我豈能代替上帝呢？", "ja": "ヨセフは彼らに言った、「恐れることはいりません。わたしが神に代ることができましょうか。"}, "20": {"en": "As for you, you meant evil against me, but God meant it for good, to save many people alive, as is happening today.", "zh": "從前你們的意思是要害我，但上帝的意思原是好的，要保全許多人的性命，成就今日的光景。", "ja": "あなたがたはわたしに対して悪をたくらんだが、神はそれを良きに変らせて、今日のように多くの民の命を救おうと計らわれました。"}, "21": {"en": "Now therefore don’t be afraid. I will provide for you and your little ones.” He comforted them, and spoke kindly to them.", "zh": "現在你們不要害怕，我必養活你們和你們的婦人孩子。」於是約瑟用親愛的話安慰他們。", "ja": "それゆえ恐れることはいりません。わたしはあなたがたとあなたがたの子供たちを養いましょう」。彼は彼らを慰めて、親切に語った。"}, "22": {"en": "Joseph lived in Egypt, he, and his father’s house. Joseph lived one hundred ten years.", "zh": "約瑟和他父親的眷屬都住在埃及。約瑟活了一百一十歲。", "ja": "このようにしてヨセフは父の家族と共にエジプトに住んだ。そしてヨセフは百十年生きながらえた。"}, "23": {"en": "Joseph saw Ephraim’s children to the third generation. The children also of Machir, the son of Manasseh, were born on Joseph’s knees.", "zh": "約瑟得見以法蓮第三代的子孫。瑪拿西的孫子、瑪吉的兒子也養在約瑟的膝上。", "ja": "ヨセフはエフライムの三代の子孫を見た。マナセの子マキルの子らも生れてヨセフのひざの上に置かれた。"}, "24": {"en": "Joseph said to his brothers, “I am dying, but God will surely visit you, and bring you up out of this land to the land which he swore to Abraham, to Isaac, and to Jacob.”", "zh": "約瑟對他弟兄們說：「我要死了，但上帝必定看顧你們，領你們從這地上去，到他起誓所應許給亞伯拉罕、以撒、雅各之地。」", "ja": "ヨセフは兄弟たちに言った、「わたしはやがて死にます。神は必ずあなたがたを顧みて、この国から連れ出し、アブラハム、イサク、ヤコブに誓われた地に導き上られるでしょう」。"}, "25": {"en": "Joseph took an oath from the children of Israel, saying, “God will surely visit you, and you shall carry up my bones from here.”", "zh": "約瑟叫以色列的子孫起誓說：「上帝必定看顧你們；你們要把我的骸骨從這裏搬上去。」", "ja": "さらにヨセフは、「神は必ずあなたがたを顧みられる。その時、あなたがたはわたしの骨をここから携え上りなさい」と言ってイスラエルの子らに誓わせた。"}, "26": {"en": "So Joseph died, being one hundred ten years old, and they embalmed him, and he was put in a coffin in Egypt.", "zh": "約瑟死了，正一百一十歲。人用香料將他薰了，把他收殮在棺材裏，停在埃及。", "ja": "こうしてヨセフは百十歳で死んだ。彼らはこれに薬を塗り、棺に納めて、エジプトに置いた。"}}}}};
